// Vocabulary Enrichment Data - 第2例文・語源/覚え方・コロケーション
// Generated by Claude Code (2026-07-19、以後エッセイ追加時に随時追記)。キーは glossary の word.toLowerCase()
const VOCAB_ENRICHMENT = {"mitigation":{"example2":"The fund manager outlined a clear risk mitigation plan for volatile markets.","exampleJa2":"ファンドマネージャーは不安定な市場に対する明確なリスク緩和計画を説明した。","origin":"ラテン語mitis(柔らかい)+agere(行う)→mitigate(和らげる)+ion。危険や損害の深刻さを和らげる行為を指す。","collocations":["risk mitigation","mitigation measures","climate mitigation"]},"adaptation":{"example2":"Our sales team showed quick adaptation to the new digital platform.","exampleJa2":"私たちの営業チームは新しいデジタルプラットフォームに素早く適応した。","origin":"ラテン語ad(〜へ)+aptare(適合させる)→状況に合わせて自分を適するように変えること。apt(適切な)と同語源。","collocations":["climate adaptation","adaptation strategy","rapid adaptation"]},"resilience":{"example2":"The bank's stress tests proved the resilience of its balance sheet.","exampleJa2":"銀行のストレステストはそのバランスシートの回復力を証明した。","origin":"ラテン語re(再び)+salire(跳ぶ)→跳ね返る力。押しつぶされてもバネのように元へ戻るイメージ。","collocations":["build resilience","economic resilience","show resilience"]},"inertia":{"example2":"Organizational inertia prevented the firm from adopting new trading systems.","exampleJa2":"組織の惰性がその会社の新しい取引システム導入を妨げた。","origin":"ラテン語iners(不活発な)=in(否定)+ars(技術)→動く技を持たない。物理の「慣性」から組織の停滞の比喩へ。","collocations":["overcome inertia","bureaucratic inertia","organizational inertia"]},"inevitable":{"example2":"Analysts warned that a market correction was inevitable after the rally.","exampleJa2":"アナリストは急騰の後には市場調整が避けられないと警告した。","origin":"ラテン語in(否定)+evitare(避ける)+able→避けることができない。evitableなら「避けられる」の意味になる。","collocations":["seem inevitable","inevitable consequence","all but inevitable"]},"disproportionately":{"example2":"Small businesses were disproportionately affected by the sudden interest rate hikes.","exampleJa2":"中小企業は突然の利上げに不釣り合いなほど大きな影響を受けた。","origin":"dis(否定)+proportion(釣り合い)+ately→本来の割合と釣り合わない形で。格差の議論で頻出する副詞。","collocations":["disproportionately affected","disproportionately high","fall disproportionately on"]},"preparedness":{"example2":"The exercise tested the bank's preparedness for a major cyberattack.","exampleJa2":"その演習は大規模サイバー攻撃に対する銀行の備えを試すものだった。","origin":"prepare=ラテン語prae(前もって)+parare(整える)+ness→事前に整えておく状態。災害対策の文脈で頻出。","collocations":["disaster preparedness","emergency preparedness","state of preparedness"]},"tangible":{"example2":"Investors want tangible results before committing additional capital to the project.","exampleJa2":"投資家は追加資本を投じる前に目に見える成果を求めている。","origin":"ラテン語tangere(触れる)+ible(できる)→触れられるほど具体的な。会計の「有形資産(tangible assets)」でも頻出。","collocations":["tangible benefits","tangible assets","tangible results"]},"hazard":{"example2":"Poorly designed incentives can create a moral hazard for bankers.","exampleJa2":"設計の悪いインセンティブは銀行家にモラルハザードを生みかねない。","origin":"アラビア語az-zahr(サイコロ)が語源とされる。賭けの偶然→危険の意味へ。金融のmoral hazardで有名。","collocations":["moral hazard","health hazard","pose a hazard"]},"drastically":{"example2":"The central bank drastically cut interest rates to support the economy.","exampleJa2":"中央銀行は経済を支えるために金利を大幅に引き下げた。","origin":"ギリシャ語drastikos(効き目の強い)←dran(行う)→劇薬のように強力に作用するさま。drama(行うこと)と同語源。","collocations":["drastically reduce","drastically change","drastically different"]},"intensified":{"example2":"Competition among asset managers intensified as fees continued to fall.","exampleJa2":"手数料の低下が続く中、運用会社間の競争は激化した。","origin":"ラテン語in(中へ)+tensus(張られた)→内へ張り詰めて強度を増す。tension(緊張)、intense(強烈な)と同語源。","collocations":["intensified competition","intensified pressure","intensify efforts"]},"emphasis":{"example2":"The new CEO placed strong emphasis on long-term shareholder value.","exampleJa2":"新しいCEOは長期的な株主価値に強い重点を置いた。","origin":"ギリシャ語em(中に)+phainein(示す)→中にはっきり見せる→強調。phase、phenomenonと同語源の「見せる」仲間。","collocations":["place emphasis on","strong emphasis","shift the emphasis"]},"vulnerable":{"example2":"Highly leveraged firms are vulnerable to sudden changes in credit conditions.","exampleJa2":"高レバレッジの企業は信用環境の急変に対して脆弱だ。","origin":"ラテン語vulnus(傷)+able→傷を負わされうる状態。物理的にも精神的にも「攻撃に無防備」を表す。","collocations":["vulnerable to attack","vulnerable groups","leave someone vulnerable"]},"infrastructure":{"example2":"Pension funds increasingly allocate capital to infrastructure such as toll roads.","exampleJa2":"年金基金は有料道路などのインフラへの資本配分を増やしている。","origin":"ラテン語infra(下に)+structure(構造)→社会を下から支える構造物。道路・電力・通信などの基盤の総称。","collocations":["critical infrastructure","infrastructure investment","digital infrastructure"]},"proliferation":{"example2":"The proliferation of ETFs has given retail investors cheaper market access.","exampleJa2":"ETFの急増により個人投資家はより安価に市場へアクセスできるようになった。","origin":"ラテン語proles(子孫)+ferre(生む)→子を次々に生み増やすこと。核拡散(nuclear proliferation)でも頻出。","collocations":["nuclear proliferation","rapid proliferation","the proliferation of"]},"forethought":{"example2":"With careful forethought, the treasurer hedged currency exposure before the vote.","exampleJa2":"財務担当者は慎重な事前の熟慮により、投票前に為替リスクをヘッジしていた。","origin":"fore(前もって)+thought(考え)→前もって考えておくこと。foresight(先見)と同じ「fore=先」の発想で覚える。","collocations":["careful forethought","with forethought","lack of forethought"]},"unforeseen":{"example2":"The project budget included reserves for unforeseen costs and delays.","exampleJa2":"プロジェクト予算には想定外の費用や遅延に備えた予備費が含まれていた。","origin":"un(否定)+fore(前もって)+seen(見えた)→前もって見えていなかった。foresee(予見する)の否定形。","collocations":["unforeseen circumstances","unforeseen consequences","unforeseen expenses"]},"erosion":{"example2":"Persistent inflation caused a steady erosion of household purchasing power.","exampleJa2":"根強いインフレは家計の購買力を着実に低下させた。","origin":"ラテン語e(外へ)+rodere(かじる)→外から少しずつかじり取る→浸食。rodent(齧歯類)と同語源。","collocations":["soil erosion","erosion of trust","gradual erosion"]},"tacit":{"example2":"There was a tacit agreement among dealers not to undercut prices.","exampleJa2":"ディーラーの間には価格を下げ合わないという暗黙の合意があった。","origin":"ラテン語tacere(黙る)→黙っていても伝わる=暗黙の。taciturn(無口な)と同語源。tacit knowledge=暗黙知。","collocations":["tacit agreement","tacit approval","tacit knowledge"]},"codified":{"example2":"Best practices were codified into a formal compliance manual last year.","exampleJa2":"ベストプラクティスは昨年、正式なコンプライアンスマニュアルとして体系化された。","origin":"ラテン語codex(法典・書物)+fy(〜化する)→ばらばらの決まりを法典のように一つにまとめ上げること。","collocations":["codified into law","codified rules","formally codified"]},"displaced":{"example2":"Thousands of residents were displaced by the severe river flooding.","exampleJa2":"深刻な河川の氾濫により数千人の住民が住む場所を追われた。","origin":"dis(離れて)+place(場所)→本来の場所から引き離された。災害・紛争・技術変化で居場所を失う文脈で頻出。","collocations":["displaced workers","displaced persons","displaced by conflict"]},"prohibitively":{"example2":"Hedging every currency position proved prohibitively costly for the fund.","exampleJa2":"すべての通貨ポジションをヘッジするのはファンドにとって法外にコスト高だった。","origin":"prohibit=ラテン語pro(前で)+habere(持つ)→前に立ちはだかって差し止める→禁止レベルに高い、の意味へ。","collocations":["prohibitively expensive","prohibitively high","prohibitively costly"]},"exacerbates":{"example2":"Panic selling often exacerbates losses during periods of market stress.","exampleJa2":"パニック売りは市場ストレス時の損失をしばしば悪化させる。","origin":"ラテン語ex(強意)+acerbus(苦い・鋭い)→苦さを一段と増す→悪化させる。acerbic(辛辣な)と同語源。","collocations":["exacerbate the problem","exacerbate tensions","exacerbate inequality"]},"disparity":{"example2":"The pay disparity between executives and staff drew shareholder criticism.","exampleJa2":"経営陣と一般従業員の報酬格差は株主の批判を招いた。","origin":"ラテン語dis(否定)+par(等しい)→等しくない状態。parは債券の「パー(額面)」やゴルフのパーと同じ語。","collocations":["income disparity","wide disparity","regional disparities"]},"cohesion":{"example2":"Strong social cohesion helped the community recover from the disaster.","exampleJa2":"強い社会的結束がその地域社会の災害からの復興を支えた。","origin":"ラテン語co(共に)+haerere(くっつく)→互いにくっつき合ってまとまること。adhesive(接着剤)と同語源。","collocations":["social cohesion","team cohesion","lack of cohesion"]},"obsolescence":{"example2":"Planned obsolescence encourages consumers to replace devices more frequently.","exampleJa2":"計画的陳腐化は消費者により頻繁な機器の買い替えを促す。","origin":"ラテン語obsolescere(すたれていく)→徐々に使われなくなる過程。obsolete(時代遅れの)の名詞形。","collocations":["planned obsolescence","technological obsolescence","risk of obsolescence"]},"perpetual":{"example2":"The issuer offered perpetual bonds with no fixed maturity date.","exampleJa2":"その発行体は満期のない永久債を発行した。","origin":"ラテン語per(通して)+petere(求め進む)→途切れずに続いていく。金融では永久債(perpetual bond)で頻出。","collocations":["perpetual motion","perpetual bonds","perpetual cycle"]},"augments":{"example2":"The new analytics tool augments our research team's forecasting accuracy.","exampleJa2":"新しい分析ツールは私たちのリサーチチームの予測精度を補強する。","origin":"ラテン語augere(増やす)→既にあるものに付け加えて大きくする。auction(競り上げる)、augmented realityも同語源。","collocations":["augment income","augment capabilities","augmented reality"]},"supplanting":{"example2":"Passive index funds are steadily supplanting actively managed portfolios worldwide.","exampleJa2":"パッシブ型インデックスファンドは世界中でアクティブ運用を着実に置き換えつつある。","origin":"ラテン語sub(下から)+planta(足の裏)→相手の足元をすくって倒し、その座を奪うイメージ→取って代わる。","collocations":["supplant traditional methods","gradually supplanting","supplant a rival"]},"incrementally":{"example2":"The committee raised rates incrementally to avoid unsettling the markets.","exampleJa2":"委員会は市場を動揺させないよう段階的に金利を引き上げた。","origin":"ラテン語in(上に)+crescere(成長する)→少しずつ積み増していくさま。increase、crescendoと同語源。","collocations":["increase incrementally","improve incrementally","adjust incrementally"]},"turnover":{"example2":"The branch reduced staff turnover by improving pay and flexibility.","exampleJa2":"その支店は給与と働き方の柔軟性を改善して離職率を下げた。","origin":"turn(回る)+over→人や商品が回転して入れ替わるイメージ。英国では「売上高」、金融では「回転率」の意味も。","collocations":["staff turnover","high turnover rate","annual turnover"]},"scrutiny":{"example2":"Large mergers inevitably attract close scrutiny from antitrust regulators.","exampleJa2":"大型合併は必然的に独占禁止規制当局による厳密な調査を招く。","origin":"ラテン語scrutari(ガラクタの山をあさって探す)→隅々まで徹底的に調べること。under scrutinyの形で頻出。","collocations":["come under scrutiny","close scrutiny","public scrutiny"]},"intractable":{"example2":"Youth unemployment remains an intractable problem across southern Europe.","exampleJa2":"若年失業は南欧全体でいまだに解決困難な問題であり続けている。","origin":"ラテン語in(否定)+tractare(引く・扱う)→引っ張っても動かせない=手に負えない。tractor(牽引機)と同語源。","collocations":["intractable problem","intractable conflict","prove intractable"]},"bottlenecks":{"example2":"Supply chain bottlenecks pushed up input costs for manufacturers.","exampleJa2":"サプライチェーンのボトルネックは製造業者の投入コストを押し上げた。","origin":"bottle(瓶)+neck(首)→瓶の首のように急に細くなって流れが滞る場所、という比喩。工程管理の定番語。","collocations":["supply bottlenecks","remove bottlenecks","production bottleneck"]},"suppress":{"example2":"The government tried to suppress reports of the bank's losses.","exampleJa2":"政府はその銀行の損失に関する報道を抑え込もうとした。","origin":"ラテン語sub(下に)+premere(押す)→下へ押さえつける。press、pressure、oppressと同じ「押す」仲間。","collocations":["suppress inflation","suppress dissent","suppress demand"]},"precipitate":{"example2":"A single default could precipitate a wider crisis of confidence.","exampleJa2":"たった一件のデフォルトがより広範な信用不安を引き起こしかねない。","origin":"ラテン語prae(前へ)+caput(頭)→頭から真っ逆さまに落とす→急激に引き起こす。化学の「沈殿(させる)」も同じ語。","collocations":["precipitate a crisis","precipitate a collapse","precipitate change"]},"susceptible":{"example2":"Emerging markets are highly susceptible to shifts in dollar liquidity.","exampleJa2":"新興国市場はドル流動性の変化の影響を非常に受けやすい。","origin":"ラテン語sus(下から)+capere(受け取る)→下から受け入れてしまう=影響や害を受けやすい。captureと同語源。","collocations":["susceptible to infection","highly susceptible","susceptible to manipulation"]},"spillover":{"example2":"Tighter US monetary policy created spillover pressures on Asian currencies.","exampleJa2":"米国の金融引き締めはアジア通貨への波及圧力を生んだ。","origin":"spill(こぼれる)+over(越えて)→容器からあふれた液体が周囲へ広がるイメージ。経済の「波及効果」の定番語。","collocations":["spillover effects","regional spillover","positive spillovers"]},"depreciate":{"example2":"Most company cars depreciate rapidly within the first three years.","exampleJa2":"社用車の多くは最初の3年間で急速に価値が下がる。","origin":"ラテン語de(下に)+pretium(価格)→価格が下がる。通貨高・値上がりを表すappreciateの対義語として覚える。","collocations":["depreciate in value","the currency depreciates","depreciate against the dollar"]},"financialization":{"example2":"Critics argue financialization diverts talent away from productive industries.","exampleJa2":"批判者は、金融化が生産的な産業から人材を奪っていると主張する。","origin":"financial(金融の)+ization(〜化)→経済や生活全体が金融市場の論理に組み込まれていく過程を指す近年の造語。","collocations":["the financialization of housing","growing financialization","financialization of the economy"]},"speculative":{"example2":"The regulator warned banks about speculative lending to property developers.","exampleJa2":"規制当局は不動産開発業者への投機的な融資について銀行に警告した。","origin":"ラテン語specere(見る)→speculari(見張る・推測する)→確証なく見込みだけで動く=投機的。spectatorと同語源。","collocations":["speculative bubble","speculative investment","purely speculative"]},"counteract":{"example2":"The central bank intervened to counteract excessive currency volatility.","exampleJa2":"中央銀行は過度な為替変動を打ち消すために介入した。","origin":"counter(反対に)+act(働く)→反対方向に作用して相手の効果を打ち消す。counterattack(反撃)と同じ発想。","collocations":["counteract the effects","counteract inflation","help counteract"]},"expansionary":{"example2":"Expansionary monetary policy kept borrowing costs near record lows.","exampleJa2":"拡張的な金融政策は借入コストを過去最低水準近くに保った。","origin":"ラテン語ex(外へ)+pandere(広げる)+ary→外へ広げる性質の。財政・金融政策の「緩和的」を表す定番語。","collocations":["expansionary policy","expansionary fiscal stance","expansionary phase"]},"dilute":{"example2":"Issuing new shares will dilute the holdings of existing investors.","exampleJa2":"新株の発行は既存投資家の持ち分を希薄化させる。","origin":"ラテン語dis(離れて)+luere(洗い流す)→水で洗い流して薄める。株式の「希薄化」として金融で頻出。","collocations":["dilute shareholder value","dilute the impact","diluted earnings"]},"indispensable":{"example2":"Reliable market data is indispensable for accurate portfolio risk management.","exampleJa2":"信頼できる市場データは正確なポートフォリオのリスク管理に不可欠だ。","origin":"in(否定)+dis(分けて)+pendere(量り渡す)+able→切り分けて手放すことができない=欠かせない。","collocations":["indispensable tool","absolutely indispensable","indispensable to success"]},"anchors":{"example2":"A shared sense of mission anchors the team during rapid change.","exampleJa2":"共有された使命感は、急激な変化の中でチームをしっかり支える。","origin":"ギリシャ語ankyra(錨)→船を流されないよう固定する錨のように、動かないよりどころとなるイメージ。","collocations":["anchor expectations","anchor the team","firmly anchored"]},"unilateral":{"example2":"The supplier made a unilateral change to the contract terms.","exampleJa2":"その供給業者は契約条件を一方的に変更した。","origin":"ラテン語uni(1つ)+latus(側面)→一方の側だけの。bilateral(二国間の)、multilateral(多国間の)とセットで覚える。","collocations":["unilateral action","unilateral decision","unilateral withdrawal"]},"resonates":{"example2":"The fund's sustainability message resonates strongly with younger clients.","exampleJa2":"そのファンドのサステナビリティのメッセージは若い顧客層の心に強く響いている。","origin":"ラテン語re(再び)+sonare(鳴る)→音が鳴り返って共鳴する。sound、sonicと同語源。心に「響く」の比喩で頻出。","collocations":["resonate with audiences","resonate deeply","continue to resonate"]},"consensus":{"example2":"Market consensus expects two further rate cuts this year.","exampleJa2":"市場のコンセンサスは年内にあと2回の利下げを見込んでいる。","origin":"ラテン語con(共に)+sentire(感じる)→皆が同じように感じ合うこと。sense、sentiment(市場心理)と同語源。","collocations":["reach a consensus","broad consensus","consensus forecast"]},"empirical":{"example2":"Their pricing model rests on decades of empirical market data.","exampleJa2":"彼らの価格モデルは数十年分の実証的な市場データに基づいている。","origin":"ギリシャ語empeiria(経験)→理論や推測でなく、観察・実験・経験に基づく。empiricism(経験論)の形容詞形。","collocations":["empirical evidence","empirical research","empirical data"]},"intricate":{"example2":"Auditors struggled to untangle the firm's intricate ownership structure.","exampleJa2":"監査人はその企業の入り組んだ資本構造の解明に苦労した。","origin":"ラテン語in(中に)+tricae(もつれ)→もつれの中にあって複雑な。extricate(もつれから救い出す)と対で覚える。","collocations":["intricate details","intricate design","intricate network"]},"detrimental":{"example2":"Prolonged uncertainty is detrimental to business investment and hiring.","exampleJa2":"長引く不確実性は企業の投資と雇用にとって有害である。","origin":"ラテン語de(離れて)+terere(すり減らす)→すり減らして損なう。detriment(損害)+al。harmfulの硬い言い換え。","collocations":["detrimental effect","detrimental to health","prove detrimental"]},"cultivate":{"example2":"Private bankers cultivate long-term relationships with wealthy client families.","exampleJa2":"プライベートバンカーは富裕層の顧客一族と長期的な関係を育む。","origin":"ラテン語colere(耕す)→畑を耕すように時間をかけて関係や能力を育てるイメージ。culture(文化・耕作)と同語源。","collocations":["cultivate relationships","cultivate skills","cultivate an image"]},"curated":{"example2":"The platform offers a curated selection of low-cost index funds.","exampleJa2":"そのプラットフォームは厳選された低コストのインデックスファンドを提供している。","origin":"ラテン語cura(世話)→curator(美術館の学芸員)。学芸員が展示品を吟味して選ぶように厳選するイメージ。","collocations":["carefully curated","curated content","curated selection"]},"ramifications":{"example2":"The tax reform has significant ramifications for cross-border investors.","exampleJa2":"その税制改革は国境を越えて投資する投資家に重大な派生的影響を及ぼす。","origin":"ラテン語ramus(枝)→枝分かれが原義。一つの出来事から木の枝のように広がっていく影響を表す。","collocations":["legal ramifications","far-reaching ramifications","political ramifications"]},"diminished":{"example2":"The scandal left the firm with diminished credibility among clients.","exampleJa2":"不祥事によりその企業は顧客からの信頼が低下した状態に陥った。","origin":"ラテン語di(離れて)+minuere(小さくする)→削り取って小さくなった。minus、minute(微小な)と同語源。","collocations":["diminished capacity","diminished returns","greatly diminished"]},"democratized":{"example2":"Low-cost brokerages have democratized stock investing for ordinary households.","exampleJa2":"低コストの証券会社は一般家庭にも株式投資を広く開放した。","origin":"ギリシャ語demos(民衆)+kratos(支配)→民衆のものにする→特権層の独占物を誰でも使えるようにする。","collocations":["democratize access","democratize finance","democratize information"]},"marginalized":{"example2":"The program offers microloans to marginalized groups excluded from banking.","exampleJa2":"そのプログラムは銀行取引から排除された疎外層に少額融資を提供する。","origin":"ラテン語margo(縁・余白)→ページの余白(margin)に追いやるイメージ→社会の中心から周縁へ押しやられた。","collocations":["marginalized communities","socially marginalized","feel marginalized"]},"solidarity":{"example2":"European leaders expressed solidarity with the flood-stricken coastal region.","exampleJa2":"欧州の指導者たちは洪水被害を受けた沿岸地域との連帯を表明した。","origin":"ラテン語solidus(固い)→固く一つにまとまること。solid(固体)と同語源。労働運動・国際政治で頻出。","collocations":["show solidarity","in solidarity with","a sense of solidarity"]},"insidious":{"example2":"Inflation acts as an insidious tax on household savings.","exampleJa2":"インフレは家計の貯蓄に対して知らぬ間に進行する税金のように働く。","origin":"ラテン語insidiae(待ち伏せ)=in(中に)+sedere(座る)→物陰に潜んで待つ→気づかぬうちに害を及ぼす。","collocations":["insidious effects","insidious threat","slow and insidious"]},"amplification":{"example2":"The echo chamber caused rapid amplification of the false rumor.","exampleJa2":"エコーチェンバーがその誤った噂の急速な増幅を招いた。","origin":"ラテン語amplus(広い)+facere(作る)→広く大きくすること。音響機器のアンプ(amplifier)と同じ仲間。","collocations":["signal amplification","algorithmic amplification","amplification of risk"]},"provocative":{"example2":"His provocative remarks about the merger unsettled the board members.","exampleJa2":"合併に関する彼の挑発的な発言は取締役たちを動揺させた。","origin":"ラテン語pro(前へ)+vocare(呼ぶ)→相手の反応を呼び起こす=挑発的な。voice、vocal、advocateと同語源。","collocations":["provocative statement","deliberately provocative","provocative question"]},"predisposition":{"example2":"Investors often show a predisposition toward stocks from their home country.","exampleJa2":"投資家はしばしば自国の株式を好む傾向を示す。","origin":"ラテン語prae(前もって)+dis(配して)+ponere(置く)→あらかじめ心や体がその方向に置かれている=素因・傾向。","collocations":["genetic predisposition","a predisposition to","natural predisposition"]},"compulsive":{"example2":"His compulsive gambling eventually destroyed both career and family.","exampleJa2":"彼の強迫的なギャンブルは最終的にキャリアと家庭の両方を壊した。","origin":"ラテン語com(強意)+pellere(駆り立てる)→内側から駆り立てられてやめられない。compel(強いる)の形容詞形。","collocations":["compulsive behavior","compulsive gambling","compulsive buying"]},"pragmatic":{"example2":"Investors took a pragmatic view, focusing on cash flow over promises.","exampleJa2":"投資家は約束よりもキャッシュフローを重視する現実的な見方を取った。","origin":"ギリシャ語pragma(行為・実務)→理屈や理想より実際の行動と結果を重視する。practice(実践)と同語源。","collocations":["pragmatic approach","pragmatic solution","be pragmatic about"]},"paramount":{"example2":"Protecting client data is paramount for any modern financial institution.","exampleJa2":"顧客データの保護は現代のあらゆる金融機関にとって最重要事項だ。","origin":"古フランス語par(〜によって)+amont(上へ)→何よりも上位にある=最重要。山のロゴの映画会社名でもおなじみ。","collocations":["of paramount importance","paramount concern","safety is paramount"]},"temporal":{"example2":"The model captures temporal patterns in high-frequency trading data.","exampleJa2":"そのモデルは高頻度取引データに含まれる時間的パターンを捉える。","origin":"ラテン語tempus(時間)→時間に関する。tempo(テンポ)、temporary(一時的な)、contemporary(同時代の)と同語源。","collocations":["temporal patterns","temporal resolution","spatial and temporal"]},"oppressive":{"example2":"The office's oppressive atmosphere drove several talented analysts away.","exampleJa2":"その職場の息苦しい雰囲気は何人もの有能なアナリストを去らせた。","origin":"ラテン語ob(〜に向かって)+premere(押す)→上から重く押さえつける。press、suppressと同じ「押す」仲間。","collocations":["oppressive regime","oppressive heat","oppressive atmosphere"]},"irrefutable":{"example2":"The auditors presented irrefutable evidence of systematic accounting fraud.","exampleJa2":"監査人は組織的な会計不正の反論できない証拠を提示した。","origin":"ラテン語ir(否定)+refutare(打ち返す・論破する)→論破し返すことが不可能な=否定しようのない。","collocations":["irrefutable evidence","irrefutable proof","irrefutable logic"]},"embezzlement":{"example2":"The trustee was imprisoned for embezzlement of pension fund assets.","exampleJa2":"その受託者は年金基金資産の横領罪で収監された。","origin":"古フランス語besillier(奪う・損なう)に由来。「信頼されて預かった金をこっそり抜き取る」犯罪の定番語。","collocations":["embezzlement charges","corporate embezzlement","embezzlement of funds"]},"meticulously":{"example2":"The compliance team meticulously documented every step of the transaction.","exampleJa2":"コンプライアンスチームは取引のすべての手順を綿密に記録した。","origin":"ラテン語metus(恐れ)が語源。「ミスを恐れるあまり細部まで気を配る」イメージで覚えると忘れにくい。","collocations":["meticulously planned","meticulously documented","meticulously maintained"]},"quandary":{"example2":"She faced a quandary between accepting the promotion or relocating abroad.","exampleJa2":"彼女は昇進を受けるか海外へ転居するかの板挟みに直面した。","origin":"語源は不詳だがラテン語quando(いつ)由来説がある。「どうすべきか」と決めかねて立ち尽くす状態のイメージ。","collocations":["in a quandary","face a quandary","ethical quandary"]},"advocated":{"example2":"The economist advocated gradual tightening rather than aggressive rate hikes.","exampleJa2":"そのエコノミストは急激な利上げよりも段階的な引き締めを支持した。","origin":"ラテン語ad(〜のもとへ)+vocare(呼ぶ)→味方として呼び出す→擁護する。advocate(擁護者・弁護士)の動詞形。","collocations":["advocate for change","strongly advocated","advocate a policy"]},"transgression":{"example2":"The trader's transgression cost the bank millions in regulatory fines.","exampleJa2":"そのトレーダーの違反行為は銀行に数百万ドルの制裁金という代償をもたらした。","origin":"ラテン語trans(越えて)+gradi(歩く)→越えてはならない一線を踏み越えること。progress、gradeと同語源。","collocations":["serious transgression","moral transgression","past transgressions"]},"reverberate":{"example2":"The bank's collapse will reverberate across global financial markets.","exampleJa2":"その銀行の破綻は世界の金融市場全体に波紋を広げるだろう。","origin":"ラテン語re(再び)+verberare(打つ)→打った音が繰り返し跳ね返る→出来事の影響が長く響き渡る。","collocations":["reverberate through","reverberate around the world","still reverberating"]},"complicit":{"example2":"Several managers were complicit in concealing the trading losses.","exampleJa2":"複数の管理職が取引損失の隠蔽に加担していた。","origin":"ラテン語com(共に)+plicare(折り重ねる)→悪事に折り重なるように関与する。accomplice(共犯者)と同語源。","collocations":["complicit in the fraud","become complicit","silently complicit"]},"siphoned":{"example2":"Auditors discovered funds had been siphoned into offshore shell companies.","exampleJa2":"監査人は資金がオフショアのペーパーカンパニーに吸い上げられていたことを発見した。","origin":"ギリシャ語siphon(管)が語源。管で液体をこっそり抜き取るイメージから「資金の不正流用」の意味に発展。","collocations":["siphon off funds","siphon money from","siphoned into accounts"]},"juxtaposition":{"example2":"The report's juxtaposition of forecasts and actual results was revealing.","exampleJa2":"予測と実績を並置したそのレポートは多くを物語っていた。","origin":"ラテン語juxta(すぐそばに)+position(置くこと)→対比効果を狙って二つのものを並べて置くこと。","collocations":["in juxtaposition with","striking juxtaposition","the juxtaposition of"]},"monolithic":{"example2":"The bank replaced its monolithic legacy system with flexible microservices.","exampleJa2":"その銀行は一枚岩の旧式システムを柔軟なマイクロサービスに置き換えた。","origin":"ギリシャ語monos(単一の)+lithos(石)→一つの巨大な岩→巨大で画一的、分割できない。IT分野でも頻出。","collocations":["monolithic structure","monolithic system","far from monolithic"]},"constellations":{"example2":"New constellations of fintech startups are reshaping the payments industry.","exampleJa2":"フィンテック新興企業の新たな一群が決済業界を再編しつつある。","origin":"ラテン語con(共に)+stella(星)→星が集まったもの=星座。比喩的に「関連し合う物事のまとまり」を表す。","collocations":["a constellation of factors","constellations of stars","a constellation of symptoms"]},"righteous":{"example2":"He spoke with righteous anger about the treatment of small depositors.","exampleJa2":"彼は小口預金者の扱いについて正義の怒りを込めて語った。","origin":"古英語riht(正しい)+wis(あり方)→道義的に正しいあり方の。righteous anger(義憤)の形で頻出する。","collocations":["righteous anger","righteous indignation","self-righteous"]},"treacherous":{"example2":"Icy roads made the morning commute treacherous for many drivers.","exampleJa2":"凍結した道路は多くのドライバーにとって朝の通勤を危険なものにした。","origin":"古フランス語trechier(だます)→人を裏切る、転じて「見た目より危険な」。道路や海など自然にも使う。","collocations":["treacherous conditions","treacherous waters","treacherous terrain"]},"irreducible":{"example2":"The model contains an irreducible level of uncertainty about defaults.","exampleJa2":"そのモデルにはデフォルトに関するこれ以上減らせない不確実性が残る。","origin":"ラテン語ir(否定)+re(元へ)+ducere(導く)→それ以上小さく還元できない。reduce(減らす)の否定形容詞。","collocations":["irreducible complexity","irreducible minimum","irreducible uncertainty"]},"consequential":{"example2":"The Fed's decision proved consequential for emerging market currencies.","exampleJa2":"FRBの決定は新興国通貨にとって重大な意味を持つことになった。","origin":"ラテン語con(共に)+sequi(後に続く)→後に続く結果(consequence)が大きい=重大な。sequence(連続)と同語源。","collocations":["highly consequential","consequential decision","consequential damages"]},"supremacy":{"example2":"The dollar's supremacy in global trade faces growing challenges.","exampleJa2":"世界貿易におけるドルの覇権は増大する挑戦に直面している。","origin":"ラテン語supremus(最上の、superの最上級)→最も上に立つ状態=覇権。Supreme Court(最高裁)のsupremeから。","collocations":["air supremacy","technological supremacy","challenge someone's supremacy"]},"confers":{"example2":"Board membership confers both prestige and serious legal responsibilities.","exampleJa2":"取締役への就任は名声と重い法的責任の両方をもたらす。","origin":"ラテン語con(共に)+ferre(運ぶ)→運んで手渡す→授与する。transfer、offerと同じ「運ぶ」仲間。","collocations":["confer a degree","confer rights","confer an advantage"]},"tectonic":{"example2":"Aging demographics are driving tectonic shifts in global capital flows.","exampleJa2":"人口の高齢化は世界の資本フローに地殻変動級の変化をもたらしている。","origin":"ギリシャ語tekton(大工・建築者)→地殻の構造に関する。プレートが動くような「根本を揺るがす変化」の比喩に。","collocations":["tectonic plates","tectonic shift","tectonic changes"]},"subsidies":{"example2":"Generous solar subsidies accelerated the adoption of renewable energy.","exampleJa2":"手厚い太陽光補助金は再生可能エネルギーの普及を加速させた。","origin":"ラテン語subsidium(予備軍・支援)=sub(下に)+sedere(座る)→後方に控えて支える存在→支援金の意味へ。","collocations":["government subsidies","cut subsidies","agricultural subsidies"]},"orthodoxy":{"example2":"Negative interest rates once defied all central banking orthodoxy.","exampleJa2":"マイナス金利はかつて中央銀行のあらゆる定説に反するものだった。","origin":"ギリシャ語orthos(正しい)+doxa(考え・教義)→「正しいとされる教え」=正統派の考え。orthodontics(歯列矯正)も同語源。","collocations":["economic orthodoxy","challenge orthodoxy","prevailing orthodoxy"]},"imperatives":{"example2":"Cost reduction and digital transformation became strategic imperatives for insurers.","exampleJa2":"コスト削減とデジタル変革は保険会社にとって戦略上の必須事項となった。","origin":"ラテン語imperare(命令する)→命令されたかのように必ず果たすべきこと。emperor(皇帝)、empireと同語源。","collocations":["strategic imperative","moral imperative","economic imperatives"]},"stringent":{"example2":"Banks must hold more capital under the stringent new rules.","exampleJa2":"銀行は厳格な新規則の下でより多くの資本を保有しなければならない。","origin":"ラテン語stringere(きつく縛る)→縛り上げるように厳しい。strict(厳格な)、strain(緊張)と同語源。","collocations":["stringent regulations","stringent requirements","stringent standards"]},"lithography":{"example2":"TSMC relies on Dutch lithography equipment for its cutting-edge chips.","exampleJa2":"TSMCは最先端チップの製造をオランダ製リソグラフィー装置に依存している。","origin":"ギリシャ語lithos(石)+graphein(書く)→石版印刷が原義。転じて光で回路パターンを「印刷」する半導体技術。","collocations":["EUV lithography","lithography equipment","advanced lithography"]},"ingenuity":{"example2":"Financial ingenuity turned illiquid loans into widely traded securities.","exampleJa2":"金融の創意工夫は流動性の低い貸付を広く取引される証券に変えた。","origin":"ラテン語ingenium(生まれつきの才能)=in(内に)+gignere(生む)→内に宿る独創力。engine(エンジン)と同語源。","collocations":["human ingenuity","engineering ingenuity","show great ingenuity"]},"indigenous":{"example2":"The kangaroo is indigenous to Australia and found nowhere else naturally.","exampleJa2":"カンガルーはオーストラリア固有で、自然には他のどこにも生息していない。","origin":"ラテン語indu(中に)+gignere(生まれる)→その土地の中で生まれた=固有の・先住の。産業政策では「自国産の」。","collocations":["indigenous peoples","indigenous species","indigenous technology"]},"precarious":{"example2":"Many gig workers live in a precarious financial situation.","exampleJa2":"多くのギグワーカーは不安定な経済状況の中で暮らしている。","origin":"ラテン語precarius(懇願で得た)←prex(祈り)→他人の好意頼みで当てにならない→不安定な。prayerと同語源。","collocations":["precarious position","precarious balance","precarious employment"]},"catastrophic":{"example2":"The uninsured losses from the earthquake were financially catastrophic.","exampleJa2":"地震による無保険の損失は財務的に壊滅的なものだった。","origin":"ギリシャ語kata(下へ)+strephein(ひっくり返す)→下へ覆される=大惨事の。劇の結末の「破局」が原義。","collocations":["catastrophic failure","catastrophic losses","catastrophic consequences"]},"coercion":{"example2":"The contract was signed under coercion and later ruled invalid.","exampleJa2":"その契約は強制の下で署名され、後に無効と判断された。","origin":"ラテン語co(共に)+arcere(閉じ込める)→囲い込んで逃げ場をなくし、無理強いすること。力や脅しによる強制。","collocations":["economic coercion","under coercion","coercion and intimidation"]},"paralyze":{"example2":"A prolonged strike could paralyze the country's port operations.","exampleJa2":"長期化するストライキは国の港湾業務を麻痺させかねない。","origin":"ギリシャ語para(側で)+lyein(緩める)→体の片側が緩んで動かなくなる→麻痺させる。組織や機能の停止にも使う。","collocations":["paralyzed by fear","paralyze the economy","paralyze decision-making"]},"bolster":{"example2":"Strong earnings helped bolster the case for holding the stock.","exampleJa2":"好決算はその株を保有し続ける根拠を補強した。","origin":"古英語で「長枕・詰め物」が原義→下から支えるクッションのイメージ→支えて強化するの意味に発展。","collocations":["bolster confidence","bolster the economy","bolster defenses"]},"underpin":{"example2":"Sound governance and transparency underpin investor trust in markets.","exampleJa2":"健全なガバナンスと透明性が市場に対する投資家の信頼を支えている。","origin":"under(下に)+pin(留める)→建物の基礎を下から補強する工法が原義。目に見えない土台として支えるイメージ。","collocations":["underpin growth","underpin the economy","underpinned by evidence"]},"instantaneously":{"example2":"The payment was settled instantaneously across both banks' ledgers.","exampleJa2":"その決済は両行の台帳で瞬時に処理された。","origin":"ラテン語 instans(すぐそばに立つ)由来。in(上に)+stare(立つ)→「その瞬間に存在する」。時間の一点に立つイメージから「瞬時に」。","collocations":["respond instantaneously","update instantaneously"]},"cognitively":{"example2":"Traders who are cognitively fatigued tend to make poorer decisions.","exampleJa2":"認知的に疲労したトレーダーは判断を誤りやすい。","origin":"ラテン語 cognoscere(知る)由来。co(共に)+gnoscere(知る)→認知。副詞化 -ly で「認知的に」。","collocations":["cognitively demanding","cognitively impaired"]},"prerequisites":{"example2":"Meeting the capital prerequisites is essential before launching the fund.","exampleJa2":"ファンド立ち上げ前に資本要件を満たすことが不可欠だ。","origin":"ラテン語 pre(前に)+requirere(求める)→「前もって求められるもの」。requisite(必要なもの)に接頭辞 pre- が付いた形。","collocations":["meet the prerequisites","essential prerequisites"]},"semi-autonomous":{"example2":"The desk runs as a semi-autonomous unit within the investment division.","exampleJa2":"そのデスクは投資部門内の半自律的なユニットとして運営されている。","origin":"semi(半分)+autonomous(自律的)。ギリシャ語 autos(自己)+nomos(法)→自ら法を持つ。半分だけ自ら統治する、が語源イメージ。","collocations":["semi-autonomous unit","semi-autonomous region"]},"decentralized":{"example2":"Decentralized finance lets users trade assets without any intermediary bank.","exampleJa2":"分散型金融ではユーザーが仲介銀行なしで資産を取引できる。","origin":"de(除く)+central(中心)+ize(化する)→「中心から離す」。中央の一点に集めた権限をばらすイメージ。","collocations":["decentralized system","decentralized network"]},"invertebrates":{"example2":"Marine invertebrates make up the vast majority of ocean biodiversity.","exampleJa2":"海洋無脊椎動物は海の生物多様性の大半を占める。","origin":"ラテン語 in(否定)+vertebra(脊椎)→「背骨がない」。vertebra は vertere(回す)から、体を曲げる関節骨の意。","collocations":["marine invertebrates","soft-bodied invertebrates"]},"episodic-like memory":{"example2":"Some birds display episodic-like memory, recalling where and when they hid seeds.","exampleJa2":"一部の鳥は、いつどこに種を隠したか思い出すエピソード的記憶を示す。","origin":"ギリシャ語 epeisodion(挿話)由来の episodic に -like を付け「エピソード記憶に似た」。動物研究で人の記憶と区別する用語。","collocations":["episodic-like memory","show episodic-like memory"]},"markedly":{"example2":"Trading volumes rose markedly after the central bank cut interest rates.","exampleJa2":"中央銀行の利下げ後、取引高は著しく増加した。","origin":"mark(印を付ける)+ed+ly。「はっきり印が付くほど」→誰の目にも際立つ変化の副詞。","collocations":["improve markedly","differ markedly"]},"hallmark":{"example2":"Transparent reporting is a hallmark of a trustworthy asset manager.","exampleJa2":"透明性の高い報告は信頼できる運用会社の特徴だ。","origin":"ロンドンの Goldsmiths' Hall で金銀の純度を保証した刻印が語源。hall(会館)+mark(刻印)→品質保証の印、転じて「特徴」。","collocations":["a hallmark of quality","bear the hallmark"]},"intrinsic":{"example2":"Analysts debated whether the stock traded below its intrinsic value.","exampleJa2":"アナリストはその株が本質的価値を下回っているか議論した。","origin":"ラテン語 intrinsecus(内側へ)由来。intra(内に)+secus(に沿って)→「内側に備わった」本質的な、の意。","collocations":["intrinsic value","intrinsic motivation"]},"diverged":{"example2":"The two firms' strategies diverged sharply after the merger fell through.","exampleJa2":"合併が破談になった後、両社の戦略は大きく分岐した。","origin":"ラテン語 dis(離れて)+vergere(傾く)→「別々の方向へ傾く」。一点から離れて広がるイメージ。","collocations":["diverge sharply","opinions diverge"]},"convergent":{"example2":"The two economies showed convergent growth rates over the decade.","exampleJa2":"両経済はこの10年で収束的な成長率を示した。","origin":"ラテン語 con(共に)+vergere(傾く)→「共に一点へ傾く」。別々のものが一つに集まるイメージ。","collocations":["convergent evolution","convergent trends"]},"catalyzed":{"example2":"The regulatory reform catalyzed a wave of fintech startups.","exampleJa2":"その規制改革はフィンテック新興企業の波を促進した。","origin":"ギリシャ語 katalysis(分解)由来。化学の触媒 catalyst の動詞形で、自らは変わらず反応を加速する→「促進する」。","collocations":["catalyzed change","catalyzed growth"]},"substrate-independence":{"example2":"Substrate-independence implies an algorithm runs the same on any hardware.","exampleJa2":"基質非依存性は、アルゴリズムがどんなハードでも同じに動くことを意味する。","origin":"ラテン語 sub(下)+stratum(敷いたもの)→土台。それに依存しない(independence)こと。土台の素材を問わない、が核。","collocations":["substrate-independence of computation","argue for substrate-independence"]},"contentious":{"example2":"Executive pay remains a contentious issue at the annual shareholder meeting.","exampleJa2":"役員報酬は年次株主総会で依然として論争的な問題だ。","origin":"ラテン語 contendere(争う)由来。con(強意)+tendere(引っ張る)→引っ張り合う=争う。議論を呼ぶ、の意。","collocations":["contentious issue","contentious debate"]},"toying with":{"example2":"The board is toying with the idea of spinning off its retail arm.","exampleJa2":"取締役会は小売部門を分離する案を検討し始めている。","origin":"toy(おもちゃ=もてあそぶ)+with。決めきらずアイデアを手の中で転がして遊ぶイメージ→「軽く検討する」。","collocations":["toying with the idea","toying with a plan"]},"breathtaking":{"example2":"The startup posted breathtaking revenue growth in its first fiscal year.","exampleJa2":"その新興企業は初年度に息をのむような収益成長を記録した。","origin":"breath(息)+taking(奪う)→「息を奪うほど」。あまりの見事さに呼吸を忘れる、が直訳イメージ。","collocations":["breathtaking view","breathtaking pace"]},"logistics":{"example2":"The logistics of settling cross-border trades require careful coordination.","exampleJa2":"国境をまたぐ取引の決済は綿密な段取りを要する。","origin":"ギリシャ語 logistikos(計算に長けた)由来。軍隊の補給計算から発展し、物流・段取りの意に。","collocations":["logistics of the operation","handle logistics"]},"exorbitantly":{"example2":"The fund charged exorbitantly high management fees relative to peers.","exampleJa2":"そのファンドは同業に比べて法外に高い運用手数料を取っていた。","origin":"ラテン語 ex(外へ)+orbita(軌道)→「軌道を外れて」。常識の範囲を大きく逸脱するほど、が語源。","collocations":["exorbitantly priced","exorbitantly expensive"]},"seasoned":{"example2":"A seasoned portfolio manager stays calm during market turbulence.","exampleJa2":"経験豊富なポートフォリオマネジャーは市場の混乱時も冷静を保つ。","origin":"season(季節)を経る=料理を「味付けする」から。多くの季節を過ごし十分に熟した→「経験豊富な」。","collocations":["seasoned professional","seasoned investor"]},"designated":{"example2":"Funds must be held in a designated segregated client account.","exampleJa2":"資金は指定された分別管理の顧客口座に保管しなければならない。","origin":"ラテン語 de(下に)+signare(印を付ける)→「印を付けて指し示す」。特定目的に印を付け割り当てる、の意。","collocations":["designated area","designated account"]},"daunting":{"example2":"Entering a saturated market can be a daunting prospect for new firms.","exampleJa2":"飽和した市場への参入は新規企業にとって気後れする見通しだ。","origin":"古仏語 danter(手なずける、屈服させる)由来。相手をひるませる→「気後れさせるような」。","collocations":["daunting task","daunting challenge"]},"calving":{"example2":"The documentary showed a glacier calving into the frigid sea.","exampleJa2":"そのドキュメンタリーは氷河が凍てつく海へ崩落する様子を映した。","origin":"calf(子牛)から。氷河が塊を「産み落とす」ように分離するイメージで「崩落する」。","collocations":["glacier calving","calving front"]},"jagged":{"example2":"The stock's jagged price chart reflected weeks of erratic trading.","exampleJa2":"その株のギザギザの価格チャートは数週間の不安定な取引を映していた。","origin":"中英語 jag(ギザギザの切れ込み)+ed。鋸歯状に尖った縁を表す。","collocations":["jagged edges","jagged terrain"]},"windswept":{"example2":"The windswept moorland offered no shelter from the biting cold.","exampleJa2":"吹きさらしの荒野には身を切る寒さから逃れる場所がなかった。","origin":"wind(風)+swept(sw​eepの過去分詞、掃かれた)→「風に掃かれた」。風がなでつけた様子。","collocations":["windswept coast","windswept plains"]},"ferocious":{"example2":"The two banks engaged in ferocious competition for retail customers.","exampleJa2":"両行は個人顧客をめぐって猛烈な競争を繰り広げた。","origin":"ラテン語 ferox(獰猛な)由来。ferus(野生の)から。野獣のように激しい、が核。","collocations":["ferocious competition","ferocious appetite"]},"funiculars":{"example2":"The hillside resort connects its levels with two vintage funiculars.","exampleJa2":"その丘の上のリゾートは2台の古いケーブルカーで各階層を結んでいる。","origin":"ラテン語 funiculus(細い綱)由来。funis(綱)の指小形。綱で引く鉄道→ケーブルカー。","collocations":["ride the funicular","century-old funiculars"]},"panoramic":{"example2":"The report gave a panoramic overview of the global bond market.","exampleJa2":"そのレポートは世界の債券市場を全景的に概観していた。","origin":"ギリシャ語 pan(すべて)+horama(眺め)→「すべてを見渡す」。19世紀の全景画 panorama から。","collocations":["panoramic view","panoramic overview"]},"counterpoint":{"example2":"Emerging-market bonds served as a counterpoint to the equity-heavy portfolio.","exampleJa2":"新興国債券は株式偏重のポートフォリオへの対比として機能した。","origin":"音楽用語 counter(対する)+point(音符 punctum)→独立した旋律の対位法。転じて「引き立てる対比」。","collocations":["serve as a counterpoint","provide a counterpoint"]},"itinerary":{"example2":"The roadshow itinerary took the executives to six financial hubs.","exampleJa2":"そのロードショーの旅程は経営陣を6つの金融拠点へ連れて行った。","origin":"ラテン語 iter(旅、道)由来。iterare(旅する)から。旅の道筋を記したもの→「旅程」。","collocations":["travel itinerary","detailed itinerary"]},"reinvigorated":{"example2":"The rate cut reinvigorated a sluggish housing market almost overnight.","exampleJa2":"その利下げは低迷していた住宅市場をほぼ一夜にして再活性化した。","origin":"re(再び)+in(中へ)+vigor(活力 ラテン語 vigere 元気である)→「再び活力を注ぐ」。","collocations":["reinvigorate the economy","reinvigorate interest"]},"culminates":{"example2":"The due diligence process culminates in a final investment decision.","exampleJa2":"デューデリジェンスの過程は最終的な投資判断で頂点に達する。","origin":"ラテン語 culmen(頂上)由来。天文で天体が最高点に達する意から、「頂点・集大成に達する」。","collocations":["culminate in","culminate with"]},"derail":{"example2":"A sudden liquidity crunch could derail the entire acquisition.","exampleJa2":"突然の流動性逼迫は買収全体を頓挫させかねない。","origin":"de(離れる)+rail(レール)→「線路から外れる」。列車の脱線が転じて、計画が「頓挫する」。","collocations":["derail the plan","derail negotiations"]},"permanently shadowed":{"example2":"Permanently shadowed regions of the moon are prime targets for ice mining.","exampleJa2":"月の永久影の領域は氷採掘の有力な標的だ。","origin":"permanent(ラテン語 per 通して+manere 留まる→ずっと留まる)+shadowed(影に覆われた)。ずっと影のまま、の意。","collocations":["permanently shadowed craters","permanently shadowed regions"]},"pivotal":{"example2":"The quarterly earnings call proved pivotal to the stock's recovery.","exampleJa2":"四半期決算説明会はその株の回復に極めて重要だった。","origin":"pivot(回転軸 古仏語)+al。すべてがその軸を中心に回る→「中枢的で極めて重要な」。","collocations":["pivotal role","pivotal moment"]},"propellant":{"example2":"Rising propellant costs squeezed margins for the launch provider.","exampleJa2":"推進剤コストの上昇は打ち上げ事業者の利益率を圧迫した。","origin":"ラテン語 pro(前へ)+pellere(押す)→propel(推進する)+ant(するもの)。前へ押し出す物質。","collocations":["rocket propellant","solid propellant"]},"hinged on":{"example2":"The deal's approval hinged on regulators clearing the antitrust review.","exampleJa2":"その取引の承認は当局が反トラスト審査を通すかにかかっていた。","origin":"hinge(蝶番)+on。扉が蝶番を軸に動くように、物事が一点に「かかっている」イメージ。","collocations":["hinge on the outcome","success hinged on"]},"autonomous":{"example2":"The trading system operates autonomously within preset risk limits.","exampleJa2":"その取引システムは設定されたリスク上限内で自律的に稼働する。","origin":"ギリシャ語 autos(自己)+nomos(法)→「自ら法を持つ」。自分で自分を統治する→自律的。","collocations":["autonomous vehicle","autonomous system"]},"cornerstone":{"example2":"Diversification is the cornerstone of prudent portfolio construction.","exampleJa2":"分散投資は堅実なポートフォリオ構築の基盤だ。","origin":"corner(隅)+stone(石)。建物の基礎の隅に据える礎石から、「土台となる最重要要素」。","collocations":["cornerstone of the strategy","lay the cornerstone"]},"durability":{"example2":"The bond's appeal lay in the durability of its coupon payments.","exampleJa2":"その債券の魅力はクーポン支払いの持続性にあった。","origin":"ラテン語 durare(続く、硬くなる)由来。durus(硬い)から。硬く長持ちする性質→「耐久性」。","collocations":["long-term durability","durability of the system"]},"escalating":{"example2":"Escalating compliance costs are reshaping the small-brokerage landscape.","exampleJa2":"増大するコンプライアンス費用が小規模証券会社の勢力図を変えつつある。","origin":"escalator(エスカレーター、ラテン語 scala 階段から)を動詞化。段階的に上へ上がっていく→「増大する」。","collocations":["escalating costs","escalating tensions"]},"dividends":{"example2":"Investing in employee training paid dividends in higher retention.","exampleJa2":"従業員研修への投資は定着率向上という恩恵をもたらした。","origin":"ラテン語 dividendum(分けられるべきもの)由来。dividere(分ける)から。利益の分配→比喩で「恩恵」。","collocations":["pay dividends","reap dividends"]},"closed-loop":{"example2":"The firm built a closed-loop system to reinvest all trading profits.","exampleJa2":"その会社は取引利益をすべて再投資する閉鎖循環型の仕組みを作った。","origin":"closed(閉じた)+loop(輪)。出力が入力へ戻る閉じた輪。制御工学のフィードバック回路が原義。","collocations":["closed-loop system","closed-loop control"]},"presuppose":{"example2":"Valuation models presuppose that markets price information efficiently.","exampleJa2":"バリュエーションモデルは市場が情報を効率的に織り込むと前提する。","origin":"pre(前もって)+suppose(ラテン語 sub 下に+ponere 置く→想定する)→「あらかじめ想定する」。","collocations":["presuppose that","presuppose knowledge"]},"determinist":{"example2":"A market determinist claims prices are fully fixed by prior conditions.","exampleJa2":"市場決定論者は、価格は事前条件で完全に定まると主張する。","origin":"ラテン語 de(完全に)+terminare(境界を定める)→determine(決定する)+ist(主義者)。すべて決まっていると考える人。","collocations":["hard determinist","determinist view"]},"predispositions":{"example2":"Behavioral predispositions can lead investors to sell in a panic.","exampleJa2":"行動上の傾向は投資家をパニック売りに導くことがある。","origin":"pre(前もって)+dis(離して)+position(置くこと)→「前もって傾けて置く」。あらかじめ備わった傾向。","collocations":["genetic predispositions","behavioral predispositions"]},"neurochemical":{"example2":"Stress triggers neurochemical changes that can cloud financial judgment.","exampleJa2":"ストレスは金融判断を曇らせうる神経化学的変化を引き起こす。","origin":"ギリシャ語 neuron(神経)+chemical(化学の)。神経系で起こる化学的な、の意。","collocations":["neurochemical imbalance","neurochemical changes"]},"compatibilists":{"example2":"Compatibilists hold that accountability survives even if choices are caused.","exampleJa2":"両立論者は、選択が因果的でも責任は成立すると考える。","origin":"ラテン語 com(共に)+pati(耐える、被る)→compatible(両立する)+ist。自由意志と決定論が両立すると説く人。","collocations":["compatibilists argue","leading compatibilists"]},"rebuttal":{"example2":"The analyst issued a sharp rebuttal to the short seller's report.","exampleJa2":"そのアナリストは空売り筋のレポートに鋭い反論を出した。","origin":"古仏語 reboter(押し返す)由来。re(戻す)+but(打つ、突く)→「打ち返す」。議論を突き返す反論。","collocations":["issue a rebuttal","offer a rebuttal"]},"metaphysical":{"example2":"Debates over what 'value' truly is can become almost metaphysical.","exampleJa2":"「価値」とは本当に何かをめぐる議論はほとんど形而上学的になりうる。","origin":"ギリシャ語 meta(後に)+physika(自然学)→アリストテレスの「自然学の後の書」から。存在の根本を問う学問。","collocations":["metaphysical question","metaphysical debate"]},"deliberation":{"example2":"After careful deliberation, the committee approved the budget allocation.","exampleJa2":"慎重な熟考の末、委員会は予算配分を承認した。","origin":"ラテン語 de(完全に)+librare(天秤で量る libra 天秤)→「はかりにかける」。よく比べ量って考える→熟考。","collocations":["careful deliberation","after much deliberation"]},"indeterminacy":{"example2":"Market indeterminacy makes precise long-term forecasts unreliable.","exampleJa2":"市場の不確定性は精密な長期予測を当てにならなくする。","origin":"in(否定)+determinacy(決定されていること)。ラテン語 terminare(境界を定める)から、境界が定まらない状態。","collocations":["quantum indeterminacy","fundamental indeterminacy"]},"retributive":{"example2":"Regulators leaned toward retributive fines rather than corrective measures.","exampleJa2":"当局は是正措置よりも応報的な罰金に傾いた。","origin":"ラテン語 re(返す)+tribuere(与える)→「報いを返す」。悪行に見合う罰を返す→応報的。","collocations":["retributive justice","retributive punishment"]},"edifice":{"example2":"The 2008 crisis exposed cracks in the whole edifice of risk modeling.","exampleJa2":"2008年の危機はリスクモデルの体系全体の綻びを露わにした。","origin":"ラテン語 aedificium(建物)由来。aedes(建物)+facere(作る)。大建造物、転じて「思想の体系」。","collocations":["the entire edifice","an edifice of rules"]},"consequentialist":{"example2":"A consequentialist would judge the policy purely by its net economic outcome.","exampleJa2":"帰結主義者はその政策を純粋に経済的な結果だけで判断するだろう。","origin":"ラテン語 consequi(後に続く con+sequi 従う)→結果 consequence に -ist/-ist的。結果で善悪を測る立場。","collocations":["consequentialist analysis","consequentialist argument"]},"deterrence":{"example2":"Steep penalties act as deterrence against insider trading.","exampleJa2":"厳しい罰則はインサイダー取引に対する抑止として働く。","origin":"ラテン語 de(離して)+terrere(怖がらせる terror 恐怖)→「怖がらせて遠ざける」。恐れで思いとどまらせる。","collocations":["nuclear deterrence","act as a deterrence"]},"rehabilitation":{"example2":"The turnaround plan focused on the rehabilitation of the distressed lender.","exampleJa2":"その再建計画は経営難の貸し手の立て直しに焦点を当てた。","origin":"ラテン語 re(再び)+habilitare(適格にする habilis 適した)→「再び適格に戻す」。更生・再建。","collocations":["focus on rehabilitation","rehabilitation program"]},"exhaustive":{"example2":"Auditors performed an exhaustive review of the trading records.","exampleJa2":"監査人は取引記録の徹底的な精査を行った。","origin":"ラテン語 ex(外へ)+haurire(汲み出す)→exhaust(汲み尽くす)。すべて汲み尽くすほど網羅的な。","collocations":["exhaustive review","exhaustive analysis"]},"prevailing":{"example2":"The prevailing interest rate shapes borrowing costs across the economy.","exampleJa2":"支配的な金利は経済全体の借入コストを左右する。","origin":"ラテン語 prae(前に)+valere(強い value)→prevail(勝る、広まる)。最も強く行き渡っている→支配的な。","collocations":["prevailing rate","prevailing view"]},"mortality":{"example2":"The high mortality rate among fintech startups deters cautious investors.","exampleJa2":"フィンテック新興企業の高い失敗率は慎重な投資家を遠ざける。","origin":"ラテン語 mortalis(死すべき mors 死)由来。死ぬ運命の性質→死亡率、比喩で「失敗率」。","collocations":["mortality rate","high mortality"]},"premature scaling":{"example2":"Premature scaling left the venture overstaffed and burning cash quickly.","exampleJa2":"時期尚早な拡大により、その事業は人員過剰で急速に資金を溶かした。","origin":"premature(pre 前+ラテン語 maturus 熟した→熟す前)+scaling(規模拡大)。熟す前に拡大する誤り。","collocations":["avoid premature scaling","premature scaling risk"]},"demise":{"example2":"The retailer's demise was hastened by its failure to go digital.","exampleJa2":"その小売業者の終焉はデジタル化の失敗で早まった。","origin":"古仏語 demettre(手放す de+mettre 置く)由来。法律で財産を譲渡する意から、転じて「終焉・死」。","collocations":["untimely demise","led to its demise"]},"buoyed":{"example2":"Shares were buoyed by stronger-than-expected quarterly earnings.","exampleJa2":"株価は予想を上回る四半期決算に勢いづけられた。","origin":"buoy(浮標、浮き)を動詞化。水面に浮かせて沈ませない→「支える・勢いづける」。","collocations":["buoyed by demand","buoyed by optimism"]},"unit economics":{"example2":"Positive unit economics finally convinced the board to expand nationwide.","exampleJa2":"ユニットエコノミクスが黒字化し、取締役会はついに全国展開を決めた。","origin":"unit(単位)+economics(経済、ギリシャ語 oikonomia 家政)。顧客1件あたりの採算という単位での収支。","collocations":["positive unit economics","unit economics of the business"]},"irreconcilable":{"example2":"Irreconcilable views on valuation ultimately sank the acquisition.","exampleJa2":"バリュエーションに関する相容れない見解が結局買収を沈めた。","origin":"ir(否定)+reconcile(ラテン語 re 再び+conciliare 和解させる)+able→「和解させられない」。","collocations":["irreconcilable differences","irreconcilable positions"]},"inequitable":{"example2":"Critics called the fee structure inequitable to smaller retail investors.","exampleJa2":"批判者はその手数料体系を小口の個人投資家に不公平だとした。","origin":"in(否定)+equitable(公正な ラテン語 aequus 等しい)→「等しく扱わない」不公平な。","collocations":["inequitable distribution","inequitable access"]},"requisite":{"example2":"The trader lacked the requisite license to handle derivatives.","exampleJa2":"そのトレーダーはデリバティブを扱うのに必要な免許を欠いていた。","origin":"ラテン語 requirere(求める re 再び+quaerere 探す)の過去分詞→「求められた」必要な。","collocations":["requisite skills","requisite approval"]},"survivorship bias":{"example2":"Fund rankings suffer from survivorship bias when closed funds vanish from data.","exampleJa2":"破綻して消えたファンドがデータから外れると、ファンド順位は生存者バイアスに陥る。","origin":"survivor(生き残った者 survive ラテン語 super 上に+vivere 生きる)+bias(偏り)。生き残りだけ見る偏り。","collocations":["suffer from survivorship bias","account for survivorship bias"]},"heuristic":{"example2":"Traders often use a simple heuristic to gauge market sentiment quickly.","exampleJa2":"トレーダーは市場心理を素早く測るのに単純な経験則をよく使う。","origin":"ギリシャ語 heuriskein(見つける)由来。アルキメデスの「Eureka(見つけた)」と同根。素早く答えを見つける経験則。","collocations":["use a heuristic","rely on heuristics"]},"statisticians":{"example2":"The bank's statisticians modeled default risk across the loan portfolio.","exampleJa2":"その銀行の統計学者はローン全体の債務不履行リスクをモデル化した。","origin":"state(国家)由来の statistics(元は国家の数量データ)+ian(専門家)。国勢データを扱う人→統計学者。","collocations":["team of statisticians","statisticians estimate"]},"charismatic":{"example2":"The charismatic CEO rallied investors despite three years of losses.","exampleJa2":"そのカリスマ的なCEOは3年連続赤字でも投資家を惹きつけた。","origin":"ギリシャ語 kharisma(神からの賜物 kharis 恵み)由来。人を惹きつける天賦の魅力→カリスマ的。","collocations":["charismatic leader","charismatic founder"]},"proprietary":{"example2":"The hedge fund guards its proprietary trading algorithms fiercely.","exampleJa2":"そのヘッジファンドは独自の取引アルゴリズムを厳重に守っている。","origin":"ラテン語 proprietas(所有物 proprius 自分自身の)由来。特定の所有者に属する→「独自の・専有の」。","collocations":["proprietary technology","proprietary data"]},"spatial awareness":{"example2":"Good spatial awareness helps a trader visualize how positions interact.","exampleJa2":"優れた空間認識は、ポジション同士の関係を思い描くのに役立つ。","origin":"spatial(空間の ラテン語 spatium 空間)+awareness(気づき)。周囲との位置関係を把握する力。","collocations":["strong spatial awareness","lack spatial awareness"]},"dissect":{"example2":"The team dissected the failed trade to identify every risk oversight.","exampleJa2":"チームは失敗した取引を詳細に分析し、あらゆるリスクの見落としを特定した。","origin":"ラテン語 dis(離して)+secare(切る)→「切り分ける」。解剖から、転じて「詳細に分析する」。","collocations":["dissect the data","dissect the problem"]},"immersive":{"example2":"The trading simulator gives trainees an immersive taste of live markets.","exampleJa2":"その取引シミュレーターは研修生に実市場の没入的な体験を与える。","origin":"ラテン語 im(中へ)+mergere(沈める merge)→「中に沈み込む」。体験にどっぷり浸る→没入型の。","collocations":["immersive experience","immersive environment"]},"vulnerabilities":{"example2":"Stress tests revealed vulnerabilities in the bank's liquidity position.","exampleJa2":"ストレステストは銀行の流動性ポジションの脆弱性を明らかにした。","origin":"ラテン語 vulnerare(傷つける vulnus 傷)由来。傷つきやすさ→弱点・脆弱性。","collocations":["identify vulnerabilities","critical vulnerabilities"]},"adversary":{"example2":"In a bidding war, each adversary drove the price steadily higher.","exampleJa2":"入札合戦では、各対戦相手が価格を着実に吊り上げた。","origin":"ラテン語 adversarius(反対側の ad 向かって+versus 向く)由来。向かい合って対する者→敵。","collocations":["formidable adversary","outmaneuver an adversary"]},"homogenization":{"example2":"The homogenization of index funds has narrowed investors' real choices.","exampleJa2":"インデックスファンドの均質化は投資家の実質的な選択肢を狭めた。","origin":"ギリシャ語 homos(同じ)+genos(種類)→homogeneous(同質の)+化。すべてを同じ質にする過程。","collocations":["homogenization of culture","market homogenization"]},"intangible":{"example2":"A brand's reputation is an intangible asset that is hard to value precisely.","exampleJa2":"ブランドの評判は正確に評価しにくい無形資産だ。","origin":"in(否定)+tangible(触れられる ラテン語 tangere 触れる)→「触れられない」無形の。","collocations":["intangible assets","intangible benefits"]},"composure":{"example2":"She kept her composure as the market plunged during the open.","exampleJa2":"彼女は寄り付きで市場が急落する中も冷静さを保った。","origin":"ラテン語 com(共に)+ponere(置く)→compose(まとめる)+ure。心をきちんとまとめた状態→冷静さ。","collocations":["maintain composure","regain composure"]},"astute":{"example2":"An astute investor spotted the undervalued stock before the rally.","exampleJa2":"鋭い投資家は上昇前に割安な株を見抜いた。","origin":"ラテン語 astutus(抜け目ない astus 巧みさ)由来。状況を的確に読んで利する→洞察力のある。","collocations":["astute investor","astute observation"]},"supplant":{"example2":"Passive index funds have begun to supplant traditional active managers.","exampleJa2":"パッシブなインデックスファンドは従来のアクティブ運用者に取って代わり始めた。","origin":"ラテン語 supplantare(足払いで倒す sub 下+planta 足の裏)→相手を倒して代わる→「取って代わる」。","collocations":["supplant the incumbent","gradually supplant"]},"siege":{"example2":"The company was under siege from activist investors demanding change.","exampleJa2":"その会社は変革を求める物言う株主から包囲攻撃を受けていた。","origin":"古仏語 sege(座ること ラテン語 sedere 座る)由来。敵が城前に「腰を据える」→包囲攻撃。","collocations":["lay siege to","under siege"]},"breached":{"example2":"The firm breached its capital requirements and faced regulatory penalties.","exampleJa2":"その会社は自己資本規制に違反し、当局の処分に直面した。","origin":"古英語 brecan(破る、break と同根)由来。壁や約束に穴を開け突破する→「破る・違反する」。","collocations":["breach a contract","breach security"]},"extinguishing":{"example2":"Aggressive rate hikes aimed at extinguishing runaway inflation.","exampleJa2":"大幅な利上げは暴走するインフレを鎮めることを狙った。","origin":"ラテン語 ex(外へ)+stinguere(消す)→「火を消し尽くす」。転じて存在や活動を「終わらせる」。","collocations":["extinguishing a debt","extinguishing hope"]},"reverberated":{"example2":"The default reverberated across every credit market for weeks.","exampleJa2":"その債務不履行は数週間にわたり全信用市場に影響を及ぼし続けた。","origin":"ラテン語 re(戻る)+verberare(打つ verber むち)→「打ち返す」。音がこだまする→影響が波及する。","collocations":["reverberate through markets","reverberate across"]},"exodus":{"example2":"A talent exodus followed the firm's controversial pay cuts.","exampleJa2":"その会社の物議を醸した賃下げの後、人材の大量流出が続いた。","origin":"ギリシャ語 ex(外へ)+hodos(道)→「外へ出る道」。旧約聖書の出エジプト記から「大量脱出」。","collocations":["mass exodus","talent exodus"]},"pedagogical":{"example2":"The bank redesigned its training with a fresh pedagogical approach.","exampleJa2":"その銀行は新たな教育学的アプローチで研修を作り直した。","origin":"ギリシャ語 paidagogos(子供 pais を導く agein 者=教育係)由来。教える方法に関する→教育学的な。","collocations":["pedagogical approach","pedagogical method"]},"ferment":{"example2":"Regulatory ferment kept the fintech sector in a state of constant flux.","exampleJa2":"規制をめぐる動乱がフィンテック業界を絶えず流動的な状態に置いた。","origin":"ラテン語 fermentum(酵母 fervere 沸き立つ)由来。発酵で泡立つ様子から、社会の「興奮・動乱」。","collocations":["political ferment","in a state of ferment"]},"humanistic":{"example2":"The firm promoted a humanistic culture valuing employees over pure profit.","exampleJa2":"その会社は純利益より従業員を重んじる人文主義的な文化を推し進めた。","origin":"ラテン語 humanus(人間の homo 人)由来。人間の価値と理性を重んじる思想→人文主義的。","collocations":["humanistic tradition","humanistic values"]},"lucrative":{"example2":"Wealth management proved a highly lucrative segment for the bank.","exampleJa2":"資産管理は銀行にとって非常に利益の多い部門であることが分かった。","origin":"ラテン語 lucrum(利益)由来。lucrari(儲ける)から。利益を生む→「儲かる」。","collocations":["lucrative business","lucrative contract"]},"inaugurate":{"example2":"The exchange inaugurated round-the-clock trading for crypto assets.","exampleJa2":"その取引所は暗号資産の24時間取引を開始した。","origin":"ラテン語 inaugurare(鳥占いで吉兆を得て始める augur 占い師)由来。吉兆のもと正式に「開始・就任させる」。","collocations":["inaugurate a new era","inaugurate a program"]},"apocalyptic":{"example2":"Some analysts painted an apocalyptic picture of a total banking collapse.","exampleJa2":"一部のアナリストは銀行の全面崩壊という黙示録的な絵を描いた。","origin":"ギリシャ語 apokalypsis(覆いを取ること apo 離す+kalyptein 覆う=啓示)由来。世界終末を描く新約の黙示録から。","collocations":["apocalyptic scenario","apocalyptic warnings"]},"spurring":{"example2":"Low rates are spurring a surge in corporate borrowing and buybacks.","exampleJa2":"低金利が企業の借入と自社株買いの急増に拍車をかけている。","origin":"古英語 spura(拍車)由来。馬の脇を拍車で突いて速く走らせる→「促す・拍車をかける」。","collocations":["spur growth","spur investment"]},"obsolete":{"example2":"Mobile banking has rendered many branch tellers nearly obsolete.","exampleJa2":"モバイルバンキングは多くの窓口係をほぼ時代遅れにした。","origin":"ラテン語 obsolescere(すり減って廃れる ob+solere 慣習)由来。使われなくなり廃れた→時代遅れの。","collocations":["become obsolete","render obsolete"]},"precipitating":{"example2":"A single downgrade risked precipitating a full-blown liquidity crisis.","exampleJa2":"一度の格下げが本格的な流動性危機を引き起こす恐れがあった。","origin":"ラテン語 praeceps(真っ逆さま prae 前+caput 頭)由来。頭から突っ込ませる→急に「引き起こす」。","collocations":["precipitate a crisis","precipitate a decline"]},"bidirectional":{"example2":"The platform enables bidirectional data flow between the two exchanges.","exampleJa2":"そのプラットフォームは2つの取引所間で双方向のデータ流通を可能にする。","origin":"bi(2つ ラテン語 bis)+directional(方向の direct 向ける)→「2つの方向の」双方向の。","collocations":["bidirectional flow","bidirectional communication"]},"gastrointestinal":{"example2":"The biotech's new drug targets chronic gastrointestinal conditions.","exampleJa2":"そのバイオ企業の新薬は慢性の胃腸疾患を標的とする。","origin":"ギリシャ語 gaster(胃)+ラテン語 intestinum(腸)。胃と腸に関する→胃腸の。","collocations":["gastrointestinal tract","gastrointestinal disorders"]},"therapeutic":{"example2":"The startup's therapeutic pipeline attracted major pharmaceutical investors.","exampleJa2":"その新興企業の治療薬パイプラインは大手製薬の投資家を惹きつけた。","origin":"ギリシャ語 therapeuein(治療する、世話する)由来。病を癒すことに関する→治療的な。","collocations":["therapeutic effect","therapeutic potential"]},"neurotransmitters":{"example2":"Researchers linked imbalanced neurotransmitters to impulsive risk-taking.","exampleJa2":"研究者は神経伝達物質の不均衡と衝動的なリスク志向を結びつけた。","origin":"ギリシャ語 neuron(神経)+ラテン語 transmittere(送り渡す trans 越えて+mittere 送る)。神経間で信号を伝える化学物質。","collocations":["release neurotransmitters","neurotransmitter levels"]},"inflammatory mediators":{"example2":"Blood tests measured inflammatory mediators to gauge the patient's recovery progress.","exampleJa2":"血液検査で炎症メディエーターを測定し、患者の回復の進み具合を評価した。","origin":"inflammatory は inflammare(ラテン語: 火をつける)+ory、mediator は medius(中間)+ator(仲介するもの)。細胞間で炎症を仲立ちする物質のイメージ。","collocations":["release inflammatory mediators","pro-inflammatory mediators","elevated inflammatory mediators"]},"synthesis":{"example2":"The analyst's report was a skillful synthesis of market data and expert forecasts.","exampleJa2":"そのアナリストのレポートは、市場データと専門家の予測を巧みに統合したものだった。","origin":"ギリシャ語 syn(共に)+thesis(置くこと)→複数のものを一つに置き合わせること。反対語 analysis(ばらすこと)と対で覚える。","collocations":["synthesis of ideas","protein synthesis","a synthesis of"]},"randomized controlled":{"example2":"Regulators favored the drug only after a randomized controlled study confirmed its safety.","exampleJa2":"無作為化対照試験で安全性が確認されて初めて、規制当局はその薬を認めた。","origin":"random(でたらめ)+ize(〜化する)+ed と、control(管理する)+ed の組み合わせ。被験者をランダムに割り付け、対照群と比べる実験デザイン。","collocations":["randomized controlled trial","randomized controlled study","double-blind randomized controlled"]},"cortisol":{"example2":"Traders under constant pressure often show elevated cortisol by the market's close.","exampleJa2":"常にプレッシャーを受けるトレーダーは、市場の引け時にコルチゾール値が上昇していることが多い。","origin":"cortex(ラテン語: 皮質)由来。副腎皮質で作られるホルモンなので cortis- を含む。ストレスと結びつけて覚える。","collocations":["cortisol levels","elevated cortisol","release cortisol"]},"psychobiotics":{"example2":"Several venture funds are betting heavily on psychobiotics as a new therapeutic frontier.","exampleJa2":"複数のベンチャーファンドが、新たな治療領域としてサイコバイオティクスに大きく賭けている。","origin":"psycho(ギリシャ語 psyche: 心)+biotics(bios: 生命)。心に効くプロバイオティクスという合成語。腸内細菌が精神に影響するイメージ。","collocations":["psychobiotics research","invest in psychobiotics","psychobiotics supplements"]},"vagus nerve":{"example2":"Deep breathing activates the vagus nerve and helps calm the body's stress response.","exampleJa2":"深呼吸は迷走神経を活性化させ、体のストレス反応を鎮めるのに役立つ。","origin":"vagus はラテン語で「さまよう」(vagrant と同語源)。脳から腹部まで広く分岐して「さまよう」神経なのでこの名。","collocations":["vagus nerve stimulation","stimulate the vagus nerve","vagal tone"]},"conduit":{"example2":"The offshore subsidiary acted as a conduit for channeling profits to lower-tax jurisdictions.","exampleJa2":"その海外子会社は、利益を低税率の地域へ流すための導管の役割を果たした。","origin":"ラテン語 conducere(con: 共に+ducere: 導く)→導く管。con+duit(導く)で「何かを運ぶ通り道」と覚える。","collocations":["serve as a conduit","a conduit for","conduit between"]},"modulate":{"example2":"Central banks modulate interest rates to keep inflation within a target range.","exampleJa2":"中央銀行は、インフレを目標圏内に保つために金利を調節する。","origin":"ラテン語 modulari(modus: 尺度・程度)→程度を測って整える。mode(様式・程度)と同語源で「程度を加減する」イメージ。","collocations":["modulate the immune response","modulate activity","finely modulate"]},"replication crisis":{"example2":"The replication crisis made investors wary of trading strategies backed only by one study.","exampleJa2":"再現性の危機により、投資家は一つの研究だけに裏付けられた取引戦略を警戒するようになった。","origin":"replication は replicare(ラテン語: 折り返す・繰り返す)由来で「追試」。再現できない研究が多発する「危機」を指す近年の造語。","collocations":["face a replication crisis","the replication crisis in psychology","address the replication crisis"]},"longitudinal":{"example2":"A longitudinal analysis of the fund's returns revealed consistent underperformance over decades.","exampleJa2":"そのファンドのリターンを長期的に分析すると、数十年にわたる継続的な低調さが明らかになった。","origin":"ラテン語 longitudo(long: 長い)→時間軸に沿って「長く」追跡する研究。地図の経度(longitude)と同じ語根。","collocations":["longitudinal study","longitudinal data","longitudinal analysis"]},"disheveled":{"example2":"After the all-night trading session, the broker looked disheveled and drained.","exampleJa2":"徹夜の取引を終え、そのブローカーは髪も服も乱れ、疲れ果てて見えた。","origin":"古フランス語 descheveler(des: 離す+chevel: 髪)→髪を乱す。もともと「髪がぼさぼさ」の意から「身なりが乱れた」に広がった。","collocations":["look disheveled","disheveled hair","disheveled appearance"]},"meticulous":{"example2":"The auditor's meticulous review of every invoice exposed a hidden accounting error.","exampleJa2":"その監査人が全ての請求書を細心に確認したことで、隠れた会計ミスが明るみに出た。","origin":"ラテン語 meticulosus(metus: 恐れ)→「恐れるほど細かい」が原義。ミスを恐れて隅々まで気を配るイメージ。","collocations":["meticulous attention to detail","meticulous record","meticulous planning"]},"instilled":{"example2":"Years at the firm instilled in her a deep respect for risk management.","exampleJa2":"その会社での長年の勤務は、彼女にリスク管理への深い敬意を植え付けた。","origin":"ラテン語 instillare(in: 中へ+stilla: 一滴)→一滴ずつ注ぎ込む。考えや価値観を少しずつ心に染み込ませるイメージ。","collocations":["instill confidence","instill discipline","instill values in"]},"invariable":{"example2":"His invariable rule was never to invest in a business he did not understand.","exampleJa2":"彼の変わらぬ鉄則は、理解できない事業には決して投資しないことだった。","origin":"in(否定)+variable(変わりうる)。variable は variare(ラテン語: 変える)由来なので「変わらない」。","collocations":["invariable routine","invariable rule","almost invariable"]},"charred":{"example2":"Only charred fragments of the shredded contracts remained in the bin.","exampleJa2":"ゴミ箱には、細断された契約書の焦げた断片だけが残っていた。","origin":"char(炭にする)+ed。char は charcoal(木炭)の略に由来。表面が炭のように黒く焦げた状態。","collocations":["charred remains","charred wood","badly charred"]},"remnants":{"example2":"The auditors traced the remnants of the failed venture through its remaining accounts.","exampleJa2":"監査人たちは、失敗した事業の残滓を残された口座を通じてたどった。","origin":"古フランス語 remenant(remanoir: 残る、ラテン語 remanere)由来。remain と同語源で「残ったもの」。","collocations":["remnants of","last remnants","charred remnants"]},"beneficiary":{"example2":"The trust names his grandchildren as the primary beneficiaries of the estate.","exampleJa2":"その信託は、遺産の第一受益者として彼の孫たちを指定している。","origin":"ラテン語 beneficium(bene: 良く+facere: なす)→恩恵。良いこと(benefit)を受け取る人。","collocations":["designated beneficiary","primary beneficiary","name a beneficiary"]},"deceased":{"example2":"The deceased client's portfolio was frozen pending the will's verification.","exampleJa2":"遺言の確認が済むまで、その亡くなった顧客のポートフォリオは凍結された。","origin":"ラテン語 decedere(de: 離れて+cedere: 行く)→「立ち去る」の婉曲表現。死を直接言わず「去った人」とする言い方。","collocations":["the deceased's estate","deceased person","recently deceased"]},"nagged":{"example2":"A doubt about the figures nagged at the accountant all weekend.","exampleJa2":"その数字への疑念が、会計士を週末じゅう気にさせ続けた。","origin":"北欧語 nagga(かじる、こする)に由来。心を絶えず「かじる」ように悩ませる、しつこく小言を言うイメージ。","collocations":["nagged at","a nagging doubt","nagging feeling"]},"incinerated":{"example2":"The bank incinerated the outdated records once the retention period expired.","exampleJa2":"保存期間が過ぎると、その銀行は古くなった記録を焼却処分した。","origin":"ラテン語 incinerare(in: 〜に+cinis: 灰)→灰にする。完全に燃やして灰にするイメージで覚える。","collocations":["incinerate waste","completely incinerated","incinerate documents"]},"contentedly":{"example2":"After securing his pension, he contentedly stepped back from the trading floor.","exampleJa2":"年金を確保したのち、彼は満足そうに取引の現場から身を引いた。","origin":"content(満足した、ラテン語 contentus: 満たされた)+ed+ly。「中身が満たされている」状態で穏やかに、と覚える。","collocations":["sigh contentedly","smile contentedly","rest contentedly"]},"sedated":{"example2":"The patient was heavily sedated and could not sign the financial documents.","exampleJa2":"その患者は強く鎮静剤を投与されており、金融書類にサインできなかった。","origin":"ラテン語 sedare(静める、sedere: 座るに関連)→落ち着かせる。座らせて静める→鎮静させるイメージ。","collocations":["heavily sedated","sedate the patient","sedated state"]},"perceptible":{"example2":"There was a perceptible shift in market sentiment after the announcement.","exampleJa2":"その発表の後、市場心理に感じ取れるほどの変化があった。","origin":"ラテン語 percipere(per: 完全に+capere: つかむ)→知覚する+ible(できる)。感覚でつかみ取れる、の意。","collocations":["barely perceptible","a perceptible change","perceptible difference"]},"methodically":{"example2":"She methodically reviewed each holding before rebalancing the portfolio.","exampleJa2":"彼女はポートフォリオを再調整する前に、各保有銘柄を系統的に見直した。","origin":"method(ギリシャ語 methodos: meta 沿って+hodos 道)+ical+ly。「道筋に沿って」順序立てて進めるイメージ。","collocations":["work methodically","methodically test","methodically go through"]},"culinary":{"example2":"The hotel's culinary reputation drew high-spending guests from across the region.","exampleJa2":"そのホテルの料理の評判は、地域中から金払いのよい客を引き寄せた。","origin":"ラテン語 culina(台所)+ary。kiln(窯)とも関連。台所・調理に関することと覚える。","collocations":["culinary tradition","culinary arts","culinary skills"]},"fusion":{"example2":"The merger created a fusion of two very different corporate cultures.","exampleJa2":"その合併は、まったく異なる二つの企業文化の融合を生み出した。","origin":"ラテン語 fundere(注ぐ・溶かす)→fusio。溶かして混ぜ合わせるイメージ。fuse(溶ける・融合する)の名詞形。","collocations":["fusion of","cultural fusion","fusion cuisine"]},"gastronomic":{"example2":"The city marketed itself as a gastronomic destination to boost tourism revenue.","exampleJa2":"その都市は観光収入を増やすため、美食の目的地として自らを売り込んだ。","origin":"ギリシャ語 gaster(胃)+nomos(法・規範)→「胃の法則」=美食学。gastro(胃)を含む語で食と結びつける。","collocations":["gastronomic experience","gastronomic delights","gastronomic tour"]},"appropriation":{"example2":"The board approved a large appropriation of funds for the new data center.","exampleJa2":"取締役会は、新しいデータセンター向けに多額の資金充当を承認した。","origin":"ラテン語 appropriare(ad: 〜へ+proprius: 自分のもの)→自分のものにする。proper(固有の)と同語源。","collocations":["cultural appropriation","appropriation of funds","budget appropriation"]},"palate":{"example2":"Sophisticated clients have a refined palate for well-structured investment products.","exampleJa2":"洗練された顧客は、よく設計された投資商品に対して高い目利き(嗜好)を持っている。","origin":"ラテン語 palatum(口蓋)由来。味を感じる口の天井→転じて「味覚・好み」。palette(絵の具板)と混同注意。","collocations":["refined palate","expand one's palate","please the palate"]},"repertoire":{"example2":"The salesperson expanded her repertoire of products to serve wealthier clients.","exampleJa2":"その営業担当は、富裕層の顧客に対応するため取り扱う商品のレパートリーを広げた。","origin":"フランス語 répertoire(ラテン語 repertorium: 目録)由来。演目リスト→使いこなせる技や項目の一覧、と覚える。","collocations":["expand one's repertoire","a repertoire of","add to the repertoire"]},"commodification":{"example2":"The commodification of personal data has become a major source of corporate revenue.","exampleJa2":"個人データの商品化は、企業収益の主要な源泉となっている。","origin":"commodity(商品、ラテン語 commodus: 便利な)+fication(化)。何でも売買可能な「商品」に変えること。","collocations":["commodification of","increasing commodification","commodification of culture"]},"foodways":{"example2":"Immigrant communities preserved their foodways even as they adapted to new economies.","exampleJa2":"移民コミュニティは、新しい経済に適応しながらも自らの食文化を守り続けた。","origin":"food(食べ物)+ways(やり方・習わし)の合成語。folkways(民俗習慣)に倣った表現で「食にまつわる慣習」。","collocations":["traditional foodways","regional foodways","document foodways"]},"irrevocably":{"example2":"Signing the contract irrevocably committed the firm to a decade of payments.","exampleJa2":"その契約に署名したことで、会社は10年間の支払いに取り返しのつかない形で拘束された。","origin":"ir(否定)+revocable。revoke は ラテン語 revocare(re: 再び+vocare: 呼ぶ)→呼び戻す。呼び戻せない=取り消せない。","collocations":["irrevocably changed","irrevocably committed","irrevocably damaged"]},"intermediaries":{"example2":"Fintech platforms cut costs by removing traditional financial intermediaries.","exampleJa2":"フィンテック・プラットフォームは、従来の金融仲介者を排除することでコストを削減する。","origin":"ラテン語 intermedius(inter: 間+medius: 中間)+ary。二者の「間」に立って取り次ぐ者。","collocations":["financial intermediaries","cut out intermediaries","role of intermediaries"]},"legitimacy":{"example2":"Regulatory approval gave the new exchange legitimacy in the eyes of institutional investors.","exampleJa2":"規制当局の認可により、その新しい取引所は機関投資家の目から見て正当性を得た。","origin":"ラテン語 legitimus(lex/legis: 法)→合法。legal と同語源で「法にかなっていること」。","collocations":["establish legitimacy","political legitimacy","question the legitimacy"]},"sustenance":{"example2":"For many households, dividend income provides essential financial sustenance in retirement.","exampleJa2":"多くの世帯にとって、配当収入は退職後の生計を支える不可欠な糧となる。","origin":"ラテン語 sustinere(sus: 下から+tenere: 保つ)→支える。sustain(維持する)の名詞形で「生命を支えるもの」。","collocations":["provide sustenance","primary sustenance","spiritual sustenance"]},"prescriptions":{"example2":"The consultants' prescriptions for cost-cutting alienated much of the workforce.","exampleJa2":"そのコンサルタントたちのコスト削減に関する処方箋(提言)は、多くの従業員を遠ざけた。","origin":"ラテン語 praescribere(prae: 前もって+scribere: 書く)→前もって書き記す。医薬の処方も政策の指針も「あらかじめ定めた指示」。","collocations":["policy prescriptions","one-size-fits-all prescriptions","offer prescriptions"]},"passive investing":{"example2":"Many advisors now recommend passive investing to clients wary of high management fees.","exampleJa2":"多くのアドバイザーは今や、高い運用手数料を嫌う顧客にパッシブ投資を勧めている。","origin":"passive(受動的な、ラテン語 pati: 耐える)+investing。市場に「身をまかせる」=指数に連動させる投資、と覚える。","collocations":["passive investing strategy","shift to passive investing","passive index funds"]},"capital allocation":{"example2":"The CEO's disciplined capital allocation turned a mediocre firm into a market leader.","exampleJa2":"そのCEOの規律ある資本配分は、平凡な企業を業界のリーダーへと変えた。","origin":"capital(資本、ラテン語 caput: 頭)+allocation(配分、ad+locare: 場所に置く)。手元の資本をどこに置くか決めること。","collocations":["capital allocation decisions","disciplined capital allocation","efficient capital allocation"]},"surpass":{"example2":"The startup's valuation surpassed that of its century-old rival within five years.","exampleJa2":"そのスタートアップの企業価値は、5年以内に100年の歴史を持つ競合を上回った。","origin":"フランス語 sur(上に、ラテン語 super)+passer(通る、pass)→上を通り越す。pass の上を行く=超える、と覚える。","collocations":["surpass expectations","surpass a target","surpass the benchmark"]},"democratize":{"example2":"Low-cost brokerage apps democratized stock trading for ordinary savers.","exampleJa2":"低コストの証券アプリは、一般の預金者にも株式取引を開かれたものにした。","origin":"democracy(ギリシャ語 demos: 民衆+kratos: 力)+ize。「民衆の手に渡す」=誰もが使えるようにする。","collocations":["democratize access","democratize finance","democratize information"]},"benchmark":{"example2":"Managers who consistently trail their benchmark struggle to retain client assets.","exampleJa2":"ベンチマークに一貫して負ける運用者は、顧客資産を維持するのに苦労する。","origin":"bench(作業台)+mark(印)。測量士が水準器を置いた台につけた基準の印に由来。比較の「基準点」。","collocations":["beat the benchmark","benchmark index","against the benchmark"]},"indiscriminately":{"example2":"The sell-off hit strong and weak companies indiscriminately.","exampleJa2":"その売りは、優良企業も脆弱な企業も見境なく直撃した。","origin":"in(否定)+discriminate(区別する、ラテン語 discriminare: 分ける)+ly。区別せずに、の意。","collocations":["fire indiscriminately","spend indiscriminately","affect indiscriminately"]},"price discovery":{"example2":"Thin trading volume weakens price discovery and widens bid-ask spreads.","exampleJa2":"薄い取引量は価格発見機能を弱め、売買の値幅を広げる。","origin":"price(価格)+discovery(発見、dis: 離す+cover: 覆う→覆いを取る)。市場が売買を通じて「適正価格を明らかにする」過程。","collocations":["efficient price discovery","price discovery mechanism","impair price discovery"]},"constituents":{"example2":"When the index reweighted its constituents, several small-cap stocks were dropped.","exampleJa2":"その指数が構成銘柄の比重を見直した際、いくつかの小型株が除外された。","origin":"ラテン語 constituere(con: 共に+statuere: 立てる)→共に組み立てるもの。全体を「構成する」要素・銘柄。","collocations":["index constituents","constituents of","add new constituents"]},"stifling":{"example2":"Heavy compliance burdens are stifling smaller asset managers' ability to compete.","exampleJa2":"重いコンプライアンス負担が、中小の資産運用会社の競争力を抑え込んでいる。","origin":"中英語 stifle(窒息させる)由来。空気を絶つように成長や自由を締めつけるイメージ。","collocations":["stifle innovation","stifle competition","stifle growth"]},"governance":{"example2":"Weak governance and opaque disclosures scared institutional investors away.","exampleJa2":"脆弱なガバナンスと不透明な情報開示が、機関投資家を遠ざけた。","origin":"ラテン語 gubernare(舵を取る、ギリシャ語 kybernan)→govern。船の舵取りのように組織を導く仕組み。","collocations":["corporate governance","good governance","governance structure"]},"prudent":{"example2":"It was prudent to hedge the currency exposure before the election.","exampleJa2":"選挙の前に為替エクスポージャーをヘッジしておくのは賢明だった。","origin":"ラテン語 prudens(providens: 先を見通す の短縮)→先を見越して用心深い。provide と同語源で「備える」イメージ。","collocations":["prudent investor","prudent decision","financially prudent"]},"horizon":{"example2":"A longer investment horizon lets investors ride out short-term volatility.","exampleJa2":"投資期間が長いほど、投資家は短期の変動を乗り切ることができる。","origin":"ギリシャ語 horizein(境界を定める、horos: 境界)→地平線。見通せる「範囲・期間」の比喩として使う。","collocations":["investment horizon","long time horizon","short horizon"]},"prefrontal cortex":{"example2":"Sound investment decisions rely on the prefrontal cortex resisting impulsive urges.","exampleJa2":"健全な投資判断は、衝動を抑える前頭前皮質の働きに支えられている。","origin":"pre(前)+frontal(前面の、ラテン語 frons: 額)+cortex(皮質、樹皮)。脳の一番前、額の裏の皮質。","collocations":["prefrontal cortex activity","develop the prefrontal cortex","damage to the prefrontal cortex"]},"neurologically":{"example2":"Chronic stress can neurologically rewire how the brain responds to risk.","exampleJa2":"慢性的なストレスは、脳がリスクに反応する仕方を神経学的に作り変えることがある。","origin":"ギリシャ語 neuron(神経)+logos(学問)+ical+ly。神経の仕組みという観点から、と覚える。","collocations":["neurologically distinct","neurologically impaired","neurologically wired"]},"dopamine":{"example2":"The thrill of a winning trade delivers a rush of dopamine to the brain.","exampleJa2":"勝ちトレードのスリルは、脳にドーパミンの高揚感をもたらす。","origin":"化学名 dihydroxyphenylethylamine の一部を縮めた語。DOPA(前駆物質)+amine から。快感・報酬に関わる神経伝達物質。","collocations":["dopamine release","dopamine hit","dopamine levels"]},"intermittent":{"example2":"The stock delivered intermittent gains but no steady long-term trend.","exampleJa2":"その株は断続的に上昇したが、安定した長期トレンドはなかった。","origin":"ラテン語 intermittere(inter: 間+mittere: 送る・放つ)→間を置いて止める。途中で止まる=断続的。","collocations":["intermittent fasting","intermittent rewards","intermittent problems"]},"reinforcement":{"example2":"Frequent small wins provide the reinforcement that keeps day traders hooked.","exampleJa2":"頻繁な小さな勝ちは、デイトレーダーを夢中にさせ続ける強化として働く。","origin":"re(再び)+enforce(force: 力を加える)+ment。行動に力を加えて定着させること。心理学で「行動の強化」。","collocations":["positive reinforcement","reinforcement learning","intermittent reinforcement"]},"diminish":{"example2":"Rising interest rates diminished the appeal of high-growth technology stocks.","exampleJa2":"金利の上昇は、高成長のテクノロジー株の魅力を低下させた。","origin":"ラテン語 diminuere(di+minuere: 小さくする、minus: より少ない)。minus を含み「少なくする」イメージ。","collocations":["diminish in value","diminishing returns","diminish the risk"]},"gray matter":{"example2":"Investment banking demanded every ounce of his gray matter for eighty-hour weeks.","exampleJa2":"投資銀行の仕事は、週80時間、彼の頭脳(灰白質)を余すことなく要求した。","origin":"gray(灰色)+matter(物質)。神経細胞体が集まり灰色に見える脳組織。口語で「頭脳」を指すこともある。","collocations":["gray matter density","gray matter volume","loss of gray matter"]},"empathy":{"example2":"Empathy with clients' anxieties helps advisors recommend suitable portfolios.","exampleJa2":"顧客の不安に共感することは、アドバイザーが適切なポートフォリオを提案する助けになる。","origin":"ギリシャ語 em(中へ)+pathos(感情)→相手の感情の中に入る。sympathy(共に感じる)より一歩踏み込むイメージ。","collocations":["show empathy","empathy for","lack of empathy"]},"precautionary principle":{"example2":"Applying the precautionary principle, the regulator delayed approving the novel derivative.","exampleJa2":"予防原則に従い、規制当局はその新しいデリバティブの承認を先送りした。","origin":"precaution(pre: 前もって+caution: 用心、ラテン語 cavere: 用心する)+ary。確証を待たず前もって用心する原則。","collocations":["apply the precautionary principle","invoke the precautionary principle","precautionary approach"]},"urbanist":{"example2":"The urbanist argued that dense, walkable districts raise nearby property values.","exampleJa2":"その都市計画家は、密度が高く歩きやすい地区は周辺の不動産価値を高めると主張した。","origin":"ラテン語 urbs(都市)→urban+ist(専門家)。都市(urban)を研究・提唱する人。","collocations":["a leading urbanist","urbanist movement","urbanist principles"]},"pedestrian":{"example2":"The fund's returns were frankly pedestrian compared with its bolder rivals.","exampleJa2":"そのファンドのリターンは、より大胆な競合と比べれば正直平凡なものだった。","origin":"ラテン語 pedester(pes/pedis: 足)→歩く人。名詞は「歩行者」、形容詞では「ありふれた・平凡な」の意も持つ。","collocations":["pedestrian zone","pedestrian traffic","pedestrian-friendly"]},"retrofitting":{"example2":"Retrofitting the legacy trading system for real-time data required a large budget.","exampleJa2":"従来の取引システムをリアルタイムデータ対応に改修するには、多額の予算が必要だった。","origin":"retro(後ろへ、ラテン語 retro)+fit(合わせる)+ing。既存のものに後から新機能を「合わせ込む」こと。","collocations":["retrofitting buildings","seismic retrofitting","cost of retrofitting"]},"paradoxically":{"example2":"Paradoxically, cutting fees boosted the firm's total revenue by attracting more clients.","exampleJa2":"逆説的に、手数料を下げたことでより多くの顧客が集まり、会社全体の収益はむしろ増えた。","origin":"ギリシャ語 para(反して)+doxa(通念)→常識に反すること+ly。一見矛盾するように、の意。","collocations":["paradoxically, however","somewhat paradoxically","paradoxically enough"]},"displacing":{"example2":"Automation is displacing back-office clerks across the banking sector.","exampleJa2":"自動化は、銀行業界全体で事務部門の職員を追い出しつつある。","origin":"dis(離す)+place(場所)+ing→場所から外す。本来の場所から押しのける・立ち退かせるイメージ。","collocations":["displacing residents","displacing workers","risk of displacing"]},"complementary":{"example2":"Bonds and equities often play complementary roles in a balanced portfolio.","exampleJa2":"債券と株式は、バランスの取れたポートフォリオの中でしばしば補完的な役割を果たす。","origin":"ラテン語 complere(com: 完全に+plere: 満たす)→complete と同語源。互いに欠けを満たし合う=補完的。compliment(褒め言葉)と綴り注意。","collocations":["complementary roles","complementary skills","highly complementary"]},"equitable":{"example2":"The settlement aimed at an equitable division of the firm's remaining assets.","exampleJa2":"その和解は、会社の残余資産を公正に分割することを目指した。","origin":"ラテン語 aequus(等しい)→equity(公正)+able。equal と同語源で「偏りなく等しく扱える」の意。","collocations":["equitable distribution","fair and equitable","equitable treatment"]},"automobile dependency":{"example2":"Sprawling office parks reinforce automobile dependency and long commutes.","exampleJa2":"広く分散したオフィスパークは、自動車依存と長時間通勤を強めている。","origin":"automobile(auto: 自ら+mobile: 動く)+dependency(depend: 頼る、de+pendere: ぶら下がる)。移動を車に頼りきる状態。","collocations":["reduce automobile dependency","automobile dependency in suburbs","break automobile dependency"]},"surge":{"example2":"Bank stocks surged after the central bank signaled higher interest rates.","exampleJa2":"中央銀行が利上げを示唆すると、銀行株は急騰した。","origin":"ラテン語 surgere(sub: 下から+regere: まっすぐ導く)→立ち上がる。波が急に盛り上がるイメージ。","collocations":["prices surge","surge in demand","a sudden surge"]},"germline":{"example2":"Editing germline cells raises ethical questions that regulators are still debating.","exampleJa2":"生殖細胞系列の編集は、規制当局が今なお議論している倫理的な問いを提起する。","origin":"germ(芽・胚、ラテン語 germen: 芽)+line(系統)。子孫へと受け継がれる「芽の系統」=遺伝を伝える細胞系列。","collocations":["germline editing","germline mutations","germline cells"]},"heritable":{"example2":"Researchers debate how much of financial risk-taking is heritable versus learned.","exampleJa2":"金融リスクを取る傾向がどこまで遺伝性で、どこまで後天的かを研究者は議論している。","origin":"ラテン語 heres(相続人)→inherit(受け継ぐ)+able。財産の相続と同じく、遺伝子で「受け継げる」性質。","collocations":["heritable trait","highly heritable","heritable diseases"]},"somatic":{"example2":"A somatic mutation in one cell does not spread to a person's offspring.","exampleJa2":"一つの細胞に生じた体細胞変異は、その人の子孫には受け継がれない。","origin":"ギリシャ語 soma(体)+ic。生殖細胞(germline)と対で、体を作る「体細胞」を指す。soma=体、と覚える。","collocations":["somatic cells","somatic mutation","somatic gene therapy"]},"eradicate":{"example2":"Regulators struggled to eradicate insider trading despite tougher penalties.","exampleJa2":"厳罰化にもかかわらず、規制当局はインサイダー取引を根絶するのに苦労した。","origin":"ラテン語 eradicare(e: 外へ+radix: 根)→根こそぎ抜く。radish(大根)と同語源。「根から絶やす」イメージ。","collocations":["eradicate poverty","eradicate a disease","efforts to eradicate"]},"off-target effects":{"example2":"The gene therapy showed off-target effects that unexpectedly altered unrelated genes.","exampleJa2":"その遺伝子治療は、無関係な遺伝子を予想外に変えてしまうオフターゲット効果を示した。","origin":"off(外れて)+target(標的)+effects(効果)。狙った標的を「外れた」ところに出る副次的影響、と覚える。","collocations":["minimize off-target effects","off-target effects of","unintended off-target effects"]},"pathologies":{"example2":"Economists study the pathologies of markets that lead to speculative bubbles.","exampleJa2":"経済学者は、投機的バブルを招く市場の病理を研究する。","origin":"ギリシャ語 pathos(苦しみ・病)+logos(学問)。病気の性質・原因の意で、比喩的に「制度などの病巣」にも使う。","collocations":["underlying pathologies","neurodegenerative pathologies","study pathologies"]},"propagate":{"example2":"Panic selling can propagate across markets faster than any regulator can respond.","exampleJa2":"パニック売りは、どの規制当局が対応するよりも速く市場全体に伝播しうる。","origin":"ラテン語 propagare(挿し木で殖やす、pro: 前へ+pag-: 固定する)→広める。植物を殖やすように広がるイメージ。","collocations":["propagate rapidly","propagate misinformation","propagate across"]},"ambiguous":{"example2":"The contract's ambiguous wording left both parties disputing the payment terms.","exampleJa2":"その契約の曖昧な文言は、支払い条件をめぐって両当事者の争いを残した。","origin":"ラテン語 ambiguus(ambi: 両方+agere: 進む)→どちらへも取れる。両方向に解釈できる=多義的、と覚える。","collocations":["ambiguous wording","highly ambiguous","ambiguous results"]},"moratorium":{"example2":"The regulator imposed a moratorium on new crypto listings pending fresh rules.","exampleJa2":"規制当局は、新ルールが整うまで新規の暗号資産上場に一時停止措置を課した。","origin":"ラテン語 mora(遅延)→morari(遅らせる)+ium。支払いや活動を公式に「遅らせる・止める」措置。","collocations":["impose a moratorium","moratorium on","lift the moratorium"]},"exacerbating":{"example2":"Rising rates are exacerbating the debt burden on heavily leveraged firms.","exampleJa2":"金利の上昇は、負債の多い企業の債務負担をさらに悪化させている。","origin":"ラテン語 exacerbare(ex: 強調+acerbus: 苦い・厳しい)→より苦く厳しくする。acid(酸っぱい)と近く「一層きつくする」イメージ。","collocations":["exacerbate the problem","exacerbate tensions","further exacerbate"]},"formidable":{"example2":"The incumbent bank remains a formidable competitor for any fintech challenger.","exampleJa2":"既存の大手銀行は、どのフィンテック新興企業にとっても手強い競合であり続けている。","origin":"ラテン語 formidare(恐れる、formido: 恐怖)+able→恐れるべき。「恐怖を抱かせるほど強大」と覚える。","collocations":["formidable competitor","formidable challenge","formidable opponent"]},"fire":{"example2":"The team's Q4 pitch deck was absolutely fire and won the client instantly.","exampleJa2":"そのチームの第4四半期の提案資料は最高の出来で、即座に顧客を獲得した。","origin":"文字通りの「火」から。燃えるように熱く素晴らしい、という比喩。straight/absolutely fire の形でよく使う。","collocations":["straight fire","absolutely fire","that's fire"]},"slaps":{"example2":"The new product demo slaps—everyone in the meeting was impressed.","exampleJa2":"その新製品のデモは最高で、会議にいた全員が感心した。","origin":"「(音楽が)体を叩くほど響く」感覚から。ビートが強く効く→転じて「めちゃくちゃ良い」。this slaps の形で使う。","collocations":["this slaps","absolutely slaps","the beat slaps"]},"lowkey":{"example2":"I'm lowkey nervous about presenting the quarterly numbers tomorrow.","exampleJa2":"実は明日、四半期の数字をプレゼンするのがちょっと緊張している。","origin":"low(低い)+key(調子)→「低いトーンで」=控えめに・こっそり。反対は highkey(はっきり・大っぴらに)。","collocations":["lowkey obsessed","lowkey nervous","lowkey want"]},"flex":{"example2":"He couldn't resist flexing his year-end bonus in front of colleagues.","exampleJa2":"彼は同僚の前で年末ボーナスを見せびらかさずにはいられなかった。","origin":"本来は「筋肉に力こぶを作る(flex)」動作。力こぶを見せつける→「自慢する・見せびらかす」に転じたスラング。","collocations":["flex on","weird flex","flexing wealth"]},"gatekeep":{"example2":"Senior brokers used to gatekeep client contacts to protect their commissions.","exampleJa2":"ベテランのブローカーは、手数料を守るために顧客との接点を独占して手放さなかった。","origin":"gate(門)+keep(守る)→門番。有益な情報や趣味への「入口」を守り、他人を入れないイメージ。","collocations":["stop gatekeeping","gatekeep information","gatekeep access"]},"slay":{"example2":"She absolutely slayed the client presentation and closed the deal on the spot.","exampleJa2":"彼女は顧客プレゼンを完璧にキメて、その場で契約をまとめた。","origin":"古英語 slean(打ち殺す)由来で本来「殺す」。「(観客を)悩殺するほど圧倒する」→「完璧にやり遂げる」に転じた。","collocations":["slay the presentation","absolutely slayed","you slay"]},"no cap":{"example2":"This quarter's growth is the best we've ever had, no cap.","exampleJa2":"今四半期の成長は過去最高だ、マジで嘘じゃなく。","origin":"cap は「嘘・誇張」を指すスラング(帽子=かぶせる→ごまかす のイメージ)。no cap=盛っていない=本当に、と覚える。","collocations":["no cap","that's no cap","for real no cap"]},"sus":{"example2":"The vendor's invoice looked sus, so accounting flagged it for review.","exampleJa2":"その業者の請求書は怪しく見えたので、経理が確認のために印をつけた。","origin":"suspicious(疑わしい)の短縮形。ゲーム発の流行語で「なんか怪しい・違和感がある」。looks sus の形で使う。","collocations":["looks sus","kinda sus","acting sus"]},"mid":{"example2":"The analysts called the earnings report mid—solid but nothing to excite investors.","exampleJa2":"アナリストはその決算を微妙だと評した。堅実だが投資家を沸かせるものではない、と。","origin":"middle(真ん中)の略。良くも悪くもない「中くらい」→「平凡・大したことない」という否定的ニュアンス。","collocations":["honestly mid","kinda mid","it's mid"]},"glow-up":{"example2":"The rebranded fund had a real glow-up and doubled its inflows this year.","exampleJa2":"ブランド刷新したそのファンドは見事に生まれ変わり、今年は資金流入が倍増した。","origin":"glow(輝く)+up(向上)。内側から輝きが増すように、劇的に良くなる変化。grow up との語感のかけ合わせも。","collocations":["major glow-up","have a glow-up","glow-up transformation"]},"coin":{"example2":"The economist coined the term to describe the market's irrational optimism.","exampleJa2":"その経済学者は、市場の不合理な楽観を表すためにその用語を作り出した。","origin":"「硬貨を鋳造する(coin)」から。新しい貨幣を型で打ち出すように、新しい語を「造り出す」の比喩。","collocations":["coin a term","coin a phrase","coin the word"]},"go viral":{"example2":"The CEO's blunt earnings call clip went viral across financial Twitter overnight.","exampleJa2":"そのCEOの率直な決算説明の切り抜きは、一晩で金融系Twitter中に拡散した。","origin":"virus(ウイルス)から。ウイルスが感染で広がるように、コンテンツがネットで爆発的に広まる、と覚える。","collocations":["go viral","went viral overnight","viral video"]},"ghosting":{"example2":"The prospect went silent mid-deal—classic ghosting that frustrated the sales team.","exampleJa2":"見込み客は取引の途中で音信不通になった。営業チームを苛立たせる典型的なフェードアウトだ。","origin":"ghost(幽霊)+ing。幽霊のように、何の説明もなく突然消えて連絡を絶つこと。","collocations":["ghosting someone","get ghosted","ghosting after"]},"vibing":{"example2":"The whole team was vibing after landing the biggest account of the quarter.","exampleJa2":"四半期最大の顧客を獲得して、チーム全体がいい感じに盛り上がっていた。","origin":"vibe(vibration: 波動・雰囲気 の略)+ing。互いの「波長」が合って心地よい状態、と覚える。","collocations":["vibing with","just vibing","good vibing"]},"out of nowhere":{"example2":"The takeover bid came out of nowhere and sent the share price soaring.","exampleJa2":"その買収提案は突然どこからともなく現れ、株価を急騰させた。","origin":"「どこ(where)でもないところ(nowhere)から」の直訳。前触れも出所も見えないまま突然に、という慣用句。","collocations":["came out of nowhere","appear out of nowhere","hit out of nowhere"]},"the tea":{"example2":"So what's the tea on the merger everyone's whispering about?","exampleJa2":"それで、みんながひそひそ話してる例の合併の真相はどうなの?","origin":"T は truth(真実)の頭文字とも、お茶を飲みながら噂話をする文化からとも言われる。spill the tea=真相を暴露する。","collocations":["spill the tea","the tea on","what's the tea"]},"a whole vibe":{"example2":"The firm's new rooftop lounge is a whole vibe for entertaining clients.","exampleJa2":"その会社の新しい屋上ラウンジは、顧客をもてなすのに完全にいい雰囲気だ。","origin":"a whole(まるごと一つの)+vibe(雰囲気)。単なる雰囲気ではなく「それ自体が一つの世界観」という強調表現。","collocations":["a whole vibe","such a vibe","it's a whole vibe"]},"swipe":{"example2":"Users swipe through dozens of profiles before deciding whom to message.","exampleJa2":"ユーザーは、誰にメッセージを送るか決める前に何十ものプロフィールをスワイプして見る。","origin":"本来は「勢いよくこする・払う」動作。指で画面を払う動きに使われ、マッチングアプリの右/左スワイプが有名に。","collocations":["swipe right","swipe left","swipe through"]},"emotional labor":{"example2":"Client-facing bankers perform constant emotional labor to stay calm under pressure.","exampleJa2":"顧客対応の銀行員は、プレッシャーの中で平静を保つため絶えず感情労働をこなしている。","origin":"emotional(感情の、emotion: e 外へ+movere 動かす)+labor(労働)。感情を職務として管理・演出する労力、と覚える。","collocations":["perform emotional labor","emotional labor of","invisible emotional labor"]},"paradox of choice":{"example2":"Offering clients fifty fund options can trigger the paradox of choice and stall decisions.","exampleJa2":"顧客に50ものファンドを提示すると選択のパラドックスが生じ、意思決定が止まってしまうことがある。","origin":"paradox(para: 反して+doxa: 通念)+choice。選択肢が多いほど自由なはずが、逆に不安と迷いが増す逆説。","collocations":["the paradox of choice","suffer from the paradox of choice","too much choice"]},"grab coffee":{"example2":"Let's grab coffee next week to talk through the portfolio proposal.","exampleJa2":"来週コーヒーでも飲みながら、ポートフォリオの提案について話しましょう。","origin":"grab(さっとつかむ)+coffee。「サッとコーヒーを一杯」=気軽で肩肘張らない短い面会、というニュアンス。","collocations":["grab coffee","grab a coffee sometime","want to grab coffee"]},"attentive":{"example2":"An attentive advisor notices when a client's risk tolerance quietly shifts.","exampleJa2":"気配りのあるアドバイザーは、顧客のリスク許容度が静かに変化したことに気づく。","origin":"ラテン語 attendere(ad: 〜へ+tendere: 伸ばす)→注意を向ける+ive。attend(注意を向ける)と同語源。","collocations":["attentive to","an attentive listener","attentive service"]},"grinding":{"example2":"She was grinding through spreadsheets until midnight before the earnings release.","exampleJa2":"彼女は決算発表前、深夜までスプレッドシートと格闘して必死に働いていた。","origin":"grind(すり潰す)から。石臼でコツコツ砕き続けるイメージが「地道に長時間働き続ける」意味に転じたスラング。","collocations":["grinding all week","keep grinding","grinding through work"]},"hustling":{"example2":"He spent his twenties hustling, cold-calling clients and chasing every lead.","exampleJa2":"彼は20代を、飛び込み営業であらゆる見込み客を追いかけながら奮闘して過ごした。","origin":"オランダ語hutselen(揺さぶる)が語源。押し合いへし合いする様子が「精力的に動き回って稼ぐ」意味に発展した。","collocations":["hustling hard","side hustle","hustling for clients"]},"quiet quitting":{"example2":"Managers worry that quiet quitting is quietly eroding the team's productivity.","exampleJa2":"マネージャーたちは、静かな退職がチームの生産性をじわじわ蝕んでいると懸念している。","origin":"quiet(静かに)+quitting(辞める)。実際には辞めず、心だけ退職して最低限しか働かない状態を指す2022年頃の造語。","collocations":["quiet quitting trend","embrace quiet quitting","combat quiet quitting"]},"bounce":{"example2":"The meeting ran long, so half the team bounced before the Q&A.","exampleJa2":"会議が長引いたので、チームの半分は質疑応答の前に帰ってしまった。","origin":"ボールが弾んで飛んでいくイメージから「その場からさっと立ち去る」意味に。軽いノリで使うカジュアル表現。","collocations":["gonna bounce","bounce early","let's bounce"]},"shook":{"example2":"Investors were shook when the CEO resigned without any warning.","exampleJa2":"CEOが何の前触れもなく辞任し、投資家たちは動揺した。","origin":"shake(揺さぶる)の過去形shookを形容詞化。「心を揺さぶられた」状態をそのまま表すヒップホップ由来のスラング。","collocations":["totally shook","left me shook","shook by the news"]},"not about that life":{"example2":"Answering emails at midnight? Sorry, I'm not about that life anymore.","exampleJa2":"深夜にメール対応？悪いけど、そういう生活はもう御免だね。","origin":"「そのライフスタイル(that life)の住人ではない」という発想。自分の流儀に合わないと距離を置く決め台詞と覚える。","collocations":["I'm not about that life","not about that hustle life"]},"hits different":{"example2":"Closing a deal after months of negotiation just hits different.","exampleJa2":"何か月も交渉を重ねた末に契約をまとめると、格別な達成感がある。","origin":"hit(心に響く)+different(いつもと違って)。「同じものでも状況次第で響き方が違う」という感覚をそのまま表現。","collocations":["it hits different","hits different at night"]},"burnout":{"example2":"The bank introduced mandatory vacations to reduce burnout among junior analysts.","exampleJa2":"その銀行は若手アナリストの燃え尽き症候群を減らすため、休暇取得を義務化した。","origin":"burn(燃える)+out(尽きる)。ロウソクが燃え尽きるように、心身のエネルギーが枯渇するイメージの比喩表現。","collocations":["employee burnout","suffer from burnout","prevent burnout"]},"clock in":{"example2":"Warehouse staff must clock in before their shift starts at six.","exampleJa2":"倉庫のスタッフは6時のシフト開始前にタイムカードを押さなければならない。","origin":"clock(時計)に打刻して出勤を記録することから。タイムレコーダーに時刻を刻む動作がそのまま句動詞になった。","collocations":["clock in at nine","clock in and out","forget to clock in"]},"laid off":{"example2":"After the merger, hundreds of back-office employees were laid off.","exampleJa2":"合併後、数百人のバックオフィス部門の従業員が解雇された。","origin":"lay off(横に置く)から。仕事から人を「一時的に外へ置く」イメージ。本人の落ち度でなく会社都合の解雇を指す。","collocations":["get laid off","laid off workers","be laid off from a job"]},"recalibration":{"example2":"Weak inflation data forced a recalibration of the bank's rate forecasts.","exampleJa2":"弱いインフレ指標を受け、銀行は金利予測の再調整を迫られた。","origin":"re(再び)+calibrate(目盛りを合わせる)+ion。計器の目盛りを合わせ直すように、方針や見立てを修正するイメージ。","collocations":["policy recalibration","a major recalibration","recalibration of strategy"]},"salty":{"example2":"He's still salty about being passed over for the promotion.","exampleJa2":"彼は昇進を見送られたことをいまだに根に持ってイラついている。","origin":"salt(塩)から。悔し涙のしょっぱさ、または船乗りの荒っぽい気性が由来とされる。「塩対応」的な不機嫌さと覚える。","collocations":["get salty","salty about losing","don't be salty"]},"snatched":{"example2":"She showed up to the client dinner looking absolutely snatched.","exampleJa2":"彼女はクライアントとのディナーに、完璧にキマった姿で現れた。","origin":"snatch(ひったくる)から。「息をのむほど良くて心を奪われる」イメージ。ドラァグカルチャー発の褒め言葉。","collocations":["looking snatched","snatched waist","absolutely snatched"]},"thirsty":{"example2":"Replying to every single comment within seconds looks a bit thirsty.","exampleJa2":"全部のコメントに秒速で返信するのは、ちょっと必死すぎに見えるよ。","origin":"thirst(渇き)から。注目や好意に「喉が渇いたように飢えている」様子の比喩。承認欲求むき出しの状態を指す。","collocations":["so thirsty","thirsty for attention","thirsty behavior"]},"roast":{"example2":"The whole office roasted him for wearing socks with sandals.","exampleJa2":"サンダルに靴下を合わせてきた彼を、オフィス中がいじり倒した。","origin":"roast(あぶり焼きにする)から。火であぶるように容赦なくいじる意味。米国では有名人を公開でいじるroast番組も定番。","collocations":["roast someone","get roasted","a friendly roast"]},"baked":{"example2":"The lyrics joke about getting baked and forgetting the chorus.","exampleJa2":"その歌詞は、大麻でキマってサビを忘れてしまうことをネタにしている。","origin":"bake(焼ける)から。頭がオーブンで焼かれたようにぼんやりする状態の比喩。stoned、highと同系統のスラング。","collocations":["completely baked","get baked","look baked"]},"spill the tea":{"example2":"Come on, spill the tea—what really happened in that board meeting?","exampleJa2":"さあ白状して。あの取締役会で本当は何があったの？","origin":"tea(=gossip、噂話)をspill(こぼす)で「秘密を漏らす」。ドラァグカルチャー発。Tはtruth(真実)の頭文字という説も。","collocations":["spill the tea","spill all the tea","the tea is hot"]},"petty":{"example2":"Refusing to greet a colleague over a parking spot is just petty.","exampleJa2":"駐車スペースのことで同僚に挨拶しないなんて、ただの器の小ささだよ。","origin":"フランス語petit(小さい)から。「些細なことにこだわる＝心が小さい」と意味が発展。スラングでは半ば自虐的にも使う。","collocations":["so petty","petty drama","being petty"]},"drag culture":{"example2":"Documentaries about drag culture introduced its slang to mainstream audiences.","exampleJa2":"ドラァグカルチャーを扱ったドキュメンタリーが、そのスラングを一般層に広めた。","origin":"dragは「引きずる」から。長いドレスの裾を引きずって歩いたことが由来という説が有力。舞台文化として発展した。","collocations":["drag culture icons","rooted in drag culture","drag queen culture"]},"trajectory":{"example2":"Analysts questioned whether the fund's return trajectory was sustainable.","exampleJa2":"アナリストたちは、そのファンドのリターンの軌道が持続可能か疑問視した。","origin":"ラテン語trans(越えて)+jacere(投げる)→「投げられた物の軌道」。ミサイルの弾道から人生やビジネスの進路まで使う。","collocations":["growth trajectory","career trajectory","on an upward trajectory"]},"validation":{"example2":"Good managers give validation through specific praise, not empty compliments.","exampleJa2":"良い上司は、中身のないお世辞ではなく具体的な称賛で承認を与える。","origin":"ラテン語validus(強い)が語源。valid(有効な)+ation。「あなたの存在は有効だ」と認めてもらう感覚と覚える。","collocations":["seek validation","external validation","need for validation"]},"rizz":{"example2":"His natural rizz makes even cold sales calls feel like friendly chats.","exampleJa2":"彼は生まれつきの人たらし力で、飛び込み営業の電話すら和やかな雑談にしてしまう。","origin":"charisma(カリスマ)の中間音「リズ」を切り出した略語。2023年頃にZ世代で爆発的に流行し、辞書にも載った。","collocations":["have rizz","serious rizz","rizz someone up"]},"main character energy":{"example2":"She negotiated her salary with pure main character energy and won.","exampleJa2":"彼女は主人公級の堂々とした自信で給与交渉に臨み、勝ち取った。","origin":"映画やドラマのmain character(主人公)のように振る舞うenergy(オーラ)。自分の人生の主役を張る自信、と覚える。","collocations":["main character energy","give main character energy"]},"delulu":{"example2":"Expecting a 50 percent return every year? That's honestly delulu.","exampleJa2":"毎年50％のリターンを期待するって？正直それは妄想レベルだよ。","origin":"delusional(妄想的な)を可愛く縮めたZ世代スラング。K-POPファン界隈発祥。「デルル」と響きが軽い分、冗談めかして使える。","collocations":["totally delulu","delulu era","being delulu"]},"ick":{"example2":"Bragging about money on the first date gave her the ick.","exampleJa2":"初デートでお金自慢をされて、彼女は一瞬で冷めてしまった。","origin":"「うえっ」という嫌悪の擬音ickが名詞化。恋愛リアリティ番組発で、「好意が一瞬で消える瞬間」を指す言葉として定着。","collocations":["give someone the ick","a major ick","get the ick"]},"unbothered":{"example2":"Despite the market selloff, the veteran trader stayed completely unbothered.","exampleJa2":"市場の急落にもかかわらず、そのベテラントレーダーは全く動じなかった。","origin":"un(否定)+bothered(悩まされた)。「何にも煩わされていない」余裕の状態。SNSでは「動じない私」を示す定番語。","collocations":["stay unbothered","completely unbothered","unbothered energy"]},"owns it":{"example2":"When the forecast missed badly, she owned it in front of the whole team.","exampleJa2":"予測が大きく外れたとき、彼女はチーム全員の前で堂々とそれを認めた。","origin":"own(所有する)から。「状況やミスを自分のものとして引き受ける」イメージ。失敗を隠さず堂々と認める姿勢を表す。","collocations":["own it","totally owned it","own the stage"]},"swagger":{"example2":"The new fund manager brought a confident swagger to the trading floor.","exampleJa2":"新任のファンドマネージャーは、トレーディングフロアに自信に満ちた雰囲気を持ち込んだ。","origin":"swag(揺れる)+頻繁を表す-er。肩で風を切って歩く様子から。シェイクスピアも使った古い語で、現代ではswagとも略す。","collocations":["walk with swagger","confident swagger","lose one's swagger"]},"moxie":{"example2":"It took real moxie to challenge the CFO's numbers in that meeting.","exampleJa2":"あの会議でCFOの数字に異を唱えるとは、相当な度胸が必要だった。","origin":"1900年代米国の強壮飲料「Moxie」のブランド名から。「これを飲めば元気が出る」イメージが「度胸・気概」の意味に転じた。","collocations":["have the moxie","real moxie","takes moxie"]},"repackaged":{"example2":"The bank repackaged risky loans into products that looked deceptively safe.","exampleJa2":"その銀行はリスクの高いローンを、一見安全に見える商品へと包み直した。","origin":"re(再び)+package(包装する)。中身は同じでも包み紙を替えて新しく見せるイメージ。金融でも証券化の文脈で頻出。","collocations":["repackaged as new","repackaged products","repackage an idea"]},"authenticity":{"example2":"Clients can sense authenticity, and it builds trust faster than any pitch.","exampleJa2":"顧客は本物かどうかを敏感に感じ取る。それはどんな売り込みよりも早く信頼を築く。","origin":"ギリシャ語authentes(自分自身で行う人)が語源。author(作者)と同根。「自分自身に忠実＝本物」という流れで覚える。","collocations":["value authenticity","brand authenticity","a sense of authenticity"]},"aave":{"example2":"Linguists study AAVE as a rule-governed dialect, not broken English.","exampleJa2":"言語学者はAAVEを、崩れた英語ではなく規則性を持つ方言として研究している。","origin":"African American Vernacular Englishの頭字語。vernacularは「土着の言葉」。多くの米スラングの源流となった方言。","collocations":["AAVE speakers","borrowed from AAVE","AAVE grammar"]},"lit":{"example2":"The launch party was lit—half the industry showed up.","exampleJa2":"ローンチパーティーは最高に盛り上がった。業界の半分が集まったほどだ。","origin":"light(火をつける)の過去分詞。元は「酔った」の意味で、「場に火がついたように盛り上がる」イメージへ発展した。","collocations":["absolutely lit","the party was lit","it's lit"]},"woke":{"example2":"The brand's woke advertising drew both praise and heavy criticism.","exampleJa2":"そのブランドの社会派広告は、称賛と激しい批判の両方を招いた。","origin":"wake(目覚める)の過去形。AAVE発で「社会の不正に目覚めている」意味。近年は皮肉として使われる意味の逆転が起きた語。","collocations":["stay woke","woke culture","go woke"]},"shade":{"example2":"Her polite congratulations contained just a hint of shade.","exampleJa2":"彼女の丁寧なお祝いの言葉には、ほんのりと嫌味が混じっていた。","origin":"shade(影)から。「正面から攻撃せず、影を落とすように遠回しにけなす」イメージ。ドラァグカルチャー発の表現。","collocations":["throw shade","subtle shade","no shade"]},"fam":{"example2":"Thanks for covering my shift, fam—I owe you one.","exampleJa2":"シフト代わってくれてありがとう。この借りは返すよ。","origin":"family(家族)の短縮形。血縁でなくても「家族同然の仲間」への呼びかけに使う。AAVE・英国スラング双方で定着。","collocations":["thanks fam","my fam","what's good fam"]},"periodt":{"example2":"We don't work for free in this house, periodt.","exampleJa2":"うちはタダ働きは絶対にしない。以上。","origin":"period(ピリオド＝文の終止符)を強調してtを付けた形。「議論はここで終わり、反論不要」の決め台詞。黒人・ドラァグ文化発。","collocations":["periodt","and that's that, periodt"]},"finna":{"example2":"It's almost five—I'm finna wrap up and head home.","exampleJa2":"もうすぐ5時だ。そろそろ切り上げて帰るつもりだよ。","origin":"fixing to(〜する準備をしている)が縮まった形。fixin' to→finna。AAVE・米南部方言で「まさに〜しようとしている」。","collocations":["finna leave","finna be late","I'm finna go"]},"cultural appropriation":{"example2":"The fashion label faced backlash over cultural appropriation of indigenous designs.","exampleJa2":"そのファッションブランドは、先住民のデザインを文化盗用したとして批判を浴びた。","origin":"appropriationはラテン語ad(自分に)+proprius(固有の)→「自分のものにする」。他文化の要素を敬意なく奪う行為を指す。","collocations":["accusations of cultural appropriation","cultural appropriation debate"]},"stigmatize":{"example2":"Workplace culture often stigmatizes employees who take long parental leave.","exampleJa2":"職場文化はしばしば、長期の育児休暇を取る従業員に負のレッテルを貼る。","origin":"ギリシャ語stigma(焼き印)から。奴隷や罪人に押した焼き印のように、消えない汚名を着せるイメージ。","collocations":["stigmatize mental illness","be stigmatized","stigmatize a group"]},"double standard":{"example2":"Critics see a double standard in how regulators treat big banks and small lenders.","exampleJa2":"批判者は、規制当局の大手銀行と中小金融機関への扱いに二重基準があると見ている。","origin":"double(二重の)+standard(基準)。同じ行為でも相手によって物差しを使い分ける不公平さ。19世紀の男女規範批判が起源。","collocations":["a clear double standard","apply a double standard","gender double standard"]},"glaring":{"example2":"The audit revealed glaring errors in the fund's risk reports.","exampleJa2":"監査により、そのファンドのリスク報告書に明白な誤りがあることが判明した。","origin":"glare(ギラギラ光る・にらむ)から。目を突き刺す光のように「無視できないほど目立つ」欠点や差を形容する。","collocations":["glaring error","glaring gap","glaring omission"]},"bet":{"example2":"Can you send me the report by noon? Bet, no problem.","exampleJa2":"正午までにレポート送ってくれる？了解、問題ないよ。","origin":"bet(賭ける)から。「それに賭けてもいい＝確実にやる、了解」の意味に。you betの短縮と考えると覚えやすい。","collocations":["bet, see you then","aight bet","say bet"]},"say less":{"example2":"You'll cover dinner if I book the flights? Say less.","exampleJa2":"航空券を取ってくれたら夕食はおごってくれるって？もうそれ以上言わなくていいよ、乗った。","origin":"「これ以上言わなくていい(say less)＝もう完全に理解して乗り気」という逆説的な同意表現。say no moreの若者版。","collocations":["say less, I'm in","say less fam"]},"i'm dead":{"example2":"He replied to the CEO with a cat meme by accident—I'm dead.","exampleJa2":"彼、間違えてCEOに猫のミームで返信したんだって。笑い死ぬ。","origin":"「笑いすぎて死んだ」という誇張表現。日本語の「死ぬほどウケる」と同じ発想で覚えやすい。骸骨の絵文字も同義。","collocations":["I'm dead","I'm literally dead","dead at this"]},"sent me":{"example2":"The typo in the official press release absolutely sent me.","exampleJa2":"公式プレスリリースの誤字に、思わず大笑いしてしまった。","origin":"send(送り出す)から。「笑いで別世界に送り飛ばされた」イメージ。it sent me flyingの省略と考えると掴みやすい。","collocations":["that sent me","absolutely sent me","this video sent me"]},"it be like that":{"example2":"The deal collapsed at the last minute, but hey, it be like that.","exampleJa2":"取引は土壇場で破談になったけど、まあ、そういうもんだよ。","origin":"AAVEの習慣beを使った表現。「世の中いつもそういうふうにあるものだ」という達観・諦めのニュアンス。sometimesを付けても定番。","collocations":["it be like that sometimes","sometimes it really do be like that"]},"speedrun":{"example2":"The new hire basically speedran the entire onboarding checklist in two days.","exampleJa2":"その新人は、研修チェックリスト全体をわずか2日で高速クリアしてしまった。","origin":"speed(速さ)+run(走破)。ゲームを最短時間でクリアする競技用語が、現実のタスクを爆速でこなす意味に拡大した。","collocations":["speedrun a game","speedrun a degree","speedrun through tasks"]},"versatile":{"example2":"ETFs are versatile instruments suitable for both hedging and long-term investing.","exampleJa2":"ETFはヘッジにも長期投資にも使える万能な金融商品だ。","origin":"ラテン語versare(回転させる)から。「くるくる向きを変えられる＝どんな用途にも対応できる」。versionと同根。","collocations":["versatile tool","highly versatile","versatile player"]},"affirmative":{"example2":"When asked if the merger would proceed, the spokesperson gave an affirmative reply.","exampleJa2":"合併は進むのかと問われ、広報担当者は肯定的な回答をした。","origin":"ラテン語ad(〜へ)+firmare(固める)→「しっかり固めて認める」。firm(固い)が入っていると気づくと覚えやすい。","collocations":["an affirmative answer","respond in the affirmative","affirmative action"]},"figuratively":{"example2":"The market figuratively held its breath before the Fed's announcement.","exampleJa2":"FRBの発表を前に、市場は比喩的に言えば息を殺して見守った。","origin":"figure(形・比喩表現)+atively。figure of speech(比喩)由来で「文字通りでなく喩えとして」。literallyの対義語。","collocations":["figuratively speaking","literally and figuratively"]},"compression":{"example2":"Margin compression forced the retailer to renegotiate supplier contracts.","exampleJa2":"利益率の圧縮を受けて、その小売業者は仕入先との契約を再交渉せざるを得なかった。","origin":"ラテン語com(共に)+premere(押す)→「押し縮める」。press(押す)が中に入っていると分解すれば意味が見える。","collocations":["data compression","margin compression","spread compression"]},"streamlines":{"example2":"Automation streamlines client onboarding, cutting paperwork from days to hours.","exampleJa2":"自動化により顧客の受け入れ手続きが効率化され、書類作業が数日から数時間に短縮された。","origin":"stream(流れ)+line(線)。水の流れに沿った抵抗の少ない流線形から、「無駄を削いで滑らかにする」意味に発展。","collocations":["streamline the process","streamline operations","streamline workflow"]},"cancel culture":{"example2":"Some executives self-censor on social media out of fear of cancel culture.","exampleJa2":"一部の経営幹部は、キャンセルカルチャーを恐れてSNSでの発言を自主規制している。","origin":"cancel(契約を取り消す)から。「人を番組打ち切りのように切り捨てる」発想。支持撤回と社会的制裁を伴うネット文化。","collocations":["a victim of cancel culture","cancel culture debate","fear of cancel culture"]},"calling out":{"example2":"Employees are increasingly calling out pay gaps on internal forums.","exampleJa2":"従業員たちは社内フォーラムで、賃金格差をますます公然と指摘するようになっている。","origin":"call(呼ぶ)+out(外へ)。「問題を人前に呼び出して晒す」イメージ。決闘の呼び出しが由来という説もある。","collocations":["call out injustice","call someone out","call out bad behavior"]},"virtue signaling":{"example2":"Posting a green logo without changing operations is just virtue signaling.","exampleJa2":"事業を変えずにロゴを緑にするだけでは、単なる美徳シグナリングにすぎない。","origin":"virtue(美徳)+signaling(発信)。経済学のシグナリング理論を援用し、「善行の中身より善人アピール」を皮肉る造語。","collocations":["mere virtue signaling","accused of virtue signaling","corporate virtue signaling"]},"receipts":{"example2":"When he denied the promise, she pulled out the receipts—his own emails.","exampleJa2":"彼が約束を否定すると、彼女は動かぬ証拠、つまり彼自身のメールを突きつけた。","origin":"receipt(レシート)から。「購入を証明するレシート」のように言動を証明するスクショや記録を指す。歌手ホイットニーの発言が有名。","collocations":["show the receipts","keep receipts","post receipts"]},"pejorative":{"example2":"In some circles, 'salesman' has become an almost pejorative label.","exampleJa2":"一部の界隈では、「セールスマン」はほとんど軽蔑的なレッテルになってしまった。","origin":"ラテン語pejor(より悪い)から。「意味をより悪い方向へ引きずり下げる」語。worse(より悪い)のラテン語版と覚える。","collocations":["a pejorative term","in a pejorative sense","become pejorative"]},"performative":{"example2":"Their sustainability pledge felt performative, with no measurable targets attached.","exampleJa2":"その持続可能性の誓約は、測定可能な目標が何もなく、見せかけに感じられた。","origin":"perform(演じる)+ative。舞台の演技のように「観客向けのポーズ」を指す。哲学用語から転じてSNS時代の批判語に。","collocations":["performative activism","feel performative","performative allyship"]},"semantic inversion":{"example2":"The word 'sick' meaning 'excellent' is a classic semantic inversion.","exampleJa2":"「sick(病気の)」が「最高」を意味するのは、典型的な意味の逆転だ。","origin":"semantic(意味の)+inversion(逆転)。ギリシャ語sema(記号)とラテン語in+vertere(ひっくり返す)の組み合わせ。","collocations":["undergo semantic inversion","a case of semantic inversion"]},"smoking gun":{"example2":"The auditors found the smoking gun: a hidden account in the CFO's name.","exampleJa2":"監査人たちは動かぬ証拠を見つけた。CFO名義の隠し口座である。","origin":"発砲直後の「煙の出ている銃」を持つ者が犯人、という推理小説的発想。シャーロック・ホームズの一場面が起源とされる。","collocations":["find the smoking gun","smoking gun evidence","no smoking gun"]},"wielded":{"example2":"The activist investor wielded her voting power to force a board shakeup.","exampleJa2":"そのアクティビスト投資家は議決権を行使し、取締役会の刷新を迫った。","origin":"古英語wealdan(支配する)から。元は剣や斧を「振るう」意味で、武器から権力・影響力へと対象が広がった。","collocations":["wield power","wield influence","wield authority"]},"accountability":{"example2":"Investors demanded greater accountability after the fund's undisclosed losses.","exampleJa2":"ファンドの非開示損失を受け、投資家たちはより強い説明責任を求めた。","origin":"account(説明・勘定)+ability(できること)。「自分の勘定を説明できる状態」が原義。会計と責任が同語源なのが面白い。","collocations":["demand accountability","hold someone accountable","public accountability"]},"touch grass":{"example2":"If a stock forum ruins your mood daily, log off and touch grass.","exampleJa2":"株の掲示板で毎日気分が悪くなるなら、ログアウトして外の空気を吸いなよ。","origin":"「芝生に触れる＝画面から離れて現実世界を体感する」というネットスラング。屋内に籠るゲーマーへの皮肉が起源。","collocations":["go touch grass","needs to touch grass","touch some grass"]},"chronically online":{"example2":"That take is so chronically online—nobody in real life talks like that.","exampleJa2":"その意見は完全にネット漬けの発想だよ。現実で誰もそんな話し方はしない。","origin":"chronic(慢性の)は医学用語。ギリシャ語chronos(時間)から。「病的に長時間オンライン」という診断風の皮肉表現。","collocations":["chronically online behavior","a chronically online take"]},"brain rot":{"example2":"He blames his short attention span on years of brain rot content.","exampleJa2":"彼は自分の集中力の短さを、長年の低質コンテンツ漬けのせいにしている。","origin":"brain(脳)+rot(腐敗)。低俗コンテンツで脳が腐るイメージ。19世紀の思想家ソローも使った古い語で、2024年に流行語復活。","collocations":["brain rot content","pure brain rot","TikTok brain rot"]},"doomscroller":{"example2":"As a recovering doomscroller, she now checks headlines only twice a day.","exampleJa2":"ドゥームスクロール癖から立ち直りつつある彼女は、今ではニュースを1日2回しか見ない。","origin":"doom(破滅)+scroll(画面をスクロール)+er(人)。破滅的なニュースを延々と追ってしまう人。コロナ禍で定着した造語。","collocations":["a habitual doomscroller","stop doomscrolling","late-night doomscrolling"]},"unhinged":{"example2":"The brand's unhinged marketing tweets somehow doubled its follower count.","exampleJa2":"そのブランドの常軌を逸したマーケティング投稿は、なぜかフォロワー数を倍増させた。","origin":"un(外れた)+hinge(蝶番)。「扉の蝶番が外れてグラグラ」なイメージから、精神のタガが外れた状態を表す。","collocations":["completely unhinged","unhinged behavior","an unhinged rant"]},"terminally":{"example2":"My coworker is terminally curious—he reads every footnote in every report.","exampleJa2":"同僚は末期的に好奇心が強く、あらゆるレポートの脚注まで全部読む。","origin":"terminal(終末の)+ly。ラテン語terminus(境界・終点)から。terminally ill(末期患者)の医療表現を誇張比喩に転用。","collocations":["terminally online","terminally bored","terminally ill"]},"catastrophize":{"example2":"Traders who catastrophize every dip rarely stick to their strategy.","exampleJa2":"下落のたびに最悪の事態を想像するトレーダーは、めったに自分の戦略を貫けない。","origin":"ギリシャ語katastrophe(kata=下へ+strophe=転回)→「破滅」+ize(〜化する)。心理学用語で「破滅思考をする」こと。","collocations":["tend to catastrophize","stop catastrophizing","catastrophize the situation"]},"plugged in":{"example2":"Stay plugged in to regulatory changes if you work in asset management.","exampleJa2":"資産運用業界で働くなら、規制の変更に常にアンテナを張っておくべきだ。","origin":"plug in(プラグを差し込む)から。電源やネットに接続しているように「情報の流れに繋がっている」状態の比喩。","collocations":["plugged in to trends","stay plugged in","well plugged in"]},"self-aware":{"example2":"A self-aware leader admits weaknesses before others point them out.","exampleJa2":"自己認識のあるリーダーは、他人に指摘される前に自分の弱点を認める。","origin":"self(自己)+aware(気づいている)。awareは古語のwary(用心深い)と同根。「自分自身を警戒的に観察できる」と覚える。","collocations":["deeply self-aware","self-aware humor","become more self-aware"]},"blunt":{"example2":"To be blunt, this proposal won't survive the compliance review.","exampleJa2":"率直に言うと、この提案はコンプライアンス審査を通らないだろう。","origin":"元は「刃が鈍い」の意味。「切れ味鋭い婉曲表現を使わず、鈍器のようにズバッと言う」イメージで「率直な」に転じた。","collocations":["blunt feedback","to be blunt","brutally blunt"]},"understood the assignment":{"example2":"The intern's market summary was so sharp—she understood the assignment.","exampleJa2":"インターンの市場サマリーは実に的確だった。期待に完璧に応えたね。","origin":"「課題(assignment)の意図を正しく理解して完璧に応えた」が原義。TikTok発で、服装や演技が「わかってる」時の称賛に。","collocations":["totally understood the assignment","she understood the assignment"]},"that tracks":{"example2":"The stock dropped after the CEO sold shares? Yeah, that tracks.","exampleJa2":"CEOが株を売却した後に株価が下がった？ああ、それは筋が通るね。","origin":"track(軌道をたどる)から。「話の筋道が線路のようにきちんと繋がっている＝辻褄が合う」というイメージ。","collocations":["yeah, that tracks","that tracks with what I heard"]},"big yikes":{"example2":"He hit reply-all with his salary complaints—big yikes.","exampleJa2":"彼、給料の愚痴を全員返信で送っちゃったんだって。うわぁ…。","origin":"yikes(うわっ、という驚きの間投詞)にbigを付けた強調形。他人の失態への「見ているこっちが恥ずかしい」感覚を表す。","collocations":["big yikes moment","that's a big yikes"]},"it's giving":{"example2":"Marble lobby, espresso bar, no employees—it's giving startup burn rate.","exampleJa2":"大理石のロビーにエスプレッソバー、なのに社員はいない。いかにも資金を溶かすスタートアップの雰囲気だ。","origin":"give off(雰囲気を放つ)の短縮から。「〜の空気を醸し出している」。ドラァグ・ボールカルチャー由来でZ世代に定着。","collocations":["it's giving luxury","it's giving main character"]},"cringe":{"example2":"The forced office birthday song is peak cringe every single time.","exampleJa2":"強制参加のオフィスの誕生日ソングは、毎回最高にイタい。","origin":"元は「身をすくめる」という動詞。他人の言動で思わず体が縮こまる感覚から、「見てて恥ずかしい」の形容詞に転じた。","collocations":["so cringe","cringe content","peak cringe"]},"here for it":{"example2":"Remote Fridays and no more status meetings? I'm so here for it.","exampleJa2":"金曜は在宅勤務で進捗会議も廃止？大賛成だね。","origin":"「私はそのためにここにいる(here for it)＝全力で支持する」という発想。推し活的な熱量のこもった賛成表現。","collocations":["I'm here for it","so here for it","totally here for it"]},"mashup":{"example2":"The conference felt like a mashup of finance seminar and music festival.","exampleJa2":"そのカンファレンスは、金融セミナーと音楽フェスを混ぜ合わせたような雰囲気だった。","origin":"mash(すり潰して混ぜる)+up。マッシュポテトのmash。2曲を混ぜるDJ文化から、異分野の組み合わせ全般に拡大。","collocations":["a mashup of genres","create a mashup","culture mashup"]},"crossover":{"example2":"Her crossover from banking to fintech surprised no one who knew her.","exampleJa2":"彼女の銀行からフィンテックへの転身は、彼女を知る人にとって驚きではなかった。","origin":"cross(横切る)+over(越えて)。ジャンルや業界の境界線を「またぎ越える」イメージ。音楽・車・アニメ等で頻出。","collocations":["crossover hit","crossover appeal","a crossover episode"]},"palpable":{"example2":"The relief on the trading floor was palpable when the deal closed.","exampleJa2":"取引が成立したとき、トレーディングフロアには安堵の空気がはっきりと感じられた。","origin":"ラテン語palpare(手で触れる)から。「触れられるほど明白な」が原義。palpation(触診)と同根で、医療用語でもある。","collocations":["palpable tension","palpable excitement","almost palpable"]},"ground zero":{"example2":"This small lab became ground zero for the AI boom.","exampleJa2":"この小さな研究所が、AIブームの震源地となった。","origin":"元は核爆発の爆心地を指す軍事用語。zero point(爆心)の地上地点。転じて「物事が始まった中心地」の意味に広がった。","collocations":["ground zero for the crisis","become ground zero"]},"jargon":{"example2":"Avoid jargon when explaining investment products to first-time clients.","exampleJa2":"初めての顧客に投資商品を説明するときは、専門用語を避けなさい。","origin":"古フランス語で「鳥のさえずり」が原義。部外者には鳥の鳴き声のように聞こえる、意味不明な業界語というイメージ。","collocations":["technical jargon","financial jargon","cut the jargon"]},"central bank independence":{"example2":"Attacks on central bank independence often rattle bond markets.","exampleJa2":"中央銀行の独立性への攻撃は、しばしば債券市場を動揺させる。","origin":"independenceはin(否定)+depend(ぶら下がる)→「誰にもぶら下がらない」。政府の顔色を見ずに政策を決める体制を指す。","collocations":["defend central bank independence","erode central bank independence"]},"monetary policy":{"example2":"Loose monetary policy pushed investors into riskier assets.","exampleJa2":"緩和的な金融政策は、投資家をよりリスクの高い資産へと向かわせた。","origin":"monetaryはラテン語moneta(貨幣)から。ローマの造幣所があったユノ・モネタ神殿が語源。money、mintと同根。","collocations":["tighten monetary policy","loose monetary policy","monetary policy stance"]},"price stability":{"example2":"The ECB treats price stability as its overriding objective.","exampleJa2":"欧州中央銀行は物価安定を最優先の目標としている。","origin":"stabilityはラテン語stare(立つ)から。「物価がしっかり立って動かない」状態。stable(安定した・馬小屋)と同根。","collocations":["maintain price stability","ensure price stability","price stability mandate"]},"political business cycle":{"example2":"Pre-election tax cuts are a textbook political business cycle move.","exampleJa2":"選挙前の減税は、政治的景気循環の教科書的な一手だ。","origin":"「選挙(political)に合わせて景気(business cycle)を操作する」現象。選挙前に景気を良くし、後でツケを払う構図と覚える。","collocations":["political business cycle theory","evidence of a political business cycle"]},"stagflation":{"example2":"Rising oil prices revived fears of 1970s-style stagflation.","exampleJa2":"原油価格の上昇が、1970年代型のスタグフレーションへの懸念を再燃させた。","origin":"stagnation(停滞)+inflation(インフレ)の混成語。景気停滞と物価上昇という「本来同居しない二つ」が併存する造語。","collocations":["stagflation fears","risk of stagflation","1970s stagflation"]},"autonomy":{"example2":"The subsidiary operates with considerable autonomy from headquarters.","exampleJa2":"その子会社は本社からかなりの自律性をもって運営されている。","origin":"ギリシャ語auto(自分)+nomos(法)→「自分の法で治める」。自動のautoと経済のeconomyのnomosを組み合わせて覚える。","collocations":["grant autonomy","full autonomy","operational autonomy"]},"political interference":{"example2":"The rating agency warned that political interference could trigger a downgrade.","exampleJa2":"格付け会社は、政治的干渉が格下げの引き金になりかねないと警告した。","origin":"interfereはラテン語inter(間に)+ferire(打つ)→「間に割り込んで打つ」。本来独立した領域に政治が割り込むこと。","collocations":["political interference in policy","free from political interference"]},"dual mandate":{"example2":"Balancing the dual mandate is hardest when inflation and unemployment rise together.","exampleJa2":"インフレと失業率が同時に上昇するとき、二つの使命の両立は最も難しくなる。","origin":"dualはラテン語duo(2)、mandateはmanus(手)+dare(与える)→「手に委ねられた命令」。FRBの雇用と物価の二大目標。","collocations":["the Fed's dual mandate","fulfill the dual mandate","dual mandate framework"]},"democratic deficit":{"example2":"Critics argue the EU suffers from a persistent democratic deficit.","exampleJa2":"批判者たちは、EUが慢性的な民主主義の欠如を抱えていると主張する。","origin":"deficitはラテン語deficere(不足する)から。財政赤字と同じ語で、「民主的正統性が赤字状態」という会計的比喩。","collocations":["address the democratic deficit","suffer from a democratic deficit"]},"technocrats":{"example2":"Italy once appointed a cabinet of technocrats to push through reforms.","exampleJa2":"イタリアはかつて改革を断行するため、テクノクラートによる内閣を任命した。","origin":"ギリシャ語techne(技術)+kratos(支配)→「技術による支配者」。democracy(民衆支配)のkratosと同じ要素と気づくと覚えやすい。","collocations":["unelected technocrats","a government of technocrats","technocrat-led reforms"]},"credibility":{"example2":"One broken promise can destroy years of hard-earned credibility.","exampleJa2":"一度の約束違反が、長年かけて築いた信頼性を打ち砕くことがある。","origin":"ラテン語credere(信じる)から。credit(信用)、credo(信条)と同根。「信じてもらえる度合い」を表す名詞。","collocations":["lose credibility","restore credibility","policy credibility"]},"macroeconomics":{"example2":"Her macroeconomics background helps her explain rate decisions to clients.","exampleJa2":"マクロ経済学の素養があるおかげで、彼女は金利決定を顧客にうまく説明できる。","origin":"ギリシャ語makros(大きい)+economics(経済学)。国全体という「大きな」視点。個別主体を見るミクロ(mikros=小さい)と対。","collocations":["study macroeconomics","macroeconomics and finance","basic macroeconomics"]},"credit spreads":{"example2":"Tight credit spreads suggest investors are underpricing default risk.","exampleJa2":"クレジットスプレッドの縮小は、投資家がデフォルトリスクを過小評価していることを示唆する。","origin":"creditはラテン語credere(信じる)、spreadは「広がり」。「信用度の差が生む利回りの開き」。企業の信用不安で拡大する。","collocations":["credit spreads widen","credit spreads tighten","corporate credit spreads"]},"risk-free":{"example2":"The risk-free rate serves as the baseline for pricing all other assets.","exampleJa2":"無リスク金利は、他のすべての資産の価格付けの基準となる。","origin":"risk(リスク)+free(〜がない)。sugar-free(無糖)と同じ構造の複合語。金融では通常、国債の利回りを指す約束事。","collocations":["risk-free rate","risk-free assets","virtually risk-free"]},"barometer":{"example2":"Copper prices are often used as a barometer of global demand.","exampleJa2":"銅価格はしばしば世界需要のバロメーターとして使われる。","origin":"ギリシャ語baros(重さ)+metron(測る)→「大気の重さを測る」気圧計。天気を予測する道具から「状況を映す指標」の比喩に。","collocations":["a barometer of confidence","economic barometer","serve as a barometer"]},"compressing":{"example2":"Fee competition is compressing profit margins across the asset management industry.","exampleJa2":"手数料競争により、資産運用業界全体で利益率が縮小している。","origin":"com(共に)+press(押す)+ing→「両側から押し縮めている」最中。スプレッドやマージンが狭まる金融文脈で頻出。","collocations":["compressing margins","spreads are compressing","compressing yields"]},"default":{"example2":"Argentina declared a default on its sovereign debt for the ninth time.","exampleJa2":"アルゼンチンは9度目となるソブリン債務のデフォルトを宣言した。","origin":"de(離れて)+fault(欠く・失敗)→義務を果たし損なうこと。フランス語defaute(欠如)が原義。","collocations":["default on a loan","risk of default","sovereign default"]},"investment-grade":{"example2":"The issuer was upgraded to investment-grade status after years of deleveraging.","exampleJa2":"その発行体は長年の負債削減を経て投資適格に格上げされた。","origin":"investment(投資)+grade(等級)。BBB-以上の格付けを指し、「投資に値する等級」という意味の複合語。","collocations":["investment-grade bonds","investment-grade rating","investment-grade credit"]},"leading indicator":{"example2":"New housing permits serve as a leading indicator for construction activity.","exampleJa2":"新築住宅許可件数は建設活動の先行指標として機能する。","origin":"lead(先導する)+indicator(指し示すもの。ラテン語indicare=指し示す)。景気に先行して動く指標の意。","collocations":["leading economic indicator","a reliable leading indicator"]},"high-yield":{"example2":"Our fund shifted into high-yield debt to boost portfolio income.","exampleJa2":"当ファンドはポートフォリオの収益を高めるためハイイールド債にシフトした。","origin":"high(高い)+yield(利回り。古英語gieldan=支払う)。高利回りと引き換えに高い信用リスクを負う債券を指す。","collocations":["high-yield bonds","high-yield spread","high-yield market"]},"junk bonds":{"example2":"Pension rules prohibit the fund from holding junk bonds outright.","exampleJa2":"年金規則により、このファンドはジャンク債の保有を全面的に禁じられている。","origin":"junk(がらくた)+bonds(債券)。「がらくた同然の債券」という蔑称が定着した俗称で、正式にはハイイールド債。","collocations":["issue junk bonds","junk bond market","junk bond yields"]},"basis points":{"example2":"The central bank raised its policy rate by 25 basis points.","exampleJa2":"中央銀行は政策金利を25ベーシスポイント引き上げた。","origin":"basis(基準)+points(点)。金利の基準となる最小単位の意で、0.01%を1bpと数える金融業界の慣用表現。","collocations":["raise rates by 25 basis points","widen by 50 basis points"]},"fixed-income":{"example2":"She manages a fixed-income portfolio focused on short-term corporate debt.","exampleJa2":"彼女は短期社債を中心とした債券ポートフォリオを運用している。","origin":"fixed(固定された。ラテン語figere=固定する)+income(収入)。あらかじめ決まった利息収入を生む資産を指す。","collocations":["fixed-income securities","fixed-income portfolio","fixed-income market"]},"market sentiment":{"example2":"Strong jobs data quickly improved market sentiment across Asian trading sessions.","exampleJa2":"堅調な雇用統計を受けて、アジア市場の取引時間中に市場心理は急速に改善した。","origin":"sentimentはラテン語sentire(感じる)由来。市場参加者が「感じている」空気や気分を集合的に捉えた表現。","collocations":["gauge market sentiment","bullish market sentiment","shift in market sentiment"]},"esg":{"example2":"Our sales team highlights ESG factors when pitching funds to clients.","exampleJa2":"当社の営業チームは顧客にファンドを提案する際、ESG要素を強調している。","origin":"Environmental(環境)・Social(社会)・Governance(企業統治)の頭文字。2004年の国連レポートで広まった投資用語。","collocations":["ESG investing","ESG criteria","ESG disclosure"]},"greenwashing":{"example2":"Regulators fined the asset manager for greenwashing in its fund marketing.","exampleJa2":"規制当局はファンドの宣伝におけるグリーンウォッシングを理由に、その運用会社に罰金を科した。","origin":"green(環境配慮)+whitewashing(うわべを取り繕う)の合成語。環境に良いふりで塗り固めるイメージ。","collocations":["accusations of greenwashing","greenwashing claims","combat greenwashing"]},"sustainability credentials":{"example2":"The bond's sustainability credentials attracted strong demand from European pension funds.","exampleJa2":"その債券の持続可能性に関する裏付けは、欧州の年金基金から強い需要を集めた。","origin":"credentialはラテン語credere(信じる)由来で「信用の証」。持続可能性への取り組みを信じさせる実績や証拠の意。","collocations":["burnish sustainability credentials","verify sustainability credentials"]},"rating agencies":{"example2":"Rating agencies downgraded the utility after its bankruptcy filing.","exampleJa2":"格付け機関は、その公益企業の破産申請を受けて格下げを行った。","origin":"rate(評価する。ラテン語ratus=計算された)+agency(代理機関。agere=行う)。信用力を評価する専門機関。","collocations":["credit rating agencies","downgraded by rating agencies"]},"contradictory":{"example2":"The CEO's statement was contradictory to the figures in the report.","exampleJa2":"CEOの発言は報告書の数字と矛盾していた。","origin":"contra(反対に)+dict(言う。ラテン語dicere)→「反対のことを言う」が原義。predictやdictionaryと同語源。","collocations":["contradictory evidence","contradictory signals","mutually contradictory"]},"underlying holdings":{"example2":"The ETF's underlying holdings include several small-cap technology stocks.","exampleJa2":"そのETFの組入銘柄には複数の小型テクノロジー株が含まれている。","origin":"under(下に)+lying(横たわる)→表面の下にあるもの。ファンドという包装の「中身」である保有証券を指す。","collocations":["review underlying holdings","disclose underlying holdings"]},"sec":{"example2":"The SEC requires funds to disclose fees in plain language.","exampleJa2":"SECはファンドに対し、手数料を平易な言葉で開示するよう義務付けている。","origin":"Securities and Exchange Commission(証券取引委員会)の頭文字。1934年、大恐慌後の市場規制強化のため設立。","collocations":["SEC filing","SEC investigation","registered with the SEC"]},"screening process":{"example2":"Our screening process eliminates companies with weak governance records.","exampleJa2":"当社のスクリーニングプロセスは、ガバナンス実績の弱い企業を除外する。","origin":"screen(ふるい・仕切り)+ing。ふるいにかけて選別するイメージ。processはラテン語procedere(前進する)由来。","collocations":["rigorous screening process","pass the screening process"]},"patchy":{"example2":"Economic recovery across the region has been patchy at best.","exampleJa2":"この地域の景気回復は、良く言ってもまだらな状態だ。","origin":"patch(継ぎはぎ・斑点)+y(〜だらけの)。継ぎはぎだらけで均一でない様子から「一貫性がない」の意に。","collocations":["patchy data","patchy performance","patchy recovery"]},"ambiguity":{"example2":"The contract's ambiguity led to a lengthy dispute between the parties.","exampleJa2":"契約の曖昧さが当事者間の長期にわたる紛争を招いた。","origin":"ambi(両方の)+ag(追い立てる。ラテン語agere)→「両方向に動く」が原義。どちらとも取れる状態を表す。","collocations":["remove ambiguity","legal ambiguity","a degree of ambiguity"]},"yield curve control":{"example2":"Abandoning yield curve control sent Japanese government bond yields sharply higher.","exampleJa2":"イールドカーブコントロールの撤廃により、日本国債の利回りは急上昇した。","origin":"yield(利回り)+curve(曲線)+control(制御)。年限ごとの利回り曲線を中央銀行が直接制御する政策の直訳。","collocations":["abandon yield curve control","yield curve control policy"]},"framework":{"example2":"The Basel framework sets capital requirements for banks worldwide.","exampleJa2":"バーゼルの枠組みは世界中の銀行に対する自己資本規制を定めている。","origin":"frame(枠を組む)+work(構造物)。建物の骨組みが原義で、政策や制度の「骨格」を指す比喩に広がった。","collocations":["regulatory framework","policy framework","legal framework"]},"adverse side effects":{"example2":"Prolonged easing produced adverse side effects, including asset bubbles and zombie firms.","exampleJa2":"長期の金融緩和は、資産バブルやゾンビ企業といった副作用をもたらした。","origin":"adverseはad(〜へ)+vertere(向く)→「敵対して向かう」。本来の狙いとは別方向(side)に出る悪い効果の意。","collocations":["cause adverse side effects","mitigate adverse side effects"]},"sovereign bond":{"example2":"Emerging market sovereign bonds rallied as the dollar weakened.","exampleJa2":"ドル安を受けて新興国のソブリン債は上昇した。","origin":"sovereignはラテン語super(上に)由来で「最高権力者・君主」。国家(主権者)が発行する債券の意。","collocations":["sovereign bond yields","issue sovereign bonds","sovereign bond market"]},"anchoring":{"example2":"Central banks focus on anchoring long-term inflation expectations near two percent.","exampleJa2":"中央銀行は長期のインフレ期待を2%近辺に固定することに注力している。","origin":"anchor(錨)はギリシャ語ankyra由来。船を錨で固定するように、期待や水準をつなぎ留めるイメージ。","collocations":["anchoring inflation expectations","anchoring the exchange rate"]},"inflationary pressures":{"example2":"Wage growth is adding to inflationary pressures in the services sector.","exampleJa2":"賃金の伸びがサービス部門のインフレ圧力を強めている。","origin":"inflateはin(中へ)+flare(吹く)→「膨らませる」。物価を押し上げる圧力(pressure。premere=押す)の意。","collocations":["mounting inflationary pressures","ease inflationary pressures"]},"depreciated":{"example2":"The peso depreciated sharply after the central bank cut rates unexpectedly.","exampleJa2":"中央銀行の予想外の利下げを受けて、ペソは急落した。","origin":"de(下に)+pretium(価格。ラテン語)→「価格が下がる」。priceやpreciousと同語源。対義語はappreciate。","collocations":["the currency depreciated","depreciated against the dollar"]},"yield cap":{"example2":"Defending the yield cap forced the central bank into massive bond purchases.","exampleJa2":"利回り上限を守るため、中央銀行は大量の国債購入を余儀なくされた。","origin":"cap(帽子。ラテン語caput=頭)から「上限」の意に。利回りに帽子をかぶせて頭打ちにするイメージ。","collocations":["defend the yield cap","breach the yield cap"]},"tolerance band":{"example2":"The exchange rate is allowed to move within a narrow tolerance band.","exampleJa2":"為替レートは狭い許容変動幅の範囲内での変動が認められている。","origin":"toleranceはラテン語tolerare(耐える)由来で「許容」。band(帯)と合わせ「許容できる変動の帯域」を表す。","collocations":["widen the tolerance band","within the tolerance band"]},"monetary experiment":{"example2":"Negative rates were a bold monetary experiment with uncertain long-term consequences.","exampleJa2":"マイナス金利は、長期的な帰結が不確かな大胆な金融実験だった。","origin":"monetaryはローマの造幣所があったユノ・モネタ神殿に由来。experimentはexperiri(試す)から。金融政策の試みの意。","collocations":["unprecedented monetary experiment","a bold monetary experiment"]},"private credit":{"example2":"Mid-sized companies increasingly turn to private credit for flexible financing.","exampleJa2":"中堅企業は柔軟な資金調達のため、プライベートクレジットの活用を増やしている。","origin":"private(公開されない。ラテン語privatus)+credit(信用。credere=信じる)。公開市場を通さない直接貸付の意。","collocations":["private credit funds","private credit market","invest in private credit"]},"alternative investments":{"example2":"Advisors recommend allocating ten percent of portfolios to alternative investments.","exampleJa2":"アドバイザーはポートフォリオの10%をオルタナティブ投資に配分するよう勧めている。","origin":"alternativeはラテン語alter(もう一方の)由来。株式・債券という伝統資産の「もう一つの選択肢」の意。","collocations":["allocate to alternative investments","alternative investment strategies"]},"assets under management":{"example2":"The boutique firm doubled its assets under management in three years.","exampleJa2":"そのブティック運用会社は3年で運用資産残高を倍増させた。","origin":"「管理(management)の下(under)にある資産(assets)」の直訳。運用会社の規模を測る基本指標でAUMと略す。","collocations":["grow assets under management","total assets under management"]},"supply gap":{"example2":"A persistent supply gap in housing keeps rents elevated nationwide.","exampleJa2":"住宅の慢性的な供給ギャップが全国の家賃を高止まりさせている。","origin":"supplyはsub(下から)+plere(満たす)→「満たして補う」。gap(隙間)と合わせ、需要との間の隙間を表す。","collocations":["fill the supply gap","a widening supply gap"]},"institutional investors":{"example2":"Institutional investors demanded better disclosure before backing the merger.","exampleJa2":"機関投資家は合併を支持する前に、より充実した情報開示を要求した。","origin":"institutionはin+statuere(立てる)→「設立された組織」。年金や保険など、組織として投資する主体を指す。","collocations":["attract institutional investors","large institutional investors"]},"endowments":{"example2":"University endowments allocate heavily to private equity and venture capital.","exampleJa2":"大学基金はプライベートエクイティとベンチャーキャピタルに厚く配分している。","origin":"en(与える)+dow(寄贈財産。ラテン語dotare=持参金を与える)。寄付で設立され長期運用される基金の意。","collocations":["university endowments","endowment fund","manage an endowment"]},"illiquidity premium":{"example2":"Private assets must offer an illiquidity premium to justify long lock-ups.","exampleJa2":"プライベート資産は、長い資金拘束を正当化するだけの非流動性プレミアムを提供する必要がある。","origin":"il(否定)+liquid(流動的な。liquere=流れる)+premium(報酬。praemium)。換金しにくさへの上乗せ報酬。","collocations":["capture the illiquidity premium","earn an illiquidity premium"]},"concentrated exposures":{"example2":"Risk managers flagged concentrated exposures to a single real estate developer.","exampleJa2":"リスク管理担当者は、一つの不動産開発業者への集中エクスポージャーを問題視した。","origin":"con(共に)+centrum(中心)→一点に集める。exposureはex(外に)+ponere(置く)→リスクにさらされた持ち高。","collocations":["reduce concentrated exposures","manage concentrated exposures"]},"credit cycle":{"example2":"Defaults typically rise in the late stage of the credit cycle.","exampleJa2":"デフォルトは通常、信用サイクルの終盤に増加する。","origin":"cycleはギリシャ語kyklos(輪)由来。信用の拡大と収縮が輪のように繰り返される現象を表す。","collocations":["late in the credit cycle","a full credit cycle","the credit cycle turns"]},"carry trade":{"example2":"Hedge funds rebuilt the carry trade once currency volatility subsided.","exampleJa2":"通貨のボラティリティが落ち着くと、ヘッジファンドはキャリートレードを再構築した。","origin":"carry(持ち運ぶ→保有して得る金利収益の意)。低金利通貨で借り、高金利資産を「持ち続けて」金利差を稼ぐ手法。","collocations":["yen carry trade","unwind the carry trade","carry trade strategy"]},"interest rate differential":{"example2":"The interest rate differential between Japan and the US widened further.","exampleJa2":"日米間の金利差はさらに拡大した。","origin":"differentialはdis(離れて)+ferre(運ぶ)→「異なること」。二国間の金利の「差」を表す専門用語。","collocations":["a wide interest rate differential","narrow the interest rate differential"]},"quintessential":{"example2":"The deal was a quintessential example of private equity financial engineering.","exampleJa2":"その案件はプライベートエクイティによる財務エンジニアリングの典型例だった。","origin":"quinta essentia(第五元素)から。四元素を超える純粋な精髄の意→「最も純粋で典型的な」に転じた。","collocations":["quintessential example","the quintessential American brand"]},"funding currency":{"example2":"The Swiss franc once served as a favored funding currency too.","exampleJa2":"スイスフランもかつては好まれる調達通貨として使われていた。","origin":"fund(資金。ラテン語fundus=土地・基盤)+currency(通貨。currere=流れる)。取引の元手として借りる通貨の意。","collocations":["a popular funding currency","borrow in a funding currency"]},"complacency":{"example2":"Regulators warned that complacency about inflation could prove costly.","exampleJa2":"規制当局は、インフレへの油断が高くつく可能性があると警告した。","origin":"com(強意)+placere(喜ばせる)→「自分に満足しきる」。現状に安住して危険に気づかない状態を指す。","collocations":["breed complacency","guard against complacency","investor complacency"]},"unwind":{"example2":"Traders rushed to unwind leveraged positions as margin calls hit.","exampleJa2":"追証が発生すると、トレーダーはレバレッジポジションの解消を急いだ。","origin":"un(逆に)+wind(巻く)→「巻いたものをほどく」。積み上げたポジションを逆の取引でほどくイメージ。","collocations":["unwind a position","unwind the trade","rapidly unwind"]},"volatility spikes":{"example2":"Options prices surge whenever volatility spikes hit the equity market.","exampleJa2":"株式市場でボラティリティが急上昇すると、オプション価格は跳ね上がる。","origin":"volatilisはラテン語で「飛び回る」(volare=飛ぶ)。spike(鋭い釘)はチャート上の針のような急騰を表す。","collocations":["sudden volatility spikes","trigger volatility spikes"]},"plummets":{"example2":"The stock plummets whenever the company delays its earnings release.","exampleJa2":"その会社が決算発表を延期するたびに、株価は急落する。","origin":"ラテン語plumbum(鉛)由来のplummet(測鉛=鉛のおもり)から。鉛のおもりのように真っ直ぐ落ちるイメージ。","collocations":["prices plummet","plummet to a record low"]},"equity selloff":{"example2":"The global equity selloff wiped out two trillion dollars in value.","exampleJa2":"世界的な株式の大量売りにより、2兆ドルの価値が消失した。","origin":"sell(売る)+off(すっかり)→「売り払う」の名詞化。equityは「公平」から転じて株式(残余持分)を意味する。","collocations":["a sharp equity selloff","trigger an equity selloff"]},"evaporate":{"example2":"Liquidity can evaporate quickly when dealers step back from the market.","exampleJa2":"ディーラーが市場から手を引くと、流動性は瞬く間に消えることがある。","origin":"e(外へ)+vapor(蒸気)→「蒸気になって出ていく」。水が蒸発するように跡形もなく消える比喩。","collocations":["profits evaporate","confidence evaporated","liquidity evaporates"]},"sovereign wealth funds":{"example2":"Gulf sovereign wealth funds are major backers of technology startups.","exampleJa2":"湾岸諸国の政府系ファンドはテクノロジー系スタートアップの主要な出資者だ。","origin":"sovereign(主権国家)+wealth(富)+fund(基金)。国家の富を運用する基金の直訳で、SWFと略される。","collocations":["state-backed sovereign wealth funds","sovereign wealth fund investments"]},"commodity revenues":{"example2":"Norway channels its commodity revenues into a giant global fund.","exampleJa2":"ノルウェーは資源収入を巨大なグローバルファンドに振り向けている。","origin":"commodityはcommodus(便利な)由来で「有用な品→商品・資源」。revenueはre+venire(戻って来る)→収入。","collocations":["volatile commodity revenues","invest commodity revenues"]},"foreign exchange reserves":{"example2":"The central bank sold foreign exchange reserves to defend the currency.","exampleJa2":"中央銀行は自国通貨を防衛するため外貨準備を売却した。","origin":"reserveはre(後ろに)+servare(保つ)→「取っておくもの」。危機や介入に備えて保有する外貨の蓄えの意。","collocations":["build up foreign exchange reserves","draw down foreign exchange reserves"]},"ownership stakes":{"example2":"The fund quietly built ownership stakes in several regional banks.","exampleJa2":"そのファンドは複数の地方銀行の持分をひそかに積み増した。","origin":"stakeは「杭」が原義。賭け金を杭に置いた習慣から「利害・出資分」に転じた。所有権としての持分を指す。","collocations":["acquire ownership stakes","hold ownership stakes","minority ownership stakes"]},"corporate governance":{"example2":"Activist investors pushed for reforms to strengthen corporate governance standards.","exampleJa2":"アクティビスト投資家はコーポレートガバナンス基準を強化する改革を求めた。","origin":"governはギリシャ語kybernan(舵を取る)由来。会社という船の「舵取りの仕組み」を表すイメージ。","collocations":["corporate governance reforms","strong corporate governance","corporate governance code"]},"diversify":{"example2":"We advise clients to diversify across regions, sectors, and asset classes.","exampleJa2":"当社は顧客に、地域・セクター・資産クラスをまたいで分散するよう助言している。","origin":"di(離れて)+versus(向けられた。vertere=向ける)→「別々の方向に向ける」。一点集中を避ける発想。","collocations":["diversify a portfolio","diversify away from oil","diversify holdings"]},"economic coercion":{"example2":"The trade restrictions were widely seen as economic coercion against smaller nations.","exampleJa2":"その貿易制限は、小国に対する経済的強制と広く受け止められた。","origin":"coerceはco(共に)+arcere(閉じ込める)→「力で抑え込む」。経済力で相手を締め付けて従わせる行為の意。","collocations":["resist economic coercion","acts of economic coercion"]},"political leverage":{"example2":"Energy exports give the country significant political leverage over its neighbors.","exampleJa2":"エネルギー輸出は、その国に近隣諸国への大きな政治的影響力を与えている。","origin":"leverはラテン語levare(持ち上げる)由来の「てこ」。小さな力で大きく動かす、てこの原理の比喩。","collocations":["gain political leverage","use political leverage","political leverage over"]},"statecraft":{"example2":"Sovereign investment has become a quiet instrument of modern statecraft.","exampleJa2":"政府系投資は現代の国家運営術における静かな道具となった。","origin":"state(国家)+craft(技能。古英語cræft=力・技)。船を操るように国家を巧みに運営する技術の意。","collocations":["economic statecraft","an instrument of statecraft"]},"value investing":{"example2":"Value investing requires patience while the market recognizes a stock's worth.","exampleJa2":"バリュー投資には、市場が株式の価値に気づくまで待つ忍耐が必要だ。","origin":"valueはラテン語valere(力がある・価値がある)由来。企業の本来の「価値」に注目する投資哲学の直訳。","collocations":["value investing strategy","a value investing approach"]},"growth investing":{"example2":"Growth investing outperformed dramatically during the decade of low interest rates.","exampleJa2":"低金利の10年間、グロース投資は劇的にアウトパフォームした。","origin":"growは古英語growan(植物が育つ)由来。利益が植物のように伸びる企業に投資するスタイルを指す。","collocations":["growth investing style","shift away from growth investing"]},"intrinsic worth":{"example2":"Analysts estimate intrinsic worth using discounted cash flow models.","exampleJa2":"アナリストは割引キャッシュフローモデルを使って本源的価値を推定する。","origin":"intrinsicはラテン語intrinsecus(内側に)由来。外部の評価ではなく、資産の「内側」にある本来の価値の意。","collocations":["estimate intrinsic worth","trade below intrinsic worth"]},"price-to-earnings ratio":{"example2":"The market's average price-to-earnings ratio is well above historical norms.","exampleJa2":"市場平均の株価収益率は過去の水準を大きく上回っている。","origin":"株価(price)を1株利益(earnings)で割った比率(ratio。ラテン語=計算)。利益の何倍で買われているかを示す。","collocations":["a high price-to-earnings ratio","forward price-to-earnings ratio"]},"price-to-book ratio":{"example2":"A price-to-book ratio below one suggests the market doubts asset values.","exampleJa2":"株価純資産倍率が1倍を下回るのは、市場が資産価値を疑っているサインだ。","origin":"bookは帳簿(book value=帳簿上の純資産)の意。株価が帳簿価額の何倍かを示し、1倍割れは解散価値以下。","collocations":["a low price-to-book ratio","trade below book value"]},"seminal":{"example2":"Markowitz's seminal work on diversification earned him a Nobel Prize.","exampleJa2":"分散投資に関するマーコウィッツの画期的な研究は、彼にノーベル賞をもたらした。","origin":"ラテン語semen(種)由来。後の発展の「種」をまいた研究や作品を指す。英語のseed(種)と発想が同じ。","collocations":["seminal paper","seminal work","a seminal study"]},"value premium":{"example2":"Researchers debate whether the value premium still exists in modern markets.","exampleJa2":"バリュープレミアムが現代の市場にまだ存在するのか、研究者の間で議論が続いている。","origin":"premiumはラテン語praemium(報酬)由来。割安株の保有で歴史的に得られてきた超過リターンを指す。","collocations":["capture the value premium","the value premium has shrunk"]},"upended":{"example2":"The pandemic upended long-held assumptions about office real estate demand.","exampleJa2":"パンデミックはオフィス不動産需要に関する長年の前提を覆した。","origin":"up(上)+end(端)→「端を上にする=逆さまにする」。テーブルをひっくり返すように秩序を覆すイメージ。","collocations":["upend the status quo","upend expectations"]},"long-duration":{"example2":"Long-duration bonds suffered historic losses during the 2022 rate shock.","exampleJa2":"デュレーションの長い債券は、2022年の金利ショックで歴史的な損失を被った。","origin":"durationはラテン語durare(続く)由来で「持続期間」。キャッシュフローの回収が先で金利感応度が高い意。","collocations":["long-duration assets","long-duration bonds"]},"liquidity trap":{"example2":"In a liquidity trap, even zero rates fail to revive borrowing.","exampleJa2":"流動性の罠に陥ると、ゼロ金利でさえ借り入れを回復させられない。","origin":"ケインズ経済学の用語。人々が現金(流動性)を抱え込み、金融政策が罠(trap)にかかったように効かない状態。","collocations":["fall into a liquidity trap","escape the liquidity trap"]},"conventional monetary policy":{"example2":"With rates at zero, conventional monetary policy had reached its limit.","exampleJa2":"金利がゼロとなり、伝統的金融政策は限界に達していた。","origin":"conventionはcon(共に)+venire(来る)→「皆で集まって決めた慣例」。慣例的な短期金利操作による政策の意。","collocations":["the limits of conventional monetary policy","beyond conventional monetary policy"]},"hoard":{"example2":"Corporations continue to hoard cash rather than invest in new capacity.","exampleJa2":"企業は新たな設備に投資するより、現金をため込み続けている。","origin":"古英語hord(宝物・蓄え)由来。ドラゴンが宝を抱え込む神話のイメージ通り、使わずにため込むこと。","collocations":["hoard cash","hoard supplies"]},"futile":{"example2":"Attempts to time the market often prove futile for individual investors.","exampleJa2":"市場のタイミングを計る試みは、個人投資家にとって徒労に終わることが多い。","origin":"ラテン語futilis(水が漏れる器)由来。穴の開いた器に水を注ぐように、努力が漏れて実らないイメージ。","collocations":["prove futile","a futile attempt","futile efforts"]},"deflationary spiral":{"example2":"Falling wages and prices reinforced each other in a deflationary spiral.","exampleJa2":"賃金と物価の下落が互いに拍車をかけ、デフレスパイラルに陥った。","origin":"de(下に)+flare(吹く)→「しぼむ」。spiral(らせん)は下落が下落を呼ぶ、らせん階段を落ちるイメージ。","collocations":["fall into a deflationary spiral","avoid a deflationary spiral"]},"quantitative easing":{"example2":"The ECB launched quantitative easing to fight persistently low inflation.","exampleJa2":"ECBは根強い低インフレと闘うため量的緩和を開始した。","origin":"quantitative(量的な。quantus=どれだけ)+easing(緩和)。金利ではなく資金供給の「量」を増やす緩和策。","collocations":["launch quantitative easing","quantitative easing program","end quantitative easing"]},"forward guidance":{"example2":"Clear forward guidance helped calm bond markets after the surprise decision.","exampleJa2":"明確なフォワードガイダンスは、サプライズ決定後の債券市場の沈静化に役立った。","origin":"forward(前方の)+guidance(導き。guide=案内する)。将来の政策方針を前もって示し、市場を導く手法。","collocations":["provide forward guidance","forward guidance on rates"]},"negative interest rates":{"example2":"Negative interest rates squeezed bank profitability across the eurozone.","exampleJa2":"マイナス金利はユーロ圏全体で銀行の収益性を圧迫した。","origin":"negativeはラテン語negare(否定する)由来。「貸し手が利息を払う」という常識の逆転を名前自体が示す。","collocations":["adopt negative interest rates","exit negative interest rates"]},"asset prices":{"example2":"Loose monetary policy tends to inflate asset prices before consumer prices.","exampleJa2":"緩和的な金融政策は、消費者物価より先に資産価格を押し上げる傾向がある。","origin":"assetは古フランス語asez(十分に)由来。「債務を返すのに十分な財産」が原義で、その財産の価格の意。","collocations":["inflate asset prices","asset price bubble","falling asset prices"]},"real economic activity":{"example2":"Stock gains do not always translate into real economic activity.","exampleJa2":"株価の上昇が常に実体経済活動につながるとは限らない。","origin":"realはラテン語res(物)由来で「実物の」。金融市場と対比し、モノやサービスの実際の生産・消費を指す。","collocations":["boost real economic activity","a slowdown in real economic activity"]},"spac":{"example2":"The SPAC merged with an electric vehicle startup within two years.","exampleJa2":"そのSPACは2年以内に電気自動車のスタートアップと合併した。","origin":"Special Purpose Acquisition Company(特別買収目的会社)の頭文字。買収だけを目的に上場する「箱」の会社。","collocations":["SPAC merger","SPAC boom","launch a SPAC"]},"blank-check entities":{"example2":"Critics argue blank-check entities shift risk onto unsophisticated investors.","exampleJa2":"白紙小切手会社は知識の乏しい投資家にリスクを転嫁している、と批判する声もある。","origin":"blank check(金額欄が白紙の小切手)の比喩。使い道を決めずに資金を託す「白紙委任」のイメージから。","collocations":["so-called blank-check entities","blank-check acquisition vehicles"]},"ipo":{"example2":"The chipmaker priced its IPO at the top of the range.","exampleJa2":"その半導体メーカーはIPO価格を仮条件の上限に設定した。","origin":"Initial(最初の)Public(公開の)Offering(売り出し)の頭文字。株式を初めて一般投資家に売り出すこと。","collocations":["launch an IPO","IPO market","price an IPO"]},"public listing":{"example2":"The startup chose a direct public listing instead of a traditional IPO.","exampleJa2":"そのスタートアップは従来型のIPOではなく直接上場を選んだ。","origin":"list(名簿に載せる)から。取引所の銘柄リストに載る=上場。publicは「公衆が売買できる」状態を表す。","collocations":["seek a public listing","path to a public listing"]},"retail investors":{"example2":"Commission-free apps brought millions of retail investors into the market.","exampleJa2":"手数料無料のアプリは何百万人もの個人投資家を市場に呼び込んだ。","origin":"retailは古フランス語retaillier(小さく切る)由来。小口に切り分けた取引=小売→個人投資家の意に。","collocations":["retail investor demand","protect retail investors"]},"promote fees":{"example2":"Sponsors collected promote fees even when the merged companies later collapsed.","exampleJa2":"合併後の企業が破綻しても、スポンサーはプロモートフィーを受け取っていた。","origin":"promote(前へ押し出す。pro+movere=動かす)。案件を推進した見返りにスポンサーが得る成功報酬の意。","collocations":["earn promote fees","generous promote fees"]},"warrants":{"example2":"The startup issued warrants to early backers as an extra incentive.","exampleJa2":"そのスタートアップは追加のインセンティブとして初期の支援者にワラントを発行した。","origin":"古フランス語warant(保証人)由来。「特定価格で買う権利を保証する」証書の意。warranty(保証)と同語源。","collocations":["exercise warrants","issue warrants","warrant holders"]},"sweeteners":{"example2":"The bank added fee waivers as sweeteners to win the mandate.","exampleJa2":"その銀行は案件を獲得するため、手数料免除をおまけとして付けた。","origin":"sweet(甘い)+en(〜にする)+er→「甘くするもの」。苦い取引を飲みやすくする砂糖、という比喩表現。","collocations":["offer sweeteners","add sweeteners to the deal"]},"dismal":{"example2":"The fund's dismal performance triggered a wave of client redemptions.","exampleJa2":"ファンドの惨憺たる運用成績は、顧客の解約の波を引き起こした。","origin":"ラテン語dies mali(悪い日々)由来。中世の暦の「不吉な日」から「暗く悲惨な」の意に転じた。","collocations":["dismal performance","dismal results","a dismal outlook"]},"regulatory crackdowns":{"example2":"Regulatory crackdowns on crypto exchanges intensified after several high-profile failures.","exampleJa2":"複数の著名な破綻を受けて、暗号資産取引所への規制の取り締まりが強化された。","origin":"crack down=「バシッと叩き落とす」イメージの句動詞の名詞化。鞭を振り下ろすように厳しく取り締まること。","collocations":["face regulatory crackdowns","a regulatory crackdown on"]},"shareholder lawsuits":{"example2":"The board faced shareholder lawsuits over the failed acquisition strategy.","exampleJa2":"取締役会は失敗した買収戦略をめぐって株主訴訟に直面した。","origin":"share(分け前)+holder(保有者)=株主。lawsuitはlaw(法)+suit(訴え・追跡)で「法廷で追及する」意。","collocations":["face shareholder lawsuits","settle shareholder lawsuits"]},"facilitation":{"example2":"Effective facilitation keeps every participant engaged and the agenda moving.","exampleJa2":"効果的なファシリテーションは、全参加者の関与を保ち、議題を前に進める。","origin":"ラテン語facilis(容易な。facere=行う)由来。「物事を容易にすること」が原義で、会議進行術の意に。","collocations":["meeting facilitation","facilitation skills"]},"on track":{"example2":"Despite early delays, the system migration remains on track for October.","exampleJa2":"序盤の遅れにもかかわらず、システム移行は10月に向けて順調に進んでいる。","origin":"track(線路・走路)の上に乗っているイメージ。列車が線路を外れず予定通り走る様子から「順調」の意。","collocations":["stay on track","on track to meet the deadline","back on track"]},"actionable":{"example2":"Turn the survey data into actionable insights for the sales team.","exampleJa2":"調査データを営業チームが実行に移せる知見に変換しよう。","origin":"action(行動。ラテン語agere=行う)+able(できる)。「そのまま行動に移せる」具体性を持つことを表す。","collocations":["actionable insights","actionable advice","actionable steps"]},"go off on tangents":{"example2":"Let's stay focused and not go off on tangents about budgets today.","exampleJa2":"今日は集中して、予算の話で脱線しないようにしよう。","origin":"tangentは円の接線(ラテン語tangere=触れる)。円周から接線方向へ飛び出すように本題から逸れるイメージ。","collocations":["go off on a tangent","tend to go off on tangents"]},"veer off course":{"example2":"Without a clear agenda, meetings quickly veer off course.","exampleJa2":"明確な議題がないと、会議はすぐに軌道から外れてしまう。","origin":"veerは船が風向きで進路を変える航海用語。course(進路)から船が逸れていく航海のイメージで覚える。","collocations":["the discussion veered off course","veer off topic"]},"table that":{"example2":"Good point, but let's table that and finish the pricing discussion.","exampleJa2":"良い指摘ですが、それは保留にして価格の議論を終わらせましょう。","origin":"議題をテーブルの脇に置いておくイメージ(米用法)。英国では逆に「議題に載せる」意になるので注意。","collocations":["table that discussion","table that for now"]},"circle back":{"example2":"Let me circle back with the compliance team and confirm tomorrow.","exampleJa2":"コンプライアンスチームに確認して、明日改めてご連絡します。","origin":"circle(円を描く)+back(戻る)。円を描いて元の場所へ戻ってくるイメージで「後で話題に戻る」の意。","collocations":["circle back on that","circle back next week"]},"take it offline":{"example2":"That detail affects only two people, so let's take it offline.","exampleJa2":"その詳細は2人にしか関係ないので、会議の外で個別に話しましょう。","origin":"IT用語のoffline(回線の外)から。全員がつながる「回線」=会議の場を離れ、個別に話すイメージ。","collocations":["take it offline","take the discussion offline"]},"action items":{"example2":"The recap email listed five action items with owners and deadlines.","exampleJa2":"まとめのメールには、担当者と期限付きの5つのアクションアイテムが記載されていた。","origin":"action(行動)+item(項目。ラテン語で「同様に」→箇条書きの各項)。会議から生まれる「やることリスト」。","collocations":["assign action items","follow up on action items"]},"take the lead":{"example2":"Our Tokyo office will take the lead on the client presentation.","exampleJa2":"顧客向けプレゼンは東京オフィスが主導する。","origin":"レースで先頭(lead)を取るイメージ。競走で先頭に立つ→物事を率いる役割を引き受ける意に広がった。","collocations":["take the lead on a project","take the lead in negotiations"]},"alignment":{"example2":"Before the launch, we need full alignment between sales and product.","exampleJa2":"ローンチ前に、営業と製品部門の完全な足並みの一致が必要だ。","origin":"a(〜へ)+line(線)→「一直線に並べる」。部門やメンバーの方向性を一本の線にそろえるイメージ。","collocations":["achieve alignment","alignment on goals","cross-team alignment"]},"takeaways":{"example2":"My three takeaways from the conference all concern generative AI.","exampleJa2":"カンファレンスからの私の3つの持ち帰りポイントは、いずれも生成AIに関するものだ。","origin":"take(取る)+away(持ち去る)。テイクアウトの食事のように、会議から「持ち帰る」要点のイメージ。","collocations":["key takeaways","main takeaway","takeaways from the meeting"]},"recap":{"example2":"Here's a quick recap before we move to the next agenda item.","exampleJa2":"次の議題に移る前に、簡単に振り返っておきます。","origin":"recapitulate(要点を繰り返す)の短縮形。re(再び)+capitulum(小さな章)→「章の要点を再び述べる」。","collocations":["a quick recap","send a recap","recap of the meeting"]},"momentum":{"example2":"The stock's upward momentum attracted a fresh wave of trend followers.","exampleJa2":"その株の上昇の勢いは、新たなトレンドフォロワーの波を呼び込んだ。","origin":"ラテン語movimentum(movere=動く)由来。物理学の「運動量」から、動き続ける勢いの比喩に広がった。","collocations":["gain momentum","lose momentum","maintain momentum"]},"make or break":{"example2":"The next earnings call will make or break investor confidence in our fund.","exampleJa2":"次の決算説明会が、当ファンドへの投資家の信頼の成否を分けるだろう。","origin":"「作る(make)か壊す(break)か」の二者択一のイメージ。成功か失敗か、中間がない決定的な局面を表す定型句。","collocations":["make or break moment","make or break the deal","a make-or-break year"]},"pitching":{"example2":"Our team spent all week pitching the fund to institutional clients.","exampleJa2":"私たちのチームは、機関投資家向けにそのファンドを売り込むことに一週間を費やした。","origin":"野球の「投球(pitch)」から。相手に向かってアイデアを投げ込むイメージで、提案・売り込みの意味に発展した。","collocations":["pitching an idea","pitching to investors","pitching a product"]},"stakeholders":{"example2":"We must balance the interests of shareholders, employees, and other stakeholders.","exampleJa2":"株主、従業員、その他の利害関係者の利益のバランスを取らなければならない。","origin":"stake(賭け金・利害)+holder(持つ人)。事業に利害という「掛け金」を投じている人、というイメージ。","collocations":["key stakeholders","engage stakeholders","stakeholder meeting"]},"hook":{"example2":"The opening slide needs a hook that grabs the client's attention immediately.","exampleJa2":"最初のスライドには、顧客の注意を即座に引きつけるつかみが必要だ。","origin":"釣り針(hook)が原義。聞き手を釣り針のように引っかけて離さない冒頭の仕掛け、というイメージで覚える。","collocations":["a strong hook","opening hook","hook the audience"]},"anecdote":{"example2":"She opened the seminar with an anecdote about a client's retirement planning.","exampleJa2":"彼女は、ある顧客の退職後の資金計画にまつわる逸話でセミナーを始めた。","origin":"ギリシャ語 an(否定)+ekdotos(公表された)→「未公表の話」が原義。表に出ていない小話→逸話の意味に。","collocations":["share an anecdote","a personal anecdote","an amusing anecdote"]},"i'd like to walk you through":{"example2":"I'd like to walk you through the fund's performance over the past year.","exampleJa2":"過去1年間のファンドの運用実績についてご説明したいと思います。","origin":"walk through は「一緒に歩いて案内する」イメージ。順を追って丁寧に説明する場面の定番の切り出し表現。","collocations":["walk you through the process","walk you through the numbers","walk you through the slides"]},"fiscal year":{"example2":"The budget for the next fiscal year must be approved by March.","exampleJa2":"来会計年度の予算は3月までに承認されなければならない。","origin":"ラテン語 fiscus(国庫・かご)が語源。国のお金を入れる「かご」→財政の意味に。fiscal=財政の、会計の。","collocations":["fiscal year 2026","end of the fiscal year","fiscal year results"]},"data-driven":{"example2":"Our portfolio managers make data-driven decisions rather than relying on intuition.","exampleJa2":"当社のポートフォリオマネージャーは、勘に頼らずデータに基づいた意思決定を行う。","origin":"data(データ)+driven(動かされる)。「データによって運転される」→データが判断を導くイメージの複合形容詞。","collocations":["data-driven approach","data-driven decision","data-driven strategy"]},"metrics":{"example2":"Which metrics do you use to evaluate the fund's risk profile?","exampleJa2":"そのファンドのリスク特性を評価するのに、どの指標を使っていますか。","origin":"ギリシャ語 metron(測るもの)が語源。meter(計器)と同源で、「測定するための物差し」→評価指標の意味。","collocations":["key metrics","performance metrics","track metrics"]},"lend credibility":{"example2":"Citing official statistics will lend credibility to your investment report.","exampleJa2":"公式統計を引用すれば、投資レポートの信頼性が高まるだろう。","origin":"lend(貸す)+credibility(信頼性)。外部の権威が自分の主張に信頼性を「貸してくれる」イメージで覚える。","collocations":["lend credibility to a claim","lend credibility to the argument","lend further credibility"]},"the key takeaway is":{"example2":"The key takeaway is that diversification protects investors during downturns.","exampleJa2":"重要なポイントは、分散投資が下落局面で投資家を守るということです。","origin":"take away(持ち帰る)から。会議や講演から「持ち帰るべきもの」→最重要の学び・結論を指すビジネス定番語。","collocations":["the key takeaway from the meeting","main takeaway","key takeaways for investors"]},"call to action":{"example2":"The campaign's call to action urged clients to review their portfolios.","exampleJa2":"そのキャンペーンの行動喚起は、顧客にポートフォリオの見直しを促すものだった。","origin":"「行動(action)への呼びかけ(call)」がそのまま名詞化。軍隊の召集命令のイメージから、聴衆を動かす一言の意味に。","collocations":["a clear call to action","end with a call to action","strong call to action"]},"diplomacy":{"example2":"Handling the client's complaint about fees required real diplomacy.","exampleJa2":"手数料に関するその顧客の苦情への対応には、真の外交手腕が必要だった。","origin":"ギリシャ語 diploma(二つ折りの公文書)が語源。外交官が携えた公文書→外交→角を立てない巧みな対応の意味へ。","collocations":["exercise diplomacy","tact and diplomacy","quiet diplomacy"]},"i'd recommend":{"example2":"Given your risk tolerance, I'd recommend a more balanced fund.","exampleJa2":"お客様のリスク許容度を考えると、よりバランス型のファンドをお勧めします。","origin":"I would recommend の短縮形。would を挟むことで「もしよろしければ」という控えめで丁寧な提案のニュアンスになる。","collocations":["I'd recommend starting with","I'd strongly recommend","I'd recommend against"]},"resource constraints":{"example2":"Due to resource constraints, we can only support three client projects this quarter.","exampleJa2":"リソースの制約により、今四半期に対応できる顧客プロジェクトは3件だけです。","origin":"ラテン語 constringere(縛り付ける)が constraint の語源。人・金・時間が「縛られて」自由に使えない状態のイメージ。","collocations":["face resource constraints","due to resource constraints","severe resource constraints"]},"in light of":{"example2":"In light of rising interest rates, we adjusted our bond allocation.","exampleJa2":"金利上昇を踏まえて、私たちは債券の配分を調整した。","origin":"「〜の光(light)の中で」が直訳。新しい情報という光に照らして物事を見直す、というイメージで覚える。","collocations":["in light of recent events","in light of the data","in light of these findings"]},"alarmist":{"example2":"Analysts warned against alarmist headlines about the market correction.","exampleJa2":"アナリストたちは、市場調整に関する危機感を煽る見出しに警鐘を鳴らした。","origin":"alarm(警報)+ist(〜する人・傾向)。イタリア語 all'arme(武器を取れ!)が語源で、必要以上に警報を鳴らす様子。","collocations":["alarmist rhetoric","sound alarmist","alarmist predictions"]},"going forward":{"example2":"Going forward, we will rebalance the portfolio every quarter.","exampleJa2":"今後は、四半期ごとにポートフォリオをリバランスします。","origin":"「前へ(forward)進んでいく(going)」が直訳。時間軸を前に進むイメージで「今後は」を表すビジネス定番句。","collocations":["going forward, we will","our strategy going forward","plans going forward"]},"allocate":{"example2":"The fund allocates 60% of assets to global equities.","exampleJa2":"そのファンドは資産の60%を世界株式に配分している。","origin":"ラテン語 ad(〜へ)+locare(置く)→「特定の場所へ置く」。資源をあるべき場所に振り分けるイメージ。","collocations":["allocate resources","allocate funds","allocate assets"]},"fell short of":{"example2":"The fund's returns fell short of its benchmark for the third year.","exampleJa2":"そのファンドのリターンは3年連続でベンチマークに届かなかった。","origin":"short(足りない)状態に fall(落ちる)→目標という的まで矢が「届かず手前に落ちる」イメージで覚える。","collocations":["fall short of expectations","fall short of the target","fall short of the goal"]},"course-correct":{"example2":"When the strategy underperformed, management moved quickly to course-correct.","exampleJa2":"戦略が振るわなかったとき、経営陣は迅速に軌道修正に動いた。","origin":"船や飛行機の「進路(course)を修正(correct)する」が原義。航海術の用語がビジネスの軌道修正に転用された。","collocations":["course-correct quickly","ability to course-correct","course-correct midway"]},"solution-oriented":{"example2":"Clients appreciate a solution-oriented advisor who offers concrete next steps.","exampleJa2":"顧客は、具体的な次の一手を示してくれる解決志向のアドバイザーを高く評価する。","origin":"solution(解決策)+oriented(〜の方向を向いた)。orient は「東を向ける」が原義で、意識の向き先を表す接尾的表現。","collocations":["solution-oriented approach","solution-oriented mindset","solution-oriented team"]},"mutually beneficial":{"example2":"The bank and the fintech firm formed a mutually beneficial partnership.","exampleJa2":"その銀行とフィンテック企業は、相互に有益なパートナーシップを結んだ。","origin":"ラテン語 mutuus(お互いの)+bene(良く)+facere(行う)。「互いに良いことをもたらす」と語源通りの意味。","collocations":["mutually beneficial relationship","mutually beneficial agreement","mutually beneficial partnership"]},"persuasive":{"example2":"His persuasive pitch convinced the committee to approve the new fund.","exampleJa2":"彼の説得力のあるプレゼンが委員会を動かし、新ファンドの承認につながった。","origin":"ラテン語 per(完全に)+suadere(勧める)→「徹底的に勧めて納得させる」。suadeは sweet(甘い)と同源。","collocations":["persuasive argument","highly persuasive","persuasive evidence"]},"do your homework":{"example2":"Before recommending any fund, do your homework on its fee structure.","exampleJa2":"ファンドを勧める前に、その手数料体系について下調べをしなさい。","origin":"学校の「宿題(homework)をやる」からの比喩。会議や商談の前に宿題を済ませておく=入念に下調べするイメージ。","collocations":["do your homework before investing","do your homework on the company","clearly did their homework"]},"pain points":{"example2":"High fees and slow reporting are common pain points for fund investors.","exampleJa2":"高い手数料と遅いレポーティングは、ファンド投資家に共通する悩みの種だ。","origin":"pain(痛み)+point(箇所)。「体の痛む場所」の比喩で、顧客が痛みを感じている具体的な問題点を指すマーケ用語。","collocations":["identify pain points","address customer pain points","major pain points"]},"resonate":{"example2":"The message about long-term investing resonated with younger clients.","exampleJa2":"長期投資に関するそのメッセージは、若い顧客層の共感を呼んだ。","origin":"ラテン語 re(再び)+sonare(鳴る)→「音が響き返る」。共鳴が原義で、心に響いて共感を呼ぶ意味に発展。","collocations":["resonate with the audience","resonate deeply","message that resonates"]},"pushes back":{"example2":"The board pushed back on the proposal to raise management fees.","exampleJa2":"取締役会は、運用報酬を引き上げる提案に反対した。","origin":"push(押す)+back(押し返す)。相手の提案という「押し」を押し返すイメージ。物理的な押し合いの比喩で覚える。","collocations":["push back on the proposal","push back against the idea","push back hard"]},"meet in the middle":{"example2":"On the contract terms, both firms agreed to meet in the middle.","exampleJa2":"契約条件について、両社は歩み寄ることで合意した。","origin":"「真ん中(middle)で会う(meet)」が直訳。両者が歩み寄って中間地点で落ち合う、交渉の妥協のイメージそのまま。","collocations":["meet in the middle on price","willing to meet in the middle","let's meet in the middle"]},"sweeten the deal":{"example2":"To sweeten the deal, the broker offered reduced fees for the first year.","exampleJa2":"取引を魅力的にするため、そのブローカーは初年度の手数料割引を提示した。","origin":"「取引(deal)を甘く(sweeten)する」が直訳。苦い薬に砂糖を加えるように、条件を上乗せして飲みやすくするイメージ。","collocations":["sweeten the deal with a bonus","sweeten the offer","to sweeten the deal further"]},"deliverables":{"example2":"The consulting agreement specifies monthly reports as key deliverables.","exampleJa2":"そのコンサルティング契約では、月次レポートが主要な成果物として明記されている。","origin":"deliver(届ける)+able(できるもの)の名詞化。「顧客に届けられるべきもの」→契約上の成果物・納品物の意味。","collocations":["key deliverables","project deliverables","deliver the deliverables on time"]},"complimentary":{"example2":"Attendees at the investor seminar received a complimentary market outlook report.","exampleJa2":"投資家セミナーの参加者には、無料の市場見通しレポートが配られた。","origin":"compliment(賛辞・儀礼)から。「儀礼として差し上げるもの」→無料の意味に。complement(補完)との混同に注意。","collocations":["complimentary breakfast","complimentary copy","complimentary access"]},"walk away":{"example2":"If the valuation doesn't improve, we're ready to walk away from the acquisition.","exampleJa2":"評価額が改善しなければ、我々はその買収から撤退する用意がある。","origin":"「歩いて(walk)その場を離れる(away)」が直訳。交渉のテーブルから席を立って去る場面をイメージすると覚えやすい。","collocations":["walk away from the deal","walk away from negotiations","willing to walk away"]},"untenable":{"example2":"Maintaining the fund's guaranteed return became untenable as rates fell.","exampleJa2":"金利が低下する中で、そのファンドの保証利回りを維持することは不可能になった。","origin":"un(否定)+ラテン語 tenere(保持する)+able→「持ちこたえられない」。tenantやmaintainと同源のtene(保つ)に注目。","collocations":["untenable position","become untenable","untenable situation"]},"erodes":{"example2":"Inflation slowly erodes the real value of cash savings.","exampleJa2":"インフレは現金貯蓄の実質的な価値を徐々に侵食していく。","origin":"ラテン語 e(外へ)+rodere(かじる)→「かじり取る」。ネズミがかじるイメージで、少しずつ削られていく様子を表す。","collocations":["erode trust","erode profit margins","erode purchasing power"]},"win-win":{"example2":"Lower costs for clients and higher retention for us is a win-win arrangement.","exampleJa2":"顧客のコスト低下と当社の顧客維持率向上につながる、双方にメリットのある仕組みだ。","origin":"「勝ち(win)+勝ち(win)」の反復。交渉理論で生まれた語で、両者が勝者になる結果を表す。反対はlose-lose。","collocations":["win-win situation","win-win outcome","create a win-win"]},"strike the right tone":{"example2":"In client apology letters, it's crucial to strike the right tone.","exampleJa2":"顧客への謝罪文では、適切なトーンをとることが極めて重要だ。","origin":"楽器の弦を打って(strike)正しい音(tone)を出すイメージ。場にふさわしい音色=言葉の調子を的確に打ち出す、と覚える。","collocations":["strike the right tone with clients","strike a balance","set the right tone"]},"undermine":{"example2":"Frequent leadership changes undermined confidence in the asset management firm.","exampleJa2":"度重なる経営陣の交代が、その運用会社への信頼を損なった。","origin":"under(下)+mine(坑道を掘る)。城壁の下にトンネルを掘って崩す中世の攻城戦術が語源。土台から弱らせるイメージ。","collocations":["undermine confidence","undermine credibility","undermine efforts"]},"per our conversation":{"example2":"Per our conversation, I've attached the revised fee schedule.","exampleJa2":"先ほどの話の通り、改定後の手数料表を添付しました。","origin":"ラテン語 per(〜を通じて・〜に従って)。「我々の会話に従って」が直訳で、口頭合意を文書で確認する定番の書き出し。","collocations":["per our conversation yesterday","per our discussion","per our phone call"]},"as per your request":{"example2":"As per your request, we have updated your investment risk profile.","exampleJa2":"ご依頼の通り、お客様の投資リスクプロファイルを更新いたしました。","origin":"as per は「〜に従って」を表す商業英語の定型。ラテン語由来のperにasを重ねたやや形式張った表現で、依頼への対応報告に使う。","collocations":["as per your request","as per your instructions","as per the agreement"]},"scannable":{"example2":"Use headings and short bullets to keep the report scannable.","exampleJa2":"見出しと短い箇条書きを使って、レポートを一目で把握できるようにしましょう。","origin":"scan(ざっと目を通す)+able(できる)。scanはラテン語scandere(登る)由来で、行を目でたどるイメージから。","collocations":["scannable format","make it scannable","scannable layout"]},"burying":{"example2":"Avoid burying the fee changes at the bottom of the client notice.","exampleJa2":"顧客通知の一番下に手数料変更の記載を埋もれさせるのは避けましょう。","origin":"bury(埋葬する・埋める)から。大事な情報を細部の土の下に「埋めて」見えなくするイメージ。報道用語 bury the lede が有名。","collocations":["burying the lede","burying the main point","burying key information"]},"please find attached":{"example2":"Please find attached the quarterly performance summary for your portfolio.","exampleJa2":"お客様のポートフォリオの四半期運用サマリーを添付いたしましたのでご確認ください。","origin":"手紙時代の商業英語の名残。「同封物を見つけてください」が直訳で、メール添付を案内するフォーマルな定型句として定着。","collocations":["please find attached the report","please find attached for your review","please find the attached file"]},"flag":{"example2":"The auditor flagged several inconsistencies in the expense reports.","exampleJa2":"監査人は経費報告書の中のいくつかの不整合を指摘した。","origin":"旗(flag)を立てて目印にすることから。問題箇所に旗を立てて「ここに注意」と知らせるイメージで覚える。","collocations":["flag an issue","flag a concern","flag it for review"]},"correspondence":{"example2":"Regulators requested all correspondence related to the fund launch.","exampleJa2":"規制当局は、そのファンド設定に関するすべてのやり取りの提出を求めた。","origin":"ラテン語 com(共に)+respondere(応答する)→「互いに応答し合う」。手紙やメールの往復のやり取りを指す。","collocations":["business correspondence","email correspondence","keep correspondence on file"]},"don't hesitate to reach out":{"example2":"If you need help interpreting the fund report, don't hesitate to reach out.","exampleJa2":"ファンドレポートの読み方でお困りの際は、お気軽にご連絡ください。","origin":"hesitate(ためらう)を否定し、reach out(手を伸ばす)を促す形。「遠慮なく手を伸ばして」という温かい定型の結び文句。","collocations":["don't hesitate to reach out anytime","feel free to reach out","reach out with any questions"]},"polished":{"example2":"Her polished delivery made the complex fund strategy easy to follow.","exampleJa2":"彼女の洗練された話しぶりのおかげで、複雑なファンド戦略が理解しやすくなった。","origin":"polish(磨く)の過去分詞。靴や宝石を磨き上げるように、細部まで磨かれて輝いている状態のイメージ。","collocations":["polished presentation","polished performance","polished and professional"]},"fundamentally":{"example2":"The two funds differ fundamentally in their approach to risk.","exampleJa2":"その2つのファンドは、リスクへのアプローチが根本的に異なる。","origin":"ラテン語 fundamentum(土台・基礎)から。fund(資金)も同源で「基金=事業の土台となる金」。土台のレベルで、の意。","collocations":["fundamentally different","fundamentally change","fundamentally sound"]},"hop on a call":{"example2":"Let's hop on a call this afternoon to review the portfolio changes.","exampleJa2":"今日の午後に電話をつないで、ポートフォリオの変更内容を確認しましょう。","origin":"hop(ぴょんと跳ぶ)+call(通話)。バスに飛び乗るように気軽にさっと通話に参加するカジュアルなイメージ。","collocations":["hop on a quick call","hop on a call later","hop on a Zoom call"]},"ping me":{"example2":"Ping me on Slack once the client approves the proposal.","exampleJa2":"クライアントが提案を承認したら、Slackで連絡してね。","origin":"潜水艦のソナー音「ピン」やネットワーク疎通確認のpingコマンドから。短い信号を送る→軽く連絡するの意味に。","collocations":["ping me when you're free","ping me on Slack","just ping me"]},"loop in":{"example2":"Please loop in our compliance officer before sending the marketing materials.","exampleJa2":"マーケティング資料を送る前に、コンプライアンス担当者を共有に加えてください。","origin":"loop(輪)の中に入れるイメージ。情報が回る「輪」に人を加える、と覚える。in the loop(輪の中=情報共有圏内)と同系。","collocations":["loop in the team","loop me in","loop in the manager"]},"distributed teams":{"example2":"Managing distributed teams across time zones requires clear documentation.","exampleJa2":"タイムゾーンをまたぐ分散チームの管理には、明確な文書化が欠かせない。","origin":"ラテン語 dis(別々に)+tribuere(分け与える)。メンバーが各地に「分け配られた」チームというイメージ。","collocations":["manage distributed teams","fully distributed teams","distributed teams across time zones"]},"asynchronous":{"example2":"Asynchronous updates let our Tokyo and London offices collaborate smoothly.","exampleJa2":"非同期の情報共有のおかげで、東京とロンドンのオフィスは円滑に協働できる。","origin":"ギリシャ語 a(否定)+syn(共に)+chronos(時間)→「同じ時間を共有しない」。chronosは時の神クロノスと同じ。","collocations":["asynchronous communication","asynchronous work","asynchronous updates"]},"in the loop":{"example2":"Please keep the sales team in the loop on any fee changes.","exampleJa2":"手数料の変更があれば、営業チームにも情報を共有しておいてください。","origin":"情報が循環する「輪(loop)」の中にいるイメージ。輪の中=常に最新情報が回ってくる立場、と覚える。","collocations":["keep me in the loop","stay in the loop","out of the loop"]},"pitfalls":{"example2":"The guide explains common pitfalls of investing in emerging markets.","exampleJa2":"そのガイドは、新興国市場への投資でよくある落とし穴を解説している。","origin":"pit(穴)+fall(落ちる)。獲物を捕らえる「落とし穴」が原義。見えない場所に潜む危険、という比喩がそのまま。","collocations":["common pitfalls","avoid the pitfalls","potential pitfalls"]},"over-reliance":{"example2":"Over-reliance on a single revenue stream puts the firm at risk.","exampleJa2":"単一の収益源への過度の依存は、その会社をリスクにさらす。","origin":"over(過度に)+reliance(依存)。relyはラテン語 re(再び)+ligare(縛る)由来で、「頼って縛られすぎる」イメージ。","collocations":["over-reliance on technology","avoid over-reliance","over-reliance on a single client"]},"nuance":{"example2":"Translating client feedback requires attention to every nuance of tone.","exampleJa2":"顧客の声を翻訳するには、トーンの微妙なニュアンスすべてに注意が必要だ。","origin":"フランス語 nuer(色合いを変える)から。雲(ラテン語nubes)の色の濃淡が原義で、意味の微妙な濃淡を表す。","collocations":["subtle nuance","capture the nuance","lose the nuance"]},"default to":{"example2":"When markets get volatile, many investors default to cash.","exampleJa2":"市場が不安定になると、多くの投資家はつい現金に逃げがちになる。","origin":"defaultは「初期設定」。設定を変えなければ自動的にそうなる、というITの比喩で「考えずに〜を選んでしまう」意味に。","collocations":["default to email","default to the safest option","default to old habits"]},"back-and-forth":{"example2":"After weeks of back-and-forth, the two firms finally signed the agreement.","exampleJa2":"数週間にわたるやり取りの末、両社はついに契約を締結した。","origin":"back(後ろへ)+forth(前へ)の往復運動から。ボールを打ち合うように、メールや意見が行ったり来たりするイメージ。","collocations":["endless back-and-forth","back-and-forth emails","weeks of back-and-forth"]},"top-line":{"example2":"The CEO prioritized top-line growth over short-term profitability.","exampleJa2":"CEOは短期的な収益性よりも売上高の成長を優先した。","origin":"損益計算書の一番上の行(top line)に売上高が記載されることから。最上行=売上、最下行(bottom line)=純利益。","collocations":["top-line growth","top-line revenue","boost the top line"]},"year-over-year":{"example2":"Assets under management grew 20% year-over-year in the second quarter.","exampleJa2":"第2四半期の運用資産残高は前年比20%増加した。","origin":"「年(year)を年(year)に重ねて」比較する表現。YoYと略される。前年の同じ期間と比べることで季節要因を除くのが狙い。","collocations":["year-over-year growth","up 10% year-over-year","year-over-year comparison"]},"bottom-line":{"example2":"Cost-cutting measures had an immediate bottom-line impact.","exampleJa2":"コスト削減策は最終利益に即座に効果をもたらした。","origin":"損益計算書の一番下の行(bottom line)が純利益であることから。「結局のところ」という結論の意味でも使われる。","collocations":["bottom-line results","impact the bottom line","improve the bottom line"]},"headwinds":{"example2":"The fund faces headwinds from rising rates and a strong yen.","exampleJa2":"そのファンドは金利上昇と円高という逆風に直面している。","origin":"head(正面)+wind(風)=向かい風。飛行機や船が向かい風で減速する比喩で、業績を妨げる要因を表す市況用語。","collocations":["face headwinds","economic headwinds","currency headwinds"]},"gross margins":{"example2":"Software companies typically enjoy much higher gross margins than retailers.","exampleJa2":"ソフトウェア企業は通常、小売業よりもはるかに高い粗利益率を享受している。","origin":"grossはラテン語 grossus(太い・全体の)由来で「控除前の総額」。margin(余白・差額)は売上と原価の間の余白のイメージ。","collocations":["improve gross margins","gross margin expansion","healthy gross margins"]},"quarter-over-quarter":{"example2":"Net inflows to the fund declined slightly quarter-over-quarter.","exampleJa2":"そのファンドへの純流入額は前四半期比でわずかに減少した。","origin":"「四半期(quarter)を四半期に重ねて」比較する表現。QoQと略す。quarterは「4分の1」で、1年を4分割した期間のこと。","collocations":["quarter-over-quarter growth","up 5% quarter-over-quarter","quarter-over-quarter decline"]},"tailwinds":{"example2":"Demographic shifts provide long-term tailwinds for healthcare stocks.","exampleJa2":"人口動態の変化は、ヘルスケア株にとって長期的な追い風となっている。","origin":"tail(尾)+wind(風)=追い風。後ろから吹く風が飛行機を加速させる比喩で、業績を後押しする好材料を表す。","collocations":["strong tailwinds","benefit from tailwinds","macro tailwinds"]},"synergies":{"example2":"The acquisition is expected to generate $50 million in annual synergies.","exampleJa2":"その買収により、年間5,000万ドルのシナジーが生まれると見込まれている。","origin":"ギリシャ語 syn(共に)+ergon(働く)→「共に働くこと」。energyのergと同源。1+1が2以上になる相乗効果。","collocations":["cost synergies","realize synergies","revenue synergies"]},"offset":{"example2":"Gains in the equity portfolio offset losses on the bond side.","exampleJa2":"株式ポートフォリオの利益が、債券側の損失を相殺した。","origin":"off(離して)+set(置く)→「反対側に置いてバランスを取る」。天秤の反対側に重りを置いて釣り合わせるイメージ。","collocations":["offset losses","offset the increase","partially offset by"]},"outlook":{"example2":"The firm raised its full-year earnings outlook after strong quarterly results.","exampleJa2":"好調な四半期決算を受けて、その企業は通期の業績見通しを引き上げた。","origin":"out(外を)+look(見る)→「外を見渡す」。高台から先の景色を見晴らすイメージで、将来の見通しを表す。","collocations":["economic outlook","raise the outlook","cautious outlook"]},"cautiously optimistic":{"example2":"Analysts remain cautiously optimistic about emerging market bonds this year.","exampleJa2":"アナリストたちは今年の新興国債券について、慎重ながらも楽観的な見方を保っている。","origin":"caution(用心)+optimism(楽観)の組み合わせ。ブレーキに足を置きつつ前向き、という市場コメントの定番表現。","collocations":["remain cautiously optimistic","cautiously optimistic about the outlook","cautiously optimistic tone"]},"articulate":{"example2":"A good advisor can articulate complex risks in plain language.","exampleJa2":"優れたアドバイザーは、複雑なリスクを平易な言葉で明確に説明できる。","origin":"ラテン語 articulus(小さな関節)から。関節で区切るように、考えを一つひとつ区切ってはっきり表現するイメージ。","collocations":["articulate a vision","articulate clearly","articulate the value proposition"]},"cultural alignment":{"example2":"Before the merger, both firms assessed their cultural alignment carefully.","exampleJa2":"合併の前に、両社は文化的な適合性を慎重に評価した。","origin":"align はラテン語 linea(線)由来で「一直線に並べる」。二つの組織の価値観のベクトルが同じ線上に揃うイメージ。","collocations":["assess cultural alignment","strong cultural alignment","cultural alignment between teams"]},"cross-functional":{"example2":"A cross-functional task force was formed to launch the new fund.","exampleJa2":"新ファンドの立ち上げのために、部門横断的なタスクフォースが結成された。","origin":"cross(横切る)+functional(機能・部門の)。営業・運用・管理など部門の壁を「横切って」つなぐイメージ。","collocations":["cross-functional team","cross-functional collaboration","cross-functional project"]},"culture fit":{"example2":"Skills matter, but culture fit often determines long-term success.","exampleJa2":"スキルも重要だが、長期的な成功を左右するのはカルチャーフィットであることが多い。","origin":"culture(社風)+fit(合うこと)。服のサイズが体に合う(fit)ように、人の価値観が組織にぴったり合うイメージ。","collocations":["assess culture fit","good culture fit","culture fit interview"]},"thrive":{"example2":"Boutique asset managers can thrive by focusing on niche strategies.","exampleJa2":"小規模な運用会社は、ニッチ戦略に特化することで成功できる。","origin":"古ノルド語 thrifask(自分をつかみ取る)が語源。自ら糧をつかんで栄えるイメージ。thrifty(倹約な)と同源。","collocations":["thrive under pressure","thrive in a competitive market","help employees thrive"]},"wear many hats":{"example2":"As branch manager, she wears many hats, from sales to compliance.","exampleJa2":"支店長として、彼女は営業からコンプライアンスまで多くの役割をこなしている。","origin":"帽子(hat)は職業の象徴。職業ごとに違う帽子をかぶり分ける、つまり一人で何役も演じるというイメージのイディオム。","collocations":["wear many hats at work","wear multiple hats","wear two hats"]},"customer retention":{"example2":"Personalized portfolio reviews boosted customer retention by 15%.","exampleJa2":"一人ひとりに合わせたポートフォリオレビューにより、顧客維持率が15%向上した。","origin":"retainはラテン語 re(後ろに)+tenere(保つ)→「引き留めておく」。獲得(acquisition)と対で使われるマーケ指標。","collocations":["improve customer retention","customer retention rate","customer retention strategy"]},"hit the ground running":{"example2":"With prior fund experience, she hit the ground running in her new role.","exampleJa2":"ファンド業務の経験があった彼女は、新しい職務で即戦力として活躍した。","origin":"走行中の乗り物から飛び降りて、着地した瞬間から走り出すイメージ。助走なしで全力始動する軍隊由来ともされる表現。","collocations":["hit the ground running on day one","expected to hit the ground running","help new hires hit the ground running"]},"make an impact":{"example2":"The new analyst made an impact by improving our reporting process.","exampleJa2":"その新任アナリストは、レポーティング業務の改善で成果を出した。","origin":"ラテン語 in(中へ)+pangere(打ち込む)がimpactの語源。杭を打ち込むように、強い影響の跡を残すイメージ。","collocations":["make a real impact","make an immediate impact","make an impact on the team"]},"conveys":{"example2":"The annual report conveys a clear message about the firm's strategy.","exampleJa2":"その年次報告書は、会社の戦略について明確なメッセージを伝えている。","origin":"ラテン語 con(共に)+via(道)→「道を共にして運ぶ」。荷物を運ぶが原義で、意味や感情を運ぶ=伝えるに発展。","collocations":["convey a message","convey confidence","convey the importance"]},"fosters":{"example2":"Regular one-on-ones foster trust between managers and their teams.","exampleJa2":"定期的な1on1ミーティングは、上司とチームの間の信頼を育む。","origin":"古英語 fostrian(食べ物を与えて育てる)が語源。foster parent(里親)のfoster。栄養を与えて育てるイメージ。","collocations":["foster innovation","foster collaboration","foster a culture of trust"]},"morale":{"example2":"Transparent communication about the merger kept employee morale high.","exampleJa2":"合併に関する透明性のある情報共有が、従業員の士気を高く保った。","origin":"フランス語 moral(精神状態)から。軍隊の士気を表す用語として英語に入った。moral(道徳)と綴りが近いので注意。","collocations":["boost morale","team morale","low morale"]},"constructive criticism":{"example2":"Frame your feedback as constructive criticism, not personal attacks.","exampleJa2":"フィードバックは個人攻撃ではなく、建設的な批判として伝えましょう。","origin":"ラテン語 con(共に)+struere(積み上げる)がconstructの語源。壊すためでなく「積み上げる」ための批判、という対比で覚える。","collocations":["offer constructive criticism","accept constructive criticism","constructive criticism and praise"]},"executive summary":{"example2":"The 50-page fund analysis opens with a one-page executive summary.","exampleJa2":"その50ページのファンド分析は、1ページのエグゼクティブサマリーから始まる。","origin":"executive(経営幹部)+summary(要約)。多忙な幹部が本文を読まずに判断できるよう冒頭に置く要約、が由来。","collocations":["write an executive summary","one-page executive summary","executive summary of the report"]},"going above and beyond":{"example2":"She went above and beyond by preparing extra materials for the client.","exampleJa2":"彼女は顧客のために追加資料まで用意し、期待以上の働きをした。","origin":"above(上に)+beyond(超えて)の重ね掛け。求められたラインの「上、さらにその先」まで行くイメージ。軍の褒章文句が由来。","collocations":["go above and beyond expectations","go above and beyond for clients","consistently go above and beyond"]},"gone unnoticed":{"example2":"The small accounting error had gone unnoticed for two quarters.","exampleJa2":"その小さな会計上の誤りは、2四半期にわたって気づかれないままだった。","origin":"go+形容詞で「〜の状態のままでいる」。un(否定)+noticed(気づかれた)で、「気づかれない状態のまま進む」構文。","collocations":["did not go unnoticed","gone unnoticed for years","efforts that go unnoticed"]},"psychologically safe":{"example2":"In a psychologically safe team, juniors freely question senior analysts' assumptions.","exampleJa2":"心理的に安全なチームでは、若手がベテランアナリストの前提に自由に疑問を投げかけられる。","origin":"ギリシャ語 psyche(魂・心)+logy(学)が psychology の語源。Googleの研究で有名になった「心理的安全性」の形容詞形。","collocations":["psychologically safe environment","psychologically safe workplace","feel psychologically safe"]},"room for improvement":{"example2":"The audit found room for improvement in our reporting procedures.","exampleJa2":"監査により、当社のレポーティング手続きには改善の余地があることが分かった。","origin":"room は「部屋」でなく「空間・余地」の意。改善が入り込める「空きスペース」がまだある、というイメージで覚える。","collocations":["there is room for improvement","considerable room for improvement","identify room for improvement"]},"attention to detail":{"example2":"Fund accounting demands exceptional attention to detail.","exampleJa2":"ファンドの計理業務には、並外れた細部への注意力が求められる。","origin":"ラテン語 ad(〜へ)+tendere(伸ばす)がattentionの語源。細部(detail)へ意識の糸をぴんと張るイメージ。","collocations":["strong attention to detail","meticulous attention to detail","require attention to detail"]},"incorporate":{"example2":"The revised model incorporates the latest inflation data.","exampleJa2":"改訂されたモデルには、最新のインフレデータが組み込まれている。","origin":"ラテン語 in(中へ)+corpus(体)→「体の中に取り込む」。栄養を体に取り込むように、一部として組み込むイメージ。","collocations":["incorporate feedback","incorporate changes","incorporate into the plan"]},"defensive":{"example2":"He grew defensive when the client questioned his fee calculations.","exampleJa2":"顧客に手数料の計算を疑問視されると、彼は身構えた態度になった。","origin":"ラテン語 de(離れて)+fendere(打つ)→「打撃を払いのける」。攻撃を防ぐ盾を構えるイメージが、心理的な身構えにも。","collocations":["get defensive","defensive reaction","become defensive about criticism"]},"departure":{"example2":"The CFO's sudden departure raised concerns among investors.","exampleJa2":"CFOの突然の退職は、投資家の間に懸念を引き起こした。","origin":"フランス語 departir(分かれて去る)から。de(分離)+part(部分)で「その場から分かれて離れる」イメージ。","collocations":["sudden departure","announce her departure","departure from the company"]},"professional reputation":{"example2":"Years of honest client service built his strong professional reputation.","exampleJa2":"長年の誠実な顧客対応が、彼の確固たる職業上の評判を築いた。","origin":"ラテン語 re(繰り返し)+putare(考える)がreputationの語源。人々が繰り返し思い浮かべる評価、というイメージ。","collocations":["build a professional reputation","protect your professional reputation","damage his professional reputation"]},"put in your notice":{"example2":"After accepting the offer, he put in his notice at the bank.","exampleJa2":"オファーを受諾した後、彼は銀行に退職届を出した。","origin":"notice は「事前通知」。退職の何週間前かに通知(notice)を提出する(put in)という欧米の退職慣行から来た表現。","collocations":["put in your two weeks' notice","put in her notice yesterday","put in my notice next month"]},"submit my resignation":{"example2":"I plan to submit my resignation once the project wraps up.","exampleJa2":"プロジェクトが完了したら、辞表を提出するつもりです。","origin":"ラテン語 re(再び)+signare(署名を消す)がresignの語源。「署名した契約を取り消す」→辞任するの意味に。","collocations":["submit my resignation letter","formally submit my resignation","submit his resignation to the board"]},"pursue other opportunities":{"example2":"The press release said the director left to pursue other opportunities.","exampleJa2":"プレスリリースには、その取締役は他の機会を追求するために退任したと書かれていた。","origin":"pursueはラテン語 pro(前へ)+sequi(追う)→「追い求める」。退職理由をぼかす外交的な決まり文句として定着。","collocations":["leave to pursue other opportunities","decided to pursue other opportunities","pursue new opportunities"]},"airing grievances":{"example2":"Airing grievances on social media can damage your professional image.","exampleJa2":"SNSで不満を言い散らすことは、あなたの職業上のイメージを傷つけかねない。","origin":"air(空気にさらす)+grievance(不満)。洗濯物を外に干すように、不満を人前にさらけ出すイメージで覚える。","collocations":["air grievances publicly","a chance to air grievances","avoid airing grievances"]},"burning bridges":{"example2":"She left the firm gracefully, careful to avoid burning bridges.","exampleJa2":"彼女は関係を断ち切らないよう気を配りながら、円満に会社を去った。","origin":"軍隊が渡った橋を焼き、退路を断った故事から。戻る道(人間関係)を自ら焼き払うイメージのイディオム。","collocations":["avoid burning bridges","don't burn bridges","burn bridges with former employers"]},"offboarding":{"example2":"A smooth offboarding process protects client relationships during staff transitions.","exampleJa2":"円滑な退職手続きは、担当者交代の際の顧客との関係を守ってくれる。","origin":"onboarding(乗船=入社手続き)の対義語として生まれた造語。船を降りる(off+board)=会社を離れるイメージ。","collocations":["offboarding process","employee offboarding","smooth offboarding"]},"document my workflows":{"example2":"Before the handover, I documented my workflows for the incoming analyst.","exampleJa2":"引き継ぎの前に、後任のアナリストのために自分の業務手順を文書化した。","origin":"documentはラテン語 docere(教える)由来で「教えるための記録」。workflow(仕事の流れ)を後任に教える文書にする、の意。","collocations":["document your workflows","document processes clearly","document workflows before leaving"]},"lasting impression":{"example2":"Her confident presentation made a lasting impression on the fund's investment committee.","exampleJa2":"彼女の自信に満ちたプレゼンは、ファンドの投資委員会に永続的な印象を残した。","origin":"last(続く)+ing→「長く続く」impression(押し付けられた跡→印象)。心に押された跡が消えずに残るイメージ。","collocations":["make a lasting impression","leave a lasting impression"]},"stay in touch":{"example2":"Good salespeople stay in touch with clients even after the deal closes.","exampleJa2":"優秀な営業担当者は、契約成立後も顧客と連絡を取り合う。","origin":"touch(触れる)の状態にstay(とどまる)。相手と「触れ合える距離」を保ち続けるイメージで「連絡を保つ」。","collocations":["stay in touch with clients","let's stay in touch"]},"keeps the door open":{"example2":"Declining the offer politely keeps the door open for future negotiations.","exampleJa2":"丁寧にオファーを断ることで、将来の交渉の可能性を残しておける。","origin":"ドアを閉めず開けたままにする→相手がいつでも戻って来られる状態。関係や選択肢を閉ざさないイメージ。","collocations":["keep the door open for","keep your options open"]},"baffling":{"example2":"The sudden market crash was baffling even to veteran analysts.","exampleJa2":"突然の市場暴落は、ベテランのアナリストにとっても理解しがたいものだった。","origin":"baffle(困惑させる)+ing。元はスコットランド語で「公然と辱める」意。人を惑わせ立ち往生させるイメージ。","collocations":["a baffling mystery","utterly baffling","baffling behavior"]},"cutting off":{"example2":"The central bank risks cutting off credit to small businesses.","exampleJa2":"中央銀行は中小企業への信用供給を断ち切るリスクを負っている。","origin":"cut(切る)+off(離す)。つながっているものをスパッと切って切り離すイメージ。電話・資金・関係などに使う。","collocations":["cut off funding","cut off contact","cut off supply"]},"highkey":{"example2":"I'm highkey proud of how our team handled that difficult client.","exampleJa2":"うちのチームがあの難しい顧客に対応した姿を、はっきり言って誇りに思う。","origin":"写真用語のhigh-key(明るい調子)から。lowkey(こっそり)の対義スラング。「隠さず全開で」と覚える。","collocations":["highkey excited","highkey obsessed with"]},"sincerity":{"example2":"Clients can sense the sincerity behind a financial advisor's recommendations.","exampleJa2":"顧客はファイナンシャルアドバイザーの提案の裏にある誠実さを感じ取れる。","origin":"ラテン語sincerus(混じり気のない、純粋な)から。飾りや偽りが混ざっていない心=誠実さ。","collocations":["speak with sincerity","doubt someone's sincerity"]},"navigating":{"example2":"Investors are carefully navigating the uncertainty caused by rising interest rates.","exampleJa2":"投資家たちは金利上昇による不確実性を慎重に切り抜けている。","origin":"ラテン語navis(船)+agere(動かす)→船を操縦する。荒波の中を舵取りするように難局を進むイメージ。","collocations":["navigate a crisis","navigate the complexities of"]},"exposure":{"example2":"The fund reduced its exposure to emerging market currencies last quarter.","exampleJa2":"そのファンドは前四半期に新興国通貨へのエクスポージャーを減らした。","origin":"ex(外に)+pose(置く)→外にさらされること。金融では「リスクにさらされている度合い」の意味で頻出。","collocations":["exposure to risk","gain exposure","reduce exposure"]},"evolve":{"example2":"Our sales strategy must evolve as client needs become more complex.","exampleJa2":"顧客ニーズが複雑化するにつれ、私たちの営業戦略も進化しなければならない。","origin":"ラテン語e(外へ)+volvere(巻く、転がす)→巻物が開いていく→徐々に展開・発展するイメージ。","collocations":["evolve over time","continue to evolve","evolve into"]},"ballpark":{"example2":"Can you give me a ballpark figure for the fund's annual fees?","exampleJa2":"そのファンドの年間手数料の概算を教えてもらえますか。","origin":"野球場(ballpark)から。「球場内のどこかに球がある」程度の大まかさ→おおよその範囲、という米国らしい比喩。","collocations":["ballpark figure","ballpark estimate","in the ballpark"]},"bandwidth":{"example2":"Our team doesn't have the bandwidth to launch two products simultaneously.","exampleJa2":"うちのチームには2つの製品を同時に立ち上げる余力がない。","origin":"本来は通信の帯域幅。回線が太いほど多くのデータを流せる→人の処理能力・余力の比喩としてビジネスで定着。","collocations":["have the bandwidth to","limited bandwidth"]},"ubiquitous":{"example2":"Cashless payments have become ubiquitous in major financial centers.","exampleJa2":"キャッシュレス決済は主要な金融センターで至る所に普及した。","origin":"ラテン語ubique(どこでも)から。ubi(どこ)+que(〜でも)→どこにでも存在する、偏在する。","collocations":["become ubiquitous","ubiquitous presence"]},"embedded":{"example2":"Risk management is embedded in every stage of our investment process.","exampleJa2":"リスク管理は当社の投資プロセスのあらゆる段階に組み込まれている。","origin":"em(中に)+bed(寝床、土台)→土台の中に埋め込む。しっかり据え付けられて動かないイメージ。","collocations":["deeply embedded in","embedded in culture"]},"approximate":{"example2":"The approximate value of the portfolio is ten million dollars.","exampleJa2":"そのポートフォリオのおおよその価値は1000万ドルです。","origin":"ラテン語ad(〜へ)+proximus(最も近い)→正確な値に「近い」。proximity(近接)と同語源。","collocations":["approximate value","approximate cost","rough approximation"]},"originates":{"example2":"The term \"bull market\" originates from the way bulls attack upward.","exampleJa2":"「強気相場(ブル・マーケット)」という言葉は、雄牛が下から上へ突き上げる様子に由来する。","origin":"ラテン語origo(始まり、源)から。oriri(昇る、生じる)が語根で、orient(日の昇る東)とも同族。","collocations":["originate from","originate in","originating bank"]},"blending":{"example2":"The strategy involves blending passive index funds with active management.","exampleJa2":"その戦略はパッシブなインデックスファンドとアクティブ運用を融合させるものだ。","origin":"古ノルド語blanda(混ぜる)から。境目がわからなくなるまで滑らかに混ざり合うイメージ。blend(ブレンド)は日本語化。","collocations":["blend together","blend in with","a blend of styles"]},"bummed out":{"example2":"The whole team was bummed out when the deal fell through.","exampleJa2":"取引が破談になって、チーム全員ががっかりしていた。","origin":"bum(怠け者、だめなもの)から。「気分がだめな状態に落ちた」イメージのカジュアルな米スラング。","collocations":["bummed out about","totally bummed out"]},"stoked":{"example2":"We're all stoked about the new office opening next month.","exampleJa2":"来月の新オフィス開設に、みんなめちゃくちゃワクワクしている。","origin":"stoke(炉に薪をくべる)から。心の炎に燃料を注がれて燃え上がった状態→大興奮。元はサーファー用語。","collocations":["stoked about","so stoked to"]},"containable":{"example2":"Regulators insisted the banking crisis was containable and temporary.","exampleJa2":"規制当局は、その銀行危機は制御可能で一時的なものだと主張した。","origin":"contain(con共に+tenere保つ→中に収める)+able(できる)→枠の中に収めておける=制御できる。","collocations":["barely containable","a containable risk"]},"lingering":{"example2":"Lingering inflation concerns kept investors away from long-term bonds.","exampleJa2":"長引くインフレ懸念により、投資家は長期債を敬遠し続けた。","origin":"linger(長居する)+ing。古英語lengan(長くする)が語源で、longと同族。去るべきものがだらだら残るイメージ。","collocations":["lingering doubts","lingering effects","lingering concerns"]},"resentment":{"example2":"Unequal bonuses created deep resentment within the sales department.","exampleJa2":"不公平なボーナスが営業部内に深い恨みを生んだ。","origin":"re(再び)+sentir(感じる)→嫌な感情を何度も感じ直すこと。繰り返し思い出しては募る恨み。","collocations":["harbor resentment","deep resentment","resentment toward"]},"easygoing":{"example2":"Despite market pressure, our manager stays easygoing and approachable.","exampleJa2":"市場のプレッシャーにもかかわらず、私たちの上司は気楽で親しみやすいままだ。","origin":"easy(楽に)+going(進む)→楽に進んでいく人。物事を深刻に構えず流れに任せるイメージ。","collocations":["easygoing personality","easygoing attitude"]},"grab a bite":{"example2":"Do you want to grab a bite between the afternoon meetings?","exampleJa2":"午後の会議の合間に軽く食べに行かない？","origin":"grab(さっとつかむ)+a bite(ひと噛み)→ひと口分をさっとつかむ→手早く軽食を取るイメージ。","collocations":["grab a bite to eat","grab a quick bite"]},"hit the spot":{"example2":"After that long client call, this coffee really hits the spot.","exampleJa2":"長い顧客電話の後だと、このコーヒーが本当に染みるね。","origin":"spot(的の中心)をhit(命中)→欲求のど真ん中に命中する。的中の爽快感で「まさに求めていたもの」。","collocations":["really hit the spot","that hits the spot"]},"pig out":{"example2":"We celebrated the quarterly results by pigging out on pizza.","exampleJa2":"四半期決算のお祝いに、ピザを思いきり食べまくった。","origin":"pig(豚)のようにout(徹底的に)食べる。豚の大食いイメージそのままのカジュアルな句動詞。","collocations":["pig out on","pig out at the buffet"]},"foodie":{"example2":"My colleague is a foodie who knows every good lunch spot downtown.","exampleJa2":"私の同僚は食通で、都心の美味しいランチの店を全部知っている。","origin":"food(食べ物)+ie(愛称の接尾辞)。1980年代生まれの語で、「食べ物大好きっ子」という親しみを込めた響き。","collocations":["a real foodie","foodie culture","foodie scene"]},"hangry":{"example2":"Skipping lunch during busy trading days makes everyone hangry.","exampleJa2":"取引が忙しい日に昼食を抜くと、みんな空腹でイライラする。","origin":"hungry(空腹)+angry(怒り)の混成語(かばん語)。空腹と怒りが合体した状態、と字面のまま覚えられる。","collocations":["get hangry","feeling hangry"]},"picky eater":{"example2":"Being a picky eater makes business dinners abroad quite challenging.","exampleJa2":"好き嫌いが多いと、海外での会食はかなり大変だ。","origin":"pick(選ぶ)+y→選り好みする+eater(食べる人)。皿の中から食べられる物だけつまむ姿をイメージ。","collocations":["a picky eater","picky about food"]},"craving":{"example2":"Investors showed a strong craving for higher yields despite the risks.","exampleJa2":"投資家はリスクにもかかわらず、より高い利回りへの強い渇望を示した。","origin":"古英語crafian(強く要求する)から。体の奥から突き上げるように「くれ」と要求する欲求のイメージ。","collocations":["have a craving for","satisfy a craving","sugar craving"]},"overindulgence":{"example2":"Analysts warned that overindulgence in risky assets could hurt retail investors.","exampleJa2":"アナリストは、リスク資産への過度な傾倒は個人投資家を傷つきかねないと警告した。","origin":"over(過度に)+indulge(甘やかす、ふける)+ence。ラテン語indulgere(寛大にする)→自分を甘やかしすぎること。","collocations":["overindulgence in food","holiday overindulgence"]},"woven into":{"example2":"Risk awareness is woven into the culture of successful investment firms.","exampleJa2":"リスク意識は、成功している運用会社の文化に織り込まれている。","origin":"weave(織る)の過去分詞woven。布の糸のように分かちがたく編み込まれ、取り出せないイメージ。","collocations":["woven into the fabric of","deeply woven into"]},"snapped at":{"example2":"Under deadline pressure, the manager snapped at his assistant unfairly.","exampleJa2":"締め切りのプレッシャーで、その部長はアシスタントに理不尽にきつく当たった。","origin":"snap(パチンと鳴る、噛みつく)から。犬がガブッと噛みつくように、鋭く短い言葉で当たるイメージ。","collocations":["snap at someone","snap back angrily"]},"cut to the chase":{"example2":"Let's cut to the chase: can your fund beat the benchmark?","exampleJa2":"本題に入りましょう。御社のファンドはベンチマークに勝てるのですか。","origin":"無声映画時代、退屈な場面を飛ばして見せ場の追跡(chase)シーンへ切り替えた編集用語から。前置き抜きで見せ場へ。","collocations":["let's cut to the chase","cut straight to the chase"]},"no brainer":{"example2":"With fees that low, switching to the index fund was a no brainer.","exampleJa2":"あれほど手数料が低ければ、インデックスファンドへの乗り換えは考えるまでもなかった。","origin":"brain(脳)を使うno(必要なし)→脳みそ不要なほど簡単な判断。「脳いらず」と直訳で覚えると忘れない。","collocations":["a total no-brainer","it's a no-brainer"]},"plot twist":{"example2":"In a surprising plot twist, the struggling startup acquired its rival.","exampleJa2":"予想外のどんでん返しで、苦戦していたスタートアップがライバル企業を買収した。","origin":"plot(筋書き)+twist(ねじれ)→物語の筋が急にねじれて予想外の方向へ。SNSでは実生活の急展開にも使う。","collocations":["a shocking plot twist","in a plot twist"]},"steal the show":{"example2":"The junior analyst stole the show with her brilliant market forecast.","exampleJa2":"その若手アナリストは見事な市場予測で注目をさらった。","origin":"show(舞台)の主役の座をsteal(盗む)→脇役なのに観客の注目を全部奪ってしまうイメージの演劇由来イディオム。","collocations":["completely steal the show","steal the spotlight"]},"cliffhanger":{"example2":"The merger vote ended in a cliffhanger, with results due tomorrow.","exampleJa2":"合併の採決はハラハラの展開のまま終わり、結果は明日判明する。","origin":"cliff(崖)+hang(ぶら下がる)→崖っぷちにぶら下がった場面で「続く」となる連載小説の手法から生まれた語。","collocations":["end on a cliffhanger","a real cliffhanger"]},"transcended":{"example2":"The crisis transcended national borders, affecting markets worldwide.","exampleJa2":"その危機は国境を超え、世界中の市場に影響を及ぼした。","origin":"ラテン語trans(越えて)+scandere(登る)→登って乗り越える。限界や枠を上へ超えていくイメージ。","collocations":["transcend boundaries","transcend generations"]},"serialized":{"example2":"The documentary about Wall Street was serialized over eight weekly episodes.","exampleJa2":"そのウォール街のドキュメンタリーは週1回、全8話で連載形式で放送された。","origin":"series(連続)+ize(〜化する)+d。ラテン語serere(つなぐ)が語源で、数珠つなぎに順番に出すイメージ。","collocations":["serialized novel","serialized in a magazine"]},"suspense":{"example2":"Traders waited in suspense for the central bank's rate decision.","exampleJa2":"トレーダーたちは中央銀行の金利決定をはらはらしながら待った。","origin":"ラテン語suspendere(吊るす)から。結末が宙に吊るされたまま決まらない→はらはらする状態。suspendと同語源。","collocations":["keep someone in suspense","build suspense"]},"effortless":{"example2":"The app makes portfolio rebalancing feel effortless for beginners.","exampleJa2":"そのアプリを使うと、初心者でもポートフォリオのリバランスが楽にできる。","origin":"effort(努力)+less(〜なし)→努力いらず。実際は熟練の裏付けがあるのに楽々見える場合によく使う。","collocations":["look effortless","effortless style","effortless grace"]},"outperforming":{"example2":"Value stocks have been outperforming growth stocks this year.","exampleJa2":"今年はバリュー株がグロース株を上回る成績を上げている。","origin":"out(〜より上に、外へ)+perform(成果を出す)→相手より上の成績を出す。運用報告書の頻出語。","collocations":["outperform the market","outperform expectations"]},"sequences":{"example2":"The film's opening sequences were shot inside a real trading floor.","exampleJa2":"その映画の冒頭シーンは、実際のトレーディングフロアで撮影された。","origin":"ラテン語sequi(後に続く)から。順番に続いていく一連の流れ→映画では連続したひとまとまりの場面。","collocations":["action sequences","opening sequence","a sequence of events"]},"cheers":{"example2":"Cheers, mate. I'll send you the report by Friday.","exampleJa2":"ありがとう。金曜までにレポートを送るよ。","origin":"乾杯の掛け声cheersが、英国で「ありがとう」「じゃあね」の軽い挨拶に転用。グラスを掲げる気軽さで覚える。","collocations":["cheers for that","cheers, mate"]},"dodgy":{"example2":"The auditors flagged some dodgy accounting in the quarterly report.","exampleJa2":"監査人は四半期報告書の中の怪しい会計処理を指摘した。","origin":"dodge(ひらりとかわす)+y→追及をかわして逃げ回るような、まともでない感じ。英国口語の定番。","collocations":["dodgy deal","a bit dodgy","dodgy accounting"]},"gutted":{"example2":"I was absolutely gutted when the promotion went to someone else.","exampleJa2":"昇進が他の人に決まったとき、本当にがっかりした。","origin":"gut(内臓)を抜かれた状態→はらわたをえぐられたような喪失感。魚をさばくイメージで「空っぽの落胆」。","collocations":["absolutely gutted","gutted about"]},"knackered":{"example2":"After back-to-back client meetings all day, I'm completely knackered.","exampleJa2":"一日中立て続けの顧客ミーティングで、もうくたくただ。","origin":"knacker(老馬の処理業者)から。働けなくなった馬のように疲れ果てた状態、という英国スラング。","collocations":["completely knackered","absolutely knackered"]},"brilliant":{"example2":"You closed the deal already? Brilliant, well done!","exampleJa2":"もう契約をまとめたの？素晴らしい、よくやった！","origin":"フランス語briller(輝く)から。宝石のように輝く→見事な。英国では「いいね！」級の日常的な賞賛語。","collocations":["absolutely brilliant","a brilliant idea"]},"vice versa":{"example2":"Higher rates hurt bond prices, and vice versa when rates fall.","exampleJa2":"金利上昇は債券価格を下げ、金利低下時はその逆になる。","origin":"ラテン語で「順序(vice)が逆転して(versa)」。位置がくるりと入れ替わるイメージで「逆もまた然り」。","collocations":["and vice versa","or vice versa"]},"identically":{"example2":"The two funds are managed identically despite their different names.","exampleJa2":"その2本のファンドは名前こそ違うが、まったく同じように運用されている。","origin":"ラテン語idem(同じもの)から。identity(同一性)と同語源で、寸分違わず同一に、という副詞。","collocations":["identically dressed","behave identically"]},"hygiene":{"example2":"Good financial hygiene means reviewing your accounts every month.","exampleJa2":"健全な資産管理の習慣とは、毎月自分の口座を見直すことだ。","origin":"ギリシャ神話の健康の女神Hygieia(ヒュギエイア)から。健康を守るための清潔・衛生の実践。","collocations":["personal hygiene","food hygiene","dental hygiene"]},"devastation":{"example2":"The typhoon left widespread devastation across the coastal region.","exampleJa2":"台風は沿岸地域一帯に広範な壊滅的被害をもたらした。","origin":"ラテン語de(完全に)+vastare(荒らす)→徹底的に荒廃させること。vast(広大な)と同語源で、何もない荒野のイメージ。","collocations":["widespread devastation","utter devastation"]},"understated":{"example2":"The luxury brand is famous for its understated, minimalist designs.","exampleJa2":"その高級ブランドは、控えめでミニマルなデザインで有名だ。","origin":"under(下に、控えめに)+state(述べる)→実際より控えめに表現する。誇張の逆で、抑えるほど効く英国的美学。","collocations":["understated elegance","understated humor"]},"ironic":{"example2":"It's ironic that the risk management team caused the biggest loss.","exampleJa2":"リスク管理チームが最大の損失を出したとは皮肉なものだ。","origin":"ギリシャ語eironeia(無知を装うこと)から。ソクラテスの「とぼけ」に由来し、本心と逆を言う修辞。","collocations":["ironic twist","deeply ironic","an ironic tone"]},"arvo":{"example2":"The Sydney office usually wraps up meetings by early arvo.","exampleJa2":"シドニーオフィスはたいてい午後の早い時間までに会議を終える。","origin":"afternoonの豪州流短縮形。afterのaf→arvと訛らせ+o。豪州人は何でも短くして-oを付けると覚える。","collocations":["this arvo","Saturday arvo"]},"reckon":{"example2":"I reckon the market will recover by the end of the year.","exampleJa2":"年末までには市場は回復すると思うよ。","origin":"古英語gerecenian(数える、計算する)から。「計算して結論を出す」→「〜だと思う」。英豪で日常的なthinkの代用。","collocations":["I reckon so","what do you reckon?"]},"heaps":{"example2":"Thanks heaps for covering my shift on such short notice.","exampleJa2":"急なお願いだったのにシフトを代わってくれて本当にありがとう。","origin":"heap(山盛りの山)の複数形→「山ほど」。豪州ではvery/a lotの代わりに乱発される強調語。","collocations":["thanks heaps","heaps of time","heaps better"]},"no worries":{"example2":"\"Sorry for the late reply.\" \"No worries, take your time.\"","exampleJa2":"「返信が遅れてすみません」「大丈夫ですよ、ごゆっくり」","origin":"worry(心配)がno(無い)→「心配無用」。豪州のおおらかな国民性を象徴する万能フレーズとして世界に広まった。","collocations":["no worries at all","no worries, mate"]},"chucking a sickie":{"example2":"He chucked a sickie to watch the cricket final at home.","exampleJa2":"彼はクリケットの決勝を家で見るために仮病で仕事を休んだ。","origin":"chuck(放り投げる)+sickie(sick+ieで病欠の愛称)→「病欠を投げ込む」。豪州流の茶目っ気あるサボり表現。","collocations":["chuck a sickie","pull a sickie"]},"brekkie":{"example2":"The hotel serves a full brekkie until ten every morning.","exampleJa2":"そのホテルは毎朝10時までフルブレックファーストを提供している。","origin":"breakfastの豪州流短縮+ie。豪州人は長い単語を縮めて-ieや-oを付ける癖がある、と覚えれば応用が効く。","collocations":["grab brekkie","a big brekkie"]},"barbie":{"example2":"Bring some drinks; we'll throw a few steaks on the barbie.","exampleJa2":"飲み物を持ってきて。バーベキューでステーキを何枚か焼くから。","origin":"barbecueの豪州流短縮+ie。人形のバービーではなく網焼きの方。豪州文化の象徴的な週末行事。","collocations":["have a barbie","throw it on the barbie"]},"laid-back":{"example2":"His laid-back negotiating style actually puts clients at ease.","exampleJa2":"彼のゆったりした交渉スタイルは、実際のところ顧客を安心させる。","origin":"lay back(後ろにもたれる)から。椅子にゆったりもたれた姿勢そのままの、力の抜けたリラックス感。","collocations":["laid-back attitude","laid-back atmosphere"]},"distinctive":{"example2":"The fund's distinctive approach combines AI screening with human judgment.","exampleJa2":"そのファンドの独特なアプローチは、AIスクリーニングと人間の判断を組み合わせている。","origin":"ラテン語distinguere(切り分ける)から。di(離す)+stinguere(突き刺す)→他と刺し分けて区別できる特徴。","collocations":["distinctive feature","distinctive style","highly distinctive"]},"old-fashioned":{"example2":"He prefers old-fashioned phone calls to emails for important clients.","exampleJa2":"彼は重要な顧客には、メールより昔ながらの電話を好む。","origin":"old(古い)+fashion(流行、様式)+ed→「古い様式の」。流行遅れの意味にも、良き伝統の意味にもなる。","collocations":["old-fashioned values","good old-fashioned"]},"beloved":{"example2":"The beloved CEO retired after leading the company for thirty years.","exampleJa2":"その愛されたCEOは、30年間会社を率いた後に引退した。","origin":"be(強意)+loved(愛された)→深く愛された。文語的な響きがあり、故人や長年親しまれた存在に使われやすい。","collocations":["beloved by fans","a beloved tradition"]},"boomer":{"example2":"My dad jokes that he's a proud boomer who still prints emails.","exampleJa2":"父は、いまだにメールを印刷する誇り高きブーマー世代だと冗談を言う。","origin":"baby boomer(ベビーブーム世代)の略。「OK Boomer」というミームで「古い価値観の人」への皮肉語に転化。","collocations":["OK boomer","boomer generation"]},"vibe":{"example2":"The new trading floor has a surprisingly relaxed vibe.","exampleJa2":"新しいトレーディングフロアは意外なほどリラックスした雰囲気だ。","origin":"vibration(振動)の略。場や人が発する「波動」を感じ取るイメージ。1960年代ヒッピー文化からSNS時代に復活。","collocations":["good vibes","chill vibe","give off a vibe"]},"vibe check":{"example2":"Before pitching the idea, do a quick vibe check on the boss.","exampleJa2":"アイデアを提案する前に、上司の機嫌をさっと確認しておこう。","origin":"vibe(雰囲気)+check(確認)→その場のノリや相手の機嫌を確かめること。ミーム発の若者スラング。","collocations":["do a vibe check","pass the vibe check"]},"goat":{"example2":"Warren Buffett is often called the GOAT of value investing.","exampleJa2":"ウォーレン・バフェットはバリュー投資の史上最高峰(GOAT)とよく呼ばれる。","origin":"Greatest Of All Timeの頭字語。動物のヤギ(goat)と同じ綴りのため、ヤギの絵文字が賞賛の意味で使われる。","collocations":["the GOAT of tennis","GOAT status"]},"viral":{"example2":"Her simple explanation of compound interest went viral on social media.","exampleJa2":"彼女の複利のわかりやすい解説はSNSで爆発的に拡散した。","origin":"virus(ウイルス)の形容詞形。ウイルス感染のように人から人へ急拡大する様子をネット拡散に転用。","collocations":["go viral","viral video","viral marketing"]},"dismissal":{"example2":"Her quick dismissal of the merger proposal surprised the board.","exampleJa2":"彼女が合併案を即座に退けたことは、取締役会を驚かせた。","origin":"ラテン語dis(離れて)+mittere(送る)→送り出して追い払うこと。人の解雇にも、意見の却下にも使う。","collocations":["dismissal of the idea","unfair dismissal"]},"out of touch":{"example2":"Executives who never meet customers quickly become out of touch.","exampleJa2":"顧客に一切会わない経営陣は、すぐに現場感覚を失ってしまう。","origin":"touch(接触)の外にいる→現実と触れ合えていない状態。連絡が途絶える意味と、感覚がずれる意味の両方がある。","collocations":["out of touch with reality","hopelessly out of touch"]},"demographic":{"example2":"Retirement products must adapt to Japan's aging demographic.","exampleJa2":"退職後向け商品は、日本の高齢化する人口構成に適応しなければならない。","origin":"ギリシャ語demos(民衆)+graphein(記述する)→民衆を記録する学問。democracy(民主主義)のdemosと同じ。","collocations":["target demographic","demographic shift","younger demographic"]},"resurfaces":{"example2":"The debate over negative interest rates resurfaces whenever growth slows.","exampleJa2":"マイナス金利をめぐる議論は、成長が鈍化するたびに再浮上する。","origin":"re(再び)+surface(水面)→沈んでいたものが再び水面に浮かび上がる。潜水艦の浮上イメージで覚える。","collocations":["resurface years later","old rumors resurface"]},"linguistic":{"example2":"Subtle linguistic differences can cause misunderstandings in global negotiations.","exampleJa2":"微妙な言語の違いが、グローバルな交渉で誤解を生むことがある。","origin":"ラテン語lingua(舌、言語)から。舌=言葉という発想で、language(言語)やイタリア語lingua(舌)と同族。","collocations":["linguistic diversity","linguistic skills","linguistic barriers"]},"ironically":{"example2":"Ironically, the safest fund lost the most money that year.","exampleJa2":"皮肉にも、その年最も安全なはずのファンドが最大の損失を出した。","origin":"ironic(皮肉な)+ly。期待と正反対の結果になる状況を導く副詞で、文頭に置いて「皮肉にも」と使うことが多い。","collocations":["ironically enough","somewhat ironically"]},"throw a curveball":{"example2":"The regulator threw us a curveball by changing disclosure rules mid-year.","exampleJa2":"規制当局は年度の途中で開示ルールを変更し、我々に不意打ちをくらわせた。","origin":"野球の変化球(カーブ)から。まっすぐ来ると思った球が曲がる→予想を裏切る出来事を投げてくるイメージ。","collocations":["throw someone a curveball","life throws a curveball"]},"game plan":{"example2":"Our game plan is to target regional banks before expanding nationally.","exampleJa2":"私たちの作戦は、全国展開の前にまず地方銀行を狙うことだ。","origin":"アメフトなどの試合(game)前に立てる作戦(plan)から。スポーツ用語がビジネスの戦略一般に転用された。","collocations":["solid game plan","stick to the game plan"]},"hit a home run":{"example2":"The marketing team hit a home run with the viral campaign.","exampleJa2":"マーケティングチームはバズったキャンペーンで大成功を収めた。","origin":"野球のホームラン=一打で最大の得点。一発で華々しい大成功を収めるイメージの米国らしいイディオム。","collocations":["hit a home run with","a real home run"]},"drop the ball":{"example2":"We dropped the ball by missing the client's renewal deadline.","exampleJa2":"顧客の契約更新期限を逃してしまい、私たちはへまをした。","origin":"球技で捕るべきボールを落とす→任された責任を果たし損ねる。落球=チームに迷惑をかけるミスのイメージ。","collocations":["drop the ball on","really dropped the ball"]},"move the goalposts":{"example2":"Investors complained that the startup kept moving the goalposts on profitability.","exampleJa2":"投資家たちは、そのスタートアップが黒字化の基準を何度もずらすことに不満を漏らした。","origin":"サッカーのゴールポストを試合中に動かす反則的イメージ→達成間際に基準を変える不公平さを表す。","collocations":["keep moving the goalposts","shift the goalposts"]},"saturated":{"example2":"The robo-advisor market is saturated, making customer acquisition expensive.","exampleJa2":"ロボアドバイザー市場は飽和しており、顧客獲得コストが高くついている。","origin":"ラテン語satur(満腹の)から。satisfied(満足)と同語源。これ以上吸収できないほど満たされた状態。","collocations":["saturated market","saturated with","market saturation"]},"metaphors":{"example2":"Financial news is full of metaphors like bubbles, storms, and landings.","exampleJa2":"金融ニュースはバブル、嵐、着陸といった比喩であふれている。","origin":"ギリシャ語meta(越えて)+pherein(運ぶ)→意味を別の物へ運び移すこと。「人生は旅だ」のような転移表現。","collocations":["use a metaphor","a metaphor for life","mixed metaphors"]},"imagery":{"example2":"The annual report used powerful imagery of bridges and journeys.","exampleJa2":"その年次報告書は、橋や旅路といった印象的なイメージ表現を用いていた。","origin":"image(像)+ry(集合)→心に浮かぶ像の総体。読者の頭の中に絵を描かせる言葉づかいを指す文学用語。","collocations":["vivid imagery","visual imagery","poetic imagery"]},"follow through":{"example2":"Promising clients quick answers means nothing unless you follow through.","exampleJa2":"迅速な回答を顧客に約束しても、最後までやり遂げなければ意味がない。","origin":"ゴルフや野球のフォロースルー(振り抜き)から。打った後も腕を止めず振り切る→着手した事を完遂する。","collocations":["follow through on a promise","fail to follow through"]},"collective":{"example2":"The rate cut was a collective decision by all board members.","exampleJa2":"その利下げは、理事会メンバー全員による共同の決定だった。","origin":"ラテン語com(共に)+legere(集める)→共に集められた。collect(集める)の形容詞形で「みんなの」。","collocations":["collective effort","collective decision","collective memory"]},"shifting":{"example2":"Fund managers must respond quickly to shifting investor sentiment.","exampleJa2":"ファンドマネージャーは、移り変わる投資家心理に素早く対応しなければならない。","origin":"shift(位置を変える)+ing。古英語sciftan(分ける、配置する)から。砂丘のように絶えず動き続けるイメージ。","collocations":["shifting priorities","shifting landscape","shifting sands"]},"broke":{"example2":"Many young traders go broke by ignoring basic risk management.","exampleJa2":"多くの若手トレーダーは、基本的なリスク管理を無視して一文無しになる。","origin":"break(壊れる)の過去形から。財産が「壊れて」しまった状態。銀行が破綻した客の皿を割った説もある。","collocations":["go broke","flat broke","completely broke"]},"loaded":{"example2":"Her new client is loaded and looking for private banking services.","exampleJa2":"彼女の新しい顧客は大金持ちで、プライベートバンキングのサービスを探している。","origin":"load(積み荷)を満載した状態→金を山ほど積んでいる。財布がずっしり重いイメージのスラング。","collocations":["absolutely loaded","loaded with cash"]},"splurge":{"example2":"After the bonus arrived, he splurged on a first-class flight home.","exampleJa2":"ボーナスが入った後、彼は奮発して帰省にファーストクラスを使った。","origin":"splash(バシャッ)+surge(噴出)を思わせる擬音的な造語。お金を派手にまき散らす音のイメージで覚える。","collocations":["splurge on","a little splurge"]},"rip-off":{"example2":"Charging three percent annually for an index fund is a rip-off.","exampleJa2":"インデックスファンドに年3%も課すのはぼったくりだ。","origin":"rip off(引き裂いて奪い取る)から。財布から金を引きちぎって持っていかれるイメージの口語名詞。","collocations":["a total rip-off","what a rip-off"]},"side hustle":{"example2":"Many bankers now run a side hustle selling online courses.","exampleJa2":"今では多くの銀行員が、オンライン講座を販売する副業を営んでいる。","origin":"side(本業の傍ら)+hustle(精力的に稼ぐ)。hustleは「押し合う」が原義で、がむしゃらに動いて稼ぐ響き。","collocations":["start a side hustle","turn a side hustle into a business"]},"rolling in it":{"example2":"After the IPO, the founders were absolutely rolling in it.","exampleJa2":"IPOの後、創業者たちはまさにお金がうなるほどある状態だった。","origin":"札束の山の上をroll(転げ回る)イメージ。itはmoneyを指す。お金のプールで泳ぐ絵を思い浮かべると忘れない。","collocations":["rolling in money","they're rolling in it"]},"penniless":{"example2":"The once-wealthy investor died penniless after years of bad bets.","exampleJa2":"かつて裕福だったその投資家は、長年の悪い賭けの末に無一文で亡くなった。","origin":"penny(最小単位の硬貨)+less(〜さえない)→1ペニーすら持たない。最小貨幣もない=完全な無一文。","collocations":["die penniless","left penniless"]},"arsenal":{"example2":"Central banks keep rate cuts in their arsenal for economic downturns.","exampleJa2":"中央銀行は景気後退に備えて、利下げという手段を蓄えている。","origin":"アラビア語dar as-sina'a(工房)からイタリア語経由で「武器庫」に。転じて使える手段・資源の豊富な蓄え。","collocations":["an arsenal of tools","add to one's arsenal"]},"stigma":{"example2":"The stigma around personal bankruptcy prevents many from seeking help.","exampleJa2":"自己破産にまつわる汚名のせいで、多くの人が助けを求められずにいる。","origin":"ギリシャ語で「焼き印、刺し傷」の意。奴隷や罪人に押した焼き印→社会が押す不名誉の烙印へと転じた。","collocations":["social stigma","carry a stigma","remove the stigma"]},"extravagantly":{"example2":"The hedge fund manager spent extravagantly on art and yachts.","exampleJa2":"そのヘッジファンドマネージャーは、美術品やヨットに贅沢にお金を使った。","origin":"ラテン語extra(外へ)+vagari(さまよう)→常識の枠外へさまよい出る→度を越して贅沢に。","collocations":["spend extravagantly","live extravagantly"]},"gig economy":{"example2":"Banks are designing new loan products for gig economy workers.","exampleJa2":"銀行はギグエコノミーで働く人向けの新しいローン商品を設計している。","origin":"gigは音楽家の単発演奏の仕事を指すスラング。一回限りの「ライブの仕事」が単発請負仕事全般に広がった。","collocations":["gig economy workers","the rise of the gig economy"]},"entrepreneurial":{"example2":"The bank rewards entrepreneurial employees who propose new business ideas.","exampleJa2":"その銀行は、新しいビジネスのアイデアを提案する起業家精神のある社員を評価する。","origin":"フランス語entre(間に)+prendre(取る)→間に立って引き受ける人=entrepreneur(起業家)の形容詞形。","collocations":["entrepreneurial spirit","entrepreneurial mindset"]},"exchange-traded fund (etf)":{"example2":"Many advisors recommend low-cost ETFs for long-term retirement accounts.","exampleJa2":"多くのアドバイザーは、長期の退職準備口座に低コストのETFを勧めています。","origin":"exchange(取引所)+traded(取引される)+fund(資金)。取引所で株式のように売買できる投資信託という直訳的な成り立ち。","collocations":["buy an ETF","bond ETF","ETF holdings"]},"diversification":{"example2":"Proper diversification across regions protected the fund during the downturn.","exampleJa2":"地域をまたぐ適切な分散投資が、下落局面でファンドを守りました。","origin":"ラテン語divertere(別方向へ向ける)+facere(作る)→多様に作り分けること。divert(そらす)と同語源。","collocations":["portfolio diversification","geographic diversification","lack of diversification"]},"underperform":{"example2":"Actively managed funds often underperform their benchmark indexes over time.","exampleJa2":"アクティブ運用のファンドは、長期ではベンチマーク指数を下回ることが多いです。","origin":"under(下に)+perform(成し遂げる)→基準より下の成績を出す。outperform(上回る)の対義語として対で覚える。","collocations":["underperform the market","underperform the benchmark","underperform expectations"]},"expense ratio":{"example2":"Compare expense ratios carefully before choosing between similar index funds.","exampleJa2":"似たインデックスファンドから選ぶ前に、経費率を慎重に比較しましょう。","origin":"expenseはラテン語expendere(支払う)から。ratio(比率)と組み合わせ、資産に対する年間費用の割合を示す。","collocations":["low expense ratio","annual expense ratio","high expense ratio"]},"intraday liquidity":{"example2":"Traders value intraday liquidity when markets move quickly on news.","exampleJa2":"相場がニュースで急変するとき、トレーダーは日中流動性を重視します。","origin":"intra(内側の)+day(日)→「一日の中の」。liquidityはラテン語liquidus(流れる)から。日中いつでも換金できる性質。","collocations":["provide intraday liquidity","ample intraday liquidity","intraday liquidity management"]},"in-kind redemption":{"example2":"The ETF processed a large in-kind redemption for an institutional client.","exampleJa2":"そのETFは機関投資家向けに大口の現物償還を処理しました。","origin":"in kindは「現金でなく同種の物で」の慣用句。redemptionはラテン語redimere(買い戻す)から。証券現物で払い戻す仕組み。","collocations":["in-kind redemption mechanism","process an in-kind redemption"]},"capital gains":{"example2":"She reported significant capital gains after selling her apartment last year.","exampleJa2":"彼女は昨年マンションを売却し、多額の譲渡益を申告しました。","origin":"capitalはラテン語caput(頭)から「元手」の意。元本から生じた利得(gains)という組み立てで覚える。","collocations":["capital gains tax","realize capital gains","long-term capital gains"]},"systemic":{"example2":"The failure of one large bank could trigger systemic problems.","exampleJa2":"大手銀行1行の破綻が、システム全体に及ぶ問題を引き起こす恐れがあります。","origin":"ギリシャ語systema(組み合わされたもの)+-ic(形容詞語尾)。個別でなく仕組み全体に関わることを表す。","collocations":["systemic risk","systemic failure","systemically important banks"]},"quantitative easing (qe)":{"example2":"Japan pioneered quantitative easing long before other major central banks.","exampleJa2":"日本は他の主要中央銀行に先駆けて量的緩和を導入しました。","origin":"quantitativeはラテン語quantus(どれだけの量)から。金利でなく資金の「量」を操作して緩和(easing)する政策という命名。","collocations":["launch quantitative easing","end QE","rounds of quantitative easing"]},"unconventional":{"example2":"Negative interest rates were once considered a highly unconventional tool.","exampleJa2":"マイナス金利はかつて、極めて非伝統的な手段と見なされていました。","origin":"un(否定)+con(共に)+ven(来る)→「皆が集まって決めた慣習」に従わない、の意。convene(招集する)と同語源。","collocations":["unconventional monetary policy","unconventional approach","unconventional methods"]},"transmission channels":{"example2":"Economists debate which transmission channels matter most for emerging markets.","exampleJa2":"新興国ではどの波及経路が最も重要か、経済学者の間で議論があります。","origin":"trans(越えて)+mission(送ること)→送り届ける道筋。政策効果が実体経済へ伝わる経路を水路(channel)に例えた表現。","collocations":["monetary transmission channels","credit transmission channel"]},"compress yields":{"example2":"Massive bond purchases by pension funds compressed yields even further.","exampleJa2":"年金基金による大量の債券購入が、利回りを一段と圧縮しました。","origin":"com(共に)+press(押す)→押し縮める。買い圧力が債券価格を押し上げ、利回りを押しつぶすイメージで覚える。","collocations":["compress bond yields","yield compression","compressed spreads"]},"wealth effect":{"example2":"The stock rally boosted consumer spending through the wealth effect.","exampleJa2":"株高は資産効果を通じて個人消費を押し上げました。","origin":"wealthは古英語wela(幸福・富)から、well(良い)と同語源。資産価格の上昇が消費心理に効く現象をeffect(効果)で表す。","collocations":["positive wealth effect","negative wealth effect","wealth effect on consumption"]},"balance sheet":{"example2":"Analysts examined the company's balance sheet before recommending the stock.","exampleJa2":"アナリストは株式を推奨する前に、その企業のバランスシートを精査しました。","origin":"balanceは「天秤」の意(ラテン語bilanx=二つの皿)。資産と負債・資本が釣り合う一枚の表というイメージ。","collocations":["strong balance sheet","balance sheet expansion","off-balance-sheet items"]},"bank reserves":{"example2":"The central bank pays interest on excess bank reserves.","exampleJa2":"中央銀行は超過準備金に利息を支払っています。","origin":"reserveはラテン語re(後ろに)+servare(保つ)→取っておくもの。銀行が支払いに備えて手元に保持する資金。","collocations":["excess bank reserves","reserve requirements","hold reserves at the central bank"]},"asset bubbles":{"example2":"History shows asset bubbles often end with painful corrections.","exampleJa2":"歴史を見ると、資産バブルはしばしば痛みを伴う調整で終わります。","origin":"bubble(泡)は中世英語の擬音語。実体なく膨らみ、はじけて消える泡に価格高騰をなぞらえた比喩表現。","collocations":["fuel asset bubbles","burst of a bubble","housing bubble"]},"unwinding":{"example2":"Investors began unwinding their yen carry trades after the announcement.","exampleJa2":"発表を受けて、投資家は円キャリー取引の巻き戻しを始めました。","origin":"un(逆に)+wind(巻く)→巻いたものをほどく。積み上げたポジションを逆の売買で解消していくイメージ。","collocations":["unwind positions","unwinding of carry trades","gradual unwinding"]},"quantitative tightening":{"example2":"Quantitative tightening drained liquidity from the banking system gradually.","exampleJa2":"量的引き締めは、銀行システムから流動性を徐々に吸収しました。","origin":"tightenはtight(締まった)+en(〜にする)。緩めるeasingの反対で、資産の「量」を絞る政策という対の命名。","collocations":["begin quantitative tightening","pace of QT","quantitative tightening program"]},"volatility":{"example2":"Options traders profit when implied volatility rises sharply.","exampleJa2":"オプショントレーダーは、インプライド・ボラティリティが急上昇すると利益を得ます。","origin":"ラテン語volare(飛ぶ)+-ilis(〜しやすい)→「飛びやすい」。価格が飛び回るように変動するイメージ。volatile(揮発性)と同語源。","collocations":["market volatility","implied volatility","volatility spike"]},"inject liquidity":{"example2":"The Bank of Japan injected liquidity through emergency lending operations.","exampleJa2":"日本銀行は緊急貸出オペを通じて流動性を注入しました。","origin":"in(中へ)+ject(投げる)→投げ入れる。市場という体に資金を注射するイメージ。eject・projectと同語源。","collocations":["inject liquidity into markets","liquidity injection","inject emergency funds"]},"green bond":{"example2":"Our bank underwrote a green bond financing offshore wind farms.","exampleJa2":"当行は洋上風力発電に資金を供給するグリーンボンドを引き受けました。","origin":"green(環境に優しい)+bond(債券)。bondは「縛るもの」が原義で、発行体と投資家を結ぶ約束を表す。","collocations":["issue green bonds","green bond market","green bond framework"]},"issuance":{"example2":"Corporate debt issuance slowed as borrowing costs climbed higher.","exampleJa2":"借入コストの上昇に伴い、社債の発行は減速しました。","origin":"issueはラテン語exire(外へ出る)から。証券を世に「出すこと」を名詞化した語で、-anceは行為を表す語尾。","collocations":["bond issuance","new share issuance","record issuance"]},"taxonomies":{"example2":"Regulators are developing taxonomies to classify sustainable investment products.","exampleJa2":"規制当局は、持続可能な投資商品を分類するタクソノミーを策定しています。","origin":"ギリシャ語taxis(配列・秩序)+nomos(法則)→分類の法則。生物分類学の用語が金融の分類体系へ転用された。","collocations":["EU taxonomy","green taxonomy","taxonomy regulation"]},"mandatory disclosure":{"example2":"Mandatory disclosure of climate risks takes effect next fiscal year.","exampleJa2":"気候リスクの義務的開示は来年度から施行されます。","origin":"mandatoryはラテン語mandare(命じる)から。dis(否定)+close(閉じる)→閉じたものを開く=公開する、の組み合わせ。","collocations":["mandatory disclosure requirements","mandatory climate disclosure"]},"niche":{"example2":"The firm dominates a profitable niche in trade finance.","exampleJa2":"その会社は貿易金融の収益性の高いニッチ市場を席巻しています。","origin":"フランス語niche(壁のくぼみ・巣)から。壁のくぼみに収まる像のように、小さな空間にぴったり収まる市場のイメージ。","collocations":["niche market","carve out a niche","niche product"]},"credentials":{"example2":"Investors questioned the fund's green credentials after the scandal.","exampleJa2":"不祥事の後、投資家はそのファンドの環境面での実績に疑問を呈しました。","origin":"ラテン語credere(信じる)から。credit(信用)と同語源で、「信じてもらうための証明」が原義。","collocations":["green credentials","establish credentials","academic credentials"]},"robust":{"example2":"The bank reported robust earnings despite the challenging environment.","exampleJa2":"その銀行は厳しい環境にもかかわらず、堅調な収益を発表しました。","origin":"ラテン語robur(樫の木・力)から。樫の木のように頑丈で揺るがない様子を表す。","collocations":["robust growth","robust demand","robust performance"]},"long-short equity":{"example2":"Long-short equity managers struggled when correlations across stocks rose.","exampleJa2":"銘柄間の相関が高まると、ロングショート戦略の運用者は苦戦しました。","origin":"long(買い持ち)+short(売り持ち)。買いと売りを組み合わせ、市場全体の上下に左右されにくくする戦略名。","collocations":["long-short equity fund","long-short equity strategy"]},"short-selling":{"example2":"Regulators temporarily banned short-selling during the market panic.","exampleJa2":"規制当局は市場パニックの間、空売りを一時的に禁止しました。","origin":"shortは「不足している」の意。手元にない(不足した)株を借りて売ることから。下落後に買い戻して返すと差益になる。","collocations":["ban short-selling","short-selling pressure","short-selling restrictions"]},"net market exposure":{"example2":"The hedge fund cut its net market exposure before the election.","exampleJa2":"そのヘッジファンドは選挙前にネット・マーケット・エクスポージャーを引き下げました。","origin":"net(正味の)は「網で漉した後に残るもの」のイメージ。買いと売りを相殺した後に残る市場リスクの量を指す。","collocations":["reduce net exposure","net long exposure","manage market exposure"]},"global macro":{"example2":"Global macro strategies performed well amid diverging central bank policies.","exampleJa2":"中央銀行の政策が分岐する中、グローバルマクロ戦略は好成績を収めました。","origin":"macroはギリシャ語makros(大きい)。個別企業でなく、世界(global)の大きな経済の流れ(macro)に賭ける戦略。","collocations":["global macro fund","global macro strategy","macro trading"]},"directional bets":{"example2":"The trader avoided directional bets and focused on relative value.","exampleJa2":"そのトレーダーは方向性のある賭けを避け、レラティブバリュー戦略に注力しました。","origin":"directionはラテン語dirigere(まっすぐ導く)から。相場が上か下か、その「方向」を当てに行く賭けの意。","collocations":["place directional bets","directional trading","directional bets on rates"]},"event-driven":{"example2":"Event-driven investors bought the stock ahead of the spinoff.","exampleJa2":"イベントドリブン型の投資家は、スピンオフを前にその株を買いました。","origin":"event(出来事)+driven(駆動される)。合併や再編など企業の「出来事」をエンジンにして利益を狙う戦略という命名。","collocations":["event-driven strategy","event-driven fund","event-driven opportunities"]},"merger arbitrage":{"example2":"Merger arbitrage returns depend heavily on deals closing as planned.","exampleJa2":"合併アービトラージの収益は、案件が予定通り成立するかに大きく依存します。","origin":"arbitrageはフランス語arbitrer(裁定する)から。合併発表後に残る価格差を「裁定」して利ざやを取る手法。","collocations":["merger arbitrage strategy","arbitrage spread","merger arbitrage fund"]},"acquirer":{"example2":"The acquirer must secure regulatory approval before completing the deal.","exampleJa2":"買収者は取引完了前に規制当局の承認を得る必要があります。","origin":"ラテン語ad(〜へ)+quaerere(求める)→求めて手に入れる者。question(探し求めること)と同語源。","collocations":["potential acquirer","strategic acquirer","acquirer's shares"]},"fee structures":{"example2":"Clients increasingly demand transparent fee structures from asset managers.","exampleJa2":"顧客は運用会社に対し、透明性の高い手数料体系をますます求めています。","origin":"feeは古フランス語fief(封土・報酬)から。structureはラテン語struere(積み上げる)で、料金の組み立てを表す。","collocations":["transparent fee structure","two-and-twenty fee structure","simplify fee structures"]},"lagged":{"example2":"Small-cap stocks lagged the broader market for most of 2025.","exampleJa2":"小型株は2025年の大半で市場全体に遅れをとりました。","origin":"北欧語系で「最後尾を歩く者」が原義とされる。jet lag(時差ぼけ=時間の遅れ)のlagと同じで「遅れ」のイメージ。","collocations":["lag behind the market","lag the benchmark","lagged performance"]},"geopolitical":{"example2":"Geopolitical risks in the region pushed oil prices sharply higher.","exampleJa2":"同地域の地政学的リスクが原油価格を大きく押し上げました。","origin":"geo(ギリシャ語で地球・土地)+political(政治の)。地理的条件が国際政治を左右するという発想から生まれた語。","collocations":["geopolitical tensions","geopolitical risk","geopolitical uncertainty"]},"sophistication":{"example2":"The model's sophistication makes it difficult for clients to understand.","exampleJa2":"そのモデルは精巧なため、顧客には理解が難しくなっています。","origin":"ギリシャ語sophos(賢い)から。sophist(詭弁家)と同語源で、現代では「知的に洗練されている」が中心的な意味。","collocations":["level of sophistication","financial sophistication","growing sophistication"]},"cryptocurrency":{"example2":"Several pension funds now hold small allocations to cryptocurrency.","exampleJa2":"現在、いくつかの年金基金は暗号資産に少額の配分を行っています。","origin":"crypto(ギリシャ語kryptos=隠された)+currency(通貨)。暗号技術で守られた通貨という成り立ち。","collocations":["cryptocurrency exchange","trade cryptocurrency","cryptocurrency regulation"]},"disintermediation":{"example2":"Online platforms accelerated disintermediation in the consumer lending market.","exampleJa2":"オンラインプラットフォームは、個人向け融資市場での中抜きを加速させました。","origin":"dis(除去)+inter(間の)+media(中間)→「間に立つもの」を取り除くこと。intermediary(仲介者)と同語源。","collocations":["bank disintermediation","disintermediation of finance"]},"money laundering":{"example2":"The exchange paid heavy fines for weak money laundering controls.","exampleJa2":"その取引所はマネーロンダリング対策の不備で多額の罰金を科されました。","origin":"launder(洗濯する)から。汚れた(違法な)資金を洗ってきれいに見せる、という比喩がそのまま定着した語。","collocations":["anti-money laundering rules","money laundering scheme","combat money laundering"]},"stablecoins":{"example2":"Regulators want stablecoins backed by high-quality liquid reserves.","exampleJa2":"規制当局は、ステーブルコインに質の高い流動性資産の裏付けを求めています。","origin":"stable(安定した。ラテン語stare「立つ」から)+coin(硬貨)。価格が安定して「立っている」コインという命名。","collocations":["dollar-pegged stablecoin","stablecoin issuer","stablecoin reserves"]},"legal tender":{"example2":"Shops cannot always refuse legal tender for settling debts.","exampleJa2":"店舗は債務の決済において、法定通貨の受け取りを常に拒めるわけではありません。","origin":"tenderはラテン語tendere(差し出す)から。「法により支払いとして差し出せるもの」が原義。attendと同語源。","collocations":["legal tender status","make Bitcoin legal tender","legal tender laws"]},"par value":{"example2":"The bond traded well below par value after the downgrade.","exampleJa2":"格下げ後、その債券は額面価格を大きく下回って取引されました。","origin":"parはラテン語で「等しい」の意。額面と「等価」である状態が原義で、ゴルフのパー(基準打数)も同語源。","collocations":["at par value","below par","redeem at par"]},"howey test":{"example2":"Under the Howey Test, many tokens qualify as securities.","exampleJa2":"ハウイ・テストの下では、多くのトークンが証券に該当します。","origin":"1946年の米最高裁判決「SEC対Howey社事件」に由来。オレンジ農園への投資契約が争われた事件名がそのまま基準名になった。","collocations":["apply the Howey Test","pass the Howey Test","Howey Test criteria"]},"permissive":{"example2":"The country attracted crypto startups with its permissive regulatory framework.","exampleJa2":"その国は寛容な規制の枠組みで暗号資産スタートアップを引き付けました。","origin":"per(通して)+mittere(送る)→通すことを許す。permit(許可する)の形容詞形で、-iveは性質を表す語尾。","collocations":["permissive regulations","permissive environment","permissive approach"]},"fiat currencies":{"example2":"Critics argue fiat currencies lose value through persistent inflation.","exampleJa2":"批判者は、法定不換通貨は継続的なインフレで価値を失うと主張します。","origin":"fiatはラテン語で「かくあれ(なされよ)」の意。政府の命令だけで価値が生まれる通貨、という聖書由来の荘重な語。","collocations":["fiat money","backed by fiat currency","fiat currency system"]},"initial public offering (ipo)":{"example2":"The IPO was priced at the top of its range.","exampleJa2":"そのIPOは仮条件レンジの上限で価格決定されました。","origin":"initial(最初の。ラテン語initium「始まり」から)+public(公の)+offering(提供)。初めて株式を公に売り出すことの直訳。","collocations":["file for an IPO","IPO pricing","go public"]},"underwriters":{"example2":"The underwriters allocated shares mainly to long-term institutional investors.","exampleJa2":"引受会社は株式を主に長期保有の機関投資家に配分しました。","origin":"under(下に)+write(書く)。保険や証券の契約書の下部に署名してリスクを引き受けたことが語源。","collocations":["lead underwriter","underwriting fees","underwrite an offering"]},"due diligence":{"example2":"We conducted thorough due diligence on the target company's finances.","exampleJa2":"私たちは買収対象企業の財務について徹底的なデューデリジェンスを行いました。","origin":"due(当然払うべき)+diligence(注意深さ。ラテン語diligere「注意深く選ぶ」から)。「払うべき注意」という法律用語が原義。","collocations":["conduct due diligence","due diligence process","legal due diligence"]},"prospectus":{"example2":"The prospectus warned investors about several significant risk factors.","exampleJa2":"目論見書は投資家に対し、いくつかの重大なリスク要因を警告していました。","origin":"ラテン語pro(前を)+spectus(見ること)→「見通し」。事業の見通しを示す文書の意。prospect(見込み)と同語源。","collocations":["read the prospectus","file a prospectus","preliminary prospectus"]},"registration statement":{"example2":"The SEC reviewed the registration statement and requested additional details.","exampleJa2":"SECは登録届出書を審査し、追加情報の提出を求めました。","origin":"registerはラテン語regerere(記録する)から。当局の帳簿に記載してもらうための陳述書(statement)という組み立て。","collocations":["file a registration statement","amend the registration statement"]},"quiet period":{"example2":"Executives declined interviews, citing the quiet period before the offering.","exampleJa2":"経営陣は公開前の沈黙期間を理由に取材を断りました。","origin":"quiet(静かな)+period(期間)。宣伝で株価をあおらないよう、会社が「静かに」していなければならない期間の直訳。","collocations":["during the quiet period","quiet period rules","violate the quiet period"]},"roadshow":{"example2":"Management met hundreds of fund managers during the two-week roadshow.","exampleJa2":"経営陣は2週間のロードショーで数百人のファンドマネージャーと面会しました。","origin":"元は劇団の「巡業公演」の意。road(道)+show(興行)で、各地を回って投資家に「上演」する説明会に転用された。","collocations":["investor roadshow","launch a roadshow","roadshow presentation"]},"proceeds":{"example2":"The company used the proceeds to repay its outstanding debt.","exampleJa2":"同社は調達資金を既存債務の返済に充てました。","origin":"ラテン語pro(前へ)+cedere(進む)→「前へ進み出てくるもの」=取引から生じて手元に入るお金。常に複数形で使う。","collocations":["net proceeds","use of proceeds","proceeds from the sale"]},"gauge":{"example2":"Analysts watch consumer surveys to gauge the economy's momentum.","exampleJa2":"アナリストは経済の勢いを見極めるために消費者調査を注視します。","origin":"古フランス語gauge(計量棒)から。線路幅や計器(ゲージ)の意味もあり、「物差しで測る」イメージで覚える。","collocations":["gauge demand","gauge investor sentiment","gauge the impact"]},"material information":{"example2":"Trading on material information before disclosure constitutes insider trading.","exampleJa2":"開示前の重要情報に基づく取引はインサイダー取引に該当します。","origin":"materialはラテン語materia(素材)から。判断の「実質・中身」に関わる情報の意で、法務・開示分野で多用される。","collocations":["material nonpublic information","disclose material information"]},"hype":{"example2":"Analysts urged caution, separating genuine growth from market hype.","exampleJa2":"アナリストは、本物の成長と市場の誇大宣伝を区別するよう注意を促しました。","origin":"hyperbole(誇張)の短縮が有力とされる俗語。あおって熱狂させるイメージで、AIブームなどの文脈で頻出。","collocations":["media hype","believe the hype","hype around AI"]},"currency risk":{"example2":"Unhedged overseas investments expose Japanese investors to significant currency risk.","exampleJa2":"為替ヘッジのない海外投資は、日本の投資家を大きな為替リスクにさらします。","origin":"currencyはラテン語currere(走る)から「流通するもの」。通貨価値の変動が損益を左右する危険を指す複合語。","collocations":["hedge currency risk","currency risk exposure","manage currency risk"]},"foreign exchange (fx)":{"example2":"The yen dominated foreign exchange headlines after the intervention.","exampleJa2":"為替介入の後、円が外国為替市場の話題を独占しました。","origin":"ex(外へ)+change(変える)→互いに取り替えること。外国の(foreign)通貨と交換する行為・市場を指す。","collocations":["foreign exchange market","foreign exchange reserves","FX intervention"]},"denominated":{"example2":"Emerging market companies often borrow through dollar-denominated debt.","exampleJa2":"新興国企業はドル建ての債務で借り入れることが多いです。","origin":"de(完全に)+nomin(名前)+ate→「名前を付ける」が原義。どの通貨の「名で」表示されるかを示す語。","collocations":["dollar-denominated bonds","yen-denominated assets","denominated in euros"]},"forward contract":{"example2":"The exporter signed a forward contract to sell dollars in June.","exampleJa2":"その輸出企業は、6月にドルを売る先渡契約を締結しました。","origin":"forward(前方へ)+contract(契約)。将来(前方)の時点の取引条件を今日決めておく契約、という直訳的な命名。","collocations":["enter into a forward contract","currency forward","forward rate"]},"receivables":{"example2":"The firm sold its receivables to improve short-term cash flow.","exampleJa2":"同社は短期の資金繰りを改善するため売掛金を売却しました。","origin":"receive(受け取る)+able(できる)→「これから受け取れるお金」。支払う側のpayables(買掛金)と対で覚える。","collocations":["accounts receivable","collect receivables","trade receivables"]},"payables":{"example2":"Extending payables helped the retailer preserve cash during the slowdown.","exampleJa2":"支払サイトの延長は、景気減速期に小売企業の現金温存に役立ちました。","origin":"payはラテン語pacare(なだめる)から。「支払って相手をなだめる」が原義。「支払うべきもの」の複数形。","collocations":["accounts payable","stretch payables","payables outstanding"]},"forward premium":{"example2":"The dollar's forward premium widened as US rates climbed.","exampleJa2":"米金利の上昇に伴い、ドルのフォワードプレミアムは拡大しました。","origin":"premiumはラテン語prae(前)+emere(買う)→「先に取る報酬」。先物レートが直物より高い「上乗せ分」を指す。","collocations":["forward premium on the dollar","trade at a forward premium"]},"interest rate differentials":{"example2":"Widening interest rate differentials strengthened the dollar against the yen.","exampleJa2":"金利差の拡大がドルを円に対して押し上げました。","origin":"differentialはラテン語differre(異なる)から。二国間の金利の「差」を表す専門語で、為替相場の基本的な決定要因。","collocations":["widening interest rate differentials","rate differential between countries"]},"currency options":{"example2":"The treasurer bought currency options to hedge the euro exposure.","exampleJa2":"財務担当者はユーロのエクスポージャーをヘッジするため通貨オプションを購入しました。","origin":"optionはラテン語optare(選ぶ)から。「行使するか選べる権利」が本質で、義務を負う先物との違いがここにある。","collocations":["buy currency options","option premium","exercise an option"]},"asymmetric":{"example2":"The trade offered asymmetric returns with limited downside risk.","exampleJa2":"その取引は、下値リスクが限定された非対称のリターンを提供しました。","origin":"a(否定)+sym(共に)+metron(尺度)→「同じ尺度でない」=左右で釣り合わない。symmetry(対称)の否定形。","collocations":["asymmetric risk","asymmetric payoff","asymmetric information"]},"upfront premium":{"example2":"Buyers pay an upfront premium in exchange for downside protection.","exampleJa2":"買い手は下値保護と引き換えに前払いプレミアムを支払います。","origin":"up frontは「前面に・最初に」の意の口語表現。契約の「入り口で先に」支払う料金というイメージで覚える。","collocations":["pay an upfront premium","upfront premium cost"]},"depreciates":{"example2":"When the yen depreciates, imported energy becomes considerably more expensive.","exampleJa2":"円が減価すると、輸入エネルギーはかなり割高になります。","origin":"de(下に)+pretium(価格)→価格が下がる。appreciate(価値が上がる・高く評価する)の対義語として覚える。","collocations":["the currency depreciates","depreciate against the dollar","depreciating asset"]},"recession":{"example2":"Economists assign a forty percent probability to a recession next year.","exampleJa2":"エコノミストは来年の景気後退の確率を40%と見ています。","origin":"re(後ろへ)+cedere(退く)→後退すること。経済が後ずさりするイメージ。recede(退く)と同語源。","collocations":["enter a recession","deep recession","recession fears"]},"inverted yield curve":{"example2":"The inverted yield curve persisted for a record eighteen months.","exampleJa2":"逆イールドカーブは過去最長の18か月間続きました。","origin":"invertはラテン語in(逆に)+vertere(回す)→ひっくり返す。通常は右上がりの利回り曲線が逆さになった状態。","collocations":["yield curve inversion","deeply inverted curve","the curve inverted"]},"duration risk":{"example2":"Insurers reduced duration risk by shifting into shorter-maturity bonds.","exampleJa2":"保険会社は残存期間の短い債券へ移すことでデュレーションリスクを削減しました。","origin":"durationはラテン語durare(続く)から「継続期間」。金利変動に対する債券価格の感応度を「期間」で測る発想。","collocations":["manage duration risk","take on duration risk","duration exposure"]},"leading economic index":{"example2":"The Leading Economic Index rebounded, easing fears of a downturn.","exampleJa2":"景気先行指数が反発し、景気悪化への懸念が和らぎました。","origin":"lead(先導する)+ing。景気に「先行して」動く複数の指標を束ねた合成指数で、米国では民間機関が毎月公表する。","collocations":["leading indicators","the index declined","composite index"]},"building permits":{"example2":"Building permits jumped ten percent as mortgage rates finally eased.","exampleJa2":"住宅ローン金利がようやく低下し、建築許可件数は10%急増しました。","origin":"permitはラテン語per(通して)+mittere(送る)→通ることを許す。着工前に当局が出す「許可」の件数で景気を先読みする。","collocations":["housing permits","permits issued","building permit applications"]},"foreshadow":{"example2":"Weak retail sales may foreshadow a broader consumer spending slowdown.","exampleJa2":"小売売上高の低迷は、より広範な個人消費減速の前兆かもしれません。","origin":"fore(前もって)+shadow(影)→「先に影を落とす」。出来事の影が本体より先に現れるイメージの語。","collocations":["foreshadow a recession","foreshadow trouble","foreshadow future declines"]},"unemployment claims":{"example2":"Initial unemployment claims fell to their lowest level since spring.","exampleJa2":"新規失業保険申請件数は春以来の低水準に減少しました。","origin":"claimはラテン語clamare(叫ぶ)から「権利を主張する」。失業給付を「請求する」件数で雇用情勢を測る指標。","collocations":["initial jobless claims","weekly unemployment claims","claims rose"]},"shed workers":{"example2":"Tech companies shed workers rapidly as venture funding dried up.","exampleJa2":"ベンチャー資金が枯渇する中、テック企業は急速に人員を削減しました。","origin":"shedは「(木が葉を)落とす、(動物の毛が)抜け替わる」の意。会社が不要になったものを振り落とすイメージ。","collocations":["shed jobs","shed thousands of workers","shed staff"]},"earnings revisions":{"example2":"Positive earnings revisions supported the market rally through the summer.","exampleJa2":"業績予想の上方修正が夏の間の株価上昇を支えました。","origin":"revisionはラテン語re(再び)+videre(見る)→見直し。アナリストが利益予想を「再び見て」修正することを指す。","collocations":["upward earnings revisions","downward revisions","revision momentum"]},"constellation":{"example2":"A constellation of risks kept the committee cautious about easing.","exampleJa2":"さまざまなリスクの集合が、委員会を利下げに慎重にさせました。","origin":"con(共に)+stella(星)→「星の集まり」=星座。複数の要素がひとまとまりに見える様子を星座に例えた比喩。","collocations":["a constellation of factors","a constellation of indicators"]},"contraction":{"example2":"Manufacturing activity showed contraction for the third consecutive month.","exampleJa2":"製造業活動は3か月連続で縮小を示しました。","origin":"con(共に)+trahere(引く)→引き寄せて縮める。contract(契約=互いを引き寄せる約束)と同語源で、経済の収縮を指す。","collocations":["economic contraction","credit contraction","sharp contraction"]},"deterioration":{"example2":"The deterioration in loan quality forced banks to raise provisions.","exampleJa2":"貸出資産の質の悪化により、銀行は引当金の積み増しを迫られました。","origin":"ラテン語deterior(より悪い)から。「悪い方へ進む過程」を表し、動詞はdeteriorate(悪化する)。","collocations":["credit deterioration","sharp deterioration","deterioration in conditions"]},"private equity (pe)":{"example2":"Private equity firms are targeting undervalued companies in Japan.","exampleJa2":"プライベートエクイティ各社は日本の割安な企業に狙いを定めています。","origin":"private(私的な。ラテン語privatus「公から切り離された」)+equity(株式)。公開市場の外で取引される株式の意。","collocations":["private equity firm","private equity fund","PE-backed company"]},"leveraged buyout (lbo)":{"example2":"The leveraged buyout loaded the retailer with unsustainable debt.","exampleJa2":"そのLBOは小売企業に持続不可能な負債を負わせました。","origin":"leverage(てこの力)+buyout(買い取り)。借入金を「てこ」にして、少ない自己資金で大きな企業を買収する手法。","collocations":["leveraged buyout deal","LBO financing","take a company private"]},"limited partners":{"example2":"Limited partners committed fresh capital despite weaker recent fund returns.","exampleJa2":"直近のファンド成績が振るわない中でも、リミテッドパートナーは新規資金を拠出しました。","origin":"limited(限定された)は、責任が出資額に「限定」されることを指す。経営に関与せず責任も限定的な出資者の意。","collocations":["limited partner commitments","LP investors","institutional limited partners"]},"general partners":{"example2":"General partners typically invest their own money alongside clients.","exampleJa2":"ジェネラルパートナーは通常、顧客と並んで自己資金も投資します。","origin":"generalはラテン語generalis(全体の)。責任が出資額に限定されず「全般に」及ぶ運用者、という法的地位からの命名。","collocations":["general partner of the fund","GP commitment","GP stakes"]},"carried interest":{"example2":"Politicians repeatedly propose taxing carried interest as ordinary income.","exampleJa2":"政治家は、キャリードインタレストを通常所得として課税する案を繰り返し提起しています。","origin":"中世の船荷貿易で、船長が運んだ積荷(carry)の利益の一部を報酬として受け取った慣行に由来するとされる語。","collocations":["earn carried interest","carried interest loophole","carried interest taxation"]},"hurdle rate":{"example2":"Returns above the hurdle rate trigger the manager's performance fee.","exampleJa2":"ハードルレートを超えるリターンが出ると、運用者の成功報酬が発生します。","origin":"hurdleは陸上競技の「障害物」。この柵を飛び越えて初めて成功報酬がもらえる、というイメージの命名。","collocations":["exceed the hurdle rate","set a hurdle rate","hurdle rate of 8 percent"]},"bolt-on":{"example2":"Two bolt-on deals expanded the platform company's regional coverage.","exampleJa2":"2件の追加型買収により、その中核企業の地域カバレッジが拡大しました。","origin":"bolt(ボルト)+on(上に)→機械にボルトで部品を付け足すイメージ。既存の投資先に小さな買収を「継ぎ足す」手法。","collocations":["bolt-on acquisition","bolt-on deal","bolt-on strategy"]},"capital structure":{"example2":"The CFO reviewed the capital structure to lower funding costs.","exampleJa2":"CFOは資金調達コストを下げるため資本構成を見直しました。","origin":"structureはラテン語struere(積み上げる)。負債と株式をどう「積み上げて」会社を支えるかという構成の意。","collocations":["optimal capital structure","capital structure decisions","debt-heavy capital structure"]},"illiquidity":{"example2":"Investors demand higher returns to compensate for illiquidity.","exampleJa2":"投資家は非流動性の見返りとして、より高いリターンを要求します。","origin":"il(否定)+liquid(液体の・流動的な)+ity。資産が水のように「流れず」、すぐに現金化できない状態を表す。","collocations":["illiquidity premium","illiquidity risk","market illiquidity"]},"locked up":{"example2":"Their money stays locked up until the fund's ten-year term ends.","exampleJa2":"資金はファンドの10年の存続期間が終わるまで引き出せません。","origin":"lock(錠)+up(完全に)→鍵をかけて閉じ込める。資金が金庫に施錠されて出せないイメージ。名詞形はlock-up。","collocations":["locked-up capital","lock-up period","funds locked up"]},"workforce reductions":{"example2":"The merger triggered workforce reductions across overlapping back-office departments.","exampleJa2":"合併により、重複するバックオフィス部門全体で人員削減が行われました。","origin":"workforce(労働力=work+force)+reduction(re「後ろへ」+ducere「導く」→減らすこと)。layoffの婉曲的な表現。","collocations":["announce workforce reductions","significant workforce reductions"]},"sovereign wealth fund (swf)":{"example2":"The sovereign wealth fund acquired stakes in several infrastructure projects.","exampleJa2":"その政府系ファンドは複数のインフラ事業の持分を取得しました。","origin":"sovereignはラテン語super(上に)から「主権者・国家」。国家の富(wealth)を運用する基金という直訳的な名称。","collocations":["sovereign wealth fund assets","state-owned fund","SWF investments"]},"fiscal surpluses":{"example2":"Years of fiscal surpluses allowed the government to cut debt.","exampleJa2":"長年の財政黒字により、政府は債務を削減できました。","origin":"fiscalはラテン語fiscus(かご・国庫)から。surplusはsur(超えて)+plus(多く)→「余り」。国庫の余剰の意。","collocations":["run a fiscal surplus","budget surplus","record surplus"]},"petroleum":{"example2":"Falling petroleum prices squeezed budgets across the Gulf states.","exampleJa2":"石油価格の下落は湾岸諸国の財政を圧迫しました。","origin":"ラテン語petra(岩)+oleum(油)→「岩の油」。岩の間から採れる油という古代からの命名がそのまま残った語。","collocations":["crude petroleum","petroleum products","petroleum exports"]},"ethical guidelines":{"example2":"The pension fund excluded weapons makers under its ethical guidelines.","exampleJa2":"その年金基金は倫理指針に基づき、兵器メーカーを投資対象から除外しました。","origin":"ethicalはギリシャ語ethos(習慣・品性)から。guidelineはguide(導く)+line(線)で「導きの線」=指針。","collocations":["follow ethical guidelines","strict ethical guidelines","ethical investment criteria"]},"diversified":{"example2":"A well-diversified fund cushioned investors from the tech sector crash.","exampleJa2":"十分に分散されたファンドは、テック株急落の打撃から投資家を守りました。","origin":"ラテン語diversus(異なる方向の)+facere(作る)→さまざまに作り分けた状態。「卵を一つの籠に盛るな」の発想。","collocations":["diversified portfolio","well-diversified","diversified holdings"]},"asset classes":{"example2":"Correlations between asset classes rose sharply during the panic.","exampleJa2":"パニックの間、資産クラス間の相関は急上昇しました。","origin":"assetは古フランス語asez(十分に)から「債務返済に十分な財産」。classはラテン語classis(区分)で、財産の区分の意。","collocations":["major asset classes","alternative asset classes","across asset classes"]},"mandates":{"example2":"Our investment mandates restrict exposure to unrated corporate bonds.","exampleJa2":"当社の運用マンデートでは、無格付け社債への投資が制限されています。","origin":"ラテン語 manus(手)+dare(与える)→「手に委ねる」が原義。手渡された任務・命令のイメージ。","collocations":["investment mandate","fulfill a mandate","conflicting mandates"]},"santiago principles":{"example2":"The new sovereign fund pledged full alignment with the Santiago Principles.","exampleJa2":"新設の政府系ファンドは、サンティアゴ原則への完全な準拠を表明した。","origin":"2008年にチリの首都サンティアゴで合意された政府系ファンド（SWF）の自主的ガバナンス指針。地名が由来。","collocations":["adopt the Santiago Principles","comply with the Santiago Principles"]},"compliance":{"example2":"The bank strengthened its compliance department after the regulatory fine.","exampleJa2":"その銀行は規制当局の罰金を受けて、コンプライアンス部門を強化した。","origin":"ラテン語 com(共に)+plere(満たす)→要求を満たす→規則に従うこと。complete(完全にする)と同語源。","collocations":["regulatory compliance","ensure compliance","compliance officer"]},"allocations":{"example2":"The committee revised its asset allocations toward emerging market equities.","exampleJa2":"委員会は資産配分を新興国株式寄りに見直した。","origin":"ラテン語 ad(〜へ)+locare(置く)→「特定の場所へ割り当てる」。location(場所)と同語源。","collocations":["asset allocation","budget allocation","strategic allocation"]},"dip":{"example2":"This meeting is dragging, so I'm about to dip.","exampleJa2":"この会議は長引いてるから、そろそろこっそり抜けるよ。","origin":"本来は「浸す・下がる」の意。姿がすっと沈んで消えるイメージから「黙って立ち去る」スラングに。","collocations":["dip early","about to dip","dip out"]},"peace out":{"example2":"That's a wrap for today's stream — peace out, everyone.","exampleJa2":"今日の配信はここまで。じゃあね、みんな。","origin":"別れ際のあいさつ peace(平和を)+out(去る)。ピースサインをして去るイメージで覚えると定着しやすい。","collocations":["peace out, everyone","say peace out"]},"call it quits":{"example2":"After years of losses, the hedge fund finally called it quits.","exampleJa2":"長年の損失の末、そのヘッジファンドはついに店じまいを決めた。","origin":"quits は「貸し借りなし」の意の古語。「貸し借りなしと宣言する」→きっぱり終わりにする、というイメージ。","collocations":["call it quits after","decide to call it quits"]},"resign":{"example2":"The CFO resigned amid questions about the firm's accounting practices.","exampleJa2":"そのCFOは、会社の会計処理への疑義が浮上する中で辞任した。","origin":"ラテン語 re(戻す)+signare(署名する)→署名して権限を返上する→辞任する。sign(署名)と同語源。","collocations":["resign from a post","resign as CEO","formally resign"]},"put in my two weeks":{"example2":"She put in her two weeks after landing a better offer.","exampleJa2":"彼女はより良いオファーを得て、2週間前の退職届を出した。","origin":"米国では退職の2週間前通知が慣例。put in(提出する)+two weeks' notice(2週間前通知)の省略形。","collocations":["put in my two weeks' notice","give two weeks' notice"]},"rage quit":{"example2":"He rage quit the trading desk after another brutal bonus season.","exampleJa2":"彼はまたも厳しいボーナス査定を受け、キレてトレーディングデスクを辞めた。","origin":"rage(激怒)+quit(辞める)。元はゲームで負けて激怒し途中退出するネットスラング。仕事にも転用された。","collocations":["rage quit a game","rage quit a job"]},"deal with":{"example2":"Our team deals with client complaints about fund performance daily.","exampleJa2":"私たちのチームは、ファンドの運用成績に関する顧客の苦情に日々対応している。","origin":"deal は「分ける・扱う」が原義。配られたカード(deal)を手元で処理するイメージで「対処する」。","collocations":["deal with a problem","deal with stress","hard to deal with"]},"had enough":{"example2":"Investors have had enough of the fund's excessive management fees.","exampleJa2":"投資家たちは、そのファンドの過大な運用報酬にもううんざりしている。","origin":"「十分(enough)を持った(had)」→これ以上は受け取れない→もう限界、の発想。コップが満杯のイメージ。","collocations":["have had enough of","I've had enough"]},"capture":{"example2":"The report captures the anxiety felt across global markets.","exampleJa2":"その報告書は、世界の市場に広がる不安感を的確に捉えている。","origin":"ラテン語 capere(つかむ)が語源。獲物を捕らえるように、感情や本質を「つかまえて表現する」イメージ。","collocations":["capture the mood","capture the essence","capture attention"]},"bussin":{"example2":"The catering at the client event was straight-up bussin.","exampleJa2":"クライアントイベントのケータリング、マジでめちゃくちゃ美味かった。","origin":"黒人英語(AAVE)由来のスラング。bust(はじける)から派生し、「味がはじけるほど美味い」イメージで覚える。","collocations":["this food is bussin","straight-up bussin"]},"go-to":{"example2":"This ETF is my go-to recommendation for first-time investors.","exampleJa2":"このETFは、初めて投資する人への私の定番のおすすめです。","origin":"「困ったらそこへ行く(go to)」が形容詞化。迷わず向かう先→定番・頼みの綱、というイメージ。","collocations":["go-to person","go-to option","go-to strategy"]},"top-notch":{"example2":"Their research team provides top-notch analysis of emerging markets.","exampleJa2":"彼らのリサーチチームは、新興国市場について一流の分析を提供している。","origin":"notch は「刻み目・段階」。目盛りの一番上(top)の段→最高ランク、というイメージで覚える。","collocations":["top-notch service","top-notch quality","top-notch team"]},"vernacular":{"example2":"Traders have their own vernacular that confuses new hires.","exampleJa2":"トレーダーには独特の業界言葉があり、新入社員を戸惑わせる。","origin":"ラテン語 vernaculus(その土地生まれの、家で育った)が語源。土地に根ざした「土着の言葉」のイメージ。","collocations":["local vernacular","in the vernacular","common vernacular"]},"mainstream":{"example2":"ESG investing has become mainstream among institutional investors.","exampleJa2":"ESG投資は機関投資家の間で主流になった。","origin":"main(主要な)+stream(流れ)→川の本流。支流ではなく本流に乗っている→世間の主流、というイメージ。","collocations":["go mainstream","mainstream media","mainstream adoption"]},"convey":{"example2":"The chairman's statement conveyed cautious optimism about rate cuts.","exampleJa2":"議長の声明は、利下げに対する慎重ながらも楽観的な見方を伝えていた。","origin":"ラテン語 con(共に)+via(道)→同じ道を運ぶ→運搬する→意味や感情を「運んで伝える」。convoy(護送)と同語源。","collocations":["convey a message","convey meaning","convey emotions"]},"enthusiasm":{"example2":"Retail investors showed renewed enthusiasm for tech stocks this quarter.","exampleJa2":"個人投資家は今四半期、ハイテク株への熱意を再び見せた。","origin":"ギリシャ語 en(中に)+theos(神)→「神が宿った状態」が原義。神がかり的な熱狂、のイメージ。","collocations":["show enthusiasm","great enthusiasm","with enthusiasm"]},"outfit":{"example2":"He wore a sharp outfit to impress the interview panel.","exampleJa2":"彼は面接官に好印象を与えようと、ビシッとした服装で臨んだ。","origin":"out(外へ)+fit(合わせる)→外出用に整えた装備一式→服装。「外に出るために揃えたもの」のイメージ。","collocations":["cute outfit","pick out an outfit","matching outfit"]},"talking stage":{"example2":"They met on an app and are still in the talking stage.","exampleJa2":"彼らはアプリで出会って、まだ付き合う前のやり取り段階だ。","origin":"talking(連絡を取り合う)+stage(段階)。交際前の「まだ話してるだけ」の探り合い期間を指すZ世代スラング。","collocations":["in the talking stage","past the talking stage"]},"situationship":{"example2":"She wants clarity, but he seems happy with their situationship.","exampleJa2":"彼女ははっきりさせたいのに、彼は今の曖昧な関係に満足しているようだ。","origin":"situation(状況)+relationship(恋愛関係)の合成語。「関係というより単なる状況」という皮肉を込めた造語。","collocations":["stuck in a situationship","end a situationship"]},"dtr":{"example2":"After three months of dating, they finally had the DTR talk.","exampleJa2":"3か月のデート期間を経て、彼らはついに関係をはっきりさせる話し合いをした。","origin":"Define The Relationship の頭字語。「この関係を定義しよう」という真剣な話し合いを指す略語。","collocations":["have the DTR talk","time to DTR"]},"catching feelings":{"example2":"They promised to keep it casual, but he's catching feelings.","exampleJa2":"気軽な関係でいようと約束したのに、彼は本気になり始めている。","origin":"catch(かかる)は風邪をひく(catch a cold)と同じ発想。恋心に「感染してしまう」イメージで覚える。","collocations":["catch feelings for someone","start catching feelings"]},"breadcrumbing":{"example2":"He texts her once a week — classic breadcrumbing behavior.","exampleJa2":"彼は週に一度だけ彼女にメッセージを送る。典型的な思わせぶり行動だ。","origin":"breadcrumb(パンくず)を少しずつまく行為から。童話ヘンゼルとグレーテルのように、期待の「パンくず」で相手を釣るイメージ。","collocations":["breadcrumbing someone","fall for breadcrumbing"]},"gray area":{"example2":"Crypto taxation remains a legal gray area in many countries.","exampleJa2":"暗号資産の課税は、多くの国で依然として法律上のグレーゾーンだ。","origin":"白(明確に良い)と黒(明確に悪い)の間の灰色(gray)。どちらとも言い切れない中間領域のイメージ。","collocations":["legal gray area","fall into a gray area"]},"flirt":{"example2":"She flirted with the bartender to get faster service.","exampleJa2":"彼女は早く注文を通してもらおうと、バーテンダーに愛想を振りまいた。","origin":"古英語で「軽くはじく・ひらひら動く」が原義。気持ちを軽くひらひらと投げかけるイメージで「いちゃつく」。","collocations":["flirt with someone","flirt shamelessly"]},"commitment":{"example2":"The firm made a long-term commitment to sustainable investing.","exampleJa2":"その会社はサステナブル投資への長期的なコミットメントを表明した。","origin":"ラテン語 com(共に)+mittere(送る)→自分を委ね送り出す→献身・約束。mission(使命)と同語源。","collocations":["make a commitment","long-term commitment","fear of commitment"]},"casual":{"example2":"The office allows casual dress on Fridays during summer.","exampleJa2":"そのオフィスでは夏の金曜日はカジュアルな服装が認められている。","origin":"ラテン語 casus(偶然の出来事)が語源。「成り行き任せ」→形式ばらない・気軽な、と意味が発展。case(事例)と同語源。","collocations":["keep it casual","casual relationship","casual dress"]},"navigate":{"example2":"Fund managers must navigate volatile markets and shifting regulations.","exampleJa2":"ファンドマネージャーは、不安定な市場と変化する規制をうまく乗り切らなければならない。","origin":"ラテン語 navis(船)+agere(動かす)→船を操縦する→難所を切り抜ける。navy(海軍)と同語源。","collocations":["navigate a crisis","navigate office politics","navigate uncertainty"]},"label":{"example2":"Some couples are happy without a label on their relationship.","exampleJa2":"関係に呼び名をつけなくても幸せなカップルもいる。","origin":"古フランス語で「布切れ・札」が原義。商品に貼る札のように、人や関係に「分類の札」を貼るイメージ。","collocations":["put a label on","reject labels","without labels"]},"ratio'd":{"example2":"The CEO got ratio'd after defending the fee increase online.","exampleJa2":"そのCEOは手数料引き上げをネット上で擁護して、批判リプの嵐を浴びた。","origin":"ratio(比率)から。投稿への「いいね数より返信数が多い比率」=炎上のサイン、というSNS発の言葉。","collocations":["get ratio'd","ratio'd on Twitter"]},"clout":{"example2":"The analyst gained serious clout after predicting the market crash.","exampleJa2":"そのアナリストは市場の暴落を的中させて、大きな影響力を得た。","origin":"元は「強打」の意の古語。「一撃を与えられるほどの力」→影響力。SNS時代に「ネット人気」の意で復活。","collocations":["chase clout","gain clout","do it for clout"]},"influencer":{"example2":"Brands now spend billions partnering with influencers for marketing campaigns.","exampleJa2":"ブランド各社は今や、マーケティング施策でインフルエンサーと組むのに数十億ドルを投じている。","origin":"influence(影響)+er(する人)。influence はラテン語 in(中へ)+fluere(流れる)→人の心に流れ込む力。","collocations":["social media influencer","influencer marketing","fitness influencer"]},"double-edged sword":{"example2":"Leverage is a double-edged sword: it amplifies both gains and losses.","exampleJa2":"レバレッジは諸刃の剣で、利益も損失も増幅する。","origin":"両側に刃のある剣は敵を切れるが自分も傷つけかねない。利点と欠点が表裏一体、のイメージそのまま。","collocations":["prove a double-edged sword","be a double-edged sword"]},"controversial":{"example2":"The central bank's controversial policy divided economists sharply.","exampleJa2":"中央銀行の物議を醸す政策は、経済学者の意見を真っ二つに分けた。","origin":"ラテン語 contra(反対に)+versare(向ける)→意見が反対方向を向き合う→論争を呼ぶ。versus(対)と同語源。","collocations":["controversial decision","highly controversial","controversial remarks"]},"glamorous":{"example2":"Investment banking looks glamorous, but the hours are punishing.","exampleJa2":"投資銀行の仕事は華やかに見えるが、労働時間は過酷だ。","origin":"glamour は元々スコットランド語で「魔法」の意。grammar(学問)が訛った語で、「魔法のように魅了する」イメージ。","collocations":["glamorous lifestyle","look glamorous","glamorous job"]},"content creation":{"example2":"She quit banking to pursue content creation full time.","exampleJa2":"彼女は銀行を辞めて、コンテンツ制作に専念する道を選んだ。","origin":"content(中身・情報の中身)+creation(創造)。ラテン語 continere(含む)→「器に含まれる中身」を作る仕事。","collocations":["digital content creation","content creation tools"]},"algorithm":{"example2":"Trading firms rely on algorithms to execute orders in milliseconds.","exampleJa2":"トレーディング会社は、ミリ秒単位で注文を執行するアルゴリズムに頼っている。","origin":"9世紀のアラビアの数学者アル＝フワーリズミーの名前が語源。彼の計算手順書がヨーロッパに伝わり一般名詞化。","collocations":["recommendation algorithm","trading algorithm","beat the algorithm"]},"following":{"example2":"The newsletter built a loyal following among retail investors.","exampleJa2":"そのニュースレターは、個人投資家の間で熱心な読者層を築いた。","origin":"follow(ついていく)+ing の名詞化。「あとをついてくる人々」→支持者・フォロワーの集団、そのままのイメージ。","collocations":["massive following","build a following","loyal following"]},"public perception":{"example2":"The scandal permanently damaged public perception of the bank.","exampleJa2":"そのスキャンダルは、銀行に対する世間の印象を回復不能なほど傷つけた。","origin":"perception はラテン語 per(完全に)+capere(つかむ)→物事を捉える働き→認識。世間(public)の捉え方。","collocations":["shape public perception","change public perception"]},"pressed":{"example2":"Why are you so pressed about one negative comment?","exampleJa2":"たった一つの否定的なコメントに、なんでそんなにムキになってるの？","origin":"press(押す)の過去分詞。「心が押さえつけられている」→気にしすぎてイライラ、というスラング的転用。","collocations":["pressed about it","so pressed","stay pressed"]},"heated":{"example2":"The board meeting turned heated over the proposed merger terms.","exampleJa2":"取締役会は、提案された合併条件をめぐって白熱した。","origin":"heat(熱)+ed→「熱せられた」。議論や感情が熱を帯びるイメージ。日本語の「白熱」と同じ発想で覚えやすい。","collocations":["heated debate","heated argument","get heated"]},"triggered":{"example2":"Don't mention the merger — he gets triggered every time.","exampleJa2":"合併の話は出さないで。彼は毎回それでカチンとくるから。","origin":"trigger(銃の引き金)から。引き金を引かれたように感情が瞬時に暴発するイメージ。ネットスラングとして定着。","collocations":["get triggered","easily triggered","triggered by criticism"]},"bitter":{"example2":"He's still bitter about being passed over for promotion.","exampleJa2":"彼は昇進を見送られたことを、いまだに根に持っている。","origin":"bite(噛む)と同語源。「噛みつくような味」→苦い→苦い経験を引きずる感情、と味覚から心情へ意味が拡大。","collocations":["bitter about","bitter rivalry","bitter disappointment"]},"intensify":{"example2":"Competition among asset managers has intensified as fees keep falling.","exampleJa2":"手数料の低下が続く中、資産運用会社間の競争は激化している。","origin":"ラテン語 in(向かって)+tendere(張る)→強く張りつめる+fy(〜化する)。緊張の糸がピンと張るイメージ。","collocations":["intensify pressure","competition intensifies","intensify efforts"]},"overreaction":{"example2":"Analysts called the sell-off an overreaction to the earnings miss.","exampleJa2":"アナリストたちは、その売り浴びせを決算未達への過剰反応だと評した。","origin":"over(過剰に)+re(反対に)+action(行動)→状況に見合わない大きすぎる反応。市場用語でも頻出。","collocations":["market overreaction","a bit of an overreaction"]},"mocking":{"example2":"Her mocking imitation of the manager drew nervous laughter.","exampleJa2":"彼女が上司を嘲笑うように真似すると、気まずい笑いが起きた。","origin":"古フランス語 mocquer(あざける)が語源。mockingbird(モノマネ鳥)のように、真似してからかうイメージ。","collocations":["mocking tone","mocking laughter","mocking smile"]},"annoyance":{"example2":"The constant system alerts became a daily annoyance for traders.","exampleJa2":"頻繁なシステム警告は、トレーダーにとって日々の苛立ちの種になった。","origin":"ラテン語 in odio(憎しみの中に)が語源。「憎らしいと感じる状態」が弱まって「軽い苛立ち」に。","collocations":["hide one's annoyance","minor annoyance","in annoyance"]},"visibly":{"example2":"The CEO was visibly relieved when the deal finally closed.","exampleJa2":"取引がようやく成立すると、CEOは目に見えて安堵した様子だった。","origin":"ラテン語 videre(見る)→visible(見える)+ly。video(映像)やvision(視覚)と同じ「見る」の語源ファミリー。","collocations":["visibly upset","visibly shaken","visibly relieved"]},"mind-blown":{"example2":"I was mind-blown by how fast the AI analyzed the report.","exampleJa2":"AIがそのレポートを分析する速さに、度肝を抜かれた。","origin":"mind(頭)+blown(吹き飛ばされた)→「頭が吹っ飛ぶほどの衝撃」。blow one's mind(仰天させる)の形容詞形。","collocations":["completely mind-blown","leave someone mind-blown"]},"i can't even":{"example2":"They doubled our year-end bonus — I can't even.","exampleJa2":"年末ボーナスが2倍になったって。もう言葉にならないよ。","origin":"I can't even describe it(言葉にすらできない)の後半を省略した形。「続きが言えないほど」の余韻で感情を表す。","collocations":["I literally can't even","I can't even right now"]},"dead":{"example2":"His impression of the boss had the whole office dead.","exampleJa2":"彼の上司のモノマネで、オフィス中が笑い死にしそうになった。","origin":"「笑いすぎて死んだ」という誇張表現。日本語の「笑い死ぬ」「爆死」と同じ発想で覚えると簡単。","collocations":["I'm dead","has me dead","dead from laughing"]},"shooketh":{"example2":"The market dropped five percent in an hour — I am shooketh.","exampleJa2":"市場が1時間で5%下落した。マジで震えたわ。","origin":"shook(shakeの過去形=動揺した)に古英語風の語尾-ethを付けた冗談表現。シェイクスピア風に大げさに驚くノリ。","collocations":["I am shooketh","left me shooketh"]},"overwhelmed":{"example2":"New analysts often feel overwhelmed by the volume of data.","exampleJa2":"新人アナリストは、データ量の多さに圧倒されがちだ。","origin":"over(上から)+whelm(覆いかぶせる)→大波が頭上から覆いかぶさるイメージ。感情や仕事量に飲み込まれる感覚。","collocations":["feel overwhelmed","overwhelmed by work","completely overwhelmed"]},"exaggeration":{"example2":"Calling it the deal of the century is a slight exaggeration.","exampleJa2":"それを世紀の取引と呼ぶのは、ちょっと大げさだ。","origin":"ラテン語 ex(外へ)+aggerare(積み上げる)→実際より高く積み上げる→話を盛る。「盛る」のイメージそのまま。","collocations":["slight exaggeration","no exaggeration","gross exaggeration"]},"earth-shattering":{"example2":"The rate decision was hardly earth-shattering; markets barely moved.","exampleJa2":"その金利決定は衝撃的とは言い難く、市場はほとんど動かなかった。","origin":"earth(地球)+shatter(粉々に砕く)→「大地を砕くほどの」衝撃。日本語の「天地を揺るがす」と同じ発想。","collocations":["earth-shattering news","nothing earth-shattering"]},"thrive on":{"example2":"Some traders thrive on the pressure of volatile markets.","exampleJa2":"不安定な市場のプレッシャーを糧にして力を発揮するトレーダーもいる。","origin":"thrive(繁栄する)は古ノルド語「つかみ取る」が語源。on以下を栄養に成長するイメージで「〜を糧にする」。","collocations":["thrive on pressure","thrive on competition","thrive on challenges"]},"facts":{"example2":"This commute is way too long. — Facts, honestly.","exampleJa2":"この通勤時間、長すぎだよ。—ほんとそれな。","origin":"fact(事実)の複数形を相槌に転用。「それは紛れもない事実」と全面同意するノリ。日本語の「それな」に相当。","collocations":["straight facts","facts, no printer","big facts"]},"on god":{"example2":"On God, that presentation was the best one all quarter.","exampleJa2":"マジで、あのプレゼンは今四半期で一番の出来だったよ。","origin":"「神に誓って(I swear on God)」の省略形。神を引き合いに出すことで発言の真剣さを強調するスラング。","collocations":["on God, I swear","no lie, on God"]},"brevity":{"example2":"Clients appreciate brevity in market reports, not lengthy jargon.","exampleJa2":"顧客が市場レポートに求めるのは簡潔さであって、長ったらしい専門用語ではない。","origin":"ラテン語 brevis(短い)が語源。brief(簡潔な・要約)やabbreviate(省略する)と同じ語源ファミリー。","collocations":["for the sake of brevity","brevity and clarity"]},"punchy":{"example2":"The pitch deck needs a punchier headline to grab investors.","exampleJa2":"そのピッチ資料には、投資家の心をつかむもっとインパクトのある見出しが必要だ。","origin":"punch(パンチ)+y→「一発のパンチのように効く」。短くて殴られたような衝撃を残す文章や話し方のイメージ。","collocations":["punchy headline","short and punchy","punchy delivery"]},"confident":{"example2":"She sounded confident presenting the fund's five-year outlook.","exampleJa2":"彼女はファンドの5年見通しを、自信を持って発表した。","origin":"ラテン語 con(完全に)+fidere(信頼する)→自分を完全に信じる→自信がある。faith(信頼)と同語源。","collocations":["feel confident","confident about","quietly confident"]},"convinced":{"example2":"The committee remains convinced that inflation will ease next year.","exampleJa2":"委員会は、来年インフレが緩和すると引き続き確信している。","origin":"ラテン語 con(完全に)+vincere(打ち負かす)→議論で完全に打ち負かされ納得した状態。victory(勝利)と同語源。","collocations":["firmly convinced","convinced that","remain convinced"]},"trait":{"example2":"Patience is an essential trait for long-term investors.","exampleJa2":"忍耐力は、長期投資家にとって欠かせない資質だ。","origin":"ラテン語 trahere(引く)→「引かれた一本の線」→人物を特徴づける一筆・性質。tract(引く)系と同語源。","collocations":["personality trait","key trait","admirable trait"]},"hard pass":{"example2":"Investing in that unaudited startup? Hard pass from me.","exampleJa2":"監査も受けていないあのスタートアップに投資？私は絶対にお断りだね。","origin":"pass(見送る・パスする)にhard(断固たる)を付けた強調形。トランプで「パス」する時の強い拒否版と覚える。","collocations":["that's a hard pass","give it a hard pass"]},"nah":{"example2":"Nah, let's push the meeting to next week instead.","exampleJa2":"いや、会議はむしろ来週に延ばそうよ。","origin":"no のくだけた発音変化形。口を大きく開けず気だるく言う「ナー」の音が、そのまま綴りになったもの。","collocations":["nah, I'm fine","nah, not really"]},"i'm good":{"example2":"Need another copy of the report? — I'm good, thanks.","exampleJa2":"レポートの控えもう一部いる？—大丈夫です、ありがとう。","origin":"直訳は「私は良い状態」→「今のままで満たされているので不要です」という婉曲な断り方。丁寧な拒否の定番。","collocations":["I'm good, thanks","nah, I'm good"]},"miss me with that":{"example2":"Another unpaid weekend shift? Miss me with that nonsense.","exampleJa2":"また週末の無給シフト？そんな馬鹿げた話は勘弁してくれ。","origin":"直訳は「それは私に当てないで(missして)」。飛んでくる球をよけるように、嫌な話を回避するイメージ。","collocations":["miss me with that nonsense","miss me with that drama"]},"definitive":{"example2":"The audit provided definitive proof that no funds were missing.","exampleJa2":"監査により、資金の欠損がないという決定的な証拠が示された。","origin":"ラテン語 de(完全に)+finire(限定する)→完全に境界を定めた→もう動かない・最終的な。finish と同語源。","collocations":["definitive answer","definitive proof","definitive guide"]},"confrontational":{"example2":"Avoid a confrontational tone when negotiating fees with clients.","exampleJa2":"顧客と手数料の交渉をするときは、けんか腰の口調を避けなさい。","origin":"ラテン語 con(共に)+frons(額)→額と額を突き合わせる→対決姿勢の。おでこを突き合わせて睨み合うイメージ。","collocations":["confrontational approach","confrontational tone","become confrontational"]},"decline":{"example2":"She politely declined the offer to join the rival firm.","exampleJa2":"彼女はライバル会社への移籍の誘いを丁重に断った。","origin":"ラテン語 de(下に)+clinare(傾く)→下へ傾く→断る・衰える。「首を横に傾けて断る」イメージで覚える。","collocations":["decline an offer","politely decline","decline an invitation"]},"nonsense":{"example2":"The rumor about the merger is complete nonsense.","exampleJa2":"合併に関するその噂は、まったくのでたらめだ。","origin":"non(無)+sense(意味)→意味が無いこと。そのまま「意味を成さない話」で、分解すれば一発で覚えられる。","collocations":["complete nonsense","talk nonsense","absolute nonsense"]},"decisive":{"example2":"Her decisive response prevented the client from pulling their assets.","exampleJa2":"彼女の迅速で断固とした対応が、顧客の資産引き揚げを食い止めた。","origin":"ラテン語 de(切り離す)+caedere(切る)→迷いを切り捨てる→決断力のある。decide(決める)と同語源。","collocations":["decisive action","decisive leader","decisive victory"]},"fluency":{"example2":"Financial fluency in English opens doors to global client work.","exampleJa2":"英語での金融の流暢な運用力は、グローバルな顧客業務への扉を開く。","origin":"ラテン語 fluere(流れる)が語源。言葉が川のようによどみなく「流れる」イメージ。fluid(流体)と同語源。","collocations":["fluency in English","achieve fluency","native-level fluency"]},"lag":{"example2":"There's often a lag between rate hikes and their economic impact.","exampleJa2":"利上げとその経済への影響の間には、しばしばタイムラグがある。","origin":"スカンジナビア方言で「のろのろ歩く」が語源とされる。列の最後尾をだらだら歩く人のイメージで「遅れ」。","collocations":["time lag","lag behind","network lag"]},"glitch":{"example2":"A software glitch briefly halted trading on the exchange.","exampleJa2":"ソフトウェアの不具合で、取引所の売買が一時停止した。","origin":"イディッシュ語 glitshn(滑る)が語源とされる。システムが一瞬「足を滑らせる」ような小さな誤作動のイメージ。","collocations":["technical glitch","software glitch","minor glitch"]},"afk":{"example2":"Sorry I missed your ping — I was AFK grabbing lunch.","exampleJa2":"連絡に気づかなくてごめん、昼食を取りに離席してたんだ。","origin":"Away From Keyboard(キーボードから離れている)の頭字語。オンラインゲームのチャット発祥で、今や職場でも使う。","collocations":["go AFK","be AFK for a while","sorry, was AFK"]},"nerf":{"example2":"The new regulation effectively nerfed the bank's most profitable strategy.","exampleJa2":"新しい規制は、その銀行の最も収益性の高い戦略を事実上骨抜きにした。","origin":"柔らかいスポンジ製おもちゃの銃ブランドNERFから。本物の銃をおもちゃに替えるように「弱体化する」の意に。","collocations":["nerf a character","get nerfed","nerf in the update"]},"gg":{"example2":"We lost the client to a rival firm — GG, they played it better.","exampleJa2":"顧客をライバル会社に取られたよ。完敗だね、向こうが上手だった。","origin":"Good Game の頭字語。対戦ゲーム終了時の「お疲れ様」が原義で、勝敗を潔く認める挨拶として定着。","collocations":["GG, well played","say GG"]},"malfunction":{"example2":"A malfunction in the pricing system caused incorrect fund valuations.","exampleJa2":"価格算定システムの誤作動により、ファンドの評価額に誤りが生じた。","origin":"ラテン語 mal(悪い)+function(機能)→機能が悪い状態→故障。malは「悪」の接頭辞(例: malware)。","collocations":["system malfunction","equipment malfunction","suffer a malfunction"]},"leak into":{"example2":"Anxiety from the markets started leaking into his weekend life.","exampleJa2":"市場からくる不安が、彼の週末の生活にまで染み出し始めた。","origin":"leak(漏れる)+into(中へ)。水が容器の隙間からじわじわ染み込むように、影響が別の領域へ広がるイメージ。","collocations":["leak into personal life","leak into other areas"]},"acknowledge":{"example2":"The firm acknowledged the reporting error and issued corrections.","exampleJa2":"その会社は報告書の誤りを認め、訂正を発表した。","origin":"ac(〜へ)+knowledge(知識)→「知っている」と表明する→認める。knowledgeを声に出して認めるイメージ。","collocations":["acknowledge a mistake","acknowledge receipt","publicly acknowledge"]},"pregame":{"example2":"They pregamed at Dave's apartment before the company party.","exampleJa2":"彼らは会社のパーティーの前に、デイブの部屋で0次会をした。","origin":"pre(前)+game(試合)。元はスポーツ観戦前に駐車場で飲む習慣から。「本番前の景気づけ」のイメージ。","collocations":["pregame at someone's place","pregame before the party"]},"turn up":{"example2":"The whole office turned up at the year-end celebration.","exampleJa2":"オフィス全員が忘年会で大いに盛り上がった。","origin":"音量を上げる(turn up the volume)から連想。テンションの「音量」を最大まで上げて騒ぐイメージ。","collocations":["turn up tonight","ready to turn up"]},"wasted":{"example2":"Don't get wasted at the client dinner — pace yourself.","exampleJa2":"接待の席でべろべろに酔うなよ。ペース配分しろ。","origin":"waste(廃棄する)の過去分詞。「廃人状態になるほど酔った」→機能停止のイメージで、泥酔を表すスラング。","collocations":["get wasted","completely wasted","wasted at the party"]},"hair of the dog":{"example2":"Feeling rough this morning? Try a little hair of the dog.","exampleJa2":"今朝はつらい？なら軽く迎え酒でもどう？","origin":"「狂犬に噛まれたらその犬の毛を傷に当てると治る」という古い迷信から。毒をもって毒を制す=迎え酒。","collocations":["a bit of hair of the dog","swear by hair of the dog"]},"hangover":{"example2":"The market still suffers a hangover from the easy-money era.","exampleJa2":"市場は今も、金融緩和時代の後遺症を引きずっている。","origin":"hang(ぶら下がる)+over(残って)→「翌日まで残ってのしかかるもの」。前夜の酒が持ち越されるイメージ。","collocations":["terrible hangover","nurse a hangover","hangover cure"]},"lightweight":{"example2":"I'm a total lightweight, so I stick to one glass of wine.","exampleJa2":"私は本当に酒に弱いから、ワインは1杯までにしている。","origin":"ボクシングの軽量級(lightweight)から転用。「重い酒に耐えられない軽量級選手」のイメージで覚える。","collocations":["total lightweight","such a lightweight"]},"moderation":{"example2":"Even high-risk assets can fit a portfolio in moderation.","exampleJa2":"高リスク資産でも、節度ある範囲ならポートフォリオに組み入れられる。","origin":"ラテン語 moderari(抑える・加減する)が語源。modus(尺度)から派生し、「程よい尺度に収める」イメージ。","collocations":["in moderation","drink in moderation","practice moderation"]},"warm-up":{"example2":"Consider this small project a warm-up for the main assignment.","exampleJa2":"この小さな案件は、本番の業務に向けたウォーミングアップだと考えてください。","origin":"warm(温める)+up(上げる)→冷えた体温を上げる運動→本番前の準備。エンジンを温める感覚で覚える。","collocations":["warm-up exercise","warm-up act","do a warm-up"]},"decode":{"example2":"Analysts spent hours decoding the central bank's vague statement.","exampleJa2":"アナリストたちは、中央銀行の曖昧な声明の真意を読み解くのに何時間も費やした。","origin":"de(解除)+code(暗号)→暗号を解く。転じて、わかりにくい言動やメッセージの意味を読み解くこと。","collocations":["decode a message","decode the signals","hard to decode"]},"nightlife":{"example2":"The city's nightlife attracts young professionals from across the region.","exampleJa2":"その街のナイトライフは、地域中から若手社会人を引き寄せている。","origin":"night(夜)+life(生活)の複合語。「夜の生活・娯楽の世界」をそのまま一語にした、分解すれば意味が明快な語。","collocations":["vibrant nightlife","nightlife scene","enjoy the nightlife"]},"nailed it":{"example2":"Your forecast on the yen was spot on — you nailed it.","exampleJa2":"円相場のあなたの予測はドンピシャだったね。完璧だったよ。","origin":"nail(釘を打つ)から。釘を一発でまっすぐ打ち込むように、狙い通り完璧に決めるイメージ。","collocations":["totally nailed it","nailed the presentation","nailed the interview"]},"crushed it":{"example2":"The sales team crushed it, beating their annual target by June.","exampleJa2":"営業チームは圧勝で、6月には年間目標を突破した。","origin":"crush(押しつぶす)から。課題を粉々に踏み潰すほど圧倒的にやり遂げるイメージ。nailed itより豪快な語感。","collocations":["absolutely crushed it","crushed the exam","crushed the quarter"]},"killing it":{"example2":"Her new fund is killing it, topping every performance ranking.","exampleJa2":"彼女の新しいファンドは絶好調で、あらゆる運用成績ランキングで首位に立っている。","origin":"kill(仕留める)の進行形。獲物を次々仕留めるように、継続して圧倒的な成果を出し続けるイメージ。","collocations":["killing it lately","killing it at work","been killing it"]},"on fire":{"example2":"He closed five deals this week — the guy is on fire.","exampleJa2":"彼は今週5件も成約した。まさにノリに乗っている。","origin":"「燃えている」→炎のように勢いが止まらない状態。日本語の「火がついた」「燃えている」と同じ発想。","collocations":["absolutely on fire","the team is on fire"]},"dominate":{"example2":"A few tech giants dominate the index's total market capitalization.","exampleJa2":"少数の巨大テック企業が、その指数の時価総額の大半を占めている。","origin":"ラテン語 dominus(主人)が語源。「主人として支配する」イメージ。dominant(支配的)やdomain(領地)と同族。","collocations":["dominate the market","dominate the competition","dominate headlines"]},"sustained":{"example2":"Sustained inflows into index funds have reshaped the asset management industry.","exampleJa2":"インデックスファンドへの持続的な資金流入が、資産運用業界を一変させた。","origin":"ラテン語 sus(下から)+tenere(保持する)→下から支え続ける→持続する。maintainやtenantと同じ「保つ」語源。","collocations":["sustained growth","sustained effort","sustained recovery"]},"transform":{"example2":"The new CEO transformed the struggling bank into a market leader.","exampleJa2":"新しいCEOは経営難だった銀行を業界のリーダーへと一変させた。","origin":"trans(越えて)+form(形)→形を越えて別のものに変える。形そのものを作り替えるイメージ。","collocations":["transform the industry","completely transform","transform into"]},"enthusiastically":{"example2":"Investors responded enthusiastically to the fund's strong quarterly results.","exampleJa2":"投資家たちはそのファンドの好調な四半期決算に熱狂的に反応した。","origin":"ギリシャ語en(中に)+theos(神)→「神が宿った状態」が原義。神懸かり的な熱中ぶりを表す。","collocations":["cheer enthusiastically","respond enthusiastically","enthusiastically support"]},"common thread":{"example2":"Risk management is the common thread running through all our strategies.","exampleJa2":"リスク管理は当社のすべての戦略に共通する要素だ。","origin":"複数の布地を貫いて縫い合わせる1本の糸(thread)のイメージ。バラバラなものをつなぐ共通項。","collocations":["common thread running through","share a common thread","find a common thread"]},"blew it":{"example2":"We had the client ready to sign, but I totally blew it.","exampleJa2":"顧客は契約寸前だったのに、私が完全に台無しにしてしまった。","origin":"blow(吹き飛ばす)の過去形。せっかくのチャンスを風で吹き飛ばして失うイメージで覚える。","collocations":["totally blew it","blew my chance","don't blow it"]},"choked":{"example2":"He choked during the final interview and forgot his prepared answers.","exampleJa2":"彼は最終面接でプレッシャーに負け、用意していた答えを忘れてしまった。","origin":"本来は「喉を詰まらせる」。緊張で喉が締まり、実力を出せなくなるイメージのスポーツ由来スラング。","collocations":["choked under pressure","choked in the finals","don't choke"]},"tanked":{"example2":"The stock tanked after the company missed its earnings forecast.","exampleJa2":"その株は業績予想を下回った後に大暴落した。","origin":"戦車(tank)ではなく水槽に沈むイメージ。株価や興行成績が底まで沈む様子を表す米俗語。","collocations":["the stock tanked","sales tanked","tanked at the box office"]},"face-plant":{"example2":"The product launch was a complete face-plant in front of investors.","exampleJa2":"その製品発表は投資家の前での完全な大失態だった。","origin":"face(顔)+plant(植える)→顔から地面に突っ込む転び方。植物を植えるように顔面着地する滑稽な失敗。","collocations":["total face-plant","epic face-plant","face-plant on stage"]},"crucial":{"example2":"Timing is crucial when entering or exiting a volatile market.","exampleJa2":"変動の激しい市場では、参入と撤退のタイミングが決定的に重要だ。","origin":"ラテン語crux(十字架・分かれ道)から。運命の分かれ道となるほど重要、という語感。","collocations":["play a crucial role","crucial moment","crucial decision"]},"spectacularly":{"example2":"The hedge fund's currency bet failed spectacularly last quarter.","exampleJa2":"そのヘッジファンドの通貨への賭けは前四半期に壮絶に失敗した。","origin":"ラテン語spectare(見る)から。spectacle(見世物)のように誰の目にも派手に映る様子。","collocations":["fail spectacularly","spectacularly successful","backfire spectacularly"]},"metaphorically":{"example2":"The market crashed, and metaphorically speaking, everyone headed for the exits.","exampleJa2":"市場は暴落し、比喩的に言えば全員が出口へ殺到した。","origin":"ギリシャ語meta(別へ)+pherein(運ぶ)→意味を別のものへ運ぶ=比喩。metaphor(隠喩)の副詞形。","collocations":["metaphorically speaking","used metaphorically","both literally and metaphorically"]},"cinematic":{"example2":"The commercial had a cinematic quality that impressed every client.","exampleJa2":"そのCMは映画のような質感があり、すべての顧客を感心させた。","origin":"ギリシャ語kinema(動き)→cinema(映画)+-tic(形容詞化)。「動く絵」が語源で映画的なという意味に。","collocations":["cinematic experience","cinematic quality","cinematic style"]},"cope":{"example2":"Many small businesses struggled to cope with rising interest rates.","exampleJa2":"多くの中小企業は金利上昇への対処に苦労した。","origin":"古フランス語couper(打ち合う)から。困難と「打ち合いながら渡り合う」イメージで対処するの意に。","collocations":["cope with stress","cope with change","struggle to cope"]},"vivid":{"example2":"She still has vivid memories of the 2008 financial crisis.","exampleJa2":"彼女は2008年の金融危機の記憶を今でも鮮明に覚えている。","origin":"ラテン語vivere(生きる)から。vital・survive と同語源。生きているように鮮やかな、が原義。","collocations":["vivid memory","vivid description","vivid imagination"]},"thrifty":{"example2":"Being thrifty in your twenties makes investing much easier later.","exampleJa2":"20代で倹約上手だと、後の投資がずっと楽になる。","origin":"thrive(繁栄する)の名詞thrift(繁栄→節約)から。うまくやりくりして栄える、という良い意味の節約。","collocations":["thrifty shopper","thrifty habits","thrifty with money"]},"penny-pinching":{"example2":"His penny-pinching approach saved money but hurt employee morale badly.","exampleJa2":"彼のケチケチしたやり方は経費を節約したが、社員の士気をひどく下げた。","origin":"penny(1セント硬貨)+pinch(つまむ)→小銭を指でつまんで離さないイメージ。否定的なケチを表す。","collocations":["penny-pinching habits","penny-pinching boss","penny-pinching measures"]},"score a deal":{"example2":"I scored a great deal on flights by booking six months early.","exampleJa2":"半年前に予約して、航空券をとてもお得に手に入れた。","origin":"score(得点する)+deal(取引)→スポーツで得点を決めるように、良い取引を「勝ち取る」イメージ。","collocations":["score a great deal","score a deal on","score an amazing deal"]},"freebie":{"example2":"The conference bag was full of freebies from sponsor companies.","exampleJa2":"カンファレンスのバッグにはスポンサー企業からの無料グッズがたくさん入っていた。","origin":"free(無料)+-bie(親しみを込める接尾辞)。「タダのちゃん」という軽い響きの口語。販促のおまけ。","collocations":["give away freebies","get a freebie","promotional freebies"]},"frugal":{"example2":"Warren Buffett is famously frugal despite his enormous wealth.","exampleJa2":"ウォーレン・バフェットは莫大な資産を持ちながら、質素なことで有名だ。","origin":"ラテン語frux(果実・成果)から。実りを大切に無駄なく使う、という肯定的な節約を表す。","collocations":["frugal lifestyle","frugal living","frugal with money"]},"bargain":{"example2":"At this price, the stock looks like a real bargain.","exampleJa2":"この価格なら、その株はまさに掘り出し物に見える。","origin":"古フランス語bargaignier(値切り交渉する)から。交渉の末に得た安い買い物、が原義。","collocations":["real bargain","bargain hunting","bargain price"]},"bang for your buck":{"example2":"Index funds often give investors the most bang for their buck.","exampleJa2":"インデックスファンドは多くの場合、投資家に最高のコスパを提供する。","origin":"bang(爆発音・迫力)+buck(ドル)。「1ドルでどれだけ大きな音が出るか」=金額あたりの価値。","collocations":["more bang for your buck","get the most bang for your buck","best bang for the buck"]},"budget-friendly":{"example2":"The firm offers budget-friendly advisory services for first-time investors.","exampleJa2":"その会社は初めての投資家向けに手頃な価格のアドバイザリーサービスを提供している。","origin":"budget(予算)+friendly(優しい)。「予算に親切」という直訳イメージそのままの複合形容詞。","collocations":["budget-friendly option","budget-friendly travel","budget-friendly prices"]},"trade show":{"example2":"Our booth at the trade show generated over two hundred leads.","exampleJa2":"展示会での当社ブースは200件以上の見込み客を獲得した。","origin":"trade(業界・商売)+show(見せる場)。業界関係者が製品を見せ合う場、というそのままの成り立ち。","collocations":["attend a trade show","trade show booth","annual trade show"]},"judgmental":{"example2":"A good financial advisor listens without being judgmental about past mistakes.","exampleJa2":"良いファイナンシャルアドバイザーは、過去の失敗を批判せずに話を聞く。","origin":"judge(裁く)+ment+al。裁判官のように人を裁く態度。judgeはラテン語jus(法)+dicere(言う)が語源。","collocations":["judgmental attitude","overly judgmental","judgmental about"]},"jelly":{"example2":"You got upgraded to business class? I'm so jelly!","exampleJa2":"ビジネスクラスにアップグレードされたの？超うらやましい！","origin":"jealous(嫉妬した)の音を縮めた遊び。食べ物のゼリーと同じ響きにして軽くかわいく言うSNSスラング。","collocations":["so jelly","I'm jelly","totally jelly"]},"green with envy":{"example2":"His colleagues were green with envy when he got the promotion.","exampleJa2":"彼が昇進したとき、同僚たちはひどく嫉妬した。","origin":"古代ギリシャ以来、嫉妬は顔色を青緑にすると考えられた。シェイクスピアも嫉妬を緑で表現した。","collocations":["turn green with envy","make someone green with envy","absolutely green with envy"]},"fomo":{"example2":"FOMO drives many retail investors to buy at market peaks.","exampleJa2":"取り残される恐怖から、多くの個人投資家は市場の天井で買ってしまう。","origin":"Fear Of Missing Outの頭字語。「乗り遅れる恐怖」。相場の高値掴みの心理を表す金融用語としても定着。","collocations":["have FOMO","serious FOMO","FOMO buying"]},"flex on":{"example2":"He bought a luxury watch just to flex on his coworkers.","exampleJa2":"彼は同僚に見せびらかすためだけに高級時計を買った。","origin":"flex(筋肉を曲げて見せる)から。力こぶを誇示するボディビルのポーズ→富や成功の誇示へ拡大。","collocations":["flex on everyone","flex on social media","flex on the haters"]},"relatable":{"example2":"The manager shared a relatable story about failing his first presentation.","exampleJa2":"その部長は初プレゼンで失敗したという共感できる話をしてくれた。","origin":"relate(関係づける)+able(できる)→自分と関係づけられる=共感できる。ラテン語referre(運び戻す)が源。","collocations":["highly relatable","relatable content","relatable character"]},"amplify":{"example2":"Leverage can amplify both gains and losses in your portfolio.","exampleJa2":"レバレッジはポートフォリオの利益も損失も増幅させる可能性がある。","origin":"ラテン語amplus(大きい)+facere(作る)→大きく作る。ampleや amplifier(アンプ)と同語源。","collocations":["amplify the effect","amplify a message","amplify losses"]},"comparison":{"example2":"A careful comparison of fund fees can save investors thousands.","exampleJa2":"ファンドの手数料を注意深く比較すれば、投資家は何千ドルも節約できる。","origin":"ラテン語com(共に)+par(等しい)→2つを等しく並べて見ること。pair(ペア)と同じ語源。","collocations":["in comparison with","draw a comparison","by comparison"]},"undercurrent":{"example2":"Despite the calm markets, there was an undercurrent of investor anxiety.","exampleJa2":"市場は穏やかだったが、投資家の不安が水面下に流れていた。","origin":"under(下)+current(流れ)→水面下の流れ。表面は穏やかでも底に潜む感情や傾向を表す比喩。","collocations":["undercurrent of tension","undercurrent of anxiety","strong undercurrent"]},"show off":{"example2":"She couldn't wait to show off her new office to visitors.","exampleJa2":"彼女は来客に新しいオフィスを見せびらかしたくてたまらなかった。","origin":"show(見せる)+off(外へ強調)→外に向かって派手に見せる。offが「これ見よがし」感を加える。","collocations":["show off his skills","love to show off","show off in front of"]},"scrolling":{"example2":"I caught myself scrolling through market news instead of working.","exampleJa2":"仕事をせずに市場ニュースをスクロールしている自分に気づいた。","origin":"scroll(巻物)から。巻物を巻いて読み進める動作が、画面を上下に送る操作の呼び名になった。","collocations":["scrolling through social media","endless scrolling","mindless scrolling"]},"dl / down low":{"example2":"Keep the merger talks on the down low until Friday's announcement.","exampleJa2":"金曜の発表まで、合併協議は内密にしておいてくれ。","origin":"down(下)+low(低く)→姿勢を低くして目立たないイメージ。「低く抑えておく」=内緒にする。","collocations":["keep it on the DL","on the down low","stay on the down low"]},"hush-hush":{"example2":"The acquisition plans are still very hush-hush inside the company.","exampleJa2":"その買収計画は社内でもまだ極秘扱いだ。","origin":"hush(シーッと静かにさせる音)を2回重ねた擬音語。「シーシー」と口止めするイメージで覚える。","collocations":["very hush-hush","hush-hush project","keep it hush-hush"]},"keep it under wraps":{"example2":"The firm kept the new product under wraps until the launch.","exampleJa2":"その会社は発売まで新製品を秘密にしていた。","origin":"wraps(包み布)の下に隠しておくイメージ。除幕式まで布を掛けたままにする様子から。","collocations":["keep the plan under wraps","stay under wraps","remain under wraps"]},"off the record":{"example2":"Off the record, the regulator is already investigating that broker.","exampleJa2":"オフレコだが、当局はすでにその証券会社を調査している。","origin":"record(記録)の外で、が直訳。記者の取材記録に載せない発言、という報道用語から一般化。","collocations":["strictly off the record","speak off the record","this is off the record"]},"between you and me":{"example2":"Between you and me, the budget will be cut next quarter.","exampleJa2":"ここだけの話、来四半期に予算が削減されるよ。","origin":"「あなたと私の間(だけに留める)」が直訳。2人の間に線を引いて外に漏らさないイメージ。","collocations":["just between you and me","between you and me, honestly","keep this between you and me"]},"merger":{"example2":"The merger between the two banks created Japan's largest lender.","exampleJa2":"その2つの銀行の合併により、日本最大の金融機関が誕生した。","origin":"ラテン語mergere(沈める・浸す)から。2社が溶け合って1つに沈み込むイメージ。emergeの逆方向。","collocations":["merger and acquisition","announce a merger","merger talks"]},"discretion":{"example2":"Please handle the client's account information with complete discretion.","exampleJa2":"その顧客の口座情報は細心の慎重さをもって扱ってください。","origin":"ラテン語dis(分けて)+cernere(ふるい分ける)→物事を見分ける力→慎重な判断力。discernと同語源。","collocations":["use discretion","at your discretion","utmost discretion"]},"confidential":{"example2":"All salary data is strictly confidential and stored on secure servers.","exampleJa2":"すべての給与データは厳格に機密扱いで、安全なサーバーに保管されている。","origin":"ラテン語con(完全に)+fidere(信頼する)→信頼して打ち明けた話→秘密の。confidence(信頼)と同族。","collocations":["strictly confidential","confidential information","keep it confidential"]},"boundary":{"example2":"She set clear boundaries between her work hours and family time.","exampleJa2":"彼女は勤務時間と家族の時間の間に明確な境界を設けた。","origin":"bound(境界線)+ary。中世ラテン語bodina(境界標)から。土地の境界杭を打つイメージ。","collocations":["set boundaries","cross a boundary","clear boundaries"]},"sensitive":{"example2":"The report contains sensitive data about upcoming interest rate decisions.","exampleJa2":"その報告書には今後の金利決定に関する機微な情報が含まれている。","origin":"ラテン語sentire(感じる)から。感じやすい→傷つきやすい→慎重な扱いを要する、と意味が発展。","collocations":["sensitive information","highly sensitive","sensitive topic"]},"launch event":{"example2":"The fund's launch event drew analysts from every major brokerage.","exampleJa2":"そのファンドの発表イベントには大手証券各社のアナリストが集まった。","origin":"launch(ロケットや船を送り出す)+event。新製品を世に「打ち上げる」お披露目の場、というイメージ。","collocations":["host a launch event","product launch event","attend the launch event"]},"slack off":{"example2":"Sales teams tend to slack off after hitting their quarterly targets.","exampleJa2":"営業チームは四半期目標を達成した後、手を抜きがちだ。","origin":"slack(ロープのたるみ)+off。ピンと張った緊張を緩めてダラけるイメージ。緩んだ縄=気の緩み。","collocations":["slack off at work","start to slack off","no time to slack off"]},"couch potato":{"example2":"Working from home turned him into a total couch potato.","exampleJa2":"在宅勤務で彼はすっかりソファでゴロゴロする人になってしまった。","origin":"couch(ソファ)+potato(ジャガイモ)。ソファに転がる芋のように動かずテレビを見る人。80年代米国発。","collocations":["total couch potato","become a couch potato","couch potato lifestyle"]},"bum around":{"example2":"After quitting his job, he bummed around Southeast Asia for months.","exampleJa2":"仕事を辞めた後、彼は何ヶ月も東南アジアをぶらぶらして過ごした。","origin":"bum(浮浪者・怠け者)+around(あちこち)。浮浪者のように目的なくうろつくイメージの口語。","collocations":["bum around the house","bum around town","bum around for a while"]},"phoning it in":{"example2":"The analyst was clearly phoning it in during the earnings call.","exampleJa2":"そのアナリストは決算説明会で明らかにやる気なく最低限の仕事しかしていなかった。","origin":"現場に行かず電話で済ませるイメージ。俳優が舞台に立たず「電話で演技する」という皮肉が由来。","collocations":["just phoning it in","phoning it in at work","stop phoning it in"]},"bare minimum":{"example2":"Some clients contribute only the bare minimum to their pension plans.","exampleJa2":"一部の顧客は年金プランに最低限の額しか拠出しない。","origin":"bare(むき出しの・裸の)+minimum(最小)。飾りを全部はぎ取った、これ以上削れない最小限。","collocations":["do the bare minimum","bare minimum effort","bare minimum required"]},"aimlessly":{"example2":"Without a clear investment goal, money tends to drift aimlessly.","exampleJa2":"明確な投資目標がないと、お金はあてもなく漂いがちだ。","origin":"aim(狙い)+less(ない)+ly→狙いなく。aimは古フランス語esmer(見積もる・狙う)が語源。","collocations":["wander aimlessly","drift aimlessly","walk aimlessly"]},"productive":{"example2":"The quarterly review meeting was surprisingly productive this time.","exampleJa2":"今回の四半期レビュー会議は驚くほど生産的だった。","origin":"ラテン語pro(前へ)+ducere(導く)→前へ導き生み出す。produce・productと同じ語源ファミリー。","collocations":["productive meeting","highly productive","stay productive"]},"self-deprecating":{"example2":"Her self-deprecating jokes about spreadsheet errors won over the audience.","exampleJa2":"スプレッドシートのミスに関する彼女の自虐ジョークは聴衆の心をつかんだ。","origin":"self(自分)+ラテン語deprecari(祈って追い払う→非難する)。自分を下げて笑いに変える謙遜の表現。","collocations":["self-deprecating humor","self-deprecating joke","self-deprecating remark"]},"procrastinate":{"example2":"Don't procrastinate on rebalancing your portfolio until year-end.","exampleJa2":"ポートフォリオのリバランスを年末まで先延ばしにしてはいけない。","origin":"ラテン語pro(前へ)+cras(明日)→「明日へ送る」。まさに「明日やろう」を語源に持つ単語。","collocations":["procrastinate on a task","tend to procrastinate","stop procrastinating"]},"swamped":{"example2":"Our compliance team is swamped with new regulatory filings this week.","exampleJa2":"今週、当社のコンプライアンスチームは新しい規制関連の提出書類で忙殺されている。","origin":"swamp(沼)から。沼にはまって身動きできないイメージ→仕事に沈んで動けない状態。","collocations":["swamped with work","completely swamped","swamped with emails"]},"slammed":{"example2":"The call center gets slammed every time the market drops sharply.","exampleJa2":"市場が急落するたびに、コールセンターはパンク状態になる。","origin":"slam(叩きつける)から。仕事や客がドンと叩きつけられるように押し寄せるイメージの口語。","collocations":["totally slammed","slammed at work","get slammed with orders"]},"drowning":{"example2":"New hires often feel like they're drowning in unfamiliar jargon.","exampleJa2":"新入社員は慣れない専門用語に溺れているように感じることが多い。","origin":"drown(溺れる)の進行形。仕事や書類の「水」に頭まで浸かって息ができない比喩表現。","collocations":["drowning in paperwork","drowning in debt","drowning in emails"]},"burning the candle at both ends":{"example2":"Trading all day and studying all night, he's burning the candle at both ends.","exampleJa2":"日中はトレード、夜は勉強で、彼は無理をしすぎている。","origin":"ろうそくを両端から燃やすと2倍速で燃え尽きる。朝も夜も働けば体力が倍速で尽きるという比喩。","collocations":["stop burning the candle at both ends","been burning the candle at both ends","keep burning the candle at both ends"]},"pile up":{"example2":"Losses can pile up quickly if you ignore stop-loss rules.","exampleJa2":"損切りルールを無視すると、損失はあっという間に積み上がる。","origin":"pile(積み重ね・山)+up(上へ)。書類や雪が上へ上へと山積みになる映像そのままの句動詞。","collocations":["bills pile up","work piles up","debts pile up"]},"spread thin":{"example2":"With five funds to cover, each analyst is spread too thin.","exampleJa2":"5本のファンドを担当していて、各アナリストは完全に手が回っていない。","origin":"バターを広いパンに薄く(thin)塗り広げる(spread)イメージ。量が足りず薄く引き伸ばされた状態。","collocations":["spread too thin","spread ourselves thin","resources spread thin"]},"running on fumes":{"example2":"By the end of earnings season, the whole team was running on fumes.","exampleJa2":"決算シーズンの終わりには、チーム全員がエネルギー切れ寸前だった。","origin":"fumes(ガソリンの気化ガス)。燃料が尽きて残り香だけで走る車のイメージ→気力の残りカスで動く状態。","collocations":["running on fumes","been running on fumes","run on fumes all week"]},"toll":{"example2":"Years of overtime took a heavy toll on her marriage.","exampleJa2":"長年の残業は彼女の結婚生活に大きな犠牲を強いた。","origin":"元は「通行料」(高速のtollと同じ)。何かを続ける「通行料」として健康や時間が支払われるイメージ。","collocations":["take a toll on","heavy toll","death toll"]},"exhausting":{"example2":"Explaining the same compliance rules repeatedly is mentally exhausting.","exampleJa2":"同じコンプライアンス規則を何度も説明するのは精神的に疲れ果てる。","origin":"ラテン語ex(外へ)+haurire(汲み出す)→中身を汲み尽くす。体力を最後まで汲み出されるイメージ。","collocations":["mentally exhausting","absolutely exhausting","exhausting day"]},"volume":{"example2":"Trading volume spiked sharply after the central bank's surprise announcement.","exampleJa2":"中央銀行のサプライズ発表の後、取引量が急増した。","origin":"ラテン語volvere(巻く)→巻物1巻→書物の分量→量全般へ。金融では出来高の意味で頻出。","collocations":["trading volume","high volume","volume of work"]},"keep up":{"example2":"Salaries in the industry haven't kept up with inflation lately.","exampleJa2":"この業界の給与は最近のインフレに追いついていない。","origin":"keep(保つ)+up(上に・遅れず)。先を行く相手と同じ高さ・速度を保ち続けるイメージ。","collocations":["keep up with demand","keep up the pace","hard to keep up"]},"chill out":{"example2":"Chill out — the market always bounces back eventually.","exampleJa2":"落ち着けよ。市場は最終的には必ず持ち直すものだ。","origin":"chill(冷やす)+out。カッカした頭を冷やすイメージ。熱を冷まして冷静になる、が直感的な由来。","collocations":["chill out at home","just chill out","need to chill out"]},"zen mode":{"example2":"I put my phone away and entered zen mode before the presentation.","exampleJa2":"プレゼンの前にスマホをしまい、完全に落ち着いたモードに入った。","origin":"日本語の「禅」が英語化したもの。座禅の静けさ+ゲーム用語の「モード」で、雑念ゼロの状態を表す。","collocations":["in zen mode","enter zen mode","full zen mode"]},"netflix and chill":{"example2":"They said it was just Netflix and chill, but everyone knew better.","exampleJa2":"ただネトフリでまったりするだけと言っていたが、皆その含みを分かっていた。","origin":"文字通りは「Netflixを見てくつろぐ」。SNSで恋愛的な誘い文句の隠語に変化。使う相手に注意。","collocations":["Netflix and chill tonight","invite someone over for Netflix and chill","just Netflix and chill"]},"veg out":{"example2":"After a brutal week of meetings, I vegged out all Sunday.","exampleJa2":"会議続きの過酷な一週間の後、日曜は一日中ボーッと過ごした。","origin":"vegetable(野菜)を動詞化。野菜のように動かずじっとしている、というcouch potatoと同系の発想。","collocations":["veg out on the couch","veg out in front of the TV","just veg out"]},"connotation":{"example2":"In finance, the word 'aggressive' carries a positive connotation sometimes.","exampleJa2":"金融の世界では、「アグレッシブ」という言葉が良い含意を持つこともある。","origin":"ラテン語con(共に)+notare(印をつける)→本来の意味と共に付いてくる印=言外のニュアンス。","collocations":["negative connotation","carry a connotation","positive connotations"]},"decompress":{"example2":"A short walk between meetings helps me decompress and refocus.","exampleJa2":"会議の合間の短い散歩は、ストレスを解消して集中し直すのに役立つ。","origin":"de(除く)+ラテン語comprimere(押し縮める)→圧力を抜く。潜水後の減圧が原義で、心の減圧へ拡大。","collocations":["decompress after work","time to decompress","decompress and relax"]},"vegetate":{"example2":"He refused to vegetate in retirement and started a consulting business.","exampleJa2":"彼は引退後に無為に過ごすことを拒み、コンサルティング業を始めた。","origin":"ラテン語vegetare(生育させる)→植物のように動かず生きるだけ、へ意味が転落。veg outの正式版。","collocations":["vegetate in front of the TV","vegetate at home","just vegetating"]},"passively":{"example2":"Many investors prefer to invest passively through low-cost index funds.","exampleJa2":"多くの投資家は低コストのインデックスファンドを通じた受動的な投資を好む。","origin":"ラテン語pati(耐える・受ける)から。受け身で耐える→自ら動かない。passion(受難)と同語源。","collocations":["passively managed","invest passively","sit passively"]},"mental health":{"example2":"The firm introduced counseling programs to support employees' mental health.","exampleJa2":"その会社は社員のメンタルヘルスを支援するためカウンセリング制度を導入した。","origin":"mental(ラテン語mens=心)+health(健康)。身体の健康と対になる「心の健康」という直訳の複合語。","collocations":["mental health support","protect your mental health","mental health awareness"]},"road trip":{"example2":"We took a weekend road trip along the coast to celebrate.","exampleJa2":"お祝いに、週末は海岸沿いを車で旅した。","origin":"road(道路)+trip(旅)。鉄道旅と区別して「道路の旅」。車社会アメリカの文化を象徴する言葉。","collocations":["go on a road trip","cross-country road trip","road trip playlist"]},"staycation":{"example2":"With hotel prices soaring, many families opted for a staycation.","exampleJa2":"ホテル代の高騰で、多くの家族が自宅での休暇を選んだ。","origin":"stay(とどまる)+vacation(休暇)の混成語。2008年の不況期に節約休暇の言葉として広まった。","collocations":["enjoy a staycation","plan a staycation","staycation ideas"]},"jet lag":{"example2":"She scheduled no client meetings for two days because of jet lag.","exampleJa2":"時差ボケのため、彼女は2日間顧客との会議を入れなかった。","origin":"jet(ジェット機)+lag(遅れ)。体内時計が飛行機の速さに「遅れて」ついていけない状態。","collocations":["suffer from jet lag","get over jet lag","terrible jet lag"]},"off the beaten path":{"example2":"Our guide took us to villages far off the beaten path.","exampleJa2":"ガイドは観光客がまず行かない村々へ私たちを連れて行ってくれた。","origin":"beaten path(踏み固められた道)から外れて。皆が歩いて固めた道=定番ルートを外れるイメージ。","collocations":["go off the beaten path","destinations off the beaten path","way off the beaten path"]},"wanderlust":{"example2":"Travel documentaries always reignite my wanderlust for remote places.","exampleJa2":"旅のドキュメンタリーを見ると、いつも辺境への旅心が再燃する。","origin":"ドイツ語からの借用語。wandern(歩き回る)+Lust(欲望)→さまよい歩きたい欲望。そのままの合成語。","collocations":["satisfy your wanderlust","a sense of wanderlust","wanderlust kicks in"]},"bucket list":{"example2":"Retiring early gave him time to work through his bucket list.","exampleJa2":"早期退職したことで、彼はやりたいことリストを消化する時間を得た。","origin":"kick the bucket(バケツを蹴る=死ぬの俗語)から。「死ぬ前にやることリスト」。同名映画で世界に普及。","collocations":["on my bucket list","bucket list destination","check off the bucket list"]},"spontaneous":{"example2":"In a spontaneous move, she booked a flight to Lisbon that night.","exampleJa2":"思いつきで、彼女はその夜リスボン行きの航空券を予約した。","origin":"ラテン語sponte(自らの意志で)から。外から強制されず内側から自然に湧き出る、が原義。","collocations":["spontaneous decision","spontaneous trip","completely spontaneous"]},"brutal":{"example2":"The morning commute on that packed train is absolutely brutal.","exampleJa2":"あの満員電車での朝の通勤は本当に過酷だ。","origin":"ラテン語brutus(愚鈍な・獣のような)から。獣のように容赦ない→残酷な→(口語で)きつい、へ拡大。","collocations":["brutal honesty","brutal schedule","absolutely brutal"]},"disorientation":{"example2":"New employees often feel disorientation during their first week.","exampleJa2":"新入社員は最初の一週間、方向感覚を失ったような戸惑いを感じることが多い。","origin":"dis(失う)+orient(東・方角を知る)→東がどちらか分からなくなる。orientは日の昇る東が語源。","collocations":["a sense of disorientation","cause disorientation","temporary disorientation"]},"grand":{"example2":"The bank unveiled a grand plan to expand across Southeast Asia.","exampleJa2":"その銀行は東南アジア全域への拡大という壮大な計画を発表した。","origin":"ラテン語grandis(大きい・成長した)から。grandeur(壮大さ)やピアノのグランドも同じ語源。","collocations":["grand opening","grand plan","grand scale"]},"tbh":{"example2":"TBH, the new investment app is easier than our old system.","exampleJa2":"正直に言うと、新しい投資アプリは以前のシステムより使いやすい。","origin":"To Be Honestの頭字語。「正直に言えば」と前置きして本音を切り出すSNS・チャット定番の略語。","collocations":["TBH, I think","TBH it's fine","TBH, not really"]},"imo":{"example2":"IMO, bonds look more attractive than stocks right now.","exampleJa2":"私の意見では、今は株より債券のほうが魅力的に見える。","origin":"In My Opinionの頭字語。「あくまで私見ですが」と主張を和らげるネット掲示板発の定番略語。","collocations":["IMO, it's worth it","just IMO","IMO, the best option"]},"iykyk":{"example2":"The ramen place behind the station is incredible — IYKYK.","exampleJa2":"駅裏のあのラーメン店は最高なんだ。分かる人には分かるやつ。","origin":"If You Know, You Knowの頭字語。「知ってる人だけが分かる」と仲間内感を出すSNSハッシュタグ発。","collocations":["IYKYK moment","total IYKYK spot","IYKYK vibes"]},"ngl":{"example2":"NGL, I was nervous presenting to the board for the first time.","exampleJa2":"正直言うと、初めて役員会でプレゼンするのは緊張した。","origin":"Not Gonna Lieの頭字語。「嘘はつかないけど」と照れや弱音を白状する前置き。TBHより砕けた響き。","collocations":["NGL, that was hard","NGL, pretty good","NGL, I'm impressed"]},"acronym":{"example2":"ETF is an acronym that stands for exchange-traded fund.","exampleJa2":"ETFは上場投資信託を表す頭字語だ。","origin":"ギリシャ語akros(先端)+onyma(名前)→各単語の「先端の文字」で作る名前。NASAやFOMOが好例。","collocations":["stand for an acronym","common acronym","acronym for"]},"sincere":{"example2":"Clients can always tell whether an advisor's interest is sincere.","exampleJa2":"顧客はアドバイザーの関心が心からのものかどうか、必ず見抜くものだ。","origin":"ラテン語sincerus(混じり気のない・純粋な)から。不純物ゼロの心=誠実、というイメージ。","collocations":["sincere apology","sincere gratitude","sincere interest"]},"insider":{"example2":"Trading on insider information can lead to criminal charges.","exampleJa2":"内部情報を使った取引は刑事罰につながる可能性がある。","origin":"inside(内側)+er(人)→内側にいる人。金融ではインサイダー取引の用語として特に重要。","collocations":["insider trading","insider information","industry insider"]},"admission":{"example2":"Her admission that the forecast was wrong earned clients' respect.","exampleJa2":"予測が間違っていたと認めたことで、彼女はかえって顧客の敬意を得た。","origin":"ラテン語ad(〜へ)+mittere(送り入れる)→中へ入れる→(事実を)受け入れ認めること。入場の意味も同源。","collocations":["admission of guilt","frank admission","by his own admission"]},"migrate":{"example2":"The bank plans to migrate all customer data to the cloud.","exampleJa2":"その銀行は全顧客データをクラウドに移行する計画だ。","origin":"ラテン語migrare(移り住む)から。鳥の渡りが原義で、IT用語のデータ移行にも同じ単語を使う。","collocations":["migrate to the cloud","migrate data","birds migrate south"]},"reshape":{"example2":"Digital payments are reshaping the entire retail banking industry.","exampleJa2":"デジタル決済はリテール銀行業界全体を再構築しつつある。","origin":"re(再び)+shape(形作る)→もう一度形を作り直す。粘土をこね直すような具体的イメージで覚える。","collocations":["reshape the industry","reshape the future","fundamentally reshape"]},"make do with":{"example2":"Until the budget is approved, we'll make do with current software.","exampleJa2":"予算が承認されるまでは、現行のソフトウェアで間に合わせることにする。","origin":"make(間に合わせて)do(用を足す)。「これでやり過ごす」という戦時の物資不足時代に広まった表現。","collocations":["make do with less","make do with what you have","have to make do with"]},"make a point of":{"example2":"He makes a point of calling every client on their birthday.","exampleJa2":"彼はすべての顧客に誕生日に電話することを心がけている。","origin":"point(要点・主義)を自分で作る→「これは自分の主義だ」と意識して必ず実行するイメージ。","collocations":["make a point of doing","make a point of thanking","make a point of being early"]},"make sense":{"example2":"Diversifying your portfolio makes sense in uncertain market conditions.","exampleJa2":"不透明な市場環境では、ポートフォリオを分散させるのは理にかなっている。","origin":"sense(意味・道理)をmake(成す)→「意味を成す」の直訳。日本語の「筋が通る」に近い発想。","collocations":["make sense of","make perfect sense","doesn't make sense"]},"make up for":{"example2":"Strong bond returns made up for this year's equity losses.","exampleJa2":"好調な債券のリターンが今年の株式の損失を埋め合わせた。","origin":"make up(埋めて作り上げる)+for(〜の分)。欠けた穴を埋めて元の高さまで戻すイメージ。","collocations":["make up for lost time","make up for the mistake","make up for it"]},"make a difference":{"example2":"Even small monthly investments can make a big difference over decades.","exampleJa2":"少額の毎月の投資でも、数十年経てば大きな違いを生む。","origin":"difference(差)をmake(作る)→「やる前と後で差を生み出す」。世界を良く変える文脈で頻用。","collocations":["make a big difference","make a real difference","make all the difference"]},"make way for":{"example2":"The old trading floor was closed to make way for automation.","exampleJa2":"旧来の取引フロアは、自動化に道を譲るために閉鎖された。","origin":"way(道)をmake(空けて作る)→通り道を空けて譲る。行列で新しい人に道を空けるイメージ。","collocations":["make way for progress","step aside to make way for","demolished to make way for"]},"make room for":{"example2":"She sold some bonds to make room for emerging market stocks.","exampleJa2":"彼女は新興国株を組み入れる余地を作るため、債券の一部を売却した。","origin":"room(空間・余地)をmake(作る)→物理的に場所を空ける意味から、予定や心の余裕にも拡大。","collocations":["make room for dessert","make room for new ideas","make room for growth"]},"make headway":{"example2":"The fund managers are making headway in reducing portfolio risk.","exampleJa2":"ファンドマネージャーたちはポートフォリオのリスク削減で前進しつつある。","origin":"headwayは船が進む「前進距離」が原義。逆風の中でも船首(head)が進む道(way)を稼ぐイメージで「困難な中での進展」を表す。","collocations":["make headway on negotiations","make significant headway","make little headway"]},"make the best of":{"example2":"With limited budget, the team made the best of existing tools.","exampleJa2":"限られた予算の中で、チームは既存のツールを最大限に活用した。","origin":"「悪い状況(it)の中からbest(最善)を作り出す」という直訳イメージそのまま。make the best of a bad situationの短縮形と覚える。","collocations":["make the best of a bad situation","make the best of it","make the best of limited resources"]},"recruitment":{"example2":"The bank increased recruitment of analysts with fintech experience.","exampleJa2":"その銀行はフィンテック経験のあるアナリストの採用を増やした。","origin":"re(再び)+crescere(成長する)が語源。兵力を「再び増やす＝新兵補充」が原義で、そこから人員の採用全般に広がった。","collocations":["recruitment process","recruitment drive","graduate recruitment"]},"resilient":{"example2":"Despite the market crash, consumer spending remained surprisingly resilient.","exampleJa2":"市場暴落にもかかわらず、個人消費は驚くほど底堅かった。","origin":"re(後ろへ)+salire(跳ぶ)→「跳ね返る」が原義。押されても跳ね返るバネのイメージで「回復力のある」。","collocations":["remarkably resilient","resilient economy","resilient to shocks"]},"constraints":{"example2":"Regulatory constraints limit how much leverage the fund can use.","exampleJa2":"規制上の制約により、ファンドが使えるレバレッジには限度がある。","origin":"con(共に)+stringere(縛る)→「縛りつけるもの」。stringにも通じる「ひもで締める」イメージから「制約」。","collocations":["budget constraints","time constraints","impose constraints on"]},"take for granted":{"example2":"Investors took low interest rates for granted for a decade.","exampleJa2":"投資家たちは10年間、低金利を当たり前のものと考えていた。","origin":"grantedは「与えられた・認められた」。「すでに認められたものとして受け取る」→疑問も感謝もなく当然視する、というイメージ。","collocations":["take it for granted that","take someone for granted","be taken for granted"]},"take into account":{"example2":"The valuation model takes currency risk into account.","exampleJa2":"その評価モデルは為替リスクを考慮に入れている。","origin":"accountは「勘定・計算」。「計算の中に入れる」→判断材料として組み込む、という会計由来のイメージで覚える。","collocations":["take costs into account","take into account the fact that","fail to take into account"]},"take a toll on":{"example2":"Prolonged inflation is taking a toll on household savings.","exampleJa2":"長引くインフレが家計の貯蓄に打撃を与えている。","origin":"tollは「通行料」。通るたびに料金を取られるように、時間とともに少しずつ犠牲や損害を「徴収される」イメージ。","collocations":["take a heavy toll on","take a toll on health","take its toll"]},"take the plunge":{"example2":"After years of renting, they took the plunge and bought a house.","exampleJa2":"何年も賃貸暮らしをした後、彼らは思い切って家を購入した。","origin":"plungeは「飛び込み」。冷たいプールにためらった末にえいっと飛び込む姿が原イメージ。迷いを断って決行する場面で使う。","collocations":["finally take the plunge","take the plunge and invest","decide to take the plunge"]},"take it upon oneself":{"example2":"He took it upon himself to update the client database weekly.","exampleJa2":"彼は自ら進んで顧客データベースを毎週更新する役目を引き受けた。","origin":"「それ(it)を自分の上(upon oneself)に載せる」→頼まれてもいない責任を自分の肩に担ぐイメージ。","collocations":["take it upon yourself to do","took it upon herself to organize","take responsibility upon oneself"]},"take heart":{"example2":"Investors can take heart from the strong earnings season.","exampleJa2":"好調な決算シーズンに投資家は勇気づけられるだろう。","origin":"heartは古くから「勇気」の象徴。「心(勇気)を取り戻す」→落ち込んだ状況で希望を持つ、という激励の定型句。","collocations":["take heart from","take heart in the fact that","you can take heart"]},"take at face value":{"example2":"Analysts rarely take company forecasts at face value.","exampleJa2":"アナリストは企業の業績予想を額面通りに受け取ることはめったにない。","origin":"face valueは紙幣や債券の「額面価格」。実際の価値を疑わず、表面に書かれた金額のまま受け取るという金融由来の比喩。","collocations":["take claims at face value","accept at face value","shouldn't be taken at face value"]},"take a step back":{"example2":"Before rebalancing the portfolio, let's take a step back and review our goals.","exampleJa2":"ポートフォリオを再調整する前に、一歩引いて目標を見直しましょう。","origin":"絵画から一歩下がると全体が見えるように、対象から物理的に離れて全体像を見直すイメージ。冷静な再検討を促す表現。","collocations":["take a step back and think","take a step back from the situation","let's take a step back"]},"take action":{"example2":"The central bank took swift action to stabilize the currency.","exampleJa2":"中央銀行は通貨を安定させるため迅速に行動を起こした。","origin":"actionはagere(行う)由来。「行動を取る」の最も基本的な言い方で、口先だけでなく実際に動くことを強調する。","collocations":["take immediate action","take legal action","take action against"]},"disrupts":{"example2":"A sudden rate hike often disrupts bond markets worldwide.","exampleJa2":"突然の利上げはしばしば世界中の債券市場を混乱させる。","origin":"dis(バラバラに)+rumpere(壊す)→「引き裂いて壊す」。流れを断ち切って秩序を乱すイメージ。","collocations":["disrupt operations","disrupt supply chains","severely disrupt"]},"reassess":{"example2":"The committee will reassess its rate outlook next month.","exampleJa2":"委員会は来月、金利見通しを再評価する予定だ。","origin":"re(再び)+assess(評価する)。assessはad(そばに)+sedere(座る)→「裁判官の隣に座り査定する」が原義。","collocations":["reassess the situation","reassess priorities","reassess the risks"]},"get the hang of":{"example2":"New hires usually get the hang of the trading system quickly.","exampleJa2":"新入社員はたいてい取引システムのコツをすぐにつかむ。","origin":"hangは道具の「持ち方・扱い方」を指した古い用法。斧の柄の握り具合を体で覚えるように、練習で要領をつかむイメージ。","collocations":["get the hang of it","quickly get the hang of","get the hang of using"]},"get around to":{"example2":"I finally got around to reviewing my retirement plan.","exampleJa2":"ようやく退職後の資金計画を見直す時間が取れた。","origin":"「あちこち回って(around)ようやくそこに到達する(get to)」イメージ。後回しにしていた用事に順番が巡ってくる感覚。","collocations":["get around to doing","never get around to it","finally get around to"]},"get carried away":{"example2":"Investors got carried away during the tech stock rally.","exampleJa2":"ハイテク株の上昇局面で投資家たちは熱狂しすぎた。","origin":"「(感情の波に)運び去られる」が直訳。興奮の流れに流されて自制を失うイメージ。相場の過熱にもよく使う。","collocations":["get carried away with","don't get carried away","easy to get carried away"]},"get away with":{"example2":"Some firms got away with misleading disclosures for years.","exampleJa2":"一部の企業は何年も誤解を招く情報開示をしながら咎められずにいた。","origin":"「悪事とともに(with)逃げ切る(get away)」イメージ。盗んだものを持ったまま捕まらずに逃げる泥棒の絵で覚える。","collocations":["get away with murder","let someone get away with","get away with it"]},"get through":{"example2":"The team got through a brutal earnings week without major errors.","exampleJa2":"チームは過酷な決算週を大きなミスなく乗り切った。","origin":"「困難というトンネルを通り抜ける(through)」イメージ。試練の向こう側にたどり着く感覚で覚える。","collocations":["get through the day","get through a crisis","help someone get through"]},"get along with":{"example2":"She gets along well with clients from different backgrounds.","exampleJa2":"彼女は様々な背景を持つ顧客とうまくやっている。","origin":"「一緒に(with)前へ進んで(along)いける」イメージ。同じ道を並んで歩ける関係＝仲が良い、と覚える。","collocations":["get along well with","get along with colleagues","easy to get along with"]},"get rid of":{"example2":"The fund got rid of its underperforming holdings last quarter.","exampleJa2":"そのファンドは前四半期に不振の保有銘柄を処分した。","origin":"ridは古ノルド語「土地を切り開く」由来。邪魔なものを取り除いてすっきりさせるイメージ。be rid of(免れている)とセットで覚える。","collocations":["get rid of debt","get rid of old habits","finally get rid of"]},"get bogged down":{"example2":"The merger talks got bogged down in regulatory details.","exampleJa2":"合併交渉は規制の細部で行き詰まった。","origin":"bogは「沼地」。沼にはまって足が抜けなくなるイメージそのまま。細かい問題に足を取られて前に進めない場面で使う。","collocations":["get bogged down in details","get bogged down by paperwork","avoid getting bogged down"]},"get to the bottom of":{"example2":"Auditors are determined to get to the bottom of the missing funds.","exampleJa2":"監査人たちは資金消失の真相を突き止める決意だ。","origin":"「物事の底(bottom)までたどり着く」イメージ。表面ではなく一番深いところに真実があるという発想の表現。","collocations":["get to the bottom of the problem","get to the bottom of this","determined to get to the bottom of"]},"get on the wrong side of":{"example2":"The broker got on the wrong side of regulators after the incident.","exampleJa2":"その証券会社は例の一件以来、規制当局に目をつけられた。","origin":"「相手の機嫌の悪い側(wrong side)に立ってしまう」イメージ。get on the right side of(気に入られる)の反対として覚える。","collocations":["get on the wrong side of the law","get on the wrong side of your boss","don't get on the wrong side of"]},"jaywalking":{"example2":"The city launched a campaign to discourage jaywalking downtown.","exampleJa2":"市は中心街での信号無視の横断を減らすキャンペーンを始めた。","origin":"jayは「田舎者・世間知らず」の古いスラング。都会のルールを知らずに道路を渡る人を揶揄した言葉が定着した。","collocations":["a fine for jaywalking","caught jaywalking","jaywalking laws"]},"tenant":{"example2":"The REIT signed a major tenant for its new office tower.","exampleJa2":"そのREITは新しいオフィスタワーに大口テナントとの契約を結んだ。","origin":"ラテン語tenere(保持する)由来。「土地を保持する人」が原義で、maintainやtenureと同語源。借りて住む人を指す。","collocations":["tenant rights","commercial tenant","evict a tenant"]},"put up with":{"example2":"Long-term investors must put up with short-term volatility.","exampleJa2":"長期投資家は短期的な値動きの荒さを我慢しなければならない。","origin":"「嫌なものを棚に上げて(put up)そのまま共存する(with)」イメージ。文句を言わず耐える、tolerateの口語版。","collocations":["put up with noise","refuse to put up with","have to put up with"]},"put forward":{"example2":"The board put forward a proposal to raise the dividend.","exampleJa2":"取締役会は増配の提案を提出した。","origin":"「案を前へ(forward)差し出す(put)」イメージそのまま。会議のテーブルの中央に案を押し出す絵で覚える。","collocations":["put forward a proposal","put forward an idea","put forward a candidate"]},"put off":{"example2":"Many households put off big purchases when rates rise.","exampleJa2":"金利が上がると多くの家庭は大きな買い物を先延ばしにする。","origin":"「予定を(カレンダーから)外して(off)置く」イメージ。今日のリストから外して後日に回す感覚で「延期する」。","collocations":["put off a decision","put off until tomorrow","keep putting off"]},"put down":{"example2":"A good manager never puts down junior staff in meetings.","exampleJa2":"良い上司は会議で若手社員をけなしたりしない。","origin":"「人を下に(down)置く」→相手の価値を下げて見せる、という上下イメージ。人前で格下げする感覚の「けなす」。","collocations":["put someone down","put down other people's ideas","feel put down"]},"put together":{"example2":"The analyst put together a detailed report on emerging markets.","exampleJa2":"そのアナリストは新興国市場に関する詳細なレポートをまとめ上げた。","origin":"「バラバラの部品を一緒に(together)置く」イメージ。部品の組み立てから、資料やチームの編成まで幅広く使える。","collocations":["put together a team","put together a plan","put together a presentation"]},"put aside":{"example2":"The rival banks put aside their differences to rescue the market.","exampleJa2":"ライバル銀行同士が対立を棚上げして市場救済にあたった。","origin":"「脇に(aside)置く」が直訳。今は扱わないものを机の端によけるイメージ。お金を「取り分けて貯める」意味でも使う。","collocations":["put aside differences","put aside money","put aside your feelings"]},"put out":{"example2":"The fund put out its quarterly performance report today.","exampleJa2":"そのファンドは本日、四半期の運用報告書を公表した。","origin":"「外に(out)出す」が直訳。社内にあったものを世の中へ出すイメージで「発表・発行する」。火を消す意味もあるので文脈で判断。","collocations":["put out a statement","put out a press release","put out a new album"]},"put on the map":{"example2":"The blockbuster fund put the small asset manager on the map.","exampleJa2":"その大ヒットファンドが小さな運用会社の名を世に知らしめた。","origin":"「地図に載せる」が直訳。無名の町が地図に記載されるほど有名になるイメージ。人や企業を一躍有名にする場面で使う。","collocations":["put the company on the map","put the town on the map","really put us on the map"]},"put into action":{"example2":"The bank put its cost-cutting plan into action this spring.","exampleJa2":"その銀行は今春、コスト削減計画を実行に移した。","origin":"「計画を行動(action)の中へ入れる」イメージ。紙の上のプランを現実の動きに変換する感覚。put into practiceも同義。","collocations":["put a plan into action","put ideas into action","put the strategy into action"]},"put yourself out there":{"example2":"She put herself out there by pitching directly to major investors.","exampleJa2":"彼女は大口投資家に直接売り込むという思い切った行動に出た。","origin":"「自分を外の世界(out there)に置く」が直訳。安全圏から出て人目にさらされる場所に立つイメージ。挑戦を促す口語表現。","collocations":["put yourself out there and try","afraid to put yourself out there","really put herself out there"]},"reckless":{"example2":"Regulators warned banks against reckless lending practices.","exampleJa2":"規制当局は銀行に対し無謀な融資慣行をやめるよう警告した。","origin":"古英語reck(気にかける)+less(〜がない)→「注意を払わない」。結果を顧みない無頓着さが原イメージ。","collocations":["reckless driving","reckless spending","reckless behavior"]},"come up with":{"example2":"The team came up with a creative solution to cut fees.","exampleJa2":"チームは手数料を削減する独創的な解決策を考え出した。","origin":"「アイデアを携えて(with)水面に浮かび上がってくる(come up)」イメージ。頭の底から答えが浮上する感覚で覚える。","collocations":["come up with an idea","come up with a solution","come up with a plan"]},"come across":{"example2":"I came across an interesting research note on inflation trends.","exampleJa2":"インフレ動向に関する興味深いリサーチノートを偶然見つけた。","origin":"「道を横切る(across)ときに出会う」イメージ。探していないのに進路上でばったり遭遇する感覚。印象を「与える」意味もある。","collocations":["come across an article","come across as confident","happen to come across"]},"come to terms with":{"example2":"Markets slowly came to terms with the era of higher rates.","exampleJa2":"市場は金利の高い時代を徐々に受け入れていった。","origin":"termsは「合意条件」。争っていた相手と条件で折り合う→つらい現実と「和解」して受け入れる、という交渉由来の比喩。","collocations":["come to terms with reality","come to terms with the loss","struggle to come to terms with"]},"come around":{"example2":"Skeptical clients eventually came around after seeing the returns.","exampleJa2":"懐疑的だった顧客も運用成績を見てやがて考えを改めた。","origin":"「ぐるっと回って(around)こちら側に来る」イメージ。反対側にいた人が円を描いて味方の位置に移動してくる絵で覚える。","collocations":["come around to the idea","come around eventually","come around to our view"]},"come into one's own":{"example2":"Index funds came into their own during the volatile decade.","exampleJa2":"インデックスファンドはあの変動の激しい10年間に本領を発揮した。","origin":"one's ownは「本来自分のもの(領分・権利)」。相続財産を受け取るように、自分にふさわしい立場や実力をついに手にするイメージ。","collocations":["really come into her own","come into its own as","come into their own during"]},"come about":{"example2":"The merger came about after months of quiet negotiations.","exampleJa2":"その合併は数か月に及ぶ水面下の交渉の末に実現した。","origin":"「物事がぐるりと巡って(about)現れる」イメージ。帆船が風向きで向きを変える航海用語にも由来し、自然な成り行きで起こる感覚。","collocations":["how did it come about","come about by chance","changes came about"]},"come to grips with":{"example2":"The industry is coming to grips with new disclosure rules.","exampleJa2":"業界は新しい開示ルールへの対応に本腰を入れ始めている。","origin":"gripは「つかむこと」。レスリングで相手と組み合うイメージから、難題から逃げずにがっちり組み付いて取り組む感覚。","collocations":["come to grips with reality","come to grips with the problem","fully come to grips with"]},"come down to":{"example2":"Choosing a fund often comes down to fees and track record.","exampleJa2":"ファンド選びは結局、手数料と運用実績に行き着くことが多い。","origin":"「複雑な話が下へ降りてきて(down)核心に着地する」イメージ。枝葉を削ぎ落とすと残る本質、という感覚で覚える。","collocations":["it all comes down to","come down to a matter of","come down to money"]},"come up against":{"example2":"The expansion plan came up against strong local opposition.","exampleJa2":"その拡大計画は地元の強い反対に直面した。","origin":"「進んでいくと目の前に壁が立ちはだかる(up against)」イメージ。前進中に障害物と正面衝突する感覚。","collocations":["come up against obstacles","come up against resistance","come up against a problem"]},"disruption":{"example2":"Fintech disruption forced traditional banks to modernize quickly.","exampleJa2":"フィンテックによる破壊的変化が伝統的な銀行に迅速な近代化を迫った。","origin":"dis(バラバラに)+rumpere(壊す)+tion(名詞化)。既存の秩序を「引き裂く」イメージで、業界構造を覆す変化を指す。","collocations":["digital disruption","market disruption","cause disruption"]},"adaptability":{"example2":"Adaptability helped the firm survive three market cycles.","exampleJa2":"適応力のおかげで、その会社は3つの市場サイクルを生き延びた。","origin":"ad(〜へ)+aptare(合わせる)→「状況に合わせる力」。aptは「適した」。環境にぴったり形を合わせるイメージ。","collocations":["show adaptability","adaptability to change","flexibility and adaptability"]},"turn things around":{"example2":"Aggressive cost cuts helped the airline turn things around.","exampleJa2":"大胆なコスト削減がその航空会社の経営立て直しに寄与した。","origin":"「物事の向きをぐるりと反転(around)させる」イメージ。下向きだった矢印を上向きに回す絵で覚える。企業再建の定番表現。","collocations":["turn things around quickly","turn the company around","help turn things around"]},"turn down":{"example2":"The board turned down the takeover bid as too low.","exampleJa2":"取締役会は買収提案を安すぎるとして拒否した。","origin":"「差し出されたものを下に向けて(down)返す」イメージ。ランプの火を絞る動作からとも言われ、相手の申し出を弱めて退ける感覚。","collocations":["turn down an offer","turn down a request","politely turn down"]},"turn out":{"example2":"The risky bond issue turned out better than anyone expected.","exampleJa2":"リスクの高い債券発行は、誰の予想よりも良い結果となった。","origin":"「中身が外に出て(out)正体が判明する」イメージ。袋をひっくり返して中身が現れるように、最終的な結果が明らかになる感覚。","collocations":["turn out well","turn out to be true","as it turned out"]},"turn a blind eye":{"example2":"Auditors cannot turn a blind eye to accounting irregularities.","exampleJa2":"監査人は会計上の不正を見て見ぬふりをすることはできない。","origin":"英提督ネルソンが望遠鏡を失明した目に当て「信号が見えない」と戦闘を続けた逸話が由来とされる。意図的な無視を表す。","collocations":["turn a blind eye to violations","turn a blind eye to the problem","authorities turned a blind eye"]},"turn one's attention to":{"example2":"Having secured funding, the startup turned its attention to hiring.","exampleJa2":"資金調達を終え、そのスタートアップは採用に注意を向けた。","origin":"「注意という照明の向きを変える(turn)」イメージ。スポットライトを次の対象に回す感覚で、話題や作業の切り替えに使う。","collocations":["turn our attention to the next issue","turn her attention to work","now turn your attention to"]},"turn a profit":{"example2":"Few new asset managers turn a profit in their first year.","exampleJa2":"初年度から利益を出せる新興運用会社はほとんどない。","origin":"turnには「(取引で)生み出す」という古い商業用法がある。商品を回転(turn over)させて利益を生むイメージで覚える。","collocations":["turn a profit quickly","fail to turn a profit","finally turn a profit"]},"turn against":{"example2":"Public opinion turned against the bank after the scandal.","exampleJa2":"スキャンダルの後、世論はその銀行に反感を抱くようになった。","origin":"「体の向きを変えて(turn)相手に敵対する(against)」イメージ。味方だった人がくるりと振り返り牙をむく絵で覚える。","collocations":["turn against each other","voters turned against","friends turned against him"]},"consecutive":{"example2":"The fund posted gains for five consecutive quarters.","exampleJa2":"そのファンドは5四半期連続で利益を計上した。","origin":"con(共に)+sequi(続く)→「切れ目なく後に続く」。sequence(連続)と同語源。間を空けず並ぶイメージ。","collocations":["three consecutive years","consecutive victories","consecutive quarters of growth"]},"rally behind":{"example2":"Shareholders rallied behind the new CEO's turnaround plan.","exampleJa2":"株主たちは新CEOの再建計画を支持して結集した。","origin":"rallyはre(再び)+allier(結びつける)→「再結集する」。旗の後ろ(behind)に兵が集まり直すイメージ。相場の反発の意味もある。","collocations":["rally behind the leader","rally behind a cause","the nation rallied behind"]},"thriving":{"example2":"The region's thriving startup scene attracts global venture capital.","exampleJa2":"その地域の活気あるスタートアップ業界は世界のベンチャー資本を引きつけている。","origin":"古ノルド語thrifask(自分をつかみ取る→繁栄する)由来。しっかり根を張ってぐんぐん育つ植物のイメージ。","collocations":["thriving business","thriving economy","thriving community"]},"run into":{"example2":"The project ran into funding problems midway through.","exampleJa2":"そのプロジェクトは途中で資金の問題にぶつかった。","origin":"「走っていて(run)何かに突っ込む(into)」イメージ。人なら偶然の出会い、問題なら衝突。予期せずぶつかる感覚が共通。","collocations":["run into trouble","run into an old friend","run into difficulties"]},"run out of":{"example2":"The startup ran out of cash before reaching profitability.","exampleJa2":"そのスタートアップは黒字化する前に資金を使い果たした。","origin":"「蓄えの中から(out of)走り出て空になる」イメージ。砂時計の砂が流れ切る感覚で、残量ゼロを表す。","collocations":["run out of money","run out of time","run out of patience"]},"run the risk of":{"example2":"Concentrated portfolios run the risk of severe drawdowns.","exampleJa2":"集中投資のポートフォリオは大幅な下落リスクを抱えている。","origin":"runには「(危険に)身をさらして進む」という用法がある。リスクの中を走り抜けようとするイメージで覚える。","collocations":["run the risk of losing","run the risk of failure","run a serious risk"]},"run the numbers":{"example2":"We ran the numbers and the acquisition doesn't make sense.","exampleJa2":"数字を精査したが、その買収は割に合わない。","origin":"計算機やプログラムを「走らせる(run)」イメージ。データを機械にかけて答えを出す感覚の、実務でよく使う口語表現。","collocations":["run the numbers on","let me run the numbers","run the numbers again"]},"run circles around":{"example2":"Their research team runs circles around larger rivals.","exampleJa2":"彼らのリサーチチームは規模で勝る競合をはるかに凌いでいる。","origin":"相手の周りをぐるぐる走り回れるほど速い、というかけっこのイメージ。実力差が歴然としている様子をユーモラスに表す。","collocations":["run circles around the competition","run circles around rivals","could run circles around"]},"run scared":{"example2":"Smaller brokers are running scared of the new fee war.","exampleJa2":"中小の証券会社は新たな手数料競争におびえている。","origin":"「怖がりながら(scared)逃げ走る」が直訳。追われる立場になって浮き足立つイメージ。選挙や競争の報道でよく使う。","collocations":["running scared of the competition","have them running scared","run scared before the election"]},"in the long run":{"example2":"Diversification usually reduces risk in the long run.","exampleJa2":"分散投資は長期的には通常リスクを低減する。","origin":"runは「(時間の)経過・道のり」。長い道のりを走り切った先で見れば、という競走の比喩。対義はin the short run。","collocations":["pay off in the long run","in the long run it's cheaper","benefit in the long run"]},"run a tight ship":{"example2":"The CFO runs a tight ship, questioning every expense.","exampleJa2":"そのCFOはあらゆる経費に目を光らせ、組織を厳格に管理している。","origin":"帆船の索具(ロープ)がピンと張られた(tight)状態は手入れが行き届いた証。規律の取れた船＝厳格に運営される組織の比喩。","collocations":["run a tight ship financially","known for running a tight ship","runs a very tight ship"]},"run like clockwork":{"example2":"Thanks to automation, the settlement process runs like clockwork.","exampleJa2":"自動化のおかげで、決済プロセスは時計仕掛けのように正確に動いている。","origin":"clockworkは「時計仕掛け」。歯車が狂いなく回る機械時計のように、寸分の狂いもなく物事が進むイメージ。","collocations":["run like clockwork every day","the operation runs like clockwork","everything ran like clockwork"]},"running low on":{"example2":"The central bank is running low on policy options.","exampleJa2":"中央銀行は政策の選択肢が少なくなってきている。","origin":"「残量メーターが低い(low)位置に向かって進んでいる」イメージ。run out of(尽きる)の一歩手前の状態と覚える。","collocations":["running low on supplies","running low on cash","running low on energy"]},"defaulting":{"example2":"Rating agencies flagged the developer as close to defaulting.","exampleJa2":"格付け会社はその不動産開発会社が債務不履行寸前だと警告した。","origin":"de(欠けて)+fallere(欺く・失敗する)→「義務を果たし損ねる」。faultと同語源で、あるべき支払いが「欠ける」イメージ。","collocations":["defaulting on a loan","risk of defaulting","defaulting borrowers"]},"break through":{"example2":"The stock finally broke through its long-standing resistance level.","exampleJa2":"その株価はついに長年の抵抗線を突破した。","origin":"「壁を壊して(break)向こう側へ抜ける(through)」イメージそのまま。障害や限界を打ち破る場面全般に使える。","collocations":["break through the barrier","break through resistance","finally break through"]},"break the ice":{"example2":"She broke the ice with a light question about weekend plans.","exampleJa2":"彼女は週末の予定についての軽い質問で場の雰囲気を和ませた。","origin":"航路を開くため砕氷船が氷を割ったことが由来。凍りついた場の空気を最初に割って会話の道を開くイメージ。","collocations":["break the ice with a joke","help break the ice","an icebreaker question"]},"break new ground":{"example2":"The ETF broke new ground by tracking private credit markets.","exampleJa2":"そのETFはプライベートクレジット市場に連動するという新境地を開いた。","origin":"未開墾の土地を初めて耕す(ground=土地)農業の比喩。誰も手をつけていない分野を切り開くイメージ。groundbreakingも同源。","collocations":["break new ground in research","break new ground with technology","truly break new ground"]},"break down":{"example2":"The elevator broke down during the morning rush.","exampleJa2":"朝のラッシュ時にエレベーターが故障した。","origin":"「壊れて(break)機能が停止・崩落する(down)」イメージ。機械の故障のほか、交渉決裂や感情の崩壊、分解説明にも広がる。","collocations":["the car broke down","talks broke down","break down the costs"]},"break even":{"example2":"The new branch should break even within eighteen months.","exampleJa2":"新支店は18か月以内に損益分岐点に達する見込みだ。","origin":"evenは「五分五分・対等」。収支がぴったり釣り合って勝ちも負けもない状態。break-even point(損益分岐点)は会計の基本用語。","collocations":["break even point","expect to break even","barely break even"]},"break away from":{"example2":"The firm broke away from paper-based processes entirely.","exampleJa2":"その会社は紙ベースの業務プロセスから完全に脱却した。","origin":"「つながれていたものを断ち切って(break)離れていく(away)」イメージ。鎖を引きちぎって独立する絵で覚える。","collocations":["break away from tradition","break away from the group","break away from old habits"]},"break with tradition":{"example2":"The bank broke with tradition and named an outsider as CEO.","exampleJa2":"その銀行は伝統を破り、外部出身者をCEOに指名した。","origin":"break with〜は「〜との関係を断つ」。長年連れ添った伝統と絶縁するイメージ。break with conventionも同型。","collocations":["break with tradition by doing","a bold break with tradition","decide to break with tradition"]},"break free from":{"example2":"The economy struggled to break free from deflation.","exampleJa2":"その経済はデフレから抜け出そうともがいていた。","origin":"「拘束を壊して(break)自由(free)になる」イメージ。縛られたロープを引きちぎって解放される絵で覚える。","collocations":["break free from constraints","break free from the past","struggle to break free"]},"big break":{"example2":"Managing the pension mandate was the firm's big break.","exampleJa2":"年金運用の受託がその会社にとって大きな飛躍のチャンスだった。","origin":"breakには「幸運の切れ目・巡り合わせ」の意味がある。無名時代を破る(break)一発の好機、という芸能界由来のニュアンス。","collocations":["get your big break","waiting for a big break","her big break came when"]},"breakthrough":{"example2":"The breakthrough in battery technology lifted related stocks sharply.","exampleJa2":"電池技術の画期的な進展で関連銘柄が急騰した。","origin":"break(破る)+through(貫通)の名詞化。軍事用語の「敵陣突破」が原義で、行き詰まりを打ち破る大発見・大進展を指す。","collocations":["a major breakthrough","scientific breakthrough","achieve a breakthrough"]},"oversaturated":{"example2":"The robo-advisor market has become oversaturated with similar products.","exampleJa2":"ロボアドバイザー市場は類似商品で供給過剰になっている。","origin":"over(過度に)+saturare(満たす)→「限界以上に満たされた」。水を吸い切ったスポンジにさらに注ぐイメージ。","collocations":["an oversaturated market","oversaturated with competitors","become oversaturated"]},"mediocrity":{"example2":"Years of mediocrity pushed investors to pull money from the fund.","exampleJa2":"長年の凡庸な成績に、投資家はそのファンドから資金を引き揚げた。","origin":"medi(中間)+ocris(険しい山)→「山の中腹止まり」。頂上に達しない中途半端さが原義で、突出しない平凡さを表す。","collocations":["settle for mediocrity","a life of mediocrity","rise above mediocrity"]},"hold your ground":{"example2":"She held her ground when clients pushed for riskier bets.","exampleJa2":"顧客がよりリスクの高い投資を求めても、彼女は自分の方針を曲げなかった。","origin":"戦場で自軍の陣地(ground)を守り抜く軍事用語が由来。敵の圧力を受けても一歩も退かないイメージ。","collocations":["hold your ground in negotiations","stand and hold your ground","held her ground despite pressure"]},"hold off":{"example2":"The Fed held off on cutting rates until inflation cooled.","exampleJa2":"FRBはインフレが落ち着くまで利下げを見送った。","origin":"「行動を離れた位置に(off)保持しておく(hold)」イメージ。手を出さずに構えたまま待つ感覚で「延期する・見合わせる」。","collocations":["hold off on a decision","hold off until next week","decide to hold off"]},"hold accountable":{"example2":"Shareholders held the board accountable for the failed merger.","exampleJa2":"株主たちは合併失敗の責任を取締役会に問うた。","origin":"accountableは「説明(account)する義務がある」。行動の顛末を説明させる立場に置く(hold)＝責任を追及するイメージ。","collocations":["hold leaders accountable","be held accountable for","hold someone accountable for mistakes"]},"hold water":{"example2":"The bull case for that stock no longer holds water.","exampleJa2":"その銘柄の強気シナリオはもはや筋が通らない。","origin":"水を入れても漏れない容器のイメージ。穴だらけの議論は水(検証)を注ぐと漏れる＝論理が破綻する、という比喩。","collocations":["the argument doesn't hold water","his theory doesn't hold water","claims that don't hold water"]},"hold the line":{"example2":"The company held the line on prices despite rising costs.","exampleJa2":"コスト上昇にもかかわらず、その会社は価格を据え置いた。","origin":"戦線(line)を守り抜く軍事用語が由来。防衛ラインを一歩も下げないイメージで、価格や方針を譲らない場面に使う。","collocations":["hold the line on spending","hold the line on prices","hold the line against pressure"]},"hold up":{"example2":"Consumer demand held up well despite higher interest rates.","exampleJa2":"金利上昇にもかかわらず、消費需要はしっかりと持ちこたえた。","origin":"「支えて(hold)上に保つ(up)」イメージ。重圧の下でも崩れず立っている柱の絵で「持ちこたえる・検証に耐える」。","collocations":["hold up under pressure","hold up well","the argument doesn't hold up"]},"hold true":{"example2":"The same investment principles hold true in bear markets.","exampleJa2":"同じ投資原則は弱気相場でも当てはまる。","origin":"「真(true)の状態を保ち続ける(hold)」が直訳。時間や条件が変わっても真実であり続けるイメージ。remain trueと同義。","collocations":["hold true for everyone","still hold true today","the rule holds true"]},"hold your nerve":{"example2":"Long-term investors must hold their nerve during market crashes.","exampleJa2":"長期投資家は市場暴落の間も冷静さを保たなければならない。","origin":"nerveは「胆力・度胸」。プレッシャーで手が震えそうな場面でも神経を制御下に保つ(hold)イメージ。英国系でよく使う表現。","collocations":["hold your nerve under pressure","held their nerve until the end","need to hold your nerve"]},"hold fire":{"example2":"Analysts advised clients to hold fire until earnings are out.","exampleJa2":"アナリストは決算発表まで様子を見るよう顧客に助言した。","origin":"軍の「撃ち方待て(hold fire)」が由来。引き金に指をかけたまま発砲を待つイメージで、行動を保留する意味に広がった。","collocations":["hold fire on the decision","hold fire until we know more","told to hold fire"]},"opposing counsel":{"example2":"Opposing counsel demanded access to the firm's internal emails.","exampleJa2":"相手方弁護士は会社の内部メールの開示を要求した。","origin":"counselはconsilium(助言)由来で「法律顧問・弁護人」。oppose(対抗する)側のcounsel＝訴訟で向かい合う相手側の弁護士。","collocations":["negotiate with opposing counsel","opposing counsel objected","meet with opposing counsel"]},"settlement":{"example2":"The bank paid a large settlement to avoid a lengthy trial.","exampleJa2":"その銀行は長期の裁判を避けるため多額の和解金を支払った。","origin":"settle(据える・落ち着かせる)+ment。争いを「落着」させる合意が原義。金融では取引の「決済」、地理では「入植地」の意味もある。","collocations":["reach a settlement","out-of-court settlement","settlement agreement"]},"pull off":{"example2":"The team pulled off the system migration over a single weekend.","exampleJa2":"チームはたった一度の週末でシステム移行をやり遂げた。","origin":"「困難な状況から成功を引き抜く(pull off)」イメージ。誰もが無理だと思う賞品を力ずくでもぎ取る感覚で覚える。","collocations":["pull off a victory","pull off a deal","manage to pull off"]},"pull strings":{"example2":"She pulled strings to get the report reviewed ahead of schedule.","exampleJa2":"彼女はコネを使って、そのレポートを予定より早く審査してもらった。","origin":"操り人形の糸(strings)を陰で引く人形師のイメージ。表に出ずに人を動かして物事を有利に運ぶことを表す。","collocations":["pull strings behind the scenes","pull a few strings","pull strings to get a job"]},"pull together":{"example2":"We pulled together data from five departments for the audit.","exampleJa2":"監査のために5つの部署からデータをかき集めた。","origin":"「バラバラのものを引き寄せて(pull)一つにまとめる(together)」イメージ。自動詞では「一致団結する」の意味にもなる。","collocations":["pull together a report","pull together resources","pull together as a team"]},"pull the plug on":{"example2":"Investors pulled the plug on the project after cost overruns.","exampleJa2":"コスト超過を受けて、投資家たちはそのプロジェクトを打ち切った。","origin":"生命維持装置や機械の「電源プラグを抜く」イメージ。資金や支援という電源を断って強制終了させる比喩。","collocations":["pull the plug on the project","pull the plug on funding","decide to pull the plug"]},"pull no punches":{"example2":"The auditor's report pulled no punches about the firm's weaknesses.","exampleJa2":"監査報告書はその会社の弱点について一切遠慮なく指摘した。","origin":"ボクシングで手加減してパンチを途中で止める(pull)ことをしない、が由来。全力で打つ＝率直に批判するイメージ。","collocations":["pull no punches in criticism","the review pulled no punches","she pulls no punches"]},"pull your weight":{"example2":"In a small firm, every employee has to pull their weight.","exampleJa2":"小さな会社では、全社員が自分の役割をきちんと果たす必要がある。","origin":"ボート競技で自分の体重分の漕力を出すことが由来。全員が自分の分だけ漕がないと船が進まないイメージ。","collocations":["pull your weight on the team","everyone must pull their weight","not pulling his weight"]},"pulled in different directions":{"example2":"The fund manager felt pulled in different directions by clients demanding both growth and safety.","exampleJa2":"そのファンドマネージャーは、成長と安全の両方を求める顧客たちから板挟みになっていると感じた。","origin":"複数の人が体を別々の方向へ物理的に引っ張り合うイメージ。相反する要求に同時に応えようとして身動きが取れない状態を表す。","collocations":["feel pulled in different directions","be pulled in two directions","pulled in opposite directions"]},"against all odds":{"example2":"Against all odds, the small brokerage survived the financial crisis and doubled its client base.","exampleJa2":"あらゆる困難にもかかわらず、その小さな証券会社は金融危機を生き延び、顧客基盤を倍増させた。","origin":"oddsは賭け事の「勝つ見込み・オッズ」。全てのオッズが不利を示す中で勝つ、というギャンブル由来の表現。","collocations":["succeed against all odds","survive against all odds","win against all odds"]},"leveraging":{"example2":"The bank is leveraging its retail network to cross-sell investment products.","exampleJa2":"その銀行はリテール網を活用して投資商品のクロスセルを行っている。","origin":"lever(てこ)+age→てこの力。金融では「レバレッジ(借入で投資効果を増幅)」。小さな力で大きな効果を得るイメージ。","collocations":["leverage technology","leverage expertise","leverage data"]},"double down":{"example2":"Despite the market correction, the fund doubled down on emerging market equities.","exampleJa2":"市場調整にもかかわらず、そのファンドは新興国株式への投資をさらに強化した。","origin":"ブラックジャックで賭け金を2倍にして勝負する「ダブルダウン」が由来。逆風でもむしろ賭け金を積み増すイメージ。","collocations":["double down on strategy","double down on investment","double down on efforts"]},"milestone":{"example2":"Surpassing one trillion yen in assets under management marked a milestone for the firm.","exampleJa2":"運用資産1兆円の突破は、その会社にとって重要な節目となった。","origin":"mile(マイル)+stone(石)。街道に1マイルごとに置かれた道標の石が原義。旅の進み具合を示す目印→重要な節目。","collocations":["reach a milestone","major milestone","milestone achievement"]},"call the shots":{"example2":"In this portfolio, the lead manager calls the shots on asset allocation.","exampleJa2":"このポートフォリオでは、リードマネージャーが資産配分の決定権を握っている。","origin":"ビリヤードで「どの球をどのポケットに入れるか宣言する」こと、または射撃の指示が由来。狙いを宣言する人=決定権者。","collocations":["call all the shots","who calls the shots","call the shots on strategy"]},"call into question":{"example2":"The sudden CEO resignation called the firm's governance into question.","exampleJa2":"CEOの突然の辞任は、その会社のガバナンスに疑問を投げかけた。","origin":"「質問(question)の場に呼び出す(call)」イメージ。当然とされていたものを尋問の場に引き出して疑いをかける表現。","collocations":["call into question the validity","call one's judgment into question","seriously call into question"]},"call for":{"example2":"Shareholders are calling for greater transparency in executive pay.","exampleJa2":"株主たちは役員報酬のさらなる透明化を求めている。","origin":"「〜を求めて声を上げる(call)」が原義。公の場で声を出して要求するイメージ。状況が「〜を必要とする」の意味もある。","collocations":["call for reform","call for action","call for a review"]},"call it a day":{"example2":"The markets are closed and the reports are done, so let's call it a day.","exampleJa2":"市場も閉まりレポートも仕上がったので、今日はここまでにしよう。","origin":"「これで一日(a day)と呼ぶことにする」→今日の仕事はもう十分やった、と区切りをつける表現。19世紀の労働者の言い回しから。","collocations":["let's call it a day","decide to call it a day","call it a day early"]},"call a meeting":{"example2":"The compliance officer called an emergency meeting after the trading error.","exampleJa2":"コンプライアンス担当役員は、取引エラーの後に緊急会議を招集した。","origin":"callの「呼び集める」という原義そのまま。人々を呼んで(call)集会を開くイメージ。convene a meetingより口語的。","collocations":["call an emergency meeting","call a board meeting","call a meeting to discuss"]},"call on":{"example2":"The regulator called on banks to strengthen their capital buffers.","exampleJa2":"規制当局は銀行に対し、資本バッファーの強化を求めた。","origin":"「〜の上に(on)声をかける(call)」→特定の相手を名指しして要請・指名するイメージ。授業で先生が生徒を当てる場面が典型。","collocations":["call on the government","call on someone to act","call on a student"]},"call off":{"example2":"The two firms called off the merger talks after due diligence.","exampleJa2":"両社はデューデリジェンスの後、合併交渉を打ち切った。","origin":"offは「離れて・中断」。猟犬を呼び戻して(call)猟を中断させたことから、予定していたものを取りやめる意味に。","collocations":["call off the deal","call off a strike","call off the search"]},"the right call":{"example2":"Reducing equity exposure before the crash proved to be the right call.","exampleJa2":"暴落前に株式の比率を下げたのは、正しい判断だったと証明された。","origin":"callはスポーツ審判の「判定」。審判の正しいジャッジ→ビジネスでの正しい決断の意味に広がった。make the callで「決断する」。","collocations":["make the right call","prove to be the right call","a tough call"]},"rebalancing":{"example2":"Quarterly rebalancing brought the portfolio back to its target weights.","exampleJa2":"四半期ごとのリバランスにより、ポートフォリオは目標比率に戻された。","origin":"re(再び)+balance(均衡)+ing。値動きで崩れた資産配分の天秤を、再び釣り合わせるイメージ。運用実務の必須用語。","collocations":["portfolio rebalancing","annual rebalancing","rebalancing strategy"]},"overweight":{"example2":"Our strategists recommend staying overweight in Japanese equities this quarter.","exampleJa2":"当社のストラテジストは、今四半期は日本株のオーバーウェイトを維持するよう推奨している。","origin":"over(超過)+weight(比重)。ベンチマークより重い配分を載せた天秤のイメージ。反対はunderweight、中立はneutral。","collocations":["overweight position","overweight in equities","go overweight"]},"keep up with":{"example2":"Smaller asset managers struggle to keep up with regulatory changes.","exampleJa2":"中小の資産運用会社は、規制の変化についていくのに苦労している。","origin":"up(遅れず高い位置に)+with(〜と共に)を保つ(keep)。並走する相手と同じ高さ・速度を維持するイメージ。","collocations":["keep up with demand","keep up with the pace","keep up with trends"]},"keep track of":{"example2":"The system helps advisors keep track of each client's risk profile.","exampleJa2":"そのシステムはアドバイザーが各顧客のリスク特性を把握するのに役立つ。","origin":"trackは「足跡・通った跡」。獲物の足跡を見失わず追い続けるハンターのイメージから、情報を追跡・把握する意味に。","collocations":["keep track of expenses","keep track of progress","lose track of time"]},"keep in mind":{"example2":"Keep in mind that past performance does not guarantee future returns.","exampleJa2":"過去の運用実績が将来のリターンを保証するものではないことを心に留めておいてください。","origin":"「心(mind)の中に保管しておく(keep)」という文字通りのイメージ。忘れずに判断材料として持ち続けることを表す。","collocations":["keep in mind that","bear in mind","keep this in mind"]},"keep at bay":{"example2":"Diversification helps keep large portfolio losses at bay.","exampleJa2":"分散投資は、ポートフォリオの大きな損失を寄せ付けないのに役立つ。","origin":"bayは猟で追い詰められた獲物が犬に向き合い吠え合う状態。犬を近づけさせず食い止める場面から「寄せ付けない」意味に。","collocations":["keep inflation at bay","keep risks at bay","hold at bay"]},"keep a close eye on":{"example2":"Investors should keep a close eye on the central bank's next move.","exampleJa2":"投資家は中央銀行の次の一手を注意深く見守るべきだ。","origin":"「目(eye)を対象の近く(close)に置き続ける(keep)」イメージ。監視カメラのように視線を離さない様子を表す定番表現。","collocations":["keep a close eye on the market","keep an eye on costs","keep a watchful eye on"]},"keep one's cool":{"example2":"A good trader keeps his cool even when the market plunges.","exampleJa2":"優れたトレーダーは市場が急落しても冷静さを保つ。","origin":"coolは「冷静さ」を表す名詞。頭が熱く(hot)ならず冷たさを保持するイメージ。lose one's cool(冷静さを失う)が対義。","collocations":["keep your cool under pressure","lose one's cool","stay cool"]},"keep things in perspective":{"example2":"During volatile markets, long-term charts help clients keep things in perspective.","exampleJa2":"市場が不安定なとき、長期チャートは顧客が物事を大局的に見るのに役立つ。","origin":"perspectiveは絵画の「遠近法」。一点だけ拡大せず、正しい距離感と比率で全体を眺めるイメージから「大局観」の意味に。","collocations":["put things in perspective","keep it in perspective","a sense of perspective"]},"keep pace with":{"example2":"Dividend growth has kept pace with the company's rising earnings.","exampleJa2":"配当の伸びは同社の利益の増加と歩調を合わせてきた。","origin":"pace(歩調・ペース)を相手と共に(with)保つ(keep)。マラソンで並走者と同じペースを維持するイメージ。","collocations":["keep pace with inflation","keep pace with change","fail to keep pace"]},"keep sight of":{"example2":"Amid short-term noise, we must keep sight of our long-term investment goals.","exampleJa2":"短期的なノイズの中でも、長期的な投資目標を見失ってはならない。","origin":"sight(視界)の中に保ち続ける(keep)イメージ。航海で目印の灯台を視界から外さない感覚。lose sight of(見失う)の反対。","collocations":["keep sight of the goal","never lose sight of","keep sight of priorities"]},"drawdown":{"example2":"Risk-averse clients often ask about the fund's maximum drawdown.","exampleJa2":"リスク回避的な顧客は、そのファンドの最大ドローダウンについてよく質問する。","origin":"draw down(引き下ろす)の名詞形。水位や資金水準が引き下げられるイメージ。運用ではピークから谷までの下落幅を指す。","collocations":["maximum drawdown","experience a drawdown","drawdown period"]},"bureaucratic":{"example2":"Opening an offshore account involves surprisingly bureaucratic paperwork.","exampleJa2":"海外口座の開設には、驚くほど官僚的な書類手続きが伴う。","origin":"仏語bureau(事務机・役所)+cratic(支配の)。「机の支配」つまりお役所仕事が原義。democratic(民衆支配)と同じ語尾。","collocations":["bureaucratic procedures","bureaucratic red tape","bureaucratic hurdles"]},"set the tone":{"example2":"The Fed chair's remarks set the tone for global markets this week.","exampleJa2":"FRB議長の発言が、今週の世界市場の方向性を決めた。","origin":"toneは音楽の「音調」。冒頭の一音が曲全体の調子を決めるように、最初の言動が全体の雰囲気を方向づけるイメージ。","collocations":["set the tone for the meeting","set a positive tone","set the tone early"]},"set a precedent":{"example2":"The regulator's approval set a precedent for future crypto ETF applications.","exampleJa2":"規制当局の承認は、今後の暗号資産ETF申請の前例となった。","origin":"precedentはpre(前に)+cede(行く)→先に行ったもの=前例。法律用語で、過去の判例が将来の判断基準になることから。","collocations":["set a dangerous precedent","set a legal precedent","break with precedent"]},"set apart":{"example2":"Consistent long-term performance sets this fund apart from its peers.","exampleJa2":"一貫した長期パフォーマンスが、このファンドを同種のファンドから際立たせている。","origin":"apart(離れた場所に)置く(set)。群衆から一人だけ離して特別な場所に立たせるイメージ。宗教語では「聖別する」の意も。","collocations":["set apart from competitors","what sets it apart","set the company apart"]},"set in motion":{"example2":"The rate cut set in motion a broad rally across asset classes.","exampleJa2":"利下げは、資産クラス全般にわたる幅広い上昇相場を始動させた。","origin":"motion(運動状態)の中に置く(set)。止まっていた機械の歯車を動かし始めるイメージ。一度動き出すと連鎖が続く含み。","collocations":["set plans in motion","set the process in motion","set events in motion"]},"set the stage for":{"example2":"Strong earnings season set the stage for a year-end rally.","exampleJa2":"好調な決算シーズンが、年末ラリーの下地を作った。","origin":"演劇で本番前に舞台(stage)を設営する(set)ことから。主役が登場する前に条件・環境を整えるイメージ。","collocations":["set the stage for growth","set the stage for negotiations","set the stage for recovery"]},"set expectations":{"example2":"Advisors should set realistic expectations about returns from the first meeting.","exampleJa2":"アドバイザーは初回面談から、リターンについて現実的な期待値を設定すべきだ。","origin":"expectationsを適切な位置にセットするイメージ。目盛りを合わせるように、相手が期待するレベルを事前に調整する表現。","collocations":["set clear expectations","set realistic expectations","manage expectations"]},"set aside":{"example2":"We advise clients to set aside six months of living expenses in cash.","exampleJa2":"私たちは顧客に、生活費6か月分を現金で確保しておくよう助言している。","origin":"aside(脇へ)置く(set)。お金や時間を本流から取り分けて別の場所に確保するイメージ。議論を「一旦脇に置く」意味でも使う。","collocations":["set aside funds","set aside time","set aside differences"]},"set up":{"example2":"She set up a trust to manage her family's assets efficiently.","exampleJa2":"彼女は一族の資産を効率的に管理するため、信託を設立した。","origin":"up(立った状態に)置く(set)。倒れていたものを立てて据え付けるイメージ。組織設立から機器設置まで幅広く使える。","collocations":["set up a company","set up a system","set up an account"]},"set a new standard":{"example2":"The firm's low-fee index funds set a new standard for the industry.","exampleJa2":"同社の低コストインデックスファンドは、業界に新しい基準を打ち立てた。","origin":"standardは中世の軍旗(基準となる旗印)が原義。新しい旗を立てて(set)、皆が目指すべき水準を示すイメージ。","collocations":["set a new standard for quality","raise the standard","industry standard"]},"materialize":{"example2":"The recession that analysts feared never materialized last year.","exampleJa2":"アナリストが恐れていた景気後退は、昨年結局現実にはならなかった。","origin":"ラテン語materia(物質)+ize(〜化する)→物質化する。目に見えない予想や計画が、形あるものとして現れるイメージ。","collocations":["fail to materialize","profits materialize","risks materialize"]},"bring to the table":{"example2":"Our firm brings decades of emerging-market expertise to the table.","exampleJa2":"当社は数十年にわたる新興国市場の専門知識を提供できる。","origin":"交渉のテーブルに自分の持ち物を並べるイメージ。会議やパートナーシップに差し出せる価値・強みを表す定番表現。","collocations":["bring value to the table","bring skills to the table","what you bring to the table"]},"bring up":{"example2":"The client brought up concerns about currency risk during the review.","exampleJa2":"その顧客は運用報告の際、為替リスクへの懸念を持ち出した。","origin":"up(表面へ)持ってくる(bring)。心の底に沈んでいた話題を水面に引き上げるイメージ。「育てる」の意味もある多義語。","collocations":["bring up an issue","bring up the subject","bring up a point"]},"bring to light":{"example2":"The internal investigation brought hidden trading losses to light.","exampleJa2":"内部調査により、隠されていた取引損失が明るみに出た。","origin":"闇の中に隠れていたものを光(light)の下へ運び出す(bring)イメージ。不正や事実の発覚を語るニュース頻出表現。","collocations":["bring the truth to light","bring problems to light","come to light"]},"bring about":{"example2":"Deregulation brought about fierce competition among online brokers.","exampleJa2":"規制緩和はネット証券間の激しい競争をもたらした。","origin":"aboutは「周囲に・実現の方へ」。物事をぐるりと回して実現の状態へ持っていくイメージ。causeよりやや硬い書き言葉。","collocations":["bring about change","bring about reform","bring about improvement"]},"bring to the fore":{"example2":"The banking turmoil brought liquidity risk to the fore.","exampleJa2":"銀行の混乱は流動性リスクを前面に浮き彫りにした。","origin":"foreは船の「前方部」(forwardと同語源)。後方に隠れていた課題を船の舳先=目立つ前面へ運ぶイメージ。","collocations":["come to the fore","bring issues to the fore","push to the fore"]},"bring in":{"example2":"The fund brought in outside consultants to review its risk models.","exampleJa2":"そのファンドはリスクモデルを見直すため、外部コンサルタントを招いた。","origin":"外から中へ(in)連れてくる(bring)。人材の招へいや制度の導入のほか、「収益を生む(bring in revenue)」の意味でも頻出。","collocations":["bring in experts","bring in revenue","bring in new rules"]},"bring down":{"example2":"Automation helped the firm bring down its operating costs sharply.","exampleJa2":"自動化により、その会社は営業費用を大幅に引き下げることができた。","origin":"down(下へ)持っていく(bring)。価格・コストを下げる意味のほか、「政権を倒す」「打ち落とす」など幅広く使う。","collocations":["bring down costs","bring down prices","bring down the government"]},"bring out the best in":{"example2":"Healthy competition among sales teams brings out the best in everyone.","exampleJa2":"営業チーム同士の健全な競争は、全員の最良の部分を引き出す。","origin":"人の内側にある最良の資質(the best)を外へ(out)引き出す(bring)イメージ。対義はbring out the worst in。","collocations":["bring out the best in people","bring out the best in a team","bring out the worst in"]},"constructive":{"example2":"The board had a constructive discussion about the dividend policy.","exampleJa2":"取締役会は配当方針について建設的な議論を行った。","origin":"ラテン語con(共に)+struere(積み上げる)→construct(建設する)。壊すのではなく積み上げる姿勢、が形容詞化した語。","collocations":["constructive feedback","constructive criticism","constructive dialogue"]},"undermining":{"example2":"Persistent inflation is undermining consumer confidence in the economy.","exampleJa2":"根強いインフレが、経済に対する消費者の信頼を蝕んでいる。","origin":"under(下を)+mine(坑道を掘る)。城壁の下にトンネルを掘って土台から崩す中世の攻城戦術が由来。じわじわ弱らせるイメージ。","collocations":["undermine confidence","undermine authority","undermine efforts"]},"empowered":{"example2":"With better financial education, clients feel empowered to invest confidently.","exampleJa2":"より良い金融教育によって、顧客は自信を持って投資できる力を得たと感じる。","origin":"em(与える)+power(力)+ed→力を与えられた。エンパワーメント(権限委譲)の形容詞形。自分で決められる状態を表す。","collocations":["feel empowered","empowered employees","empowered to decide"]},"fall through":{"example2":"The financing fell through, so the property deal was abandoned.","exampleJa2":"資金調達が不成立となり、その不動産取引は断念された。","origin":"支えを失って床を突き抜けて(through)落ちる(fall)イメージ。順調に見えた計画の底が抜けて崩れる場面で使う。","collocations":["the deal fell through","plans fell through","negotiations fell through"]},"fall apart":{"example2":"The acquisition talks fell apart over disagreements on valuation.","exampleJa2":"買収交渉は、企業価値評価をめぐる意見の相違で決裂した。","origin":"apart(ばらばらに)落ちる(fall)。接着が剥がれて部品が散らばるイメージ。組織・計画・精神状態の崩壊まで幅広く使う。","collocations":["the deal fell apart","fall apart at the seams","everything fell apart"]},"fall behind":{"example2":"The company fell behind its rivals in adopting digital banking.","exampleJa2":"その会社はデジタルバンキングの導入で競合他社に遅れをとった。","origin":"behind(後方に)落ちる(fall)。マラソンで集団から脱落して後ろに下がるイメージ。支払いの延滞にもよく使う。","collocations":["fall behind schedule","fall behind on payments","fall behind competitors"]},"fall into place":{"example2":"After months of planning, the fund launch finally fell into place.","exampleJa2":"数か月の準備を経て、ファンドの立ち上げはついにすべてうまく収まった。","origin":"パズルのピースがあるべき場所(place)に自然に落ちて(fall)はまるイメージ。バラバラだった要素が一気に整う場面で使う。","collocations":["everything fell into place","the pieces fell into place","things fall into place"]},"fall short of":{"example2":"Quarterly revenue fell short of analysts' expectations.","exampleJa2":"四半期売上高はアナリストの予想に届かなかった。","origin":"shortは「距離が足りない」。矢が的の手前に落ちる(fall)イメージ。目標や基準との差を語る決算報道の頻出表現。","collocations":["fall short of expectations","fall short of the target","fall short of requirements"]},"fall prey to":{"example2":"Retail investors sometimes fall prey to high-pressure sales tactics.","exampleJa2":"個人投資家は時に、強引な販売手法の餌食になることがある。","origin":"preyは「捕食される獲物」。捕食者の前に落ちて(fall)獲物になるイメージ。詐欺や誘惑の被害者になる場面で使う。","collocations":["fall prey to scams","fall prey to temptation","fall prey to fraud"]},"fall into one's lap":{"example2":"A major client account fell into her lap when a colleague retired.","exampleJa2":"同僚の退職により、大口顧客の担当が彼女のもとに思いがけず転がり込んだ。","origin":"lapは座った時の「膝の上」。木の実が努力なしに膝の上へ落ちてくるイメージ。棚からぼた餅に近い感覚の表現。","collocations":["fall into your lap","opportunities fall into one's lap","land in one's lap"]},"fall into a pattern":{"example2":"The market has fallen into a pattern of rallying after each Fed meeting.","exampleJa2":"市場はFOMCのたびに上昇するというパターンにはまっている。","origin":"pattern(型)の中に落ち込む(fall)イメージ。意識せぬまま同じ行動の溝にはまり、繰り返してしまう様子を表す。","collocations":["fall into a familiar pattern","fall into a routine","fall into bad habits"]},"acquisition":{"example2":"The bank announced the acquisition of a fintech startup to expand digitally.","exampleJa2":"その銀行はデジタル展開を拡大するため、フィンテック企業の買収を発表した。","origin":"ラテン語ad(〜へ)+quaerere(求める)→獲得。M&AのAはこの語。求めて手に入れる行為全般から、企業買収の意味に特化。","collocations":["mergers and acquisitions","complete an acquisition","acquisition target"]},"organic growth":{"example2":"Analysts praised the insurer's steady organic growth in premium income.","exampleJa2":"アナリストたちは、その保険会社の保険料収入の着実な自力成長を高く評価した。","origin":"organicは「有機的な・生物本来の」。買収という外科手術ではなく、植物が自ら育つように内部から成長するイメージ。","collocations":["achieve organic growth","organic revenue growth","organic growth strategy"]},"go through the motions":{"example2":"He attended the training but was clearly just going through the motions.","exampleJa2":"彼は研修に出席したが、明らかに形だけこなしているだけだった。","origin":"motions(動作)だけを通過する(go through)イメージ。魂の入っていない振り付けだけの踊りのように、中身なく形式をなぞる表現。","collocations":["just going through the motions","merely go through the motions","go through the motions at work"]},"go along with":{"example2":"The board went along with the CEO's plan despite some reservations.","exampleJa2":"取締役会は多少の留保はありつつも、CEOの計画に同意した。","origin":"along(沿って)相手と共に(with)進む(go)。相手の敷いた道に並んで歩くイメージ。積極的賛成より「異を唱えず従う」ニュアンス。","collocations":["go along with the plan","go along with the decision","reluctantly go along with"]},"go without saying":{"example2":"It goes without saying that diversification reduces portfolio risk.","exampleJa2":"分散投資がポートフォリオのリスクを減らすことは言うまでもない。","origin":"仏語の慣用句cela va sans dire(それは言わずに済む)の直訳借用。「言葉にしなくても通じるほど当然」というイメージ。","collocations":["it goes without saying that","needless to say","that goes without saying"]},"go over":{"example2":"Before signing, let's go over the fee structure one more time.","exampleJa2":"署名の前に、手数料体系をもう一度確認しましょう。","origin":"over(上を端から端まで)進む(go)。書類の上を目でなぞって全体を点検するイメージ。reviewの口語版として頻出。","collocations":["go over the details","go over the report","go over the numbers"]},"go through":{"example2":"The industry went through a painful consolidation after the crisis.","exampleJa2":"その業界は危機の後、痛みを伴う再編を経験した。","origin":"through(中を通り抜けて)進む(go)。トンネルの中を通過するイメージから、困難な経験をくぐり抜ける意味に。書類を「検討する」意味も。","collocations":["go through a difficult time","go through changes","go through the process"]},"go the extra mile":{"example2":"Our advisors go the extra mile to explain products in plain language.","exampleJa2":"当社のアドバイザーは、商品を平易な言葉で説明するために期待以上の努力をする。","origin":"聖書の「1マイル行けと強いられたら2マイル行け」(マタイ5章)が由来。求められた距離より1マイル余分に歩くイメージ。","collocations":["go the extra mile for clients","willing to go the extra mile","always go the extra mile"]},"go out of one's way":{"example2":"The branch manager went out of his way to resolve the client's complaint.","exampleJa2":"支店長はその顧客の苦情を解決するため、わざわざ骨を折った。","origin":"自分の通り道(one's way)から外れて(out of)まで行動するイメージ。本来の道順を曲げてでも手を貸す親切さを表す。","collocations":["go out of one's way to help","go out of your way for someone","went out of their way"]},"go about":{"example2":"How should new investors go about building a balanced portfolio?","exampleJa2":"初心者投資家はバランスの取れたポートフォリオ構築にどう取り組むべきだろうか。","origin":"aboutは「あちこち動き回って」。仕事の周りを動き回りながら着手するイメージ。go about doingの形で「取り組み方」を語る。","collocations":["go about the task","go about it the right way","go about one's business"]},"go above and beyond":{"example2":"The team went above and beyond to deliver the report ahead of schedule.","exampleJa2":"チームは予定より早くレポートを納品するため、期待を超える働きをした。","origin":"above(上へ)もbeyond(限界の先へ)も超えるイメージ。職務の要求ライン(the call of duty)を二重に超える軍の表彰文句が由来。","collocations":["go above and beyond expectations","go above and beyond the call of duty","above and beyond for customers"]},"go unnoticed":{"example2":"Small fee increases often go unnoticed by retail investors.","exampleJa2":"小さな手数料の引き上げは、個人投資家に気づかれないことが多い。","origin":"go+形容詞で「〜の状態のまま進む」。un(否定)+noticed(気づかれた)→誰にも気づかれない状態のまま過ぎていくイメージ。","collocations":["go unnoticed by many","not go unnoticed","largely go unnoticed"]},"cutting corners":{"example2":"Auditors warned that cutting corners on compliance could cost millions.","exampleJa2":"監査人は、コンプライアンスで手を抜けば数百万ドルの損失になりかねないと警告した。","origin":"道の角(corner)を曲がらず斜めに突っ切る(cut)ショートカットが由来。正規の手順を省いて楽をするイメージ。","collocations":["cut corners on quality","cut corners to save money","no cutting corners"]},"thoroughness":{"example2":"The due diligence was praised for its thoroughness and attention to detail.","exampleJa2":"そのデューデリジェンスは、徹底ぶりと細部への注意で高く評価された。","origin":"thoroughはthrough(通り抜けて)と同語源。端から端まで貫き通す→隅々まで漏れなく行う性質、が名詞化した語。","collocations":["thoroughness of the review","with great thoroughness","speed and thoroughness"]},"stand out":{"example2":"Among hundreds of funds, only a few stand out for consistent returns.","exampleJa2":"数百のファンドの中で、安定したリターンで際立つものはごくわずかだ。","origin":"out(外へ)立つ(stand)。平らな面から一つだけ突き出して立っているイメージ。目立って優れている場面で使う。","collocations":["stand out from the crowd","stand out among competitors","make it stand out"]},"stand for":{"example2":"The letters ESG stand for environmental, social, and governance.","exampleJa2":"ESGという文字は環境・社会・ガバナンスを表している。","origin":"「〜の代わりに(for)立つ(stand)」→象徴・代表する。略語の意味説明と「主義を掲げる」の両方で使う。won't stand forは「許さない」。","collocations":["stand for quality","what the letters stand for","stand for one's principles"]},"stand corrected":{"example2":"I said the fund launched in 2010, but I stand corrected—it was 2008.","exampleJa2":"ファンドの設定は2010年と言いましたが、訂正します。2008年でした。","origin":"「訂正された(corrected)状態で立つ(stand)」→誤りを指摘され、それを受け入れた立場に立つ。潔く非を認めるフォーマルな表現。","collocations":["I stand corrected","happy to stand corrected","stand corrected on that point"]},"stand a chance":{"example2":"Without a clear differentiator, new funds barely stand a chance in this market.","exampleJa2":"明確な差別化要因がなければ、新しいファンドはこの市場でほとんど勝ち目がない。","origin":"chance(勝機)を持って立っている(stand)イメージ。主に否定文で「勝ち目がない」と使う。standは「〜の状態にある」の古い用法。","collocations":["stand a chance of winning","not stand a chance","stand a good chance"]},"stand one's ground":{"example2":"Despite pushback from the board, the CFO stood her ground on the forecast.","exampleJa2":"取締役会からの反発にもかかわらず、CFOは業績予想について自分の立場を貫いた。","origin":"戦場で自分の陣地(ground)から退かず立ち続ける(stand)軍事表現が由来。攻められても一歩も引かないイメージ。","collocations":["stand your ground","stood his ground","hold one's ground"]},"stand by":{"example2":"The firm stood by its earnings guidance despite market skepticism.","exampleJa2":"市場の懐疑的な見方にもかかわらず、その会社は業績見通しを堅持した。","origin":"「そば(by)に立つ(stand)」が原義。そばで見ているだけ=傍観と、そばに立ち続ける=支持、の両義に分かれた。待機(standby)も同源。","collocations":["stand by a decision","stand by one's word","stand by and watch"]},"stand the test of time":{"example2":"Value investing principles have stood the test of time for nearly a century.","exampleJa2":"バリュー投資の原則は、およそ1世紀にわたり時の試練に耐えてきた。","origin":"「時間(time)という試験(test)に耐えて立ち続ける(stand)」イメージ。standには「持ちこたえる」の意味がある。","collocations":["stand the test of time","has stood the test of time","designs that stand the test of time"]},"stand behind":{"example2":"The asset manager stands behind its research with full transparency.","exampleJa2":"その運用会社は、完全な透明性をもって自社のリサーチを保証している。","origin":"「後ろ(behind)に立つ(stand)」→後ろ盾になるイメージ。人や製品の背後に控えて、責任を持って支える様子を表す。","collocations":["stand behind the product","stand behind our work","stand behind a decision"]},"stand apart":{"example2":"Its disciplined risk management makes the fund stand apart in a crowded field.","exampleJa2":"規律あるリスク管理により、そのファンドは激戦区の中で一線を画している。","origin":"apart(離れて)立つ(stand)。群衆から距離を置いて独り立つイメージ。stand outより「別格・独自路線」の含みが強い。","collocations":["stand apart from the competition","stand apart from peers","stand apart from the rest"]},"poach":{"example2":"The hedge fund poached two senior traders from a rival bank.","exampleJa2":"そのヘッジファンドはライバル銀行からシニアトレーダー2名を引き抜いた。","origin":"原義は「他人の土地で密猟する」。他社という猟場から人材や顧客をこっそり奪うイメージ。卵のポーチ(茹でる)は別語源。","collocations":["poach employees","poach clients","poach talent from rivals"]},"convictions":{"example2":"The portfolio reflects the manager's strongest convictions about future growth sectors.","exampleJa2":"そのポートフォリオには、将来の成長セクターに対する運用者の強い信念が反映されている。","origin":"ラテン語con(完全に)+vincere(打ち負かす)→議論で完全に納得させられた状態=確信。「有罪判決」の意味も同語源。","collocations":["deep convictions","act on one's convictions","high-conviction ideas"]},"work out":{"example2":"The joint venture didn't work out, so both firms went separate ways.","exampleJa2":"その合弁事業はうまくいかず、両社は別々の道を歩むことになった。","origin":"outは「最後まで・結果が出るまで」。問題を最後まで処理して答えが出るイメージ。「計算する」「運動する」の意味も同じ発想。","collocations":["work out well","work out a solution","things will work out"]},"work around":{"example2":"The team worked around the budget freeze by reallocating existing resources.","exampleJa2":"チームは既存リソースを再配分することで、予算凍結を回避した。","origin":"障害物の周り(around)を迂回して作業する(work)イメージ。IT用語workaround(回避策)としても定着している。","collocations":["work around the problem","work around the limitations","find a workaround"]},"work up to":{"example2":"New savers can start with small amounts and work up to larger monthly investments.","exampleJa2":"貯蓄初心者は少額から始めて、徐々に毎月の投資額を増やしていけばよい。","origin":"up(上へ)向かって段階的に働きかける(work)イメージ。階段を一段ずつ登って目標水準に到達する感覚。","collocations":["work up to a goal","work your way up to","gradually work up to"]},"work wonders":{"example2":"Compound interest works wonders for investors who start early.","exampleJa2":"複利は早く始めた投資家に驚くほどの効果をもたらす。","origin":"wonders(奇跡)を成し遂げる(work)。workの古い用法「(奇跡などを)行う」から。魔法のように劇的な効果を生むイメージ。","collocations":["work wonders for","can work wonders","do wonders"]},"work up the courage":{"example2":"He finally worked up the courage to ask his boss for a raise.","exampleJa2":"彼はついに勇気を奮い起こして、上司に昇給を願い出た。","origin":"work upは「徐々に作り上げる」。ポンプで水を汲み上げるように、時間をかけて勇気を心の中に溜めていくイメージ。","collocations":["work up the courage to speak","work up the nerve","finally worked up the courage"]},"work through":{"example2":"The bank is still working through the bad loans on its balance sheet.","exampleJa2":"その銀行はいまだにバランスシート上の不良債権の処理を進めている。","origin":"through(通り抜けて)作業する(work)。山積みの問題をトンネルを掘るように一つずつ片付けて突破するイメージ。","collocations":["work through the issues","work through the backlog","work through difficulties"]},"work in one's favor":{"example2":"A weaker yen worked in the exporters' favor last quarter.","exampleJa2":"前四半期は円安が輸出企業に有利に働いた。","origin":"favorは「好意・有利」。状況が自分の利益の方向(in one's favor)に作用する(work)イメージ。裁判・スポーツの判定でも使う。","collocations":["work in your favor","the odds work in one's favor","turn things in one's favor"]},"work at":{"example2":"Building client trust takes years, and you have to work at it every day.","exampleJa2":"顧客の信頼を築くには何年もかかり、毎日それに取り組み続けなければならない。","origin":"atは「一点に向かって」。対象に狙いを定めて継続的に努力を注ぐイメージ。work onより「粘り強く続ける」含みが強い。","collocations":["work at it","keep working at","work hard at"]},"went sideways":{"example2":"The system migration went sideways, delaying trades for two days.","exampleJa2":"システム移行が想定外の事態となり、取引が2日間遅延した。","origin":"前進(forward)でも成功でもなく「横(sideways)へ逸れた」イメージ。相場用語では「横ばい」の意味もあり文脈で判断。","collocations":["the deal went sideways","things went sideways","the project went sideways"]},"rollout":{"example2":"The nationwide rollout of the new payment app begins next month.","exampleJa2":"新しい決済アプリの全国展開は来月から始まる。","origin":"roll out(巻物や絨毯を転がして広げる)の名詞形。新製品を絨毯を広げるように段階的に世に出すイメージ。","collocations":["product rollout","phased rollout","nationwide rollout"]},"collaborative":{"example2":"The research report was a collaborative effort between the two teams.","exampleJa2":"そのリサーチレポートは、2つのチームによる共同作業の成果だった。","origin":"ラテン語col(共に)+laborare(働く)→共に労働する。labor(労働)が語幹。コラボレーションの形容詞形。","collocations":["collaborative effort","collaborative approach","collaborative environment"]},"draw on":{"example2":"In volatile markets, veteran managers draw on decades of experience.","exampleJa2":"不安定な相場では、ベテランの運用者は数十年の経験を頼りにする。","origin":"onは「源に接して」。井戸から水を引く(draw)ように、蓄えた知識や経験という源泉から必要なものを汲み出すイメージ。","collocations":["draw on experience","draw on resources","draw on expertise"]},"draw conclusions":{"example2":"Analysts warned against drawing conclusions from a single quarter's results.","exampleJa2":"アナリストたちは、一四半期の結果だけから結論を導くことに警鐘を鳴らした。","origin":"drawは「引き出す」。散らばった証拠の中から結論という糸を引き出すイメージ。draw(描く)ではなく「引く」の意味。","collocations":["draw conclusions from data","jump to conclusions","draw the wrong conclusions"]},"draw attention to":{"example2":"The prospectus draws attention to the fund's currency hedging costs.","exampleJa2":"目論見書はそのファンドの為替ヘッジコストに注意を向けさせている。","origin":"人々の注意(attention)を対象へ引き寄せる(draw)イメージ。磁石が鉄を引きつけるように視線を集める表現。","collocations":["draw attention to the issue","draw public attention","draw attention away from"]},"draw the line":{"example2":"We accept aggressive growth targets, but we draw the line at misleading clients.","exampleJa2":"積極的な成長目標は受け入れるが、顧客を誤解させることには一線を引く。","origin":"地面に線を引いて「ここから先は越えるな」と示すイメージ。テニスコートの境界線説もある。draw the line atで頻出。","collocations":["draw the line at","know where to draw the line","draw a fine line"]},"draw out":{"example2":"Skilled interviewers draw out insights that clients didn't know they had.","exampleJa2":"熟練したインタビュアーは、顧客自身も気づいていなかった洞察を引き出す。","origin":"out(外へ)引き出す(draw)。内側に隠れているものを外へ引っ張り出すイメージ。「長引かせる(drawn-out)」の意味もある。","collocations":["draw out ideas","draw out the truth","draw out a shy person"]},"draw a clear picture":{"example2":"The quarterly report draws a clear picture of the fund's risk exposures.","exampleJa2":"四半期レポートはそのファンドのリスクエクスポージャーの全体像を明確に示している。","origin":"ここのdrawは「描く」。複雑な情報を一枚の分かりやすい絵(picture)として描き出すイメージ。paint a pictureも同義。","collocations":["draw a clear picture of","paint a clear picture","give a clear picture"]},"draw up":{"example2":"The committee drew up new guidelines for responsible investment.","exampleJa2":"委員会は責任投資に関する新しいガイドラインを起草した。","origin":"upは「完成へ向けて」。文書を引き上げて仕上げるイメージ。契約書・計画・リストなどを正式に作成する場面で使う。","collocations":["draw up a contract","draw up a plan","draw up a list"]},"draw a contrast":{"example2":"The CEO drew a sharp contrast between short-term traders and long-term investors.","exampleJa2":"CEOは短期トレーダーと長期投資家との対比を鮮明に描き出した。","origin":"contrast(対比)を線で描き出す(draw)イメージ。2つのものの間に境界線を引いて違いをくっきり見せる表現。","collocations":["draw a sharp contrast","draw a contrast between","in stark contrast"]},"draw in":{"example2":"Low fees and easy apps are drawing in a new generation of investors.","exampleJa2":"低い手数料と使いやすいアプリが、新しい世代の投資家を引きつけている。","origin":"in(中へ)引き込む(draw)。網で魚を引き寄せるように、人を輪の中へ引き入れるイメージ。巻き込む(get drawn in)の形も頻出。","collocations":["draw in customers","draw in new investors","get drawn in"]},"turbulent":{"example2":"Fund managers stayed defensive during the turbulent trading sessions last week.","exampleJa2":"ファンドマネージャーは先週の荒れた取引セッションの間、守りの姿勢を保った。","origin":"ラテン語turba(騒ぎ・群衆)が語源。turbulentus(かき乱された)→渦巻くように乱れた状態。disturbやturbineも同語源。","collocations":["turbulent times","turbulent market","turbulent period"]},"behavioral finance":{"example2":"Our seminar uses behavioral finance to help clients avoid panic selling.","exampleJa2":"当社のセミナーでは、顧客が狼狽売りを避けられるよう行動ファイナンスを活用している。","origin":"behavior(行動)+finance(金融)。人間は合理的という従来理論への反証として、心理学を金融に持ち込んだ分野。","collocations":["behavioral finance theory","apply behavioral finance","behavioral finance research"]},"client retention":{"example2":"Regular portfolio reviews significantly boosted our client retention rate.","exampleJa2":"定期的なポートフォリオレビューが顧客維持率を大幅に高めた。","origin":"retentionはラテン語re(後ろに)+tenere(保つ)→引き留めておくこと。retain(保持する)の名詞形と覚える。","collocations":["client retention rate","improve client retention","client retention strategy"]},"lay the groundwork":{"example2":"The two banks laid the groundwork for a merger through informal talks.","exampleJa2":"両行は非公式協議を通じて合併への基盤を築いた。","origin":"groundwork＝建物の基礎工事。土台を「置く(lay)」イメージで、本格的な仕事の前の下準備を指す。","collocations":["lay the groundwork for","carefully lay the groundwork","groundwork for success"]},"lie ahead":{"example2":"Analysts warn that tougher regulatory hurdles lie ahead for the industry.","exampleJa2":"アナリストは、業界にはより厳しい規制のハードルが待ち受けていると警告する。","origin":"道の先(ahead)に横たわる(lie)イメージ。未来の道の途中に課題や機会が置かれている絵で覚える。","collocations":["challenges lie ahead","what lies ahead","difficulties lie ahead"]},"lay off":{"example2":"The investment bank laid off a third of its trading desk.","exampleJa2":"その投資銀行はトレーディング部門の3分の1を解雇した。","origin":"仕事から人を「脇に置く(lay off)」イメージ。本来は一時帰休の意味で、景気回復後の再雇用を含意した。","collocations":["lay off workers","lay off staff","be laid off"]},"lie low":{"example2":"The fund manager decided to lie low until the media attention faded.","exampleJa2":"そのファンドマネージャーはメディアの注目が薄れるまで目立たないようにすることにした。","origin":"低い姿勢で横たわる(lie low)→敵に見つからないよう身をかがめるイメージ。嵐が過ぎるのを待つ場面で使う。","collocations":["lie low for a while","decide to lie low","lie low until"]},"lay out":{"example2":"The CFO laid out a five-year plan to reduce debt.","exampleJa2":"CFOは負債削減の5カ年計画を提示した。","origin":"物を広げて並べ「置く(lay out)」イメージ。計画や案をテーブルに広げて見せる→詳しく説明する、と覚える。","collocations":["lay out a plan","lay out the details","lay out a strategy"]},"lay bare":{"example2":"The audit laid bare serious weaknesses in the bank's risk controls.","exampleJa2":"監査はその銀行のリスク管理体制の深刻な弱点をさらけ出した。","origin":"bare(むき出しの)状態に「置く(lay)」→覆いを剥がして中身を露出させるイメージ。隠れた実態の暴露に使う。","collocations":["lay bare the truth","lay bare the problems","laid bare by the crisis"]},"lies in":{"example2":"The appeal of index funds lies in their low costs.","exampleJa2":"インデックスファンドの魅力は低コストにある。","origin":"答えや本質がその場所に「横たわっている(lie in)」イメージ。The key lies in...の形で頻出。","collocations":["the answer lies in","the key lies in","the problem lies in"]},"lay down":{"example2":"The new regulation lays down strict capital requirements for banks.","exampleJa2":"新しい規制は銀行に厳格な自己資本要件を定めている。","origin":"ルールを紙に書いて「下に置く(lay down)」→公式に定めるイメージ。石板に刻んだ掟を据える絵で覚える。","collocations":["lay down rules","lay down the law","lay down principles"]},"paying dividends":{"example2":"Years of client relationship building are finally paying dividends.","exampleJa2":"長年の顧客関係づくりがついに成果を上げている。","origin":"dividend(配当)を払う→投資した株が配当を生むように、過去の努力が利益として返ってくる比喩表現。","collocations":["pay dividends in the long run","start paying dividends","pay big dividends"]},"restructuring":{"example2":"The debt restructuring gave the issuer three more years to repay.","exampleJa2":"債務再編により、発行体の返済期限は3年延長された。","origin":"re(再び)+structure(構造)+ing→組織や債務の構造を組み直すこと。ラテン語struere(築く)が語根。","collocations":["corporate restructuring","debt restructuring","undergo restructuring"]},"transition":{"example2":"The fund is managing the transition from active to passive strategies.","exampleJa2":"そのファンドはアクティブ運用からパッシブ運用への移行を進めている。","origin":"ラテン語trans(越えて)+ire(行く)→一方から他方へ渡って行くこと。transit(輸送)やtransfer(移転)と同語源。","collocations":["smooth transition","energy transition","transition period"]},"reap what you sow":{"example2":"Skipping due diligence means you will reap what you sow.","exampleJa2":"デューデリジェンスを怠れば、蒔いた種を自分で刈り取ることになる。","origin":"sow(種を蒔く)→reap(刈り取る)。聖書由来の農耕比喩で、良くも悪くも行動の結果は自分に返るという教訓。","collocations":["you reap what you sow","reap the rewards","sow the seeds"]},"inflow":{"example2":"Strong inflows into money market funds continued as rates stayed high.","exampleJa2":"金利が高止まりする中、MMFへの力強い資金流入が続いた。","origin":"in(中へ)+flow(流れ)→中へ流れ込むこと。対義語はoutflow(流出)。資金の川の流れをイメージすると覚えやすい。","collocations":["capital inflows","record inflows","fund inflows"]},"tax efficiency":{"example2":"We restructured the client's holdings to improve tax efficiency.","exampleJa2":"税効率を高めるため、顧客の保有資産を組み替えた。","origin":"efficiencyはラテン語ex(外へ)+facere(作る)→無駄なく成果を生む力。税負担を最小化して手取りを最大化する概念。","collocations":["improve tax efficiency","tax-efficient investing","maximize tax efficiency"]},"market inefficiency":{"example2":"Small-cap stocks often exhibit market inefficiencies that skilled analysts exploit.","exampleJa2":"小型株には熟練アナリストが利用できる市場の非効率性がしばしば存在する。","origin":"in(否定)+efficiency(効率)→価格に情報が反映されきらない状態。効率的市場仮説の逆で、アルファの源泉。","collocations":["exploit market inefficiencies","identify market inefficiencies","persistent market inefficiency"]},"high-yield bond":{"example2":"The portfolio allocates 15% to high-yield bonds for extra income.","exampleJa2":"そのポートフォリオは追加収益のためハイイールド債に15%配分している。","origin":"high(高い)+yield(利回り)の債券。信用力が低い分、高利回りで報いる。別名junk bond(ジャンク債)。","collocations":["high-yield bond market","high-yield bond fund","invest in high-yield bonds"]},"smart beta":{"example2":"Many pension plans now allocate to smart beta strategies for cost-effective factor exposure.","exampleJa2":"多くの年金基金は今や、低コストでファクターに投資するためスマートベータ戦略に配分している。","origin":"beta(市場連動リターン)を賢く(smart)改良する意。時価総額比率ではなく、割安度などのルールで指数を組む発想。","collocations":["smart beta ETF","smart beta strategy","smart beta fund"]},"systematic exposure":{"example2":"The ETF offers systematic exposure to emerging market currencies.","exampleJa2":"そのETFは新興国通貨へのシステマティックなエクスポージャーを提供する。","origin":"ギリシャ語systema(組み合わされた全体)＋exposure(さらすこと)。ルールに基づき特定リスクに身をさらす配分。","collocations":["systematic exposure to factors","gain systematic exposure","provide systematic exposure"]},"risk tolerance":{"example2":"We assess each client's risk tolerance before recommending any fund.","exampleJa2":"当社はファンドを提案する前に、各顧客のリスク許容度を評価する。","origin":"toleranceはラテン語tolerare(耐える)から。損失の揺れにどこまで耐えられるかという投資家の器の大きさ。","collocations":["assess risk tolerance","low risk tolerance","risk tolerance questionnaire"]},"capital deployment":{"example2":"The board approved a disciplined capital deployment plan for next year.","exampleJa2":"取締役会は来年度の規律ある資本配分計画を承認した。","origin":"deployはラテン語dis(広げる)+plicare(折る)→折り畳んだものを展開する。軍隊の展開から資金の投入へ転用。","collocations":["capital deployment strategy","efficient capital deployment","accelerate capital deployment"]},"credit rating":{"example2":"A strong credit rating lets the firm borrow at lower cost.","exampleJa2":"高い信用格付けにより、その企業は低コストで借り入れができる。","origin":"creditはラテン語credere(信じる)から。返済を信じられる度合いをAAA〜Dの記号で格付け(rating)したもの。","collocations":["credit rating agency","credit rating downgrade","maintain a credit rating"]},"issuer":{"example2":"Investors compare issuers carefully before buying corporate debt.","exampleJa2":"投資家は社債を買う前に発行体を慎重に比較する。","origin":"issueはラテン語exire(外へ出る)が語源。証券を市場へ「出す」主体がissuer(発行体)。-erは行為者を表す接尾辞。","collocations":["bond issuer","corporate issuer","sovereign issuer"]},"investment grade":{"example2":"The insurer's mandate limits purchases to investment grade securities only.","exampleJa2":"その保険会社の運用方針では、購入は投資適格証券のみに限定されている。","origin":"投資(investment)に値する等級(grade)の意。gradeはラテン語gradus(段階)から。BBB-以上が目安のライン。","collocations":["investment grade bonds","investment grade rating","below investment grade"]},"speculative grade":{"example2":"The downgrade pushed the airline's debt into speculative grade territory.","exampleJa2":"格下げにより、その航空会社の債務は投機的等級の水準に転落した。","origin":"speculateはラテン語specere(見る)から→先を見て賭けること。投資ではなく投機と見なされる格付け帯。","collocations":["speculative grade debt","speculative grade issuer","fall to speculative grade"]},"credit spread":{"example2":"Narrow credit spreads suggest investors are complacent about default risk.","exampleJa2":"信用スプレッドの縮小は、投資家がデフォルトリスクに楽観的であることを示唆する。","origin":"spreadは「広がり・開き」。国債利回りとの利回り差＝信用リスクの値段。開けば警戒、縮めば楽観のサイン。","collocations":["credit spreads widen","credit spreads tighten","narrow credit spreads"]},"basis point":{"example2":"The central bank raised rates by twenty-five basis points.","exampleJa2":"中央銀行は政策金利を25ベーシスポイント引き上げた。","origin":"basis(基準)となる小さな点(point)の意。1bp=0.01%。利回り差を明確に語るため金融界が作った単位。","collocations":["raise rates by 25 basis points","a few basis points","basis point move"]},"refinancing":{"example2":"Many issuers rushed refinancing before the rate hike took effect.","exampleJa2":"多くの発行体は利上げが実施される前に借り換えを急いだ。","origin":"re(再び)+financing(資金調達)→古い借金を新しい借金で置き換えること。住宅ローンの借り換えが身近な例。","collocations":["refinancing risk","mortgage refinancing","refinancing costs"]},"issuer-pays model":{"example2":"Critics argue the issuer-pays model inflated ratings before the financial crisis.","exampleJa2":"批判者は、発行体支払いモデルが金融危機前に格付けを甘くしたと主張する。","origin":"issuer(発行体)がpay(支払う)model(仕組み)。採点される側が採点者に報酬を払う構図で、利益相反の典型例。","collocations":["issuer-pays model conflicts","criticism of the issuer-pays model","under the issuer-pays model"]},"interest coverage ratio":{"example2":"Analysts flagged the retailer's declining interest coverage ratio as a warning.","exampleJa2":"アナリストはその小売企業のインタレスト・カバレッジ・レシオの低下を警戒信号として指摘した。","origin":"利息(interest)を利益でどれだけ覆える(cover)かの比率(ratio)。傘で雨を覆うイメージで、大きいほど安全。","collocations":["low interest coverage ratio","calculate the interest coverage ratio","interest coverage ratio of five times"]},"leverage multiple":{"example2":"Lenders refused to fund deals with leverage multiples above seven.","exampleJa2":"貸し手はレバレッジ倍率が7倍を超える案件への融資を拒否した。","origin":"leverはてこ(lever)の意→借金をてこに投資を増幅する。EBITDAの何倍(multiple)の負債かで安全度を測る。","collocations":["high leverage multiple","leverage multiple of six times","reduce the leverage multiple"]},"default probability":{"example2":"Credit models revise default probabilities as economic conditions deteriorate.","exampleJa2":"信用モデルは経済状況の悪化に応じてデフォルト確率を修正する。","origin":"defaultはラテン語de(離れて)+fallere(欺く・怠る)→義務の不履行。その起こりやすさ(probability)を数値化。","collocations":["estimate default probability","rising default probability","low default probability"]},"venture capital":{"example2":"Venture capital firms compete fiercely for promising AI startups.","exampleJa2":"ベンチャーキャピタル各社は有望なAIスタートアップを激しく奪い合っている。","origin":"ventureはadventure(冒険)と同語源のラテン語venire(来る)から。冒険的な事業に賭ける資本(capital)。","collocations":["venture capital firm","raise venture capital","venture capital funding"]},"seed funding":{"example2":"Seed funding allowed the founders to build a working prototype.","exampleJa2":"シード資金のおかげで、創業者たちは動くプロトタイプを作ることができた。","origin":"seed(種)＋funding(資金)。事業という植物の種を蒔く段階のお金。発芽前の最初期投資という農業の比喩。","collocations":["raise seed funding","seed funding round","secure seed funding"]},"exit":{"example2":"The private equity firm is exploring exit options for its oldest holding.","exampleJa2":"そのPE会社は最も古い保有先のイグジット手段を検討している。","origin":"ラテン語ex(外へ)+ire(行く)→外へ出ること。投資から「出口」を通って利益と共に退出するイメージ。","collocations":["exit strategy","successful exit","exit through an IPO"]},"initial public offering":{"example2":"The fintech firm postponed its initial public offering due to market volatility.","exampleJa2":"そのフィンテック企業は市場のボラティリティを理由に新規株式公開を延期した。","origin":"initial(最初の)+public(公衆への)+offering(売り出し)。株式を初めて一般に提供すること。略称IPO。","collocations":["launch an initial public offering","initial public offering price","file for an initial public offering"]},"total addressable market":{"example2":"Investors questioned whether the total addressable market justified the valuation.","exampleJa2":"投資家は、獲得可能な最大市場規模がそのバリュエーションを正当化するのか疑問視した。","origin":"address(狙いを定める)可能な市場全体の意。シェア100%なら得られる売上の天井。VCの定番指標、略称TAM。","collocations":["estimate the total addressable market","expand the total addressable market","a large total addressable market"]},"defensibility":{"example2":"Network effects give the platform strong defensibility against new entrants.","exampleJa2":"ネットワーク効果により、そのプラットフォームは新規参入者に対する強い防御力を持つ。","origin":"ラテン語defendere(打ち払う・守る)+ibility(可能性)→守り切れる度合い。城の堀(moat)の比喩と併用される。","collocations":["business defensibility","strengthen defensibility","lack of defensibility"]},"equity stake":{"example2":"The bank sold its equity stake in the joint venture for $400 million.","exampleJa2":"その銀行は合弁事業の持分を4億ドルで売却した。","origin":"stakeは元々「杭」。杭を打って土地の権利を主張したことから「利害・出資分」の意味に発展した。","collocations":["acquire an equity stake","minority equity stake","sell an equity stake"]},"board representation":{"example2":"The activist investor demanded board representation after acquiring 8% of shares.","exampleJa2":"そのアクティビスト投資家は株式の8%を取得した後、取締役会への参画を要求した。","origin":"boardは会議の「板張りテーブル」が原義→取締役会。そこに代表(representation)を送り込む権利のこと。","collocations":["demand board representation","gain board representation","board representation rights"]},"power-law distribution":{"example2":"Startup outcomes follow a power-law distribution, so one winner funds the portfolio.","exampleJa2":"スタートアップの成果はべき乗分布に従うため、一つの当たりがポートフォリオ全体を賄う。","origin":"power(累乗)の法則に従う分布。ごく少数が全体の大半を占める偏り。8割は2割が生むパレートの法則の親戚。","collocations":["follow a power-law distribution","power-law returns","power-law dynamics"]},"strategic acquisition":{"example2":"The strategic acquisition gave the insurer instant access to Asian markets.","exampleJa2":"その戦略的買収により、保険会社はアジア市場への足がかりを即座に得た。","origin":"acquisitionはラテン語ad(〜へ)+quaerere(求める)→手に入れること。戦略目的で他社を丸ごと取得する行為。","collocations":["make a strategic acquisition","pursue strategic acquisitions","strategic acquisition target"]},"innovation pipeline":{"example2":"The pharma giant's innovation pipeline includes twelve drugs in late-stage trials.","exampleJa2":"その製薬大手のイノベーション・パイプラインには、後期治験段階の12の新薬が含まれる。","origin":"pipeline(パイプ管)の中をアイデアが順に流れ、製品として出口に届くイメージ。研究開発の進行在庫を表す。","collocations":["robust innovation pipeline","build an innovation pipeline","innovation pipeline management"]},"tips":{"example2":"Advisors recommend TIPS when clients fear rising living costs in retirement.","exampleJa2":"顧客が老後の生活費上昇を懸念する場合、アドバイザーはTIPSを勧める。","origin":"Treasury Inflation-Protected Securitiesの頭字語。物価上昇から元本を守る(protect)米国債と分解して覚える。","collocations":["invest in TIPS","TIPS yields","hold TIPS"]},"purchasing power":{"example2":"Wage growth failed to keep pace with declining purchasing power.","exampleJa2":"賃金の伸びは購買力の低下に追いつかなかった。","origin":"purchaseは古フランス語pourchacier(追い求める)から→買うこと。お金1単位で買える量＝お金の実力を指す。","collocations":["erode purchasing power","preserve purchasing power","loss of purchasing power"]},"consumer price index":{"example2":"Markets rallied after the Consumer Price Index came in below expectations.","exampleJa2":"消費者物価指数が予想を下回ったことを受け、市場は上昇した。","origin":"indexはラテン語indicare(指し示す)から。消費者(consumer)が払う価格(price)の平均変化を指し示す物差し。","collocations":["Consumer Price Index data","core Consumer Price Index","the Consumer Price Index rose"]},"coupon payment":{"example2":"The fund reinvests all coupon payments to compound returns.","exampleJa2":"そのファンドはリターンを複利にするため、すべてのクーポン支払いを再投資する。","origin":"couponはフランス語couper(切る)から。昔の債券に付いた利札を切り取って利息と交換した名残の言葉。","collocations":["receive coupon payments","semiannual coupon payment","miss a coupon payment"]},"redemption value":{"example2":"Investors compared the bond's market price with its redemption value.","exampleJa2":"投資家はその債券の市場価格と償還価額を比較した。","origin":"ラテン語red(再び)+emere(買う)→買い戻すこと。発行体が満期に債券を「買い戻す」際に払う金額。","collocations":["guaranteed redemption value","redemption value at maturity","above redemption value"]},"real interest rate":{"example2":"Rising real interest rates typically pressure gold and growth stocks.","exampleJa2":"実質金利の上昇は通常、金やグロース株の重しとなる。","origin":"realはラテン語res(物・実体)から→名目から物価上昇分を引いた「実体」の金利。実質＝インフレ調整後と覚える。","collocations":["negative real interest rates","real interest rates rise","low real interest rates"]},"nominal yield":{"example2":"A 5% nominal yield means little if inflation runs at 6%.","exampleJa2":"インフレ率が6%なら、5%の名目利回りにはほとんど意味がない。","origin":"nominalはラテン語nomen(名前)から→「名目上の」。額面に書かれた名前だけの利回りで、インフレ調整前の数字。","collocations":["nominal yield on Treasuries","high nominal yield","nominal yield curve"]},"breakeven inflation rate":{"example2":"Traders watch the breakeven inflation rate to gauge market expectations.","exampleJa2":"トレーダーは市場の期待を測るため、ブレークイーブン・インフレ率を注視する。","origin":"break even＝損益がちょうど釣り合う。TIPSと普通国債の損得が同じになるインフレ率＝市場のインフレ予想。","collocations":["10-year breakeven inflation rate","breakeven inflation rate rises","monitor the breakeven inflation rate"]},"inflation expectation":{"example2":"The central bank acted early to keep inflation expectations anchored.","exampleJa2":"中央銀行はインフレ期待を安定させておくため早期に行動した。","origin":"expectはラテン語ex(外を)+spectare(見る)→先を見て待つこと。人々が予想する将来の物価上昇率。","collocations":["anchored inflation expectations","rising inflation expectations","survey of inflation expectations"]},"inflation-linked asset":{"example2":"The endowment added inflation-linked assets to hedge long-term spending needs.","exampleJa2":"その大学基金は長期的な支出ニーズをヘッジするためインフレ連動資産を追加した。","origin":"link(鎖の輪)でインフレ指標とつながれた資産の意。物価が上がればリターンも連動して上がる仕組み。","collocations":["hold inflation-linked assets","inflation-linked bonds","allocate to inflation-linked assets"]},"correlation":{"example2":"Adding assets with low correlation reduces overall portfolio volatility.","exampleJa2":"相関の低い資産を加えることで、ポートフォリオ全体のボラティリティが低下する。","origin":"ラテン語cor(共に)+relatio(関係)→互いに関係し合うこと。2つの資産が一緒に動く度合いを-1〜+1で表す。","collocations":["low correlation","negative correlation","correlation between assets"]},"reit":{"example2":"Rising interest rates weighed on REIT share prices last year.","exampleJa2":"昨年は金利上昇がREITの株価の重しとなった。","origin":"Real Estate Investment Trustの頭字語。不動産(real estate)への投資(investment)を信託(trust)形式で束ねた器。","collocations":["listed REITs","REIT dividends","invest in REITs"]},"income-producing property":{"example2":"The fund acquires income-producing properties in major logistics hubs.","exampleJa2":"そのファンドは主要物流拠点の収益不動産を取得している。","origin":"income(収入)をproduce(生み出す)物件の意。produceはラテン語pro(前へ)+ducere(導く)→前へ生み出す。","collocations":["acquire income-producing property","income-producing real estate","portfolio of income-producing properties"]},"taxable income":{"example2":"Deductions for depreciation lowered the REIT's taxable income substantially.","exampleJa2":"減価償却の控除により、そのREITの課税所得は大幅に減少した。","origin":"tax(税)+able(できる)→課税可能な所得。taxはラテン語taxare(評価する)から。控除後に税率を掛ける基礎額。","collocations":["reduce taxable income","report taxable income","taxable income threshold"]},"dividend":{"example2":"The bank has raised its dividend for ten consecutive years.","exampleJa2":"その銀行は10年連続で配当を増やしている。","origin":"ラテン語dividere(分ける)から→利益を株主に「分け与える」もの。divide(分割する)と同語源で覚えやすい。","collocations":["pay a dividend","dividend yield","raise the dividend"]},"liquidity":{"example2":"The fund holds cash reserves to meet sudden liquidity needs.","exampleJa2":"そのファンドは突発的な流動性需要に備えて現金を保有している。","origin":"ラテン語liquidus(流れる・液体の)から。資産が水のようにさらさらと現金に変わる度合いを表す比喩。","collocations":["market liquidity","liquidity risk","provide liquidity"]},"equity reit":{"example2":"Equity REITs benefited from rising rents in the logistics sector.","exampleJa2":"エクイティREITは物流セクターの賃料上昇の恩恵を受けた。","origin":"equity(持分・実物保有)型のREIT。建物そのものを所有して賃料を稼ぐタイプ。ローン投資型のmortgage REITと対。","collocations":["equity REIT sector","invest in equity REITs","equity REIT returns"]},"mortgage reit":{"example2":"Mortgage REITs suffered as funding costs rose faster than asset yields.","exampleJa2":"調達コストが資産利回りを上回る速さで上昇し、モーゲージREITは苦戦した。","origin":"mortgageは古フランス語mort(死)+gage(担保)→完済で契約が「死ぬ」担保。ローン債権に投資するREIT。","collocations":["mortgage REIT dividends","mortgage REIT sector","leveraged mortgage REITs"]},"occupancy rate":{"example2":"Hotel occupancy rates recovered to pre-pandemic levels this summer.","exampleJa2":"ホテルの稼働率は今夏、パンデミック前の水準まで回復した。","origin":"occupyはラテン語ob(〜に向かって)+capere(つかむ)→場所を占めること。埋まっている割合＝稼働率。","collocations":["high occupancy rate","maintain occupancy rates","occupancy rate of 95%"]},"rental growth":{"example2":"Analysts forecast 4% annual rental growth in prime office markets.","exampleJa2":"アナリストは一等地オフィス市場で年4%の賃料成長を予想している。","origin":"rentはラテン語reddere(返す・支払う)が語源。貸した対価として戻る収入が伸びる(growth)ことを指す。","collocations":["strong rental growth","rental growth forecast","drive rental growth"]},"cap rate":{"example2":"Investors demanded higher cap rates as borrowing costs climbed.","exampleJa2":"借入コストの上昇に伴い、投資家はより高いキャップレートを求めた。","origin":"capitalization rate(還元利回り)の略。純収益を価値に「資本還元(capitalize)」する率。低いほど物件は割高。","collocations":["cap rate compression","cap rates rise","prime cap rates"]},"multi-asset portfolio":{"example2":"A multi-asset portfolio cushioned investors during the equity selloff.","exampleJa2":"マルチアセット・ポートフォリオは株式急落時に投資家の損失を和らげた。","origin":"ラテン語multus(多くの)+asset(資産)。株・債券・不動産など複数の資産クラスを一つの器に混ぜる設計。","collocations":["build a multi-asset portfolio","multi-asset portfolio strategy","diversified multi-asset portfolio"]},"factor investing":{"example2":"Factor investing lets institutions target value and momentum systematically.","exampleJa2":"ファクター投資により、機関投資家はバリューやモメンタムを体系的に狙える。","origin":"factorはラテン語facere(作る・なす)から→リターンを「作り出す」要因。要因ごとに分解して投資する手法。","collocations":["factor investing strategy","adopt factor investing","factor investing framework"]},"value factor":{"example2":"The value factor rebounded strongly when interest rates began rising.","exampleJa2":"金利が上昇し始めると、バリュー・ファクターは力強く反発した。","origin":"value(価値)＝本来の価値より安く売られる株を買う要因。valueはラテン語valere(価値がある・強い)から。","collocations":["value factor exposure","value factor performance","tilt toward the value factor"]},"quality factor":{"example2":"Funds with high quality factor exposure held up well in the recession.","exampleJa2":"クオリティ・ファクターへのエクスポージャーが高いファンドは景気後退局面でも底堅かった。","origin":"qualityはラテン語qualis(どのような)から→性質・質。財務が健全で収益力の高い「質の良い」企業を選ぶ要因。","collocations":["quality factor stocks","quality factor exposure","quality factor premium"]},"risk-adjusted return":{"example2":"The Sharpe ratio is the standard measure of risk-adjusted return.","exampleJa2":"シャープレシオはリスク調整後リターンの標準的な尺度である。","origin":"adjustはラテン語ad(〜へ)+juxta(近くに)→正しく合わせる。取ったリスクの量でリターンを割り引いて比べる発想。","collocations":["superior risk-adjusted returns","maximize risk-adjusted return","risk-adjusted return metrics"]},"factor premium":{"example2":"Researchers debate whether the size factor premium still exists today.","exampleJa2":"研究者たちは、小型株ファクター・プレミアムが今も存在するのか議論している。","origin":"premiumはラテン語prae(前に)+emere(取る)→先に取る褒美。特定ファクターを持つ見返りに得る超過リターン。","collocations":["harvest factor premiums","the value premium","persistent factor premium"]},"long-short strategy":{"example2":"The long-short strategy profited even as the broad market declined.","exampleJa2":"そのロング・ショート戦略は市場全体が下落する中でも利益を上げた。","origin":"long(買い持ち)+short(売り持ち)。割安を買い割高を空売りし、市場の上下に関係なく差分で稼ぐ設計。","collocations":["equity long-short strategy","run a long-short strategy","long-short hedge fund"]},"quantitative hedge fund":{"example2":"Quantitative hedge funds recruit physicists and engineers rather than traditional analysts.","exampleJa2":"クオンツ・ヘッジファンドは伝統的なアナリストよりも物理学者やエンジニアを採用する。","origin":"quantitativeはラテン語quantus(どれだけの量)から→数量的な。数式とデータで判断する「クオンツ」運用のファンド。","collocations":["quantitative hedge fund strategies","leading quantitative hedge funds","launch a quantitative hedge fund"]},"factor crowding":{"example2":"Factor crowding in momentum stocks amplified losses during the sudden reversal.","exampleJa2":"モメンタム株でのファクター・クラウディングが、急反転時の損失を増幅させた。","origin":"crowd(群衆)+ing→同じファクターに皆が群がる状態。満員の出口に殺到すると転倒する、という相場の混雑リスク。","collocations":["signs of factor crowding","factor crowding risk","measure factor crowding"]},"profitability":{"example2":"Cost discipline restored the division's profitability within two years.","exampleJa2":"コスト規律により、その部門の収益性は2年以内に回復した。","origin":"profitはラテン語proficere(前進する・役立つ)から。pro(前へ)+facere(作る)→前進して生み出す利益の力。","collocations":["improve profitability","high profitability","profitability metrics"]},"cbdc":{"example2":"Several central banks are studying how a CBDC would affect commercial lending.","exampleJa2":"複数の中央銀行が、CBDCが商業銀行の融資に与える影響を研究している。","origin":"Central Bank Digital Currencyの頭字語。中央銀行(CB)が発行するデジタル通貨(DC)と2つに分けて覚える。","collocations":["CBDC pilot","launch a CBDC","retail CBDC"]},"sovereign money":{"example2":"Stablecoins compete with sovereign money in some emerging economies.","exampleJa2":"一部の新興国では、ステーブルコインがソブリンマネーと競合している。","origin":"sovereignはラテン語super(上に)から→最高権力者・主権。国家の主権が価値を裏付けるお金という意味。","collocations":["digital sovereign money","trust in sovereign money","sovereign money supply"]},"cross-border remittance":{"example2":"Blockchain rails could cut cross-border remittance fees dramatically.","exampleJa2":"ブロックチェーン基盤は国際送金の手数料を劇的に下げる可能性がある。","origin":"cross(越える)+border(国境)＋remittance。remitはラテン語re(戻して)+mittere(送る)→故郷へ送金する意。","collocations":["cross-border remittance fees","cross-border remittance market","speed up cross-border remittances"]},"financial inclusion":{"example2":"Mobile banking has driven financial inclusion across rural Africa.","exampleJa2":"モバイルバンキングはアフリカの農村部で金融包摂を推進してきた。","origin":"inclusionはラテン語in(中に)+claudere(閉じる)→中に含めること。金融サービスの輪から誰も締め出さない理念。","collocations":["promote financial inclusion","financial inclusion initiatives","advance financial inclusion"]},"unbanked":{"example2":"Digital wallets give unbanked workers a safe way to receive wages.","exampleJa2":"デジタルウォレットは、銀行口座を持たない労働者に安全な賃金の受け取り手段を提供する。","origin":"un(否定)+banked(銀行口座を持つ)→口座を持たない。underbanked(サービス不足)と併せて覚えると便利。","collocations":["the unbanked population","serve the unbanked","unbanked adults"]},"digital wallet":{"example2":"The bank's digital wallet now supports instant peer-to-peer transfers.","exampleJa2":"その銀行のデジタルウォレットは、即時の個人間送金に対応した。","origin":"wallet(財布)のデジタル版。物理的な革の財布の代わりに、スマホのアプリがお金やカード情報を持ち歩く。","collocations":["digital wallet app","store funds in a digital wallet","digital wallet adoption"]},"surveillance":{"example2":"Regulators increased surveillance of suspicious trading patterns after the scandal.","exampleJa2":"不祥事の後、規制当局は不審な取引パターンの監視を強化した。","origin":"フランス語sur(上から)+veiller(見張る)→上から見張ること。ラテン語vigilare(起きて見張る)が語根。","collocations":["mass surveillance","financial surveillance","under surveillance"]},"fractional reserve banking":{"example2":"Under fractional reserve banking, a bank run can quickly become self-fulfilling.","exampleJa2":"部分準備銀行制度の下では、取り付け騒ぎは瞬く間に自己実現的になり得る。","origin":"fraction(一部分)はラテン語frangere(砕く)から。預金の「ほんの一部」だけを手元に残して貸し出す仕組み。","collocations":["fractional reserve banking system","critics of fractional reserve banking","abolish fractional reserve banking"]},"digital yuan":{"example2":"Some exporters now settle trade payments in digital yuan.","exampleJa2":"一部の輸出業者は今や貿易代金をデジタル人民元で決済している。","origin":"yuan(元)は「丸いもの」を意味する漢字に由来。中国人民銀行が発行するCBDCで、正式名称はe-CNY。","collocations":["digital yuan pilot","pay with digital yuan","digital yuan adoption"]},"monetary system":{"example2":"The Bretton Woods agreement shaped the postwar monetary system for decades.","exampleJa2":"ブレトンウッズ協定は戦後の通貨制度を数十年にわたり形づくった。","origin":"monetaryはローマの女神Juno Moneta(その神殿が造幣所だった)に由来。moneyと同語源で、通貨の仕組み全体。","collocations":["global monetary system","international monetary system","reform the monetary system"]},"acquisition premium":{"example2":"Shareholders rejected the bid, arguing the acquisition premium was too small.","exampleJa2":"株主は買収プレミアムが小さすぎるとして、その買収提案を拒否した。","origin":"acquisition(取得)+premium(上乗せ)。経営権を得る対価として市場価格に上乗せする「支配の値段」。","collocations":["pay an acquisition premium","acquisition premium of 30%","justify the acquisition premium"]},"market capitalization":{"example2":"The chipmaker's market capitalization briefly topped one trillion dollars.","exampleJa2":"その半導体メーカーの時価総額は一時1兆ドルを超えた。","origin":"capitalizeは「資本化する」→株数×株価で会社を丸ごと値付けした金額。capitalはラテン語caput(頭)から。","collocations":["large market capitalization","market capitalization of $8 billion","grow market capitalization"]},"revenue synergy":{"example2":"The merged banks expect revenue synergies from sharing distribution channels.","exampleJa2":"合併した両行は、販売チャネルの共有による収益シナジーを見込んでいる。","origin":"synergyはギリシャ語syn(共に)+ergon(働く)→共に働いて生む力。合体で売上が1+1>2になる効果。","collocations":["realize revenue synergies","revenue synergy targets","cross-selling revenue synergies"]},"cost synergy":{"example2":"Consolidating back-office functions delivered most of the cost synergies.","exampleJa2":"バックオフィス機能の統合が、コストシナジーの大半を実現した。","origin":"syn(共に)+ergon(働く)のコスト版。重複部門の削減や共同購買で、合併後に経費が減る効果を指す。","collocations":["achieve cost synergies","annual cost synergies","cost synergy estimates"]},"economies of scale":{"example2":"The asset manager's economies of scale allow it to cut fund fees.","exampleJa2":"その運用会社は規模の経済により、ファンドの手数料を引き下げられる。","origin":"economyはギリシャ語oikos(家)+nomos(管理)→家計のやりくり。規模(scale)が大きいほど単価が下がる原理。","collocations":["achieve economies of scale","benefit from economies of scale","significant economies of scale"]},"accretion-dilution analysis":{"example2":"The accretion-dilution analysis showed earnings would dilute for two years.","exampleJa2":"増益・希薄化分析は、2年間は利益が希薄化することを示した。","origin":"accretionはラテン語accrescere(増え加わる)、dilutionはdiluere(薄める)。買収でEPSが増えるか薄まるかの検査。","collocations":["run an accretion-dilution analysis","accretion-dilution model","EPS accretion-dilution"]},"contingent liability":{"example2":"The acquirer demanded a price cut to reflect the target's contingent liabilities.","exampleJa2":"買収側は、対象企業の偶発債務を反映した値下げを要求した。","origin":"contingentはラテン語con(共に)+tangere(触れる)→偶然触れ合う・起こるかもしれない。条件次第で生じる債務。","collocations":["disclose contingent liabilities","material contingent liability","assess contingent liabilities"]},"managerial hubris":{"example2":"Managerial hubris drove the CEO to ignore warnings about the deal.","exampleJa2":"経営者の過信により、CEOはその案件への警告を無視した。","origin":"hubrisはギリシャ語で「神をも恐れぬ傲慢」。ギリシャ悲劇では傲慢が破滅を招く定番の筋書きで、M&A失敗の説明に使われる。","collocations":["managerial hubris hypothesis","driven by managerial hubris","signs of managerial hubris"]},"winner's curse":{"example2":"Bidding wars for startups often end in the winner's curse.","exampleJa2":"スタートアップを巡る入札合戦は、しばしば勝者の呪いに終わる。","origin":"オークションで「勝った」人ほど払い過ぎている逆説。競り勝つ＝最も高値を付けた人、という構造から生まれた呪い。","collocations":["fall victim to the winner's curse","avoid the winner's curse","the winner's curse in auctions"]},"post-closing integration":{"example2":"A dedicated team managed post-closing integration of the two sales forces.","exampleJa2":"専任チームが両社の営業部隊のクロージング後統合を担った。","origin":"closing(取引完了)の後(post)のintegration(統合)。integrateはラテン語integer(完全な)→一つに完全化する。","collocations":["post-closing integration plan","smooth post-closing integration","post-closing integration risks"]},"alternative investment":{"example2":"Wealthy clients increasingly ask about alternative investments like infrastructure funds.","exampleJa2":"富裕層の顧客は、インフラファンドのようなオルタナティブ投資について尋ねることが増えている。","origin":"alternativeはラテン語alter(もう一方の)から。株・債券という王道の「もう一つの」選択肢となる資産群。","collocations":["alternative investment strategies","allocate to alternative investments","alternative investment funds"]},"absolute return":{"example2":"Absolute return funds aim to profit in both bull and bear markets.","exampleJa2":"絶対リターン型ファンドは、強気相場でも弱気相場でも利益を狙う。","origin":"absoluteはラテン語absolvere(解き放つ)から→何にも縛られない。指数比較(相対)ではなくプラス自体を狙う考え方。","collocations":["absolute return strategy","target absolute returns","absolute return fund"]},"private equity":{"example2":"Private equity firms raised record funds despite higher borrowing costs.","exampleJa2":"借入コスト上昇にもかかわらず、PE各社は過去最高の資金を集めた。","origin":"private(非公開の)+equity(株式持分)。上場市場の外で企業を丸ごと買い、磨いて売るビジネスモデル。","collocations":["private equity firm","private equity fund","private equity buyout"]},"operational improvement":{"example2":"The new owners focused on operational improvements rather than financial engineering.","exampleJa2":"新しいオーナーは財務テクニックよりも業務改善に注力した。","origin":"operateはラテン語opus(仕事)から→事業を動かすこと。現場の仕事のやり方を良くして利益を生む改善。","collocations":["drive operational improvements","operational improvement initiatives","deliver operational improvements"]},"limited partnership":{"example2":"The venture fund raised $500 million through a Delaware limited partnership.","exampleJa2":"そのベンチャーファンドはデラウェア州のリミテッド・パートナーシップを通じて5億ドルを調達した。","origin":"limited(有限の)+partnership(共同経営)。出資者(LP)の責任が出資額に限定されることから。運営者はGP(general partner)と対で覚える。","collocations":["form a limited partnership","limited partnership agreement","limited partnership interests"]},"qualified institutional buyer":{"example2":"The private placement was marketed exclusively to qualified institutional buyers under Rule 144A.","exampleJa2":"その私募はルール144Aに基づき適格機関投資家のみに販売された。","origin":"qualified(資格を満たした)+institutional(機関の)+buyer(買い手)。米SEC規則で定義される用語で、略称QIBもセットで覚えると実務で便利。","collocations":["qualified institutional buyer status","sold to qualified institutional buyers","Rule 144A qualified institutional buyers"]},"high-net-worth individual":{"example2":"Private banks compete fiercely to serve high-net-worth individuals in Asia.","exampleJa2":"プライベートバンクはアジアの富裕層個人投資家の獲得を激しく競っている。","origin":"net worth(純資産=資産−負債)がhigh(高い)個人。略称HNWI。さらに上位はultra-high-net-worth(UHNW)と呼ぶ。","collocations":["high-net-worth individual clients","serve high-net-worth individuals","high-net-worth individual segment"]},"democratization":{"example2":"Tokenization promises further democratization of access to private market funds.","exampleJa2":"トークン化はプライベート市場ファンドへのアクセスをさらに民主化すると期待されている。","origin":"ギリシャ語demos(民衆)+kratos(支配)に由来するdemocracyの派生語。「一部の特権層のものを大衆に開放する」イメージで金融でも頻出。","collocations":["democratization of finance","democratization of access","drive democratization"]},"market microstructure":{"example2":"Her thesis applied market microstructure theory to cryptocurrency exchange data.","exampleJa2":"彼女の論文はマーケット・マイクロストラクチャー理論を暗号資産取引所のデータに応用した。","origin":"micro(ギリシャ語mikros=小さい)+structure(ラテン語struere=組み立てる)。市場を顕微鏡で見るように、注文や約定の細部の仕組みを研究する分野。","collocations":["market microstructure theory","market microstructure research","market microstructure effects"]},"limit order book":{"example2":"Algorithms scan the limit order book for imbalances between buyers and sellers.","exampleJa2":"アルゴリズムは指値注文板を走査し、買い手と売り手の不均衡を探す。","origin":"limit order(指値注文)+book(帳簿)。かつて取引所で注文を帳簿に記録したことの名残。日本語の「板」に対応すると覚える。","collocations":["limit order book depth","limit order book data","central limit order book"]},"bid-ask spread":{"example2":"The bid-ask spread widened sharply as volatility spiked before the announcement.","exampleJa2":"発表前にボラティリティが急上昇し、ビッド・アスク・スプレッドが大きく広がった。","origin":"bid(買い呼び値)+ask(売り呼び値)+spread(広がり)。spreadは「パンにバターを塗り広げる」のspread。二つの価格の開きと覚える。","collocations":["narrow bid-ask spread","widen the bid-ask spread","quoted bid-ask spread"]},"market maker":{"example2":"Designated market makers must quote prices even during turbulent sessions.","exampleJa2":"指定マーケットメーカーは荒れた相場でも気配値を提示し続けなければならない。","origin":"market(市場)+maker(作る人)。売り買い両方の値段を常に出して「市場を成立させる」人、という直訳イメージそのままの語。","collocations":["act as a market maker","designated market maker","market maker quotes"]},"inventory risk":{"example2":"Wider spreads compensate dealers for the inventory risk of illiquid bonds.","exampleJa2":"スプレッドの広さは、流動性の低い債券を抱える在庫リスクへの対価としてディーラーに支払われる。","origin":"inventory(在庫、ラテン語invenire=見つける→財産目録)+risk。商店の売れ残り在庫と同じく、抱えた証券が値下がりする危険のこと。","collocations":["manage inventory risk","bear inventory risk","inventory risk exposure"]},"high-frequency trading":{"example2":"Critics argue high-frequency trading extracts profits without providing durable liquidity.","exampleJa2":"批判者は、高頻度取引は持続的な流動性を提供せずに利益を吸い上げていると主張する。","origin":"high(高い)+frequency(頻度、ラテン語frequens=混み合った)+trading。1秒に何千回も売買する「頻度の高さ」が名前の由来。略称HFT。","collocations":["high-frequency trading firms","high-frequency trading strategies","high-frequency trading algorithms"]},"co-location":{"example2":"Exchanges earn substantial fees by selling co-location services to trading firms.","exampleJa2":"取引所はトレーディング会社にコロケーションサービスを販売して多額の手数料を得ている。","origin":"co-(共に)+location(場所、ラテン語locus=場所)。取引所のサーバーと「同じ場所に」自社サーバーを置くことから。","collocations":["co-location services","co-location fees","co-location facilities"]},"latency":{"example2":"The firm invested millions in microwave towers to shave latency.","exampleJa2":"その会社はレイテンシーを削るためにマイクロ波塔に数百万ドルを投じた。","origin":"ラテン語latere(隠れている)が語源。「潜んでいる時間」→目に見えない待ち時間・遅延。latent(潜在的な)と同語源。","collocations":["low latency","reduce latency","network latency"]},"phantom liquidity":{"example2":"Regulators worry that phantom liquidity masks the market's true fragility.","exampleJa2":"規制当局は、見せかけの流動性が市場の本当の脆さを覆い隠していることを懸念している。","origin":"phantom(幽霊、ギリシャ語phantasma=幻影)+liquidity(流動性)。触れようとすると消える幽霊のように、約定しようとすると消える注文のこと。","collocations":["phantom liquidity problem","create phantom liquidity","phantom liquidity in markets"]},"flash crash":{"example2":"A fat-finger order triggered a brief flash crash in the futures market.","exampleJa2":"誤発注が先物市場で短時間のフラッシュ・クラッシュを引き起こした。","origin":"flash(閃光、一瞬)+crash(暴落)。カメラのフラッシュのように「一瞬で」起きて戻る暴落。2010年5月の米国株の事件で定着した語。","collocations":["trigger a flash crash","the 2010 flash crash","flash crash risk"]},"circuit breaker":{"example2":"The exchange widened its circuit breaker thresholds after repeated halts.","exampleJa2":"度重なる売買停止を受けて、取引所はサーキットブレーカーの発動基準を緩和した。","origin":"本来は電気回路(circuit)の遮断器(breaker)。過電流でブレーカーが落ちるように、過熱した相場を強制的に「遮断」する仕組みという比喩。","collocations":["trigger a circuit breaker","circuit breaker rules","market-wide circuit breaker"]},"spoofing":{"example2":"The bank's surveillance system flagged a pattern consistent with spoofing.","exampleJa2":"銀行の監視システムがスプーフィングに合致する取引パターンを検知した。","origin":"spoof(だます、なりすます)+ing。元は英国の喜劇役者が考案した「だましゲーム」の名前。約定させる気のない注文で他者を欺く行為。","collocations":["spoofing charges","engage in spoofing","detect spoofing"]},"autonomously":{"example2":"The AI agent autonomously rebalances portfolios within preset risk limits.","exampleJa2":"そのAIエージェントは、事前に定めたリスク制限の範囲内でポートフォリオを自律的にリバランスする。","origin":"ギリシャ語auto(自分自身)+nomos(法・規律)→「自分の法で動く」。自治を意味するautonomyの副詞形。automaticと同じautoが目印。","collocations":["operate autonomously","act autonomously","function autonomously"]},"reconcile":{"example2":"The back office reconciles trade confirmations against the custodian's records daily.","exampleJa2":"バックオフィスは毎日、取引確認書をカストディアンの記録と照合している。","origin":"ラテン語re-(再び)+conciliare(結び合わせる)。「仲直りさせる」が原義で、そこから「二つの記録を一致させる=照合する」の意味に広がった。","collocations":["reconcile accounts","reconcile the records","reconcile discrepancies"]},"redraw the boundary":{"example2":"Generative AI is redrawing the boundary between junior and senior analyst work.","exampleJa2":"生成AIは、若手アナリストとシニアアナリストの仕事の境界線を引き直しつつある。","origin":"redraw(re=再び+draw=線を引く)+boundary(境界)。地図の国境線を書き直すイメージ。役割分担や領域の再定義を表す比喩表現。","collocations":["redraw the boundary between","redraw national boundaries","redraw the boundaries of the industry"]},"tedious":{"example2":"Compiling the quarterly compliance report is tedious but unavoidable work.","exampleJa2":"四半期コンプライアンス報告書の作成は退屈だが避けられない仕事だ。","origin":"ラテン語taedium(嫌気、うんざり)が語源。「長くて単調でうんざりする」ニュアンス。boringより「延々と続く作業」に使うことが多い。","collocations":["tedious task","tedious process","tedious paperwork"]},"stagnant":{"example2":"Loan growth stayed stagnant even after the central bank cut rates.","exampleJa2":"中央銀行が利下げした後も、融資の伸びは停滞したままだった。","origin":"ラテン語stagnum(よどんだ池・沼)が語源。流れのない池の水のように「動きがなくよどんだ」状態。stagnation(停滞)、stagflationも同語源。","collocations":["stagnant wages","stagnant economy","remain stagnant"]},"displacement":{"example2":"Economists debate whether AI-driven displacement will outpace new job creation.","exampleJa2":"エコノミストは、AIによる雇用喪失が新規雇用の創出を上回るかどうかを議論している。","origin":"dis-(離れて)+place(場所)+ment→「場所から追い出すこと」。労働者が technology に「持ち場を奪われる」イメージで覚える。","collocations":["job displacement","worker displacement","displacement of labor"]},"rung":{"example2":"Entry-level analyst roles form the lowest rung of the banking hierarchy.","exampleJa2":"新人アナリスト職は、銀行のヒエラルキーの最下段に位置する。","origin":"古英語hrung(棒)が語源で、はしごの横木のこと。「はしご(ladder)の段」→「組織や社会の階層の一段」へと比喩が広がった。","collocations":["the lowest rung","climb the rungs","a rung on the ladder"]},"wrenching":{"example2":"Restructuring the pension system will require wrenching political choices.","exampleJa2":"年金制度の再構築には、苦痛を伴う政治的決断が必要になるだろう。","origin":"wrench(ねじる・もぎ取る、工具のレンチも同語)+ing。「心をねじり上げるような」痛みのイメージ。gut-wrenching(断腸の思いの)も頻出。","collocations":["wrenching change","wrenching decision","gut-wrenching experience"]},"hollow out":{"example2":"Analysts warn automation could hollow out middle-office banking jobs entirely.","exampleJa2":"アナリストは、自動化が銀行のミドルオフィス業務を完全に空洞化させかねないと警告する。","origin":"hollow(空洞の)+out(すっかり)。木の幹の中身をくり抜くイメージ。外形は残るのに中身(中間層・中核)が失われる状況にぴったりの句動詞。","collocations":["hollow out the middle class","hollow out the industry","hollowed-out labor market"]},"surplus":{"example2":"The trade surplus widened as exports of machinery surged.","exampleJa2":"機械輸出の急増により貿易黒字が拡大した。","origin":"ラテン語super(上に)+plus(より多く)→「必要を超えて上乗せされた分」。対義語はdeficit(赤字・不足)。財政・貿易の文脈で頻出。","collocations":["trade surplus","budget surplus","run a surplus"]},"receptor agonist":{"example2":"Sales of the GLP-1 receptor agonist doubled, lifting the drugmaker's shares.","exampleJa2":"そのGLP-1受容体作動薬の売上が倍増し、製薬会社の株価を押し上げた。","origin":"receptor(受け取るもの、ラテン語recipere=受け取る)+agonist(ギリシャ語agon=競技→作動させる者)。受容体の「スイッチを押す」薬。対義語はantagonist(拮抗薬)。","collocations":["GLP-1 receptor agonist","receptor agonist therapy","selective receptor agonist"]},"efficacious":{"example2":"The committee approved only the most efficacious and cost-effective therapies.","exampleJa2":"委員会は最も効果的で費用対効果の高い治療法のみを承認した。","origin":"ラテン語efficere(ex=外へ+facere=作る→成し遂げる)から。「狙った効果を実際に生み出す」の意。名詞efficacy(有効性)は治験報道で頻出。","collocations":["highly efficacious","efficacious treatment","prove efficacious"]},"actuarial":{"example2":"The insurer revised its actuarial assumptions to reflect longer lifespans.","exampleJa2":"その保険会社は寿命の伸びを反映して保険数理上の前提を見直した。","origin":"ラテン語actuarius(帳簿係・記録係)が語源。記録と統計から危険を計算する職業actuary(アクチュアリー)の形容詞形。","collocations":["actuarial assumptions","actuarial tables","actuarial valuation"]},"indefinitely":{"example2":"The regulator suspended the fund's redemptions indefinitely pending an investigation.","exampleJa2":"規制当局は調査が終わるまで、そのファンドの解約を無期限に停止した。","origin":"in-(否定)+definite(限定された、ラテン語finis=境界)+ly→「期限が定められていない」。finish、finalと同じfinisが核。","collocations":["postponed indefinitely","suspended indefinitely","continue indefinitely"]},"staggering":{"example2":"The fund reported a staggering 40 percent loss in a single quarter.","exampleJa2":"そのファンドは1四半期だけで40%という途方もない損失を報告した。","origin":"stagger(よろめく)+ing→「聞いた人がよろめくほどの」。衝撃で足元がふらつくイメージから「驚異的に大きい」の意味になった。","collocations":["a staggering amount","staggering losses","a staggering sum"]},"ration":{"example2":"When credit tightens, banks effectively ration loans to smaller businesses.","exampleJa2":"信用が引き締まると、銀行は事実上、中小企業向け融資を制限する。","origin":"ラテン語ratio(計算・割合)が語源。戦時の食糧「配給」のように、限られたものを計算して割り当てる行為。credit rationing(信用割当)は金融用語。","collocations":["ration care","ration credit","ration supplies"]},"prior authorization":{"example2":"Insurers use prior authorization to control spending on expensive new drugs.","exampleJa2":"保険会社は高額な新薬への支出を抑えるために事前承認制度を使っている。","origin":"prior(前の、ラテン語prior=より先の)+authorization(権限付与、author=創始者と同語源)。「先に許可を取る」という直訳通りの米医療保険用語。","collocations":["require prior authorization","obtain prior authorization","prior authorization process"]},"proponent":{"example2":"Proponents of passive investing point to decades of fee savings.","exampleJa2":"パッシブ運用の支持者は、数十年にわたる手数料の節約効果を根拠に挙げる。","origin":"ラテン語pro-(前に)+ponere(置く)→「案を前に置く人」=提唱者。propose(提案する)と同語源。対義語はopponent(反対者)。","collocations":["proponents of the plan","a leading proponent","proponents argue that"]},"curtail":{"example2":"The board voted to curtail share buybacks to preserve cash.","exampleJa2":"取締役会は手元資金を温存するため自社株買いの縮小を決議した。","origin":"古フランス語courtault(短く切られた)から。cur-部分はcourt/short(短い)と同系。「尻尾を切り詰める」イメージで「削減する」と覚える。","collocations":["curtail spending","curtail activities","severely curtail"]},"downstream":{"example2":"Poor data quality creates costly downstream errors in risk reporting.","exampleJa2":"データ品質の悪さは、リスク報告の後工程で高くつくエラーを生む。","origin":"down(下へ)+stream(流れ)→「川下の」。工程を川の流れに見立て、後の段階を指す。石油業界では精製・販売部門の意味でも使う。対義語はupstream。","collocations":["downstream effects","downstream costs","downstream processes"]},"accrue":{"example2":"Unpaid management fees accrue to the general partner each quarter.","exampleJa2":"未払いの管理報酬は四半期ごとにジェネラル・パートナーに発生していく。","origin":"ラテン語ad-(〜へ)+crescere(成長する)→「増え加わる」。increase、crescendoと同語源。会計の「発生主義(accrual basis)」もこの語から。","collocations":["interest accrues","benefits accrue to","accrued expenses"]},"temporal mismatch":{"example2":"Green investment faces a temporal mismatch: costs now, benefits decades later.","exampleJa2":"グリーン投資は、費用は今、便益は数十年後という時間的ミスマッチに直面している。","origin":"temporal(時間の、ラテン語tempus=時)+mismatch(mis=誤り+match=一致)。「時間軸のずれ」という直訳イメージ。tempoやtemporaryと同語源。","collocations":["a temporal mismatch between","suffer from a temporal mismatch","resolve the temporal mismatch"]},"reimbursement":{"example2":"Drugmakers negotiate reimbursement rates with each national health system.","exampleJa2":"製薬会社は各国の医療保険制度と償還価格を交渉する。","origin":"re-(再び)+im-(中へ)+bourse(財布、ラテン語bursa=革袋)→「財布にお金を戻すこと」。証券取引所を意味する仏語Bourseと同語源。","collocations":["reimbursement rates","seek reimbursement","insurance reimbursement"]},"negligible":{"example2":"The currency hedge added negligible cost to the portfolio.","exampleJa2":"為替ヘッジがポートフォリオに追加したコストは無視できるほどだった。","origin":"ラテン語neglegere(nec=〜ない+legere=拾い上げる)→「拾い上げる価値もない」。neglect(無視する)の仲間で、「無視してよいほど小さい」の意。","collocations":["negligible impact","negligible risk","negligible amount"]},"benign":{"example2":"Credit conditions remained benign, with default rates near historic lows.","exampleJa2":"デフォルト率が歴史的低水準にとどまり、信用環境は良好なままだった。","origin":"ラテン語bene(良く)+gignere(生む)→「良い性質に生まれついた」。医療では「良性の」、市場では「穏やかで無害な」。対義語はmalignant(悪性の)。","collocations":["benign environment","benign inflation","benign tumor"]},"term premium":{"example2":"Estimates suggest the term premium turned positive after years below zero.","exampleJa2":"推計によれば、タームプレミアムは長年のマイナス圏を脱してプラスに転じた。","origin":"term(期間、ラテン語terminus=境界・期限)+premium(割増金、ラテン語praemium=報酬)。「長い期間」を我慢する見返りに上乗せされる利回り。","collocations":["rising term premium","term premium estimates","compress the term premium"]},"debt service":{"example2":"Rising rates pushed the company's debt service above its operating income.","exampleJa2":"金利上昇により、その企業の債務返済額は営業利益を上回った。","origin":"debt(債務)+service(奉仕→義務の履行)。serviceには「定期的な支払い義務を果たす」の意があり、「借金に仕える」イメージで覚える。","collocations":["debt service costs","debt service coverage ratio","annual debt service"]},"unforgiving":{"example2":"The bond market proved unforgiving when the deficit plan unraveled.","exampleJa2":"財政赤字削減計画が崩れると、債券市場は容赦ない反応を示した。","origin":"un-(否定)+forgiving(許す)→「許してくれない」。小さなミスも見逃さず罰する、という市場や自然環境の厳しさを表す定番の形容詞。","collocations":["unforgiving market","unforgiving environment","unforgiving terrain"]},"ratchet upward":{"example2":"Wage settlements ratcheted upward as inflation expectations became entrenched.","exampleJa2":"インフレ期待が定着するにつれ、賃金の妥結水準は段階的に切り上がっていった。","origin":"ratchet(ラチェット=一方向にしか回らない歯車工具)+upward(上へ)。逆戻りしない工具のように「上がったら下がらない」上昇を表す。","collocations":["ratchet upward over time","prices ratchet upward","expectations ratchet upward"]},"maturity":{"example2":"The fund ladders bonds across maturities to manage reinvestment risk.","exampleJa2":"そのファンドは再投資リスクを管理するため、満期を分散して債券を保有している。","origin":"ラテン語maturus(熟した)から。「果実が熟す」→「人が成熟する」→「債券が満期を迎える」。債券が「熟して」償還の時を迎えるイメージ。","collocations":["maturity date","average maturity","held to maturity"]},"profligate":{"example2":"Rating agencies downgraded the profligate borrower after years of deficits.","exampleJa2":"格付け会社は、長年赤字を続けた浪費的な債務国を格下げした。","origin":"ラテン語pro-(前へ)+fligere(打ち倒す)→「打ち崩された」→「身を持ち崩した」→「浪費的な」。財政規律を失った政府の描写で頻出。","collocations":["profligate spending","profligate government","fiscally profligate"]},"latitude":{"example2":"Strong fiscal buffers give policymakers greater latitude in a downturn.","exampleJa2":"強固な財政余力は、景気後退時に政策当局へより大きな裁量の余地を与える。","origin":"ラテン語latus(広い)から。地理の「緯度」が原義で、「横方向の広がり」→「動ける幅=裁量の余地」へ。広さのイメージで覚える。","collocations":["considerable latitude","give someone latitude","latitude to act"]},"risk premia":{"example2":"The strategy harvests risk premia across equities, credit, and currencies.","exampleJa2":"その戦略は株式・クレジット・通貨にまたがるリスクプレミアムを獲得しにいく。","origin":"premiaはラテン語praemium(報酬)の複数形。単数はpremium。「リスクを取る者への報酬」で、学術・運用業界ではラテン語複数形をそのまま使う。","collocations":["harvest risk premia","alternative risk premia","risk premia widen"]},"falter":{"example2":"The recovery faltered as consumers cut back on discretionary spending.","exampleJa2":"消費者が選択的支出を切り詰めるにつれ、景気回復は勢いを失った。","origin":"中英語falteren(よろめく)から。足取りがふらつく・声が震えるが原義で、経済や自信が「よろめく=弱まる」比喩に広がった。","collocations":["growth falters","confidence falters","the recovery falters"]},"primary surplus":{"example2":"The IMF program requires a primary surplus of two percent of GDP.","exampleJa2":"IMFプログラムはGDP比2%のプライマリーバランス黒字を求めている。","origin":"primary(第一の、ラテン語primus=最初の)+surplus(super=上に+plus=より多く)。利払いを除いた「基礎的」収支の黒字。日本の財政議論でも頻出。","collocations":["run a primary surplus","achieve a primary surplus","primary surplus target"]},"financial repression":{"example2":"Capped deposit rates are a classic tool of financial repression.","exampleJa2":"預金金利の上限規制は金融抑圧の典型的な手段である。","origin":"financial+repression(re=後ろへ+premere=押す→押さえつけ)。金利を人為的に低く「押さえつけ」、政府debtを軽くする政策。pressと同語源。","collocations":["financial repression policies","an era of financial repression","resort to financial repression"]},"austerity":{"example2":"Voters rejected the austerity package in a national referendum.","exampleJa2":"有権者は国民投票で緊縮財政パッケージを否決した。","origin":"ギリシャ語austeros(舌を乾かす渋み)→ラテン語austerus(厳しい)。渋く厳しい生活の「禁欲」が原義で、政府支出の切り詰めを指す語に。","collocations":["austerity measures","impose austerity","fiscal austerity"]},"retrench":{"example2":"Global lenders retrenched from emerging markets as funding costs rose.","exampleJa2":"資金調達コストの上昇を受け、グローバル銀行は新興国市場から撤退・縮小した。","origin":"フランス語re-(後ろへ)+trancher(切る)→「切り詰めて引き下がる」。塹壕(trench)と同語源で、「防御線まで下がって守りを固める」イメージ。","collocations":["banks retrench","retrench from overseas markets","forced to retrench"]},"vacuum":{"example2":"The regulator's inaction created a vacuum that shadow banks quickly exploited.","exampleJa2":"規制当局の不作為が生んだ空白を、シャドーバンクがすかさず突いた。","origin":"ラテン語vacuus(空の)から。vacant(空いている)、vacation(仕事が空く=休暇)と同語源。「何もない空間」→「power vacuum(権力の空白)」等の比喩に。","collocations":["fill the vacuum","power vacuum","leave a vacuum"]},"balloon":{"example2":"The bank's balance sheet ballooned to twice its pre-crisis size.","exampleJa2":"その銀行のバランスシートは危機前の2倍にまで急膨張した。","origin":"イタリア語ballone(大きな球)から。名詞「風船」が動詞化し、風船がみるみる膨らむように「急激に膨張する」を表す。赤字・債務の急増に頻出。","collocations":["costs balloon","the deficit balloons","balloon out of control"]},"floating-rate":{"example2":"Investors rotated into floating-rate notes ahead of expected rate hikes.","exampleJa2":"利上げ観測を受けて、投資家は変動利付債へ資金をシフトした。","origin":"floating(浮いている)+rate(金利)。金利が固定されず市場水準に合わせて「浮き沈みする」イメージ。対義語はfixed-rate(固定金利の)。","collocations":["floating-rate notes","floating-rate loans","floating-rate debt"]},"insulation":{"example2":"Long-term funding gives the bank insulation from short-term market stress.","exampleJa2":"長期の資金調達は、短期的な市場ストレスからその銀行を守る遮断材となる。","origin":"ラテン語insula(島)から。「島のように切り離す」→熱や電気の「絶縁」→比喩的に「外部ショックからの遮断」。半島peninsulaも同語源。","collocations":["insulation from shocks","provide insulation against","a degree of insulation"]},"artifact":{"example2":"The apparent outperformance was an artifact of survivorship bias in the data.","exampleJa2":"見かけ上の超過リターンは、データの生存者バイアスが生んだ人為的産物だった。","origin":"ラテン語ars(技術)+factum(作られたもの)→「人の手で作られたもの」。考古学では「遺物」、統計では「測定方法が生んだ見かけの結果」。","collocations":["a statistical artifact","an artifact of the data","measurement artifact"]},"deceptively":{"example2":"Private asset valuations can appear deceptively stable during market turmoil.","exampleJa2":"市場が混乱している間、プライベート資産の評価額は見かけによらず安定しているように見えることがある。","origin":"ラテン語de-(離れて)+capere(つかむ)→deceive(欺く=正しい理解から引き離す)の副詞形。captureと同語源。「見た目と実態が違う」が核。","collocations":["deceptively simple","deceptively calm","look deceptively safe"]},"volatility laundering":{"example2":"Quarterly appraisals enable volatility laundering that flatters risk-adjusted returns.","exampleJa2":"四半期ごとの鑑定評価はボラティリティ・ロンダリングを可能にし、リスク調整後リターンを実態より良く見せる。","origin":"money laundering(資金洗浄)のもじり。汚れたお金を洗うように、まばらな評価で価格変動を「洗い流して」リスクを低く見せる、という批判的造語。","collocations":["accusations of volatility laundering","volatility laundering in private markets","engage in volatility laundering"]},"placid":{"example2":"The placid credit markets showed no sign of the coming storm.","exampleJa2":"平穏なクレジット市場には、来たるべき嵐の兆しは見えなかった。","origin":"ラテン語placere(喜ばせる)から。please、pleasantと同語源。「人を喜ばせるほど穏やかな」→波風のない湖面のような静けさを表す。","collocations":["placid surface","placid markets","remarkably placid"]},"covenant":{"example2":"Covenant-lite loans now dominate the leveraged lending market.","exampleJa2":"コベナンツの緩い（コブライト）ローンが今やレバレッジド・ローン市場の大半を占めている。","origin":"ラテン語con-(共に)+venire(来る)→「合意に至る」。convention(協定)と同語源。聖書の「契約」が原義で、金融では貸し手を守る特約条項。","collocations":["loan covenants","breach a covenant","covenant-lite loans"]},"payment-in-kind":{"example2":"Struggling borrowers increasingly toggle to payment-in-kind to conserve cash.","exampleJa2":"資金繰りに窮した借り手は、現金温存のため現物払いへの切り替えを増やしている。","origin":"in kind は「現金でなく同種の物で」の意(kindは種類)。利息を現金でなく「追加の債券という現物」で払うことから。略称PIKで覚える。","collocations":["payment-in-kind notes","payment-in-kind interest","toggle to payment-in-kind"]},"opacity":{"example2":"The opacity of private credit valuations worries systemic risk regulators.","exampleJa2":"プライベートクレジットの評価の不透明性は、システミックリスクを監督する当局を不安にさせている。","origin":"ラテン語opacus(陰になった・暗い)から。光を通さない「不透明さ」が原義で、情報が見通せない状態の比喩に。対義語はtransparency(透明性)。","collocations":["market opacity","the opacity of the system","criticize the opacity"]},"refinancing wall":{"example2":"Companies rushed to issue bonds early, chipping away at the refinancing wall.","exampleJa2":"企業は前倒しで社債を発行し、借り換えの壁を少しずつ崩していった。","origin":"refinancing(借り換え)+wall(壁)。満期が集中する時期をグラフにすると壁のようにそびえて見えることから。maturity wallとも言う。","collocations":["face a refinancing wall","the looming refinancing wall","refinancing wall in 2027"]},"belatedly":{"example2":"Rating agencies belatedly acknowledged the risks building in private credit.","exampleJa2":"格付け会社は、プライベートクレジットに蓄積していたリスクを遅ればせながら認めた。","origin":"be-(強意)+late(遅い)+ly→「本来より遅れて」。belatedはbelated birthday wishes(遅ればせの誕生日祝い)のように日常でも使う。","collocations":["belatedly recognize","belatedly respond","act belatedly"]},"obscure":{"example2":"An obscure clause in the prospectus later proved decisive in court.","exampleJa2":"目論見書の中の目立たない条項が、のちに法廷で決定的な意味を持った。","origin":"ラテン語ob-(覆って)+scurus(暗い)→「暗く覆われた」。「無名の・目立たない」(形容詞)と「覆い隠す」(動詞)の両方で使われる。","collocations":["an obscure company","relatively obscure","obscure origins"]},"rare earths":{"example2":"Export controls on rare earths rattled defense and auto supply chains.","exampleJa2":"レアアースの輸出規制は、防衛産業と自動車のサプライチェーンを動揺させた。","origin":"rare(希少な)+earths(土類)。18世紀に鉱石から見つかった酸化物を「土」と呼んだ名残。実は埋蔵量は多いが、採掘・精錬が難しいので「rare」。","collocations":["rare earths supply","rare earths exports","rare earths mining"]},"hinge on":{"example2":"The fund's entire return profile hinges on exit valuations at sale.","exampleJa2":"そのファンドのリターン特性は、売却時のエグジット評価額にすべてかかっている。","origin":"hinge(ちょうつがい)+on。ドア全体が小さなちょうつがいで支えられて動くように、物事の帰趨が一点に「かかっている」イメージ。","collocations":["hinge on the outcome","hinge on approval","success hinges on"]},"extraction":{"example2":"Deep-sea mineral extraction raises both environmental and legal disputes.","exampleJa2":"深海での鉱物採掘は、環境面と法律面の両方で論争を引き起こしている。","origin":"ラテン語ex-(外へ)+trahere(引く)→「引き出すこと」。tractor(トラクター=引く機械)、attract(引きつける)と同語源。抜歯にも使う。","collocations":["resource extraction","mineral extraction","extraction costs"]},"confer":{"example2":"Owning the index franchise confers durable competitive advantages on the exchange.","exampleJa2":"指数事業の保有は、その取引所に持続的な競争優位を与えている。","origin":"ラテン語con-(共に)+ferre(運ぶ)→「運んで与える」。transfer、offerと同じferre系。confer with(協議する)の用法もあるが、まず「授与する」を押さえる。","collocations":["confer an advantage","confer rights","confer legitimacy"]},"scramble":{"example2":"Banks scrambled to hedge exposure as the currency peg broke.","exampleJa2":"通貨ペッグが崩れると、銀行はエクスポージャーのヘッジに奔走した。","origin":"「はい登る・かき集める」が原義の擬態語的な語。卵をかき混ぜるscrambled eggsと同じ語で、慌ただしく先を争って動き回るイメージ。","collocations":["scramble to secure","scramble for resources","scramble to respond"]},"friend-shoring":{"example2":"Friend-shoring is redirecting foreign direct investment toward allied economies.","exampleJa2":"フレンドショアリングは、対外直接投資の流れを同盟国経済へと向け直しつつある。","origin":"friend(友好国)+shoring(offshoring=海外移転のshore(岸)から)。offshoring→reshoring(国内回帰)に続く造語で、「友好国の岸へ」移す政策。","collocations":["friend-shoring strategies","friend-shoring of supply chains","pursue friend-shoring"]},"stockpile":{"example2":"Chipmakers built stockpiles of critical components ahead of new export bans.","exampleJa2":"半導体メーカーは新たな輸出禁止措置に先立ち、重要部品の備蓄を積み上げた。","origin":"stock(蓄え)+pile(積み重ね)。「蓄えの山」という直訳イメージそのまま。動詞でも使え、戦略物資・武器・食料の文脈で頻出。","collocations":["strategic stockpile","build a stockpile","stockpile of reserves"]},"lavish":{"example2":"The sovereign fund is known for lavish spending on trophy assets.","exampleJa2":"その政府系ファンドは、トロフィー資産への気前のよい支出で知られている。","origin":"古フランス語lavasse(豪雨)、さらにラテン語lavare(洗う)から。「雨のように惜しみなく注ぐ」イメージ。lavish A on B(AをBに惜しみなく与える)の動詞用法も。","collocations":["lavish subsidies","lavish spending","lavish praise"]},"proclaim":{"example2":"The minister proclaimed the reform a turning point for capital markets.","exampleJa2":"大臣はその改革を資本市場の転換点だと宣言した。","origin":"ラテン語pro-(前で)+clamare(叫ぶ)→「公衆の前で叫ぶ」。claim、exclaim(叫ぶ)と同語源。公式・堂々と announce するニュアンス。","collocations":["proclaim victory","proclaim independence","proclaim a new era"]},"at one's peril":{"example2":"Fund managers dismiss demographic trends at their peril.","exampleJa2":"ファンドマネジャーが人口動態のトレンドを軽視すれば、痛い目を見るのは自分自身だ。","origin":"peril(危険)はラテン語periculum(試み・危険)から。experiment(実験)と同語源。「無視するなら危険は自分持ちだぞ」という警告の定型句。","collocations":["ignore it at your peril","do so at their peril","at his own peril"]},"indifferent":{"example2":"Bond investors seemed indifferent to the political noise until yields jumped.","exampleJa2":"利回りが急騰するまで、債券投資家は政治的な喧噪に無関心のようだった。","origin":"in-(否定)+different(異なる)→「どちらでも差がない」→「どうでもよい・無関心な」。差を感じないから気にしない、と繋げて覚える。","collocations":["indifferent to risk","largely indifferent","remain indifferent"]},"fertility rate":{"example2":"Insurers model long-term liabilities using projections of the fertility rate.","exampleJa2":"保険会社は出生率の将来予測を用いて長期負債をモデル化している。","origin":"fertility(肥沃さ・多産、ラテン語ferre=運ぶ・産む)+rate(率)。土地の「肥沃さ」と同じ語で、女性1人当たりの出生数を示す統計用語。","collocations":["declining fertility rate","total fertility rate","fertility rate below replacement"]},"replacement level":{"example2":"Even generous child subsidies have failed to restore replacement level fertility.","exampleJa2":"手厚い子育て補助金をもってしても、出生率を人口置換水準に戻すことはできていない。","origin":"replacement(re=再び+place=置く→置き換え)+level(水準)。親世代を子世代が「置き換える」のに必要な出生率(約2.1)という直訳イメージ。","collocations":["below replacement level","reach replacement level","replacement level fertility"]},"pay-as-you-go":{"example2":"Shrinking workforces strain pay-as-you-go systems across the developed world.","exampleJa2":"労働人口の減少が、先進国の賦課方式の制度に重い負担をかけている。","origin":"「進みながら(as you go)払う(pay)」が直訳。積み立てず、今の現役世代の保険料で今の受給者を支える方式。携帯の従量課金プランにも使う語。","collocations":["pay-as-you-go pension system","pay-as-you-go basis","pay-as-you-go financing"]},"deteriorate":{"example2":"Credit quality deteriorated steadily across the lowest-rated loan tranches.","exampleJa2":"最低格付けのローン・トランシェ全体で、信用の質が着実に悪化していった。","origin":"ラテン語deterior(より悪い)から。「より悪い状態へ進む」が原義。improve(改善する)の対義語として、財政・信用・健康の悪化に頻出。","collocations":["conditions deteriorate","deteriorate rapidly","deteriorating credit quality"]},"remedy":{"example2":"Raising the retirement age is an unpopular but effective remedy.","exampleJa2":"定年引き上げは不人気だが効果的な解決策である。","origin":"ラテン語re-(再び)+mederi(癒す)→「治し直すもの」。medicine(薬)と同語源。「病気の治療薬」から「問題の是正策・法的救済」へ意味が拡大。","collocations":["seek a remedy","legal remedy","remedy for the problem"]},"prefund":{"example2":"Norway prefunds future obligations through its giant sovereign wealth fund.","exampleJa2":"ノルウェーは巨大な政府系ファンドを通じて将来の債務を事前積立している。","origin":"pre-(前もって、ラテン語prae=先に)+fund(資金を用意する)。「先に資金を積んでおく」という直訳通りの語。賦課方式(pay-as-you-go)の対概念。","collocations":["prefund pension obligations","prefund future liabilities","prefunded benefits"]},"topple":{"example2":"The scandal threatened to topple the bank's long-serving chief executive.","exampleJa2":"そのスキャンダルは、長年君臨してきた銀行のCEOを失脚させる恐れがあった。","origin":"top(頂点)+-le(反復動作)→「頭から倒れる」。積み木がぐらりと倒れるイメージで、政権・指導者・体制が「倒される」比喩に使う。","collocations":["topple the government","topple a leader","threaten to topple"]},"dwarf":{"example2":"Passive fund inflows now dwarf allocations to active managers.","exampleJa2":"パッシブファンドへの資金流入は、今やアクティブ運用への配分を圧倒的に上回る。","origin":"名詞「小人(こびと)」が動詞化した語。「相手を小人に見せるほど自分が大きい」→比較で霞ませる。白雪姫の七人の小人(dwarfs)から連想すると忘れない。","collocations":["dwarf its rivals","be dwarfed by","dwarf previous records"]},"compound":{"example2":"Delaying pension reform only compounds the burden on younger workers.","exampleJa2":"年金改革の先送りは、若い世代の負担を悪化させるだけだ。","origin":"ラテン語com-(共に)+ponere(置く)→「積み重ねる」。利息が利息を生むcompound interest(複利)が金融での核。積み重なって「悪化する」意味にも。","collocations":["compound the problem","compound interest","compound annually"]},"intergenerational equity":{"example2":"Funding today's benefits with debt undermines intergenerational equity.","exampleJa2":"今日の給付を借金で賄うことは、世代間公平を損なう。","origin":"inter-(間の)+generational(世代の)+equity(公平、ラテン語aequus=等しい)。「世代の間の公平」という直訳通り。equityは株式でなく「公平」の意。","collocations":["questions of intergenerational equity","promote intergenerational equity","intergenerational equity concerns"]},"gradualism":{"example2":"The central bank's gradualism kept markets calm through the tightening cycle.","exampleJa2":"中央銀行の漸進主義的アプローチは、引き締め局面を通じて市場の平静を保った。","origin":"ラテン語gradus(歩み・段)+-ism(主義)。gradually(徐々に)、grade(段階)と同語源。「一段ずつ歩む」改革・政策運営のスタイルを指す。","collocations":["policy gradualism","a strategy of gradualism","favor gradualism"]},"automatic stabilizer":{"example2":"Unemployment insurance works as an automatic stabilizer during recessions.","exampleJa2":"失業保険は景気後退期に自動安定化装置として機能する。","origin":"automatic(ギリシャ語autos=自ら+matos=動く)+stabilizer(ラテン語stabilis=安定した)。新たな立法なしに「自動で」経済や制度を安定させる仕組み。","collocations":["act as an automatic stabilizer","fiscal automatic stabilizers","built-in automatic stabilizers"]},"rotation":{"example2":"Sector rotation into defensives often signals late-cycle caution.","exampleJa2":"ディフェンシブ銘柄へのセクターローテーションは、景気サイクル後期の警戒感を示すことが多い。","origin":"ラテン語rotare(回す)←rota(車輪)。車輪が回るように資金がセクター間を循環するイメージ。rotate, rotaryと同語源。","collocations":["sector rotation","rotation out of tech","rotation into value"]},"hawkishness":{"example2":"Growing hawkishness among board members pushed bond yields higher.","exampleJa2":"理事たちの間で強まるタカ派姿勢が債券利回りを押し上げた。","origin":"hawk(タカ)+-ish(〜的)+-ness(性質)。獲物に厳しく襲いかかるタカ=インフレに厳しい引き締め派。対義語はdove(ハト派)。","collocations":["central bank hawkishness","a shift toward hawkishness"]},"bear-market territory":{"example2":"Small caps entered bear-market territory well before large caps did.","exampleJa2":"小型株は大型株よりかなり早く弱気相場圏入りした。","origin":"bear(クマ)は爪を上から下に振り下ろす→下落相場の象徴。直近高値から20%下落した領域(territory)を指す定型表現。","collocations":["enter bear-market territory","slip into bear-market territory"]},"batter":{"example2":"The peso was battered by capital flight after the election.","exampleJa2":"選挙後の資本流出でペソは打ちのめされた。","origin":"古フランス語batre(打つ)の反復形→「何度も打つ」。野球のバッター、料理のbatter(かき混ぜた生地)も同語源。受身のbe batteredで頻出。","collocations":["battered by losses","batter the currency"]},"commensurate":{"example2":"Fees should be commensurate with the value the adviser provides.","exampleJa2":"手数料はアドバイザーが提供する価値に見合ったものであるべきだ。","origin":"ラテン語com(共に)+mensura(測る)→「同じ物差しで測れる」。measure(測定)と同語源。commensurate with〜の形で使う。","collocations":["commensurate with risk","commensurate returns"]},"monetization":{"example2":"Investors questioned the monetization strategy behind the free app.","exampleJa2":"投資家はその無料アプリの裏にある収益化戦略に疑問を呈した。","origin":"ラテン語moneta(貨幣。ローマの造幣所があったユノ・モネタ神殿に由来)+-ize+-ation。「お金に変えるプロセス」。money, mintと同語源。","collocations":["AI monetization","monetization strategy","path to monetization"]},"uncompromising":{"example2":"The regulator took an uncompromising line on disclosure violations.","exampleJa2":"規制当局は情報開示違反に対して妥協しない路線を取った。","origin":"un(否定)+compromise(com共に+promise約束する→互いに譲る)+ing。「互いに譲り合うことをしない」→断固たる。","collocations":["uncompromising stance","uncompromising commitment"]},"repricing":{"example2":"Credit markets saw a violent repricing of default risk in March.","exampleJa2":"3月のクレジット市場ではデフォルトリスクの激しい織り込み直しが起きた。","origin":"re(再び)+price(値付けする)+ing。市場が前提の変化を受けて資産価格や期待を「付け直す」こと。金融市場の定番用語。","collocations":["repricing of rate expectations","a sharp repricing"]},"stem from":{"example2":"The fund's underperformance stemmed from a single concentrated bet.","exampleJa2":"そのファンドの不振は、たった一つの集中投資に起因していた。","origin":"stem(植物の茎・幹)から。「茎をたどれば根に行き着く」→結果から原因へ遡るイメージ。stem from＝〜から生じる。","collocations":["stem from a misunderstanding","problems stemming from debt"]},"specter":{"example2":"The specter of a currency crisis loomed over emerging markets.","exampleJa2":"通貨危機の影が新興国市場に忍び寄っていた。","origin":"ラテン語spectrum(見えるもの、幻影)←specere(見る)。spectacle, inspectと同語源。「亡霊のようにつきまとう嫌な可能性」。","collocations":["raise the specter of","the specter of recession"]},"sobering":{"example2":"The stress-test results were a sobering reminder of leverage risks.","exampleJa2":"ストレステストの結果は、レバレッジのリスクを思い出させる身の引き締まるものだった。","origin":"sober(しらふの、酔っていない)+ing。「酔いから覚めさせる」→浮かれた気分を冷まし、現実を直視させるという比喩。","collocations":["a sobering reminder","sobering statistics"]},"breadth":{"example2":"Narrow breadth means a handful of mega-caps drive the index.","exampleJa2":"裾野の狭さは、一握りの超大型株が指数を動かしていることを意味する。","origin":"broad(広い)の名詞形(broadのd→th変化。deep→depth、long→lengthと同じパターン)。市場では「上昇に参加する銘柄の広がり」。","collocations":["market breadth","breadth of the rally","narrow breadth"]},"catch a cold":{"example2":"Half the sales team caught a cold before the quarterly meeting.","exampleJa2":"四半期会議の前に営業チームの半分が風邪をひいた。","origin":"catchは「捕まえる」。病気を空中から“捕まえて”もらってしまうイメージ。病気系はcatchやgetと相性が良い。","collocations":["catch a bad cold","catch a cold from someone","avoid catching a cold"]},"wear someone down":{"example2":"Endless client complaints slowly wore the support staff down.","exampleJa2":"終わりのない顧客からの苦情が、サポート担当者たちを徐々に疲弊させた。","origin":"wear downは「すり減らす」。靴底が少しずつすり減るように、人の体力や気力が摩耗していくイメージ。","collocations":["wear down resistance","slowly wear someone down","worn down by stress"]},"kick the habit":{"example2":"After the health checkup, our director finally kicked the habit of late-night snacks.","exampleJa2":"健康診断のあと、部長はついに夜食の習慣を断った。","origin":"kickは「蹴り飛ばす」。まとわりつく悪習を足で蹴って追い払うイメージ。元は麻薬中毒からの離脱を指した俗語。","collocations":["kick the smoking habit","finally kick the habit","help someone kick the habit"]},"pick up a habit":{"example2":"Working from home, many traders picked up the habit of checking markets at midnight.","exampleJa2":"在宅勤務で、多くのトレーダーが深夜に市場をチェックする習慣が身についた。","origin":"pick upは「拾い上げる」。道端で物を拾うように、意図せず習慣を“拾って”しまうイメージ。良い習慣にも悪い習慣にも使う。","collocations":["pick up a bad habit","pick up the habit of","habits picked up in childhood"]},"go cold turkey":{"example2":"She deleted every trading app and went cold turkey on day trading.","exampleJa2":"彼女はすべての取引アプリを削除し、デイトレードをきっぱりやめた。","origin":"薬物を突然断った際の鳥肌が冷えた七面鳥の皮に似ることから。段階的でなく“一気に断つ”のが核心イメージ。","collocations":["go cold turkey on caffeine","quit cold turkey","go cold turkey overnight"]},"cut down on":{"example2":"The fund manager cut down on unnecessary meetings to focus on research.","exampleJa2":"そのファンドマネージャーは調査に集中するため、不要な会議を減らした。","origin":"cut down は木を「切り倒す」が原義。量をばっさり切って低くするイメージ。onの後に減らす対象が来る。","collocations":["cut down on expenses","cut down on sugar","cut down on screen time"]},"fall ill":{"example2":"The CEO suddenly fell ill and the earnings call was postponed.","exampleJa2":"CEOが突然体調を崩し、決算説明会は延期された。","origin":"fallは「落ちる」。健康な状態から病気の状態へ“転落する”イメージ。fall asleep（眠りに落ちる）と同じ発想。","collocations":["fall seriously ill","fall ill with flu","suddenly fall ill"]},"pay off":{"example2":"Years of studying English finally paid off when she led the global deal.","exampleJa2":"長年の英語学習は、彼女がグローバル案件を主導したときについに報われた。","origin":"元は「借金を完済する」。積み重ねた努力という“投資”が、利益となって返ってくるイメージで覚える。","collocations":["hard work pays off","the gamble paid off","pay off in the long run"]},"drive a hard bargain":{"example2":"The pension fund drives a hard bargain on management fees every year.","exampleJa2":"その年金基金は毎年、運用報酬について厳しい条件で交渉する。","origin":"driveは「押し進める」、bargainは「取引」。自分に有利な条件まで取引をぐいぐい押し込むイメージ。","collocations":["drive a hard bargain with suppliers","known to drive a hard bargain","drive a hard bargain over price"]},"refuse to budge":{"example2":"The seller refused to budge on price despite three counteroffers.","exampleJa2":"売り手は3度の対案にもかかわらず、価格を一切譲らなかった。","origin":"budgeは「わずかに動く」。否定文で使うのが定番で、“ミリも動かない”頑固さを表す。巨岩が押しても動かない絵で覚える。","collocations":["refuse to budge on price","won't budge an inch","refuse to budge from one's position"]},"at stake":{"example2":"Billions in client assets were at stake during the system outage.","exampleJa2":"システム障害の間、数十億の顧客資産が危機にさらされていた。","origin":"stakeは賭け事で掛け金を結ぶ「杭」。杭に縛られた掛け金は勝負次第で失われることから、「失うかもしれない状態」を表す。","collocations":["jobs are at stake","with so much at stake","reputation at stake"]},"find common ground":{"example2":"The sales and compliance teams finally found common ground on the new product.","exampleJa2":"営業部とコンプライアンス部は、新商品についてついに共通点を見いだした。","origin":"直訳は「共通の地面を見つける」。対立する二人が同じ地面に立てる場所を探すイメージ。交渉・外交の定番表現。","collocations":["find common ground on the issue","seek common ground","little common ground between them"]},"meet someone halfway":{"example2":"We met the client halfway by extending the deadline but keeping the fee.","exampleJa2":"私たちは料金は据え置きつつ納期を延ばすことで、顧客に歩み寄った。","origin":"直訳は「中間地点で会う」。互いに半分ずつ歩いて真ん中で落ち合うイメージ。双方が譲る対等な妥協を表す。","collocations":["meet you halfway on price","willing to meet halfway","meet each other halfway"]},"back out":{"example2":"The acquirer backed out of the merger after reviewing the books.","exampleJa2":"買収側は帳簿を精査したあと、合併から手を引いた。","origin":"backは「後ろへ」、outは「外へ」。合意の輪から後ずさりして抜け出すイメージ。土壇場での撤退によく使う。","collocations":["back out of a deal","back out at the last minute","back out of a commitment"]},"strike a deal":{"example2":"The two banks struck a deal to co-manage the bond issuance.","exampleJa2":"2つの銀行は債券発行を共同主幹事とする取引をまとめた。","origin":"strikeは「打つ」。昔の商人が手を打ち合わせて合意を確定したことから。日本語の「手を打つ」と同じ発想で覚えやすい。","collocations":["strike a deal with","strike a last-minute deal","strike a bargain"]},"race against the clock":{"example2":"The settlement team raced against the clock to process trades before cutoff.","exampleJa2":"決済チームは締め時刻前に取引を処理しようと時間と競争した。","origin":"直訳は「時計と競走する」。相手は人ではなく時計＝制限時間。針が進む前にゴールへ駆け込むイメージ。","collocations":["race against the clock to finish","in a race against time","racing the clock"]},"buy time":{"example2":"The CFO requested more documents just to buy time before the board vote.","exampleJa2":"CFOは取締役会の採決前に時間を稼ぐため、追加資料を要求した。","origin":"直訳は「時間を買う」。お金で物を買うように、別の行動と引き換えに猶予を手に入れるイメージ。日本語の「時間を稼ぐ」に対応。","collocations":["buy some time","buy time to think","a tactic to buy time"]},"cut corners":{"example2":"Auditors found the vendor had cut corners on security testing.","exampleJa2":"監査人は、その業者がセキュリティテストで手を抜いていたことを発見した。","origin":"曲がり角を直角に曲がらず斜めに突っ切る（＝近道する）イメージ。距離は縮むが本来の手順を省くため品質が犠牲になる。","collocations":["cut corners on quality","cut corners to save money","no cutting corners"]},"backfire":{"example2":"The aggressive discount campaign backfired and cheapened the brand image.","exampleJa2":"強気の値引きキャンペーンは裏目に出て、ブランドイメージを安っぽくした。","origin":"back（後ろへ）+fire（発火）。銃やエンジンが前でなく手元側で爆発する故障が原義。狙いと逆方向に被害が出るイメージ。","collocations":["the plan backfired","backfire badly","backfire on someone"]},"pull an all-nighter":{"example2":"The IPO team pulled an all-nighter to finalize the prospectus.","exampleJa2":"IPOチームは目論見書を仕上げるために徹夜した。","origin":"all-nighterは「夜通しの作業」を名詞化した学生スラング。pullは「やってのける」のくだけた用法。pull a prank（いたずらする）と同じ型。","collocations":["pull an all-nighter before the exam","pull two all-nighters","survive an all-nighter"]},"beat the deadline":{"example2":"We beat the deadline and filed the report two days early.","exampleJa2":"私たちは締め切りより早く、2日前倒しで報告書を提出した。","origin":"beatは「打ち負かす」。締め切りを競争相手に見立て、先にゴールして“勝つ”イメージ。beat the traffic（渋滞を避ける）も同じ型。","collocations":["beat the deadline by two days","work hard to beat the deadline","just beat the deadline"]},"hold a grudge":{"example2":"Clients rarely hold a grudge if you admit mistakes quickly and fix them.","exampleJa2":"ミスを素早く認めて修正すれば、顧客が恨みを抱き続けることはめったにない。","origin":"holdは「持ち続ける」、grudgeは「恨み」。過去の怒りを手放さず、ずっと抱え歩くイメージ。against～で相手を示す。","collocations":["hold a grudge against someone","still holding a grudge","not one to hold grudges"]},"make the first move":{"example2":"In salary talks, letting the other side make the first move can help.","exampleJa2":"給与交渉では、相手に先に動いてもらうのが有利に働くことがある。","origin":"チェスの「先手を打つ」が原義。膠着した場面で最初の一手を指す勇気を表す。恋愛でも交渉でも和解でも使える万能表現。","collocations":["make the first move toward peace","wait for someone to make the first move","afraid to make the first move"]},"clear the air":{"example2":"The manager called a meeting to clear the air after the bonus dispute.","exampleJa2":"賞与をめぐる対立のあと、部長は空気を一新するため会議を招集した。","origin":"直訳は「空気を澄ませる」。雷雨が過ぎると空気が澄むように、率直に話すことでよどんだ雰囲気を洗い流すイメージ。","collocations":["clear the air between us","a chance to clear the air","clear the air with a talk"]},"reach out":{"example2":"Feel free to reach out to our desk if you have questions about the fund.","exampleJa2":"ファンドについてご質問があれば、お気軽に当デスクまでご連絡ください。","origin":"直訳は「手を伸ばす」。物理的に腕を差し出す動作が、連絡・支援・歩み寄りの比喩に発展。ビジネスメールの定番語。","collocations":["reach out to a colleague","don't hesitate to reach out","reach out for help"]},"see eye to eye":{"example2":"The portfolio managers don't always see eye to eye on risk levels.","exampleJa2":"ポートフォリオマネージャーたちは、リスク水準について必ずしも意見が一致するわけではない。","origin":"直訳は「目と目を合わせて見る」。同じ高さの目線で同じ景色を見る＝考えが揃うイメージ。否定文で使われることが多い。","collocations":["see eye to eye on everything","rarely see eye to eye","see eye to eye with the boss"]},"mend fences":{"example2":"After the failed joint venture, both firms worked to mend fences.","exampleJa2":"合弁事業の失敗後、両社は関係の修復に努めた。","origin":"直訳は「柵を修理する」。隣人との境界の柵を直しに行きがてら仲直りする、農村の情景から。壊れた仲を修繕するイメージ。","collocations":["mend fences with a rival","try to mend fences","time to mend fences"]},"bury the hatchet":{"example2":"The two founders buried the hatchet and rebuilt the partnership.","exampleJa2":"二人の創業者は和解し、パートナーシップを再構築した。","origin":"hatchetは「手斧」。ネイティブアメリカンが和平の証に武器の斧を地中に埋めた儀式に由来。武器を葬る＝戦いの終わり。","collocations":["bury the hatchet with someone","finally bury the hatchet","agree to bury the hatchet"]},"water under the bridge":{"example2":"The pricing dispute from last quarter is water under the bridge now.","exampleJa2":"前四半期の価格をめぐる争いは、今となっては過ぎ去ったことだ。","origin":"直訳は「橋の下の水」。一度橋の下を流れた水は二度と戻らないことから、済んだことは蒸し返さないという発想。","collocations":["it's all water under the bridge","that's water under the bridge now","let it be water under the bridge"]},"weigh one's options":{"example2":"Before rebalancing the portfolio, the committee weighed its options carefully.","exampleJa2":"ポートフォリオを再調整する前に、委員会は選択肢を慎重に比較検討した。","origin":"weighは「重さを量る」。天秤の両皿に選択肢を載せ、どちらが重い（価値がある）か量るイメージ。決断前の熟考を表す。","collocations":["weigh your options carefully","take time to weigh the options","weigh all available options"]},"follow one's gut":{"example2":"The veteran trader followed his gut and closed the position early.","exampleJa2":"そのベテラントレーダーは直感に従い、早めにポジションを閉じた。","origin":"gutは「腸・腹」。英語では直感は頭でなく“腹”に宿るとされる。日本語の「腹をくくる」「腹の底」と近い身体感覚。","collocations":["follow your gut instinct","trust your gut","go with your gut feeling"]},"sit on the fence":{"example2":"Analysts accused the central bank of sitting on the fence about rate cuts.","exampleJa2":"アナリストたちは、中央銀行が利下げについて態度を保留していると批判した。","origin":"直訳は「柵の上に座る」。柵の右側にも左側にも降りず、境界線上に留まるイメージ。どっちつかずの中立を皮肉る表現。","collocations":["sit on the fence about the issue","stop sitting on the fence","fence-sitting politicians"]},"sleep on it":{"example2":"The offer looks fine, but let me sleep on it and reply tomorrow.","exampleJa2":"その提案は良さそうですが、一晩考えて明日お返事させてください。","origin":"直訳は「その上で眠る」。決断事項を枕の下に置いて眠るイメージ。一晩置くと頭が整理されるという生活の知恵が語源。","collocations":["sleep on it before deciding","let me sleep on it","sleep on the decision"]},"make up one's mind":{"example2":"Investors must make up their minds before the subscription window closes.","exampleJa2":"投資家は申込期間が締め切られる前に決断しなければならない。","origin":"make upは「組み立てる」。迷ってバラバラだった心を一つに組み上げ、完成させるイメージ。完成＝決心の確定。","collocations":["make up your mind quickly","can't make up my mind","made up her mind to quit"]},"have second thoughts":{"example2":"After reading the fine print, she had second thoughts about the contract.","exampleJa2":"細則を読んだあと、彼女はその契約について迷いが生じた。","origin":"直訳は「2度目の考えを持つ」。最初の決断のあとに浮かぶ“2番目の考え”＝疑念。on second thought（考え直すと）も頻出。","collocations":["have second thoughts about the deal","without a second thought","start having second thoughts"]},"leap of faith":{"example2":"Backing an unproven startup was a leap of faith for the conservative fund.","exampleJa2":"実績のないスタートアップへの出資は、その保守的なファンドにとって思い切った賭けだった。","origin":"leapは「跳躍」、faithは「信じる心」。結果が見えない崖の向こうへ、信じて跳ぶイメージ。哲学者キルケゴールの概念が広まった表現。","collocations":["take a leap of faith","a huge leap of faith","require a leap of faith"]},"foot the bill":{"example2":"Ultimately, taxpayers footed the bill for the bank bailout.","exampleJa2":"最終的に、銀行救済の費用を負担したのは納税者だった。","origin":"footは請求書の「末尾（foot＝足元）」の合計欄のこと。伝票の一番下の合計金額に責任を持つ＝全額支払うイメージ。","collocations":["foot the bill for dinner","the company foots the bill","left to foot the bill"]},"cut costs":{"example2":"The asset manager cut costs by moving its back office overseas.","exampleJa2":"その運用会社はバックオフィスを海外に移して経費を削減した。","origin":"直訳は「費用を切る」。膨らんだコストをはさみでばっさり切り落とすイメージ。cost-cutting（経費削減）の形でも頻出。","collocations":["cut costs drastically","cut operating costs","cost-cutting measures"]},"make a dent in":{"example2":"The new fee structure barely made a dent in overall expenses.","exampleJa2":"新しい手数料体系は、全体の費用をほとんど減らせなかった。","origin":"dentは車のボディの「へこみ」。巨大な塊にガツンと当てて目に見えるへこみを作るイメージ。借金・在庫・仕事の山に使う。","collocations":["make a dent in the debt","barely make a dent","make a dent in the workload"]},"break the bank":{"example2":"Upgrading the software won't break the bank for a firm our size.","exampleJa2":"当社の規模なら、ソフトの更新で家計が圧迫されるほどの大金はかからない。","origin":"カジノで客が勝ちすぎて胴元（bank）の資金が尽きることが原義。否定文で「大金はかからない」と使うのが定番。","collocations":["won't break the bank","without breaking the bank","a gift that doesn't break the bank"]},"for a rainy day":{"example2":"Our advisor suggests keeping six months of salary for a rainy day.","exampleJa2":"私たちのアドバイザーは、万一に備えて給料6か月分を取っておくよう勧めている。","origin":"直訳は「雨の日のために」。英語では雨の日＝困難な時期の象徴。晴れのうちに雨に備えて蓄えるイメージ。saveと相性抜群。","collocations":["save for a rainy day","put money aside for a rainy day","a rainy-day fund"]},"live within one's means":{"example2":"Even after his promotion, he kept living within his means.","exampleJa2":"昇進したあとも、彼は収入の範囲内での生活を続けた。","origin":"meansは「資力・収入」。withinは「枠の内側」。収入という枠の内側に支出を収めるイメージ。反対はbeyond one's means。","collocations":["learn to live within your means","live beyond one's means","live comfortably within one's means"]},"climb the corporate ladder":{"example2":"She climbed the corporate ladder from teller to branch manager in ten years.","exampleJa2":"彼女は10年で窓口係から支店長へと出世の階段を上った。","origin":"直訳は「会社のはしごを登る」。組織の階層を、はしごの段を一段ずつ登る姿にたとえた定番メタファー。","collocations":["climb the career ladder","move up the corporate ladder","the bottom rung of the ladder"]},"dead-end job":{"example2":"He felt stuck in a dead-end job with no new skills to gain.","exampleJa2":"彼は新しく学べるスキルもない、先の見えない仕事で行き詰まりを感じていた。","origin":"dead endは「行き止まり」。道路標識のDEAD ENDから。その先に道（昇進・成長）が続いていない仕事のイメージ。","collocations":["stuck in a dead-end job","quit a dead-end job","a dead-end career"]},"hand in one's notice":{"example2":"After securing the new role, he handed in his notice on Monday.","exampleJa2":"新しい職を確保したあと、彼は月曜に退職届を出した。","origin":"hand inは「手渡して提出する」、noticeは「予告・通知」。退職予告の紙を上司に手渡す動作がそのまま表現になった。","collocations":["hand in your notice","give two weeks' notice","hand in one's resignation"]},"burn bridges":{"example2":"Criticizing your old employer online is a sure way to burn bridges.","exampleJa2":"ネットで前の勤務先を批判するのは、確実に関係を断ち切る行為だ。","origin":"軍隊が渡った橋を焼き、退路を断って進んだ故事から。戻り道（元の関係）を自ら焼き払うイメージ。転職文脈で頻出。","collocations":["burn bridges with former employers","don't burn your bridges","burn all one's bridges"]},"career move":{"example2":"Taking the overseas posting was a bold but rewarding career move.","exampleJa2":"海外赴任を引き受けたのは大胆だが実り多いキャリア上の一手だった。","origin":"moveはチェスの「一手」。キャリアを盤面に見立て、転職や異動を次の一手として指すイメージ。smart/bold moveと相性が良い。","collocations":["a smart career move","a risky career move","plan your next career move"]},"land a job":{"example2":"She landed a job at a top asset management firm right after graduation.","exampleJa2":"彼女は卒業後すぐに大手運用会社での職を勝ち取った。","origin":"landは釣った魚を「陸に揚げる」こと。応募という釣りの末に、獲物（内定）をついに引き揚げるイメージ。land a dealも同じ型。","collocations":["land a dream job","land a job interview","land a big contract"]},"step out of one's comfort zone":{"example2":"Presenting in English pushed me to step out of my comfort zone.","exampleJa2":"英語でのプレゼンは、私を慣れた領域から踏み出させてくれた。","origin":"comfort zoneは「快適な領域」。ぬるま湯の円の外へ一歩踏み出す図で覚える。成長は円の外にある、という自己啓発の定番。","collocations":["step outside your comfort zone","push someone out of their comfort zone","stay in one's comfort zone"]},"pick up a skill":{"example2":"She picked up basic Python to automate her daily fund reports.","exampleJa2":"彼女は日々のファンドレポートを自動化するため、Pythonの基礎を身につけた。","origin":"pick upは「拾い上げる」。教室で正式に学ぶというより、道具を拾うように気軽に技能を習得するニュアンスがある。","collocations":["pick up a new language","pick up skills on the job","quick to pick up new skills"]},"from scratch":{"example2":"The team rebuilt the risk model from scratch after the audit.","exampleJa2":"監査のあと、チームはリスクモデルを一から作り直した。","origin":"scratchは競走で地面に引いた「スタート線」。ハンデなしの線から走る＝何もない地点から始めるイメージ。料理や開発で頻出。","collocations":["start from scratch","build from scratch","bake a cake from scratch"]},"brush up on":{"example2":"Before the client visit, brush up on the fund's performance figures.","exampleJa2":"顧客訪問の前に、ファンドの運用実績の数字を復習しておきなさい。","origin":"brush upは「ブラシで磨き直す」。ほこりをかぶった知識をブラシでこすり、輝きを取り戻すイメージ。onの後に対象が来る。","collocations":["brush up on your English","brush up on the basics","brush up before the exam"]},"learn the ropes":{"example2":"New analysts spend the first quarter learning the ropes of the trading desk.","exampleJa2":"新人アナリストは最初の四半期をトレーディングデスクの要領を覚えることに費やす。","origin":"帆船時代、新人水夫が無数のロープの扱いを覚えたことから。仕事の“綱さばき”＝基本手順を覚えるイメージ。","collocations":["learn the ropes quickly","show someone the ropes","still learning the ropes"]},"get up to speed":{"example2":"Please get up to speed on the new regulations before Friday's briefing.","exampleJa2":"金曜の説明会までに新しい規制について習熟しておいてください。","origin":"up to speedは「規定速度に達して」。合流車線で本線の流れの速さに追いつくイメージ。人にも知識にもシステムにも使う。","collocations":["get up to speed quickly","bring someone up to speed","get up to speed on the project"]},"keep at it":{"example2":"Cold calls are tough, but keep at it and the numbers will improve.","exampleJa2":"電話営業はつらいが、根気よく続ければ数字は改善する。","origin":"at itは「その作業に取り組んで」。keepで「その状態を保て」＝手を止めるな。励ましの決まり文句として丸ごと覚える。","collocations":["keep at it every day","just keep at it","keep at it until it works"]},"play it safe":{"example2":"Given the volatile market, the fund played it safe with short-term bonds.","exampleJa2":"不安定な市場を踏まえ、そのファンドは短期債で安全策を取った。","origin":"野球で無理な進塁をせず確実にプレーすることから。itは状況全般。冒険せず手堅い選択肢を取るイメージ。","collocations":["play it safe with investments","decide to play it safe","better to play it safe"]},"weigh the pros and cons":{"example2":"The committee weighed the pros and cons of hedging the currency exposure.","exampleJa2":"委員会は為替エクスポージャーをヘッジすることの長所と短所を比較検討した。","origin":"prosとconsはラテン語のpro（賛成）とcontra（反対）。賛成材料と反対材料を天秤の両皿に載せて量るイメージ。","collocations":["weigh the pros and cons carefully","list the pros and cons","discuss the pros and cons"]},"err on the side of caution":{"example2":"When valuing illiquid assets, we always err on the side of caution.","exampleJa2":"流動性の低い資産を評価する際、私たちは常に慎重なほうに倒す。","origin":"errは「誤る」。どうせ誤るなら慎重側に誤れ、という発想。危険側と安全側の分かれ道で、あえて安全側に寄るイメージ。","collocations":["err on the side of caution and wait","always err on the side of caution","err on the side of safety"]},"take a gamble":{"example2":"The firm took a gamble by entering the emerging market early.","exampleJa2":"その会社は早期に新興市場へ参入するという賭けに出た。","origin":"gambleは「賭博」。結果は運任せと知りつつ、勝ちを狙ってチップを置くイメージ。take a risk より当たり外れの大きさを強調。","collocations":["take a gamble on a startup","a gamble that paid off","take a big gamble"]},"hedge one's bets":{"example2":"The fund hedged its bets by holding both growth and value stocks.","exampleJa2":"そのファンドはグロース株とバリュー株の両方を保有してリスクを分散した。","origin":"hedgeは「生け垣＝防護壁」。賭けを複数に分けて損失の壁を作ることから。金融の「ヘッジ」もこの語。一点張りの逆。","collocations":["hedge your bets by diversifying","hedge one's bets on the outcome","no need to hedge your bets"]},"safety net":{"example2":"Deposit insurance works as a safety net for ordinary savers.","exampleJa2":"預金保険は一般の預金者にとっての安全網として機能する。","origin":"サーカスの空中ブランコの下に張る「安全ネット」が原義。落ちても受け止めてくれる備えの比喩。社会保障や貯蓄に使う。","collocations":["a financial safety net","social safety net","act as a safety net"]},"lose one's train of thought":{"example2":"Sorry, the phone call made me lose my train of thought completely.","exampleJa2":"すみません、電話のせいで話の流れをすっかり見失ってしまいました。","origin":"train は「列車」ではなく「連なり」。思考が貨車のように連結して進むイメージで、その連結が外れる＝考えが途切れる。","collocations":["completely lose my train of thought","lose your train of thought mid-sentence","regain one's train of thought"]},"get one's point across":{"example2":"Use charts in the client meeting to get your point across quickly.","exampleJa2":"顧客との会議では、図表を使って言いたいことを素早く伝えましょう。","origin":"across は「向こう側へ渡す」イメージ。自分の要点(point)を川の対岸にいる相手まで届ける、と覚える。","collocations":["get the point across clearly","struggle to get his point across","get the message across"]},"hold someone's attention":{"example2":"A strong opening slide will hold the investors' attention until the end.","exampleJa2":"冒頭のスライドが強力なら、最後まで投資家の関心をつかんでおけます。","origin":"hold は「握って離さない」。聴衆の注意(attention)を手のひらでぎゅっと握り続けるイメージで覚える。","collocations":["hold the audience's attention","hold their attention for long","fail to hold my attention"]},"paint a picture":{"example2":"The quarterly report paints a worrying picture of consumer spending trends.","exampleJa2":"四半期レポートは、個人消費の動向について憂慮すべき状況を描き出しています。","origin":"言葉で絵を描く、が直訳。数字や事実を並べるだけでなく、聞き手の頭にカラーの絵が浮かぶよう語るイメージ。","collocations":["paint a clear picture","paint a grim picture","paint a picture of the future"]},"drive home":{"example2":"The CEO repeated the sales figures twice to drive home the urgency.","exampleJa2":"CEOは緊急性を強く印象づけるため、売上の数字を2度繰り返しました。","origin":"drive は釘を「打ち込む」、home は「奥まで完全に」。要点を釘のように相手の頭へ深く打ち込むイメージ。","collocations":["drive home the point","drive the message home","drive home the importance of"]},"strike a chord":{"example2":"Her speech about work-life balance struck a chord with young employees.","exampleJa2":"ワークライフバランスについての彼女のスピーチは、若手社員の共感を呼びました。","origin":"chord は和音。心の中の弦をポロンと鳴らす＝相手の感情がまさに共鳴する、という音楽のイメージ。","collocations":["strike a chord with the audience","really struck a chord","strike a familiar chord"]},"off the cuff":{"example2":"I can't quote exact returns off the cuff, but I'll check.","exampleJa2":"正確なリターンの数字は即答できませんが、確認しておきます。","origin":"cuff は袖口。昔の講演者がシャツの袖口に走り書きしたメモだけで話したことから「準備なしで」の意味に。","collocations":["speak off the cuff","an off-the-cuff remark","answer off the cuff"]},"ping":{"example2":"Ping me on Teams once the compliance team approves the draft.","exampleJa2":"コンプライアンス部の承認が下りたら、Teamsで一報ください。","origin":"潜水艦のソナー音「ピン」が語源。ネットワーク疎通確認のpingコマンドを経て「軽く連絡する」の意味に。","collocations":["ping me later","ping the team on Slack","just ping me anytime"]},"touch base":{"example2":"Let's touch base next week about the fund's rebalancing schedule.","exampleJa2":"ファンドのリバランス日程について、来週軽くすり合わせましょう。","origin":"野球でランナーが塁(base)に一瞬タッチする動きが語源。深入りせず、要点だけ軽く確認し合うイメージ。","collocations":["touch base with the client","touch base next week","let's touch base soon"]},"in the weeds":{"example2":"I'm in the weeds preparing NAV reports, can we talk tomorrow?","exampleJa2":"基準価額のレポート作成で手一杯なので、明日話せますか。","origin":"背の高い雑草(weeds)の中で足を取られ、周りが見えない状態。細部に埋もれて全体を見失うイメージ。","collocations":["totally in the weeds","get into the weeds","deep in the weeds with paperwork"]},"hard stop":{"example2":"Let's start on time because I have a hard stop at three.","exampleJa2":"3時には絶対抜けないといけないので、時間通りに始めましょう。","origin":"hard は「動かせない・固い」。ソフトに延ばせる終了ではなく、壁のように固定された終了時刻というイメージ。","collocations":["have a hard stop at noon","a hard stop in ten minutes","hit a hard stop"]},"strapped for cash":{"example2":"Many startups are strapped for cash until their next funding round closes.","exampleJa2":"多くのスタートアップは、次の資金調達が完了するまで資金繰りが苦しいものです。","origin":"strap(革ひも)で縛られたように身動きが取れない状態。財布がベルトで締め上げられているイメージで覚える。","collocations":["a bit strapped for cash","strapped for cash this month","cash-strapped companies"]},"living paycheck to paycheck":{"example2":"Rising rents leave many families living paycheck to paycheck despite steady jobs.","exampleJa2":"家賃の上昇で、安定した仕事があっても給料ぎりぎりの生活の家庭が多いのです。","origin":"paycheck(給料)から次のpaycheckへ綱渡りする直訳イメージ。貯金ゼロで給料日をジャンプでつなぐ絵で覚える。","collocations":["live paycheck to paycheck","families living paycheck to paycheck","stuck paycheck to paycheck"]},"ball on a budget":{"example2":"Her travel blog shows readers how to ball on a budget abroad.","exampleJa2":"彼女の旅行ブログは、海外で低予算でも贅沢気分を味わう方法を紹介しています。","origin":"ball はスラングで「豪遊する」。budget(限られた予算)で豪遊気分を出す、という対比の面白さで覚える。","collocations":["ball on a budget","balling on a budget tips","look rich on a budget"]},"chip in":{"example2":"The whole team chipped in to buy our retiring manager a watch.","exampleJa2":"チーム全員でお金を出し合って、退職する部長に腕時計を贈りました。","origin":"ポーカーで各自がチップ(chip)を場に投げ入れる動きが語源。皆が少しずつ場に出し合うイメージ。","collocations":["chip in for the gift","everyone chipped in","chip in a few dollars"]},"penny pincher":{"example2":"Being a penny pincher helped him retire ten years earlier than planned.","exampleJa2":"極度の倹約家だったおかげで、彼は予定より10年早くリタイアできました。","origin":"penny(1セント硬貨)をpinch(つまむ)、つまり最小単位の硬貨すら指でつまんで離さない人、という直訳イメージ。","collocations":["a real penny pincher","penny-pinching habits","known as a penny pincher"]},"w":{"example2":"Landing that big corporate client was a massive W for our branch.","exampleJa2":"あの大口法人顧客を獲得できたのは、我々の支店にとって大きな勝利でした。","origin":"Win の頭文字。スポーツの勝敗表のW/L欄から。発音は「ダブ」(double-uの短縮)なのが通っぽいポイント。","collocations":["a huge W","take the W","big W for the team"]},"l":{"example2":"Forgetting my laptop on presentation day was a serious L.","exampleJa2":"プレゼン当日にノートPCを忘れたのは、かなり痛い失態でした。","origin":"Loss の頭文字。勝敗表のL欄から。「take the L(負けを受け入れる)」の形でよく使うとセットで覚える。","collocations":["take the L","a major L","catch an L"]},"elite":{"example2":"The coffee from that tiny kiosk near the office is elite.","exampleJa2":"オフィス近くの小さな売店のコーヒー、あれは別格です。","origin":"本来は「選ばれた精鋭」。スラングでは食べ物や曲など身近なものに使い「トップクラスにうまい」を表す。","collocations":["elite taste","an elite combo","that meal was elite"]},"peak":{"example2":"Watching the sunrise from Mount Fuji is peak Japan travel.","exampleJa2":"富士山から日の出を見るのは、日本旅行の最高峰の体験です。","origin":"山の頂上(peak)が原義。「これ以上高い所はない」＝ジャンルの頂点・最高傑作、と山の絵で覚える。","collocations":["peak performance","peak comedy","this is peak fiction"]},"goated":{"example2":"Our analyst is goated at spotting market trends before anyone else.","exampleJa2":"うちのアナリストは、誰よりも早く市場トレンドを見抜く天才級の腕前です。","origin":"GOAT(Greatest Of All Time＝史上最高)を形容詞化した語。ヤギの絵文字とセットで褒め言葉に使われる。","collocations":["goated at math","absolutely goated","a goated performance"]},"clears":{"example2":"For me, the Tokyo office cafeteria clears every restaurant nearby.","exampleJa2":"私に言わせれば、東京オフィスの社食は近隣のどのレストランも圧倒しています。","origin":"ハードルをclear(余裕で飛び越える)イメージ。比較対象の上を軽々と越えていく＝圧勝、と覚える。","collocations":["clears the competition","easily clears the original","this version clears"]},"different":{"example2":"Her closing pitch to hesitant clients is just different.","exampleJa2":"迷っている顧客への彼女のクロージングトークは、まさに次元が違います。","origin":"普通の「異なる」が、スラングでは「他と比べようがないほど別次元」という最大級の褒め言葉に変化した。","collocations":["he's just different","built different","that performance was different"]},"wiped":{"example2":"After back-to-back client visits all week, I was completely wiped.","exampleJa2":"1週間ぶっ通しの顧客訪問続きで、完全にくたくたでした。","origin":"wipe(拭き取る)から。体力が雑巾で拭き取られたように残っていない、エネルギー残量ゼロのイメージ。","collocations":["completely wiped","wiped out after work","feeling wiped"]},"beat":{"example2":"I'm beat after presenting to three branches in one day.","exampleJa2":"1日で3つの支店を回ってプレゼンしたので、もうへとへとです。","origin":"beat(叩く)の過去分詞。1日じゅう叩かれ続けたようにボロボロ、という受け身のイメージで覚える。","collocations":["totally beat","I'm beat tonight","dead beat after the shift"]},"crash":{"example2":"He crashed at his desk after the all-night system migration.","exampleJa2":"徹夜のシステム移行作業のあと、彼はデスクで力尽きて眠り込みました。","origin":"墜落・衝突のcrash。電池切れの機械がガシャンと落ちるように、意識ごと突然眠りに落ちるイメージ。","collocations":["crash on the couch","crash early tonight","crash at a friend's place"]},"zonked":{"example2":"Jet lag left the whole delegation zonked before the morning session.","exampleJa2":"時差ボケで、代表団全員が午前のセッション前から疲れ果てていました。","origin":"「ゾンク」という擬音由来の俗語。頭を殴られてボーッとしたような、意識が飛びかけの疲労感を表す。","collocations":["totally zonked","zonked out on the sofa","zonked after the flight"]},"out like a light":{"example2":"After the twelve-hour flight, she was out like a light by eight.","exampleJa2":"12時間のフライトのあと、彼女は8時にはあっという間に眠り込んでいました。","origin":"電灯のスイッチを切る(light out)と一瞬で真っ暗になることから。カチッと消灯＝瞬時に熟睡のイメージ。","collocations":["out like a light in seconds","he was out like a light","fall asleep like a light"]},"scorcher":{"example2":"Today's a real scorcher, so the beer garden will be packed.","exampleJa2":"今日は本当にうだるような暑さなので、ビアガーデンは満員になるでしょう。","origin":"scorch(焦がす)＋er。地面や肌が焦げそうな日、という意味。「スコーチ＝焦げる」の音で覚える。","collocations":["a real scorcher","another scorcher today","scorcher of a day"]},"muggy":{"example2":"The trading floor felt muggy after the air conditioning broke down.","exampleJa2":"空調が故障して、トレーディングフロアは蒸し風呂のようでした。","origin":"古語mug(霧雨)由来とされる。湿った空気がまとわりつく感覚。日本の梅雨〜夏の空気そのものと覚える。","collocations":["hot and muggy","a muggy afternoon","muggy summer nights"]},"dog days":{"example2":"Trading volume usually thins out during the dog days of August.","exampleJa2":"8月の酷暑の時期には、取引量はたいてい細ります。","origin":"おおいぬ座のシリウス(Dog Star)が真夏に太陽と共に昇ることから、古代ローマで「犬の日々」と呼ばれた。","collocations":["the dog days of summer","during the dog days","dog days of August"]},"nippy":{"example2":"Mornings are getting nippy, so I keep a cardigan at my desk.","exampleJa2":"朝が肌寒くなってきたので、デスクにカーディガンを置いています。","origin":"nip(軽くかむ・つねる)から。冷気が頬や指先をチクッとつねるような、軽い寒さのイメージ。","collocations":["a bit nippy","nippy in the morning","getting nippy outside"]},"freezing my toes off":{"example2":"We were freezing our toes off watching the New Year sunrise.","exampleJa2":"初日の出を見ながら、私たちは凍えるほど寒い思いをしました。","origin":"「寒さでつま先がもげ落ちる」という大げさな比喩。体のパーツ+offで誇張する英語らしい言い回し。","collocations":["freezing my toes off out here","freeze your toes off","freezing our toes off waiting"]},"bundle up":{"example2":"Bundle up tonight, the client dinner is at an outdoor terrace.","exampleJa2":"今夜は厚着してきてください。顧客との会食は屋外テラスなので。","origin":"bundle は「束・包み」。コートやマフラーで自分を荷物のようにぐるぐる包む、という直訳イメージ。","collocations":["bundle up warm","bundle up before going out","bundle the kids up"]},"coming down":{"example2":"The snow was really coming down when the market closed early.","exampleJa2":"市場が早じまいした頃には、雪が本降りになっていました。","origin":"「(雨雪が)降りてくる」の進行形が「本降り」の定番表現に。空から途切れなくdown、の絵で覚える。","collocations":["the rain is really coming down","snow coming down hard","it's coming down out there"]},"hits the spot":{"example2":"After that marathon meeting, this hot ramen really hits the spot.","exampleJa2":"あの長時間会議のあとでは、この熱々のラーメンがまさに五臓六腑に染みます。","origin":"spot は「まさにその一点」。喉の渇きや空腹という的のど真ん中に、飲食物が命中するイメージ。","collocations":["really hits the spot","that hit the spot","nothing hits the spot like coffee"]},"to die for":{"example2":"The view from the hotel's rooftop bar is to die for.","exampleJa2":"そのホテルの屋上バーからの眺めは、たまらなく魅力的です。","origin":"「そのためなら死んでもいい」という最大級の誇張。日本語の「死ぬほどおいしい」と発想が同じで覚えやすい。","collocations":["a dessert to die for","absolutely to die for","views to die for"]},"chef's kiss":{"example2":"Your final slide summarizing the proposal was chef's kiss.","exampleJa2":"提案を締めくくる最後のスライド、あれは完璧でした。","origin":"シェフが指先にキスして「完璧！」と示すイタリア発祥のジェスチャーから。この仕草の絵ごと覚える。","collocations":["absolutely chef's kiss","the ending was chef's kiss","chef's kiss perfection"]},"food coma":{"example2":"Avoid scheduling client calls right after lunch, or the food coma wins.","exampleJa2":"昼食直後に顧客との電話を入れるのは避けましょう。さもないと食後の眠気に負けます。","origin":"coma は「昏睡」。満腹で意識が昏睡レベルまで落ちる、という医学用語を使った大げさなジョーク表現。","collocations":["fall into a food coma","in a food coma","post-lunch food coma"]},"squad":{"example2":"My college squad still meets every December for a year-end dinner.","exampleJa2":"大学時代の仲良しグループとは、今でも毎年12月に忘年会で集まります。","origin":"軍隊の「分隊」が原義。いつも一緒に行動する少人数の精鋭部隊＝仲良しメンバー、というノリで使われる。","collocations":["squad goals","the whole squad","roll with my squad"]},"roll with":{"example2":"He mostly rolls with coworkers from his first job in Osaka.","exampleJa2":"彼は大阪での最初の職場の同僚たちと、今もよくつるんでいます。","origin":"roll(転がる・走る)から。同じ車に乗って一緒に流す仲間、というアメリカの車文化由来のイメージ。","collocations":["roll with my crew","who do you roll with","roll with the same crowd"]},"bestie":{"example2":"She flew to Korea with her bestie for a weekend trip.","exampleJa2":"彼女は親友と週末の韓国旅行に出かけました。","origin":"best friend を短くかわいくした語。日本語の「親友→ズッ友」のような、砕けた愛称化と覚える。","collocations":["my bestie forever","besties since college","texting my bestie"]},"ride or die":{"example2":"A true ride or die tells you the truth even when it hurts.","exampleJa2":"本物の生涯の相棒は、耳が痛いことでも本当のことを言ってくれます。","origin":"「一緒にバイクに乗るか、さもなくば死ぬ」という誓いが原義。何があっても降りない相棒のイメージ。","collocations":["my ride or die","a ride-or-die friend","ride or die since day one"]},"day one":{"example2":"Before I got promoted, my day ones already believed in me.","exampleJa2":"昇進する前から、昔からの仲間たちはずっと私を信じてくれていました。","origin":"「1日目からいる人」が直訳。売れる前・成功する前の最初期から支えてくれた友、という時間軸で覚える。","collocations":["my day ones","a real day one","day one supporter"]},"have someone's back":{"example2":"Speak up in the meeting; the whole team has your back.","exampleJa2":"会議で堂々と発言してください。チーム全員があなたの味方です。","origin":"戦場で仲間の背後(back)を守る隊形が語源。死角である背中を任せられる関係、というイメージ。","collocations":["I've got your back","always have my back","have each other's backs"]},"steal":{"example2":"At that price, this fund's expense ratio makes it a steal.","exampleJa2":"この価格でこの信託報酬なら、このファンドは破格のお買い得です。","origin":"「盗み」が原義。安すぎて「ほぼ盗んだも同然」という買い手側の喜びの誇張表現として使う。","collocations":["an absolute steal","such a steal","a steal at that price"]},"treat yourself":{"example2":"Bonus season is here, so treat yourself to that nice watch.","exampleJa2":"ボーナスの季節ですから、憧れの腕時計で自分にご褒美をあげましょう。","origin":"treat は「もてなす・おごる」。他人ではなく自分自身をおごってあげる、という自分向けのご褒美表現。","collocations":["treat yourself to dessert","go treat yourself","treat yourself once in a while"]},"retail therapy":{"example2":"After the audit ended, she indulged in some retail therapy at Ginza.","exampleJa2":"監査が終わったあと、彼女は銀座で買い物によるストレス解消を楽しみました。","origin":"retail(小売)＋therapy(治療)。買い物を心の治療に見立てたユーモア表現。「財布に悪い治療法」と覚える。","collocations":["a bit of retail therapy","need some retail therapy","indulge in retail therapy"]},"haul":{"example2":"She showed off her Black Friday haul in a ten-minute video.","exampleJa2":"彼女はブラックフライデーの戦利品を10分の動画で披露しました。","origin":"haul は「網で引き上げた漁獲量」。一度の買い物で引き上げてきた獲物一式、というイメージ。動画文化で定着。","collocations":["a huge haul","haul video","show off my haul"]},"gym rat":{"example2":"Our new intern is a gym rat who lifts before morning meetings.","exampleJa2":"新しいインターンはジムの常連で、朝会の前に筋トレをしています。","origin":"rat は「入り浸る人」の比喩。ネズミが巣に住み着くように、ジムに住み着いているような人と覚える。","collocations":["a total gym rat","gym rat lifestyle","become a gym rat"]},"gains":{"example2":"Skipping sleep will cost you more gains than skipping one workout.","exampleJa2":"睡眠を削るほうが、一回の筋トレを休むより筋肉の成長を損ないます。","origin":"gain(利得)の複数形。投資のリターンと同じ発想で、筋トレで積み上げた「筋肉の利益」を指す。","collocations":["protect your gains","muscle gains","make serious gains"]},"swole":{"example2":"He came back from vacation looking surprisingly swole.","exampleJa2":"彼は休暇から戻ってきたら、驚くほど筋肉ムキムキになっていました。","origin":"swollen(膨れた)の俗語形。筋肉が風船のようにパンパンに膨らんだ状態、と「スウォール」の音で覚える。","collocations":["get swole","seriously swole","swole after months of lifting"]},"leg day":{"example2":"Never skip leg day, or your squat numbers will embarrass you.","exampleJa2":"脚トレの日をサボってはいけません。スクワットの記録が恥ずかしいことになりますよ。","origin":"部位別トレーニングの「脚の日」。きつくてサボられがちなので「Never skip leg day」が合言葉化した。","collocations":["never skip leg day","yesterday was leg day","sore from leg day"]},"pr":{"example2":"He treats every quarter's sales target like a PR to beat.","exampleJa2":"彼は毎四半期の売上目標を、更新すべき自己ベストのように扱っています。","origin":"personal record の頭字語。株価の高値更新と同じく、過去の自分という記録を塗り替えるイメージ。","collocations":["hit a new PR","PR on the deadlift","chasing a PR"]},"spot":{"example2":"Always ask someone to spot you on heavy bench press sets.","exampleJa2":"高重量のベンチプレスでは、必ず誰かに補助を頼みましょう。","origin":"spot(見張る・位置につく)から。持ち上げる人のそばに立ち、落下に備えて見守る役割のこと。","collocations":["spot me on this set","need a spot","spot someone at the gym"]},"jam-packed":{"example2":"My calendar is jam-packed with client reviews until quarter end.","exampleJa2":"四半期末まで、私の予定は顧客レビューでぎっしり詰まっています。","origin":"jam(ぎゅうぎゅう詰める)＋packed(詰め込まれた)の二重強調。瓶にジャムを詰め込む絵で覚えてもよい。","collocations":["jam-packed with people","a jam-packed schedule","jam-packed train"]},"bumper to bumper":{"example2":"The expressway was bumper to bumper for the entire holiday weekend.","exampleJa2":"連休の間ずっと、高速道路は数珠つなぎの大渋滞でした。","origin":"前の車のbumper(バンパー)に自分のbumperが触れそうなほど密着して並ぶ、という直訳そのままの情景。","collocations":["bumper-to-bumper traffic","stuck bumper to bumper","bumper to bumper for miles"]},"gridlock":{"example2":"Budget talks in parliament ended in complete gridlock again this week.","exampleJa2":"議会の予算協議は、今週もまた完全な膠着状態に終わりました。","origin":"grid(碁盤目の道路網)＋lock(施錠)。交差点が塞がり道路網全体が鍵をかけたように固まる状態。政治の膠着にも使う。","collocations":["complete gridlock","cause gridlock downtown","political gridlock"]},"beat the traffic":{"example2":"I take the six a.m. train to beat the traffic into the city.","exampleJa2":"都心への渋滞を避けるため、私は朝6時の電車に乗っています。","origin":"beat は「打ち負かす」。渋滞という敵とレースをして、先回りして勝つ、という勝負のイメージで覚える。","collocations":["leave early to beat the traffic","beat the rush hour traffic","beat the morning traffic"]},"make good time":{"example2":"We made good time and reached the client's office thirty minutes early.","exampleJa2":"移動が順調で、顧客のオフィスに30分早く着きました。","origin":"「良い時間(記録)を作る」が直訳。渋滞なく想定より速く進み、良い所要時間を叩き出すイメージ。","collocations":["make good time on the highway","we're making good time","made really good time"]},"cutting it close":{"example2":"Submitting the report five minutes before the deadline is cutting it close.","exampleJa2":"締切5分前のレポート提出は、かなりぎりぎりの綱渡りです。","origin":"cut close は「際(きわ)ぎりぎりを切る」。余白ゼロで紙を切るように、時間の余裕を残さない行動のこと。","collocations":["cutting it a bit close","you're cutting it close","cut it too close"]},"long time no see":{"example2":"Long time no see! How's the new branch office treating you?","exampleJa2":"久しぶり！新しい支店はどんな感じ？","origin":"中国語「好久不見」の直訳が英語に定着したとされる。文法的に壊れた形のまま挨拶として市民権を得た珍しい表現。","collocations":["long time no see, my friend","hey, long time no see","well, long time no see"]},"keep one's head above water":{"example2":"With month-end reports piling up, I'm barely keeping my head above water.","exampleJa2":"月末レポートが山積みで、なんとか持ちこたえている状態だよ。","origin":"溺れずに頭だけ水面に出して浮いているイメージ。仕事や借金に「沈まず」ぎりぎり耐えている状態を表す。","collocations":["barely keep my head above water","struggle to keep her head above water","manage to keep our heads above water"]},"tell me about it":{"example2":"\"Clients keep changing their orders last minute.\" \"Tell me about it.\"","exampleJa2":"「顧客が直前に注文を変えてばかりで」「ほんとそれだよ」","origin":"直訳「それについて教えて」だが、実際は「言われなくても知ってる、同感」の皮肉的な相づち。逆の意味になるのがポイント。","collocations":["ugh, tell me about it","\"So tiring.\" \"Tell me about it.\"","tell me about it, I've been there"]},"gig":{"example2":"He picked up a consulting gig advising a small asset manager.","exampleJa2":"彼は小さな運用会社に助言するコンサルの仕事を引き受けた。","origin":"元は1920年代のジャズミュージシャンの隠語で「演奏の仕事」。そこから単発・臨時の仕事全般に広がり、gig economyの語源にもなった。","collocations":["land a gig","a side gig","a freelance gig"]},"my treat":{"example2":"Great quarter, team. Lunch today is my treat.","exampleJa2":"今四半期は最高だったね。今日のランチは私のおごりだ。","origin":"treatは「もてなし・ごちそう」。「これは私のもてなしです」と支払いを引き受ける決まり文句。It's my treat.の短縮形。","collocations":["dinner's my treat","come on, my treat","next round is my treat"]},"sounds like a plan":{"example2":"\"Let's review the portfolio Monday morning.\" \"Sounds like a plan.\"","exampleJa2":"「月曜の朝にポートフォリオを見直そう」「いいね、そうしよう」","origin":"「それは(良い)計画に聞こえる」が原義。提案に軽く乗るときの定番の返事で、planに深い意味はなく「OK、それで行こう」の合図。","collocations":["sounds like a plan to me","\"Coffee at three?\" \"Sounds like a plan.\"","great, sounds like a plan"]},"twist someone's arm":{"example2":"I didn't want to present, but the manager twisted my arm.","exampleJa2":"発表したくなかったけど、部長に説き伏せられたんだ。","origin":"腕をねじり上げて無理やり従わせるイメージから。実際は暴力ではなく「強く頼み込んで首を縦に振らせる」ユーモラスな比喩。","collocations":["twist my arm a little","you twisted my arm","no one twisted your arm"]},"count me in":{"example2":"A study group for the securities exam? Count me in.","exampleJa2":"証券試験の勉強会？ぜひ参加させて。","origin":"count in は「頭数に入れる」。「参加者の人数に私も数えて」という発想。逆に不参加なら count me out と言う。","collocations":["count me in for dinner","if you're going, count me in","count me out"]},"swing by":{"example2":"Can you swing by my desk after the morning meeting?","exampleJa2":"朝会のあと、私の席にちょっと寄ってくれる？","origin":"swingは「弧を描いて振れる」。進路をふらりと曲げて立ち寄るイメージで、drop byより「ついでに軽く」の軽さが出る。","collocations":["swing by the office","swing by later","swing by and pick it up"]},"fingers crossed":{"example2":"The client decides on our proposal today, fingers crossed.","exampleJa2":"今日クライアントが提案の可否を決める。うまくいきますように。","origin":"中指を人差し指に重ねる幸運のおまじないから。十字架を作って魔除けにした古い習慣が由来とされる。仕草とセットで覚える。","collocations":["keep your fingers crossed","fingers crossed for good news","fingers crossed it works"]},"be dying to":{"example2":"Investors are dying to hear the central bank's next move.","exampleJa2":"投資家は中央銀行の次の一手を聞きたくてたまらない。","origin":"「死ぬほど〜したい」という誇張表現。日本語の「死ぬほど会いたい」と同じ発想なので直感的に覚えやすい。","collocations":["dying to know","dying to see you","dying to try it"]},"hands down":{"example2":"This fund is hands down our best performer this year.","exampleJa2":"このファンドは今年、文句なしにうちの最高の成績だ。","origin":"競馬で騎手が手綱から手を離しても(hands down)楽勝できたことから。「余裕の圧勝＝疑いなく一番」の意味に。","collocations":["hands down the best","win hands down","hands down my favorite"]},"go all out":{"example2":"We went all out to win the pension fund mandate.","exampleJa2":"年金基金の受託を勝ち取るために全力を尽くした。","origin":"all out は「持てる力を全部外へ出し切る」イメージ。手加減ゼロ、出し惜しみなしで挑む様子を表す。","collocations":["go all out for the party","go all out on decorations","decide to go all out"]},"doggy-bag":{"example2":"The portions were huge, so we doggy-bagged half the steak.","exampleJa2":"量が多すぎて、ステーキの半分は持ち帰りにしたよ。","origin":"「犬に食べさせる用」という建前で残り物を包んでもらったのが由来。実際は自分が食べる場合が多いのがご愛嬌。","collocations":["ask for a doggy bag","get a doggy bag","doggy-bag the leftovers"]},"have a kick to it":{"example2":"Try this ginger sauce, it has a nice kick to it.","exampleJa2":"このジンジャーソース食べてみて、いい感じにピリッとくるよ。","origin":"kickは「蹴り」。口の中を蹴られたような刺激、つまり辛さやパンチの効いた味を表す。飲み物のアルコールの強さにも使う。","collocations":["has quite a kick","a spicy kick","gives it a kick"]},"on me":{"example2":"You closed the deal, so tonight's drinks are on me.","exampleJa2":"契約をまとめてくれたから、今夜の飲み代は私持ちだ。","origin":"「勘定が私の上に乗る」イメージで、支払い責任が自分にあることを表す。The drinks are on the house(店のおごり)も同じ発想。","collocations":["it's on me","dinner's on me","on the house"]},"crush it":{"example2":"Our sales team crushed it, beating the quarterly target early.","exampleJa2":"営業チームは大活躍で、四半期目標を早々に達成した。","origin":"crushは「押しつぶす」。課題や目標を粉々に潰すほど圧倒的にやり遂げるイメージ。米口語でkill itと並ぶ褒め言葉。","collocations":["crush it at work","you're crushing it","crushed it today"]},"stay on track":{"example2":"Weekly check-ins keep the fund launch project on track.","exampleJa2":"週次の確認で、ファンド立ち上げ計画は予定どおり進んでいる。","origin":"trackは線路や競走路。列車が脱線せずレールの上を走り続けるイメージで、計画から外れず進むことを表す。","collocations":["stay on track with the plan","keep the project on track","get back on track"]},"get the hang of it":{"example2":"The new trading system felt confusing, but I'm getting the hang of it.","exampleJa2":"新しい取引システムは戸惑ったけど、だんだんコツをつかんできた。","origin":"hangは道具の「扱い方・balanceの取り方」を指した古い用法から。何度も触るうちに体で覚える感覚を表す。","collocations":["get the hang of the new software","soon get the hang of it","took a while to get the hang of it"]},"pace yourself":{"example2":"The audit season is long, so pace yourself this month.","exampleJa2":"監査シーズンは長丁場だから、今月はペース配分してね。","origin":"paceは歩幅・速度。マラソンのように、最初に飛ばしすぎず自分の速度を守って最後まで走り切る発想。","collocations":["pace yourself at work","remember to pace yourself","pace yourself, it's a long day"]},"wipe someone out":{"example2":"Back-to-back client meetings wiped me out by Friday evening.","exampleJa2":"立て続けの顧客面談で、金曜の夜にはくたくただった。","origin":"wipe outは「拭き消す・全滅させる」。体力がきれいさっぱり消し去られるイメージで、疲労困憊を表す。","collocations":["totally wiped me out","feel wiped out","the trip wiped us out"]},"no pain, no gain":{"example2":"Studying for the CFA is brutal, but no pain, no gain.","exampleJa2":"CFAの勉強は過酷だけど、苦労なくして得るものなしだ。","origin":"1980年代のエアロビ流行で広まったトレーニング標語。「痛みなければ利得なし」で、painとgainが韻を踏み覚えやすい。","collocations":["no pain, no gain, right?","as they say, no pain, no gain","believe in no pain, no gain"]},"hit the gym":{"example2":"He hits the gym before the market opens each morning.","exampleJa2":"彼は毎朝、市場が開く前にジムに行く。","origin":"hitは口語で「〜に行く・取りかかる」。hit the road(出発する)、hit the sack(寝る)と同じ仲間でまとめて覚えると効率的。","collocations":["hit the gym after work","hit the road","hit the sack"]},"pencil in":{"example2":"Let's pencil in the client call for Thursday at ten.","exampleJa2":"木曜10時にクライアントとの電話を仮で入れておこう。","origin":"ペンではなく鉛筆で書く＝あとで消して変更できる、という発想。確定したら ink in(ペンで清書)と言うこともある。","collocations":["pencil in a meeting","pencil you in for Monday","pencil in a tentative date"]},"unreal":{"example2":"The view from the client's penthouse office was unreal.","exampleJa2":"クライアントの最上階オフィスからの眺めは信じられないほどだった。","origin":"「現実(real)とは思えない」が原義。良すぎて夢みたい、という誇張の褒め言葉。incredibleやamazingのカジュアル版。","collocations":["absolutely unreal","the food was unreal","that goal was unreal"]},"blow someone away":{"example2":"Her market analysis blew the whole committee away.","exampleJa2":"彼女の市場分析は委員会全員を圧倒した。","origin":"強風で人が吹き飛ばされるイメージ。衝撃や感動が強すぎて「吹っ飛ばされる」ほどだという誇張表現。","collocations":["blew me away","blown away by the performance","it'll blow you away"]},"hole-in-the-wall":{"example2":"We found a hole-in-the-wall noodle shop near the exchange.","exampleJa2":"取引所の近くで、小さいけど旨い麺の店を見つけたんだ。","origin":"「壁の穴」のように小さく目立たない店構えの意。外見は地味でも味は絶品、という隠れた名店のニュアンスで褒め言葉になる。","collocations":["a hole-in-the-wall restaurant","a little hole-in-the-wall place","some hole-in-the-wall bar"]},"rip off":{"example2":"That fund's fees are so high it feels like a rip-off.","exampleJa2":"あのファンドの手数料は高すぎて、ぼったくりみたいだ。","origin":"rip offは「引きちぎる」。財布から金を力ずくでむしり取るイメージで、法外な値段で客をだます意味になった。","collocations":["get ripped off","a total rip-off","rip off tourists"]},"worth every penny":{"example2":"The premium research subscription was worth every penny for our desk.","exampleJa2":"有料リサーチの購読は、うちの部署には払った価値が十分あった。","origin":"「支払った1ペニー(最小硬貨)まで全部価値があった」が原義。1円単位まで無駄がなかった、という満足の最上級表現。","collocations":["worth every penny of it","expensive but worth every penny","worth every single penny"]},"be itching to":{"example2":"Traders are itching to buy the dip after the selloff.","exampleJa2":"急落のあと、トレーダーたちは押し目買いをしたくてうずうずしている。","origin":"itchは「かゆみ」。かゆくて掻かずにいられないように、やりたくて我慢できない状態。体の感覚に例えた表現。","collocations":["itching to get started","itching to travel again","itching for a chance"]},"save up":{"example2":"She's saving up her bonus for a down payment.","exampleJa2":"彼女は頭金のためにボーナスを貯めている。","origin":"saveに「積み上げる」のupが付き、目的のためコツコツ貯め続けるニュアンスが加わる。save単体より目標志向が強い。","collocations":["save up for a house","save up enough money","save up little by little"]},"settle in":{"example2":"Have you settled in to the new headquarters yet?","exampleJa2":"新しい本社にはもう慣れた？","origin":"settleは「沈んで落ち着く」。鳥が巣に降り立つように、新しい場所に体と心がなじんでいくイメージ。","collocations":["settle in to the new job","take time to settle in","settling in nicely"]},"getting there":{"example2":"\"Is the quarterly report ready?\" \"Not quite, but getting there.\"","exampleJa2":"「四半期レポートはできた？」「まだだけど、もう少しだよ」","origin":"「目的地(there)に向かっている途中」が原義。完成ではないが前進中、と前向きに伝える便利な返事。","collocations":["slowly getting there","we're getting there","not perfect, but getting there"]},"live out of boxes":{"example2":"After relocating for work, he lived out of boxes for a month.","exampleJa2":"転勤のあと、彼は1か月も段ボール生活をしていた。","origin":"「箱の中から物を出して暮らす」が直訳。荷解きせず段ボールから直接服や食器を取り出す、引っ越し直後の生活風景。","collocations":["still living out of boxes","live out of a suitcase","weeks of living out of boxes"]},"such a pain":{"example2":"Filing these compliance forms every month is such a pain.","exampleJa2":"毎月このコンプライアンス書類を出すのは本当に面倒だ。","origin":"pain(痛み)を「苦痛なほど面倒なこと」に転用。a pain in the neck(首の痛み＝悩みの種)の短縮版と覚えるとよい。","collocations":["such a pain to deal with","a pain in the neck","what a pain"]},"game changer":{"example2":"The new AI screening tool is a game changer for fund analysis.","exampleJa2":"新しいAIスクリーニングツールはファンド分析を一変させる存在だ。","origin":"スポーツで「試合の流れを変える選手・プレー」が原義。そこからビジネスで局面を根本から変える製品や出来事を指すように。","collocations":["a real game changer","a game changer for the industry","prove to be a game changer"]},"steep":{"example2":"A two percent management fee? That's pretty steep these days.","exampleJa2":"信託報酬2％？今どきそれはかなり高いね。","origin":"本来は「(坂が)急な」。値段のグラフが急角度で上がるイメージから「法外に高い」の意味に。坂道と一緒に覚える。","collocations":["a steep price","pretty steep for lunch","steep fees"]},"hold someone to that":{"example2":"You said drinks are on you after the deal closes. I'll hold you to that.","exampleJa2":"契約が決まったらおごるって言ったよね。その約束、忘れないからね。","origin":"hold A to B で「AをBに縛りつけておく」。相手を約束に固定して逃がさないイメージ。冗談めかして念を押すときの定番。","collocations":["I'll hold you to that","hold him to his word","don't worry, I'll hold you to it"]},"vent":{"example2":"After the tough client call, she needed to vent for ten minutes.","exampleJa2":"きつい顧客対応のあと、彼女は10分ほど愚痴を吐き出す必要があった。","origin":"ventは「通気口」。溜まった蒸気を外へ逃がすように、心に溜まった不満を口から放出するイメージ。","collocations":["vent about work","need to vent","vent my frustration"]},"drive someone up the wall":{"example2":"The printer jamming every morning drives the whole office up the wall.","exampleJa2":"毎朝プリンターが詰まるので、オフィス中がイライラしている。","origin":"イライラのあまり壁をよじ登りたくなるほど追い詰められるイメージ。crazyに「追い込む(drive)」という発想の仲間。","collocations":["drives me up the wall","driving everyone up the wall","it drives her up the wall"]},"pick up the slack":{"example2":"While she's on leave, the rest of us will pick up the slack.","exampleJa2":"彼女の休暇中は、残りのメンバーでその分をカバーするよ。","origin":"slackはロープの「たるみ」。たるんだ分を引っ張ってピンと張り直すイメージで、誰かの分の仕事を引き受ける意味に。","collocations":["pick up the slack for a colleague","someone has to pick up the slack","step in and pick up the slack"]},"loop someone in":{"example2":"Please loop compliance in before we send the fund brochure.","exampleJa2":"パンフレットを送る前に、コンプライアンス部門にも共有しておいて。","origin":"情報が回る「輪(loop)」の中に人を入れるイメージ。メールのCCに入れる場面で頻出。外すのはkeep out of the loop。","collocations":["loop me in on the email","keep her in the loop","out of the loop"]},"burn out":{"example2":"Analysts often burn out from working hundred-hour weeks.","exampleJa2":"アナリストは週100時間労働で燃え尽きてしまうことが多い。","origin":"ろうそくや電球が燃え尽きて消えるイメージ。エネルギーを使い果たし、意欲まで灰になる状態。名詞burnoutは燃え尽き症候群。","collocations":["burn out at work","suffer from burnout","avoid burning out"]},"throw someone under the bus":{"example2":"He threw his analyst under the bus when the forecast missed.","exampleJa2":"予測が外れたとき、彼は部下のアナリストに責任を押し付けた。","origin":"自分が助かるために仲間をバスの下へ突き飛ばす、という残酷な絵から。保身のための裏切りを表す現代スラング。","collocations":["throw a colleague under the bus","got thrown under the bus","don't throw me under the bus"]},"take a nosedive":{"example2":"The stock took a nosedive after the earnings miss.","exampleJa2":"決算が予想を下回り、その株は急落した。","origin":"飛行機が機首(nose)から真っ逆さまに落ちる「急降下」から。株価や人気がまっすぐ下に落ちる様子にぴったりの比喩。","collocations":["sales took a nosedive","prices took a nosedive","his popularity took a nosedive"]},"no kidding":{"example2":"\"The yen hit a new low again.\" \"No kidding, it's rough.\"","exampleJa2":"「円がまた最安値を更新したよ」「ほんとだよ、厳しいね」","origin":"kidは「からかう」。「冗談抜きで」が原義で、強い同意にも「マジで？」という驚きにも使える万能の相づち。","collocations":["no kidding, right?","\"It's freezing.\" \"No kidding.\"","no kidding, I was shocked"]},"in the red":{"example2":"The subsidiary stayed in the red for three straight years.","exampleJa2":"その子会社は3年連続で赤字のままだった。","origin":"帳簿で損失を赤インクで記入した慣習から。黒字は in the black。日本語の「赤字・黒字」と完全に同じ発想で覚えやすい。","collocations":["operate in the red","back in the black","deep in the red"]},"ride it out":{"example2":"Long-term investors chose to ride out the market turbulence.","exampleJa2":"長期投資家たちは市場の混乱をじっと耐え抜くことを選んだ。","origin":"船が嵐の中、錨を下ろして波に「乗ったまま」やり過ごす航海用語から。逃げずに終わるまで持ちこたえる意味。","collocations":["ride out the storm","ride out the recession","just ride it out"]},"a fool's errand":{"example2":"Timing the market perfectly is a fool's errand, honestly.","exampleJa2":"市場のタイミングを完璧に読もうなんて、正直、無駄な骨折りだよ。","origin":"errandは「お使い」。新人をからかって実在しない物を買いに行かせた悪戯が由来とされる。「愚か者のお使い＝徒労」。","collocations":["send someone on a fool's errand","prove to be a fool's errand","a complete fool's errand"]},"heads up":{"example2":"Quick heads up: the compliance training deadline is this Friday.","exampleJa2":"ちょっとお知らせ。コンプライアンス研修の締切は今週金曜だよ。","origin":"「頭を上げろ！(ボールが飛んでくるぞ)」という球技の掛け声から。前もって注意を促す「事前アラート」の意味に発展。","collocations":["just a heads up","give me a heads up","thanks for the heads up"]},"good to go":{"example2":"The system update is done, so the platform is good to go.","exampleJa2":"システム更新が完了したので、プラットフォームは稼働準備万端だ。","origin":"軍やNASAの発射前チェック用語が起源とされる。「全項目クリア、出発してよし」の許可サインのイメージ。","collocations":["we're good to go","all set and good to go","good to go anytime"]},"first thing":{"example2":"I'll check the overnight market moves first thing tomorrow.","exampleJa2":"明日の朝一番に、夜間の市場の動きを確認するよ。","origin":"first thing in the morning(朝の最初の仕事として)の短縮形。「他の何よりも先に」という優先順位の宣言。","collocations":["first thing in the morning","first thing Monday","do it first thing"]},"got a minute":{"example2":"Got a minute? I want your take on this fund proposal.","exampleJa2":"ちょっといい？このファンド提案について意見を聞きたいんだ。","origin":"Have you got a minute?の頭を省いたカジュアルな形。「1分ある？」と小さく尋ねることで相手の負担感を減らす声かけ。","collocations":["got a minute to talk?","got a sec?","when you've got a minute"]},"run something by someone":{"example2":"Let me run the new fee structure by legal first.","exampleJa2":"新しい手数料体系は、まず法務に相談させて。","origin":"アイデアを相手の前に「走らせて通す」イメージ。正式決定の前にさっと見せて反応をうかがう、根回しに近い動き。","collocations":["run it by the boss","run this idea by you","run the numbers by me"]},"take time off":{"example2":"I'm taking three days off after the fiscal year-end rush.","exampleJa2":"年度末の繁忙期が終わったら3日休みを取るんだ。","origin":"offは「仕事から離れて」。仕事の時間を切り取って自分のために使うイメージ。take a day offなど日数を挟んで使える。","collocations":["take a few days off","take time off work","take some well-deserved time off"]},"a big deal":{"example2":"Winning that institutional client was a big deal for our firm.","exampleJa2":"あの機関投資家を顧客にできたのは、わが社にとって一大事だった。","origin":"dealは「取引」。大きな取引＝重大事という発想。皮肉でnot a big deal(大したことない)と否定形でも頻出する。","collocations":["a really big deal","not a big deal","make a big deal out of it"]},"make it work":{"example2":"The deadline is tight, but our team always makes it work.","exampleJa2":"締切は厳しいけど、うちのチームはいつも何とかしてしまう。","origin":"「それを機能させる」が直訳。条件が悪くても工夫でどうにか回す、という前向きな決意の定番フレーズ。","collocations":["we'll make it work somehow","find a way to make it work","make it work with what we have"]},"wrap up":{"example2":"Let's wrap up the meeting; the market opens in ten minutes.","exampleJa2":"会議を切り上げよう。あと10分で市場が開く。","origin":"wrapは「包む」。仕事を包み紙できれいに包んで完了させるイメージ。会議や作業の「締め」に幅広く使える。","collocations":["wrap up the meeting","wrap things up","wrap up by five"]},"hand off":{"example2":"Before her leave, she handed off the client accounts to me.","exampleJa2":"休暇前に、彼女は担当顧客を私に引き継いだ。","origin":"アメフトでボールを味方にそっと手渡すプレー(ハンドオフ)から。仕事や責任をバトンのように渡すイメージ。","collocations":["hand off the project","a smooth handoff","hand it off to the team"]},"sign off":{"example2":"Risk management signed off on the new derivatives strategy.","exampleJa2":"リスク管理部門が新しいデリバティブ戦略を承認した。","origin":"書類の末尾に署名(sign)して案件を送り出す(off)イメージ。sign off on 〜で「〜に正式なゴーサインを出す」。","collocations":["sign off on the budget","get sign-off from the director","waiting for final sign-off"]},"sink in":{"example2":"It took days for the promotion news to sink in.","exampleJa2":"昇進の知らせを実感するまで数日かかった。","origin":"水が土にゆっくり染み込む(sink in)イメージ。頭では聞いたことが、時間をかけて心の奥まで届く感覚を表す。","collocations":["let it sink in","the news slowly sank in","hasn't sunk in yet"]},"kill it":{"example2":"She killed it in the investor pitch and won the mandate.","exampleJa2":"彼女は投資家向けプレゼンで大活躍し、受託を勝ち取った。","origin":"「(舞台などを)完全に仕留める」というショービジネス由来の褒め言葉。crush it、nail itと同グループでまとめて覚える。","collocations":["you killed it out there","killed it on stage","go kill it"]},"kick in":{"example2":"The new tariff rules kick in next quarter, so plan ahead.","exampleJa2":"新しい関税ルールは来四半期から始まるから、前もって備えよう。","origin":"エンジンが「ドンと蹴られて」始動するイメージ。薬・制度・効果などが動き出す瞬間を表す。","collocations":["the medicine kicks in","the new rules kick in","wait for it to kick in"]},"the whole nine yards":{"example2":"The launch event had press, demos, catering, the whole nine yards.","exampleJa2":"発表会には報道陣、デモ、ケータリングと、何もかも揃っていた。","origin":"由来は諸説あり(機関銃の弾帯9ヤード説など)不明のまま定着。「9ヤード分まるごと＝フルセット全部」とイメージで覚える。","collocations":["with flowers, music, the whole nine yards","go the whole nine yards","the whole shebang"]},"could use":{"example2":"This report could use another pair of eyes before submission.","exampleJa2":"このレポートは提出前にもう一人チェックしてくれる人がいるとありがたい。","origin":"「あれば使えるのに」＝「欲しい」を控えめに言う婉曲表現。I want より大人びた、遠回しなおねだりの形。","collocations":["could use some help","could use a break","could use a coffee"]},"spread the word":{"example2":"Spread the word: the seminar on NISA is next Wednesday.","exampleJa2":"みんなに知らせて。NISAセミナーは来週水曜だよ。","origin":"the word は「知らせ・情報」。言葉を種のようにまき広げるイメージで、口コミで告知を広める意味になる。","collocations":["help spread the word","spread the word about the event","word spreads fast"]},"show up":{"example2":"Over a hundred investors showed up for the fund seminar.","exampleJa2":"100人を超える投資家がファンドセミナーに駆けつけた。","origin":"show(姿を見せる)+up(その場に)で「現れる」。予告なしに現れる、または約束どおり顔を出す、どちらにも使える基本句動詞。","collocations":["show up on time","show up late","didn't show up"]}};

// === VISUAL_OVERRIDES: フラッシュカードのイラスト（2026-07-26点検+新語追加分） ===
